import * as React from 'react';
import { useState, useMemo, useRef, useEffect } from 'react';
import { Question, TelegramConfig, Feedback } from '../types';
import { DEFAULT_TG_BOT_TOKEN, TG_CHANNELS } from '../constants';
import html2canvas from 'html2canvas';
import { sendQuizPoll, sendQuestionImage } from '../services/telegramService';

// ប្រកាស Global Variable សម្រាប់បណ្ណាល័យដែលបាននាំចូលក្នុង index.html
declare var html2pdf: any;
declare var JSZip: any;

interface CreateSectionProps {
  quizData: Question[];
  feedbackList?: Feedback[];
  onDeleteFeedback?: (id: string) => void;
  onAdd: (q: Question) => void;
  onUpdate: (index: number, q: Question) => void;
  onRemove: (index: number) => void;
  onToggleSubject: (subject: string, type: 'mcq' | 'short', active: boolean) => void;
  onUpdateSubject: (subject: string, type: 'mcq' | 'short', newName: string) => void;
  onRemoveSubject: (subject: string, type: 'mcq' | 'short') => void;
  onReorderSubject: (subject: string, type: 'mcq' | 'short', direction: 'up' | 'down') => void;
  onBatchAdd: (qs: Question[]) => void;
  onLogout: () => void;
}

interface PdfSettings { showAnswerKey: boolean; shuffleQuestions: boolean; schoolName: string; examDate: string; studentNameField: boolean; }
interface ImageSettings { style: 'modern' | 'classic' | 'elegant' | 'dark'; showBrand: boolean; brandName: string; }

// រចនាប័ទ្ម Font ខ្មែរដែលរឹងមាំបំផុតសម្រាប់ការ Capture (Fallback Strategy)
const KHMER_FONT_STACK = "'Kantumruy Pro', 'Khmer OS Battambang', 'Khmer OS', sans-serif";
const KHMER_SIEMREAP_STACK = "'Siemreap', 'Khmer OS Siemreap', 'Kantumruy Pro', sans-serif";
const KHMER_HEADING_STACK = "'Kantumruy Pro', 'Khmer OS Muol Light', serif";

const SubjectCard: React.FC<{
  sub: { name: string, isActive: boolean, count: number, type: 'mcq' | 'short' };
  isFirst: boolean;
  isLast: boolean;
  onToggleSubject: (subject: string, type: 'mcq' | 'short', active: boolean) => void;
  onEditSubject: (subject: string, type: 'mcq' | 'short') => void;
  onRemoveSubject: (subject: string, type: 'mcq' | 'short') => void;
  onReorderSubject: (subject: string, type: 'mcq' | 'short', direction: 'up' | 'down') => void;
  onOpenExport: (name: string, type: 'mcq' | 'short', mode: 'pdf' | 'image' | 'telegram') => void;
}> = ({ sub, isFirst, isLast, onToggleSubject, onEditSubject, onRemoveSubject, onReorderSubject, onOpenExport }) => (
  <div className={`group glass-card p-6 rounded-[2.5rem] border transition-all flex flex-col justify-between ${sub.isActive ? 'bg-white border-white shadow-xl' : 'bg-gray-100/50 border-gray-200 grayscale opacity-60'}`}>
    <div>
      <div className="flex justify-between items-start mb-4">
        <div className="flex-1 truncate pr-2">
          <div className="flex items-center gap-2 mb-2">
            <h3 className="text-lg font-black heading-kh text-maroon truncate cursor-pointer hover:underline" onClick={() => onOpenExport(sub.name, sub.type, 'telegram')}>{sub.name}</h3>
            <button onClick={() => onEditSubject(sub.name, sub.type)} className="p-1.5 bg-maroon/5 text-maroon rounded-lg hover:bg-maroon hover:text-white transition-all">✏️</button>
          </div>
          <div className="flex flex-wrap gap-2">
            <span className="text-[9px] font-black bg-blue-50 text-blue-600 px-3 py-1 rounded-full uppercase tracking-tighter">
              {sub.type === 'mcq' ? 'QCM' : 'Q & A'} ({sub.count})
            </span>
            <span className={`text-[9px] font-black px-3 py-1 rounded-full uppercase tracking-tighter ${sub.isActive ? 'bg-green-50 text-green-600' : 'bg-gray-200 text-gray-500'}`}>
              {sub.isActive ? 'Active' : 'Inactive'}
            </span>
          </div>
        </div>
        <div className="flex flex-col gap-1">
          <button disabled={isFirst} onClick={() => onReorderSubject(sub.name, sub.type, 'up')} className="w-8 h-8 flex items-center justify-center rounded-lg bg-white border border-gray-100 shadow-sm hover:bg-maroon hover:text-white disabled:opacity-20">🔼</button>
          <button disabled={isLast} onClick={() => onReorderSubject(sub.name, sub.type, 'down')} className="w-8 h-8 flex items-center justify-center rounded-lg bg-white border border-gray-100 shadow-sm hover:bg-maroon hover:text-white disabled:opacity-20">🔽</button>
        </div>
      </div>
    </div>

    <div className="grid grid-cols-2 gap-2 mt-4">
      <button onClick={() => onOpenExport(sub.name, sub.type, 'pdf')} className="py-2.5 bg-indigo-50 text-indigo-600 rounded-xl font-black text-[10px] hover:bg-indigo-600 hover:text-white transition-all flex items-center justify-center gap-1.5">📄 PDF</button>
      <button onClick={() => onOpenExport(sub.name, sub.type, 'image')} className="py-2.5 bg-orange-50 text-orange-600 rounded-xl font-black text-[10px] hover:bg-orange-600 hover:text-white transition-all flex items-center justify-center gap-1.5">🖼️ Image</button>
      <button onClick={() => onOpenExport(sub.name, sub.type, 'telegram')} className="col-span-2 py-3 bg-blue-600 text-white rounded-xl font-black text-[10px] hover:brightness-110 transition-all flex items-center justify-center gap-2">✈️ ផ្ញើទៅ Telegram</button>
      <div className="col-span-2 flex gap-2 pt-2">
        <button onClick={() => onToggleSubject(sub.name, sub.type, !sub.isActive)} className="flex-1 py-2 rounded-lg text-[9px] font-bold border border-gray-100 hover:bg-gray-50">{sub.isActive ? 'បិទដំណើរការ' : 'បើកដំណើរការ'}</button>
        <button onClick={() => onRemoveSubject(sub.name, sub.type)} className="p-2 bg-red-50 text-red-500 rounded-lg hover:bg-red-500 hover:text-white">🗑️</button>
      </div>
    </div>
  </div>
);

const CreateSection: React.FC<CreateSectionProps> = ({ 
  quizData, feedbackList = [], onDeleteFeedback, onAdd, onUpdate, onRemove, onToggleSubject, onUpdateSubject, onRemoveSubject, onReorderSubject, onBatchAdd
}) => {
  const KHMER_PREFIXES = ['ក', 'ខ', 'គ', 'ឃ'];
  const KHMER_DIGITS = ['០', '១', '២', '៣', '៤', '៥', '៦', '៧', '៨', '៩'];
  const [entryMode, setEntryMode] = useState<'single' | 'bulk' | 'subjects' | 'feedback'>('single');
  const [qType, setQType] = useState<'mcq' | 'short'>('mcq');
  const [bulkType, setBulkType] = useState<'mcq' | 'short'>('mcq');
  const [subject, setSubject] = useState('');
  const [question, setQuestion] = useState('');
  const [options, setOptions] = useState(['', '', '', '']);
  const [correct, setCorrect] = useState(0);
  const [shortAnswer, setShortAnswer] = useState('');
  const [editingIndex, setEditingIndex] = useState<number | null>(null);
  const [bulkText, setBulkText] = useState('');

  // Export & Telegram States
  const [viewingExport, setViewingExport] = useState<{name: string, type: 'mcq' | 'short', mode: 'pdf' | 'image' | 'telegram'} | null>(null);
  const [tgConfig, setTgConfig] = useState<TelegramConfig>({ botToken: DEFAULT_TG_BOT_TOKEN, chatId: TG_CHANNELS[0].value });
  const [sendAsImage, setSendAsImage] = useState(false);
  const [isProcessing, setIsProcessing] = useState<number | 'all' | boolean>(false);

  // Settings
  const [pdfSettings, setPdfSettings] = useState<PdfSettings>({ showAnswerKey: true, shuffleQuestions: false, schoolName: 'វិទ្យាស្ថានបណ្តុះបណ្តាលបច្ចេកទេស', examDate: 'ឆ្នាំសិក្សា ២០២៤-២០២៥', studentNameField: true });
  const [imageSettings, setImageSettings] = useState<ImageSettings>({ style: 'elegant', showBrand: true, brandName: 'Master Quiz KH' });

  // Refs
  const imageTemplateRef = useRef<HTMLDivElement>(null);
  const pdfTemplateRef = useRef<HTMLDivElement>(null);
  const [previewQ, setPreviewQ] = useState<Question | null>(null);

  const toKhmerNumeral = (n: number) => n.toString().split('').map(digit => KHMER_DIGITS[parseInt(digit)] || digit).join('');

  const groupedSubjects = useMemo(() => {
    const getSubjectsByType = (type: 'mcq' | 'short') => {
      const seen = new Set<string>();
      const list: any[] = [];
      quizData.filter(q => q.type === type).forEach(q => {
        if (!seen.has(q.subject)) {
          seen.add(q.subject);
          const related = quizData.filter(rq => rq.subject === q.subject && rq.type === type);
          list.push({ name: q.subject, isActive: related.every(rq => rq.isActive !== false), count: related.length, type });
        }
      });
      return list;
    };
    return { mcq: getSubjectsByType('mcq'), short: getSubjectsByType('short') };
  }, [quizData]);

  const activeExportQuestions = useMemo(() => {
    if (!viewingExport) return [];
    let qs = quizData.filter(q => q.subject === viewingExport.name && q.type === viewingExport.type);
    if (viewingExport.mode === 'pdf' && pdfSettings.shuffleQuestions) {
      qs = [...qs].sort(() => Math.random() - 0.5);
    }
    return qs;
  }, [quizData, viewingExport, pdfSettings.shuffleQuestions]);

  // Export Logic: PDF
  const handleExportPdf = async () => {
    if (!pdfTemplateRef.current || !viewingExport) return;
    setIsProcessing(true);
    try {
      const opt = {
        margin: 10,
        filename: `Exam_${viewingExport.name}_${new Date().getTime()}.pdf`,
        image: { type: 'jpeg', quality: 0.98 },
        html2canvas: { scale: 2, useCORS: true, letterRendering: true },
        jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' }
      };
      await html2pdf().from(pdfTemplateRef.current).set(opt).save();
    } catch (e) {
      alert("កំហុសក្នុងការបង្កើត PDF");
    } finally {
      setIsProcessing(false);
    }
  };

  /**
   * មុខងារ Capture រូបភាពដែលមានភាពស៊ាំខ្ពស់បំផុតនឹងបញ្ហា Font
   */
  const captureImage = async (): Promise<Blob | null> => {
    if (!imageTemplateRef.current) return null;

    // ជំហានទី១៖ ធានាថា Font ទាំងអស់ត្រូវបាន Load រួចរាល់ក្នុង Browser
    await document.fonts.ready;

    // ជំហានទី២៖ រង់ចាំបន្តិចទៀតឱ្យ DOM ឆ្លងកាត់ការ Render ពេញលេញ
    await new Promise(r => setTimeout(r, 800)); 

    try {
      const canvas = await html2canvas(imageTemplateRef.current, {
        scale: 3, // បង្កើន Resolution ឱ្យច្បាស់
        useCORS: true,
        allowTaint: true,
        backgroundColor: imageSettings.style === 'dark' ? '#121212' : '#ffffff',
        logging: false,
        onclone: (clonedDoc) => {
          // ជំហានទី៣៖ បង្ខំ Style ខ្មែរទៅលើ Clone DOM យ៉ាងម៉ឺងម៉ាត់បំផុត
          const template = clonedDoc.getElementById('image-export-template');
          if (template) {
            template.style.visibility = 'visible';
            template.style.display = 'block';

            // បង្ខំ Font ខ្មែរ Siemreap សម្រាប់ផ្នែក "វិញ្ញាសា" (Subject)
            const subjectLabel = template.querySelector('.subject-label-capture') as HTMLElement;
            if (subjectLabel) {
              subjectLabel.style.fontFamily = KHMER_SIEMREAP_STACK;
              subjectLabel.style.fontWeight = '700';
              subjectLabel.style.lineHeight = '1.8';
              subjectLabel.style.display = 'inline-block';
            }

            // បង្ខំ Font សម្រាប់ផ្នែក "សំណួរ" (Question)
            const questionText = template.querySelector('.question-text-capture') as HTMLElement;
            if (questionText) {
              questionText.style.fontFamily = KHMER_FONT_STACK;
              questionText.style.fontWeight = '700';
              questionText.style.lineHeight = '2';
            }

            // បង្ខំ Font សម្រាប់ "ជម្រើសចម្លើយ"
            const optionsTexts = template.querySelectorAll('.option-text-capture');
            optionsTexts.forEach((opt: any) => {
              opt.style.fontFamily = KHMER_FONT_STACK;
              opt.style.fontWeight = '600';
            });

            const brandName = template.querySelector('.brand-name-capture') as HTMLElement;
            if (brandName) {
              brandName.style.fontFamily = KHMER_HEADING_STACK;
            }
          }
        }
      });

      return new Promise<Blob | null>(r => canvas.toBlob(r, 'image/png', 1.0));
    } catch (e) {
      console.error("Capture Error:", e);
      return null;
    }
  };

  // Export Logic: Image ZIP
  const handleExportImageZip = async () => {
    if (!viewingExport) return;
    setIsProcessing(true);
    const zip = new JSZip();
    try {
      for (let i = 0; i < activeExportQuestions.length; i++) {
        const q = activeExportQuestions[i];
        setPreviewQ(q);
        const blob = await captureImage();
        if (blob) zip.file(`Question_${i+1}.png`, blob);
      }
      const content = await zip.generateAsync({ type: "blob" });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(content);
      link.download = `Images_${viewingExport.name}.zip`;
      link.click();
    } catch (e) {
      alert("កំហុសក្នុងការបង្កើតរូបភាព ZIP");
    } finally {
      setPreviewQ(null);
      setIsProcessing(false);
    }
  };

  // Telegram Logic
  const handleSendToTelegram = async (q: Question, index: number | 'all') => {
    setIsProcessing(index);
    try {
      if (sendAsImage) {
        setPreviewQ(q);
        const blob = await captureImage();
        if (blob) {
          const caption = `📌 ${q.question.substring(0, 150)}...\n\nវិញ្ញាសា៖ ${q.subject}\n#QuizMasterKH 🇰🇭`;
          await sendQuestionImage(tgConfig, blob, caption);
        }
      } else {
        if (q.type === 'mcq') {
          await sendQuizPoll(tgConfig, q);
        } else {
          const text = `📌 *សំណួរ៖* ${q.question}\n\n✅ *ចម្លើយ៖* ${q.answer}\n\nវិញ្ញាសា៖ ${q.subject}\nWeb QCM 🇰🇭`;
          await fetch(`https://api.telegram.org/bot${tgConfig.botToken}/sendMessage`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ chat_id: tgConfig.chatId, text, parse_mode: 'Markdown' })
          });
        }
      }
    } catch (e) {
      console.error(e);
    } finally {
      if (index !== 'all') {
        setIsProcessing(false);
        setPreviewQ(null);
      }
    }
  };

  const handleSendAllTelegram = async () => {
    if (!confirm(`តើអ្នកចង់ផ្ញើទាំង ${activeExportQuestions.length} សំណួរទៅកាន់ Telegram មែនទេ?`)) return;
    setIsProcessing('all');
    for (let i = 0; i < activeExportQuestions.length; i++) {
      await handleSendToTelegram(activeExportQuestions[i], i);
      await new Promise(r => setTimeout(r, sendAsImage ? 5000 : 2000));
    }
    setIsProcessing(false);
    setPreviewQ(null);
    alert("បានផ្ញើរួចរាល់!");
  };

  const handleSubmitSingle = () => {
    if (!subject.trim() || !question.trim()) return alert("សូមបំពេញព័ត៌មាន!");
    const cleanQ: Question = {
      subject: subject.trim(),
      question: question.trim(),
      type: qType,
      isActive: true,
      ...(qType === 'mcq' ? { options: options.map(o => o.trim()), correct } : { answer: shortAnswer.trim() })
    };
    if (editingIndex !== null) onUpdate(editingIndex, cleanQ); else onAdd(cleanQ);
    setQuestion(''); setOptions(['', '', '', '']); setShortAnswer(''); setEditingIndex(null);
  };

  const handleBulkSubmit = () => {
    if (!subject.trim() || !bulkText.trim()) return alert("សូមបំពេញព័ត៌មាន!");
    const lines = bulkText.split('\n');
    const parsed: Question[] = [];
    let current: any = null;
    let iA = false;

    if (bulkType === 'mcq') {
      lines.forEach(l => {
        const t = l.trim(); if (!t) return;
        const qm = t.match(/^[០-៩0-9]+\.\s*(.*)/);
        if (qm) {
          if (current && current.options?.length >= 2) parsed.push(current);
          current = { type: 'mcq', subject: subject.trim(), question: qm[1].trim(), options: [], correct: 0, isActive: true };
          return;
        }
        const om = t.match(/^[កខគឃ]\.\s*(.*)/);
        if (om && current) {
          let txt = om[1].replace('(ចម្លើយត្រឹមត្រូវ)', '').trim();
          current.options.push(txt);
          if (om[1].includes('(ចម្លើយត្រឹមត្រូវ)')) current.correct = current.options.length - 1;
        }
      });
      if (current && current.options?.length >= 2) parsed.push(current);
    } else {
      lines.forEach(l => {
        const t = l.trim();
        const qm = t.match(/^[០-៩0-9]+\.\s*(.*)/);
        if (qm) {
          if (current && current.answer) parsed.push(current);
          current = { type: 'short', subject: subject.trim(), question: qm[1].trim(), answer: '', isActive: true };
          iA = false; return;
        }
        const am = t.match(/^ចម្លើយ\s*[៖:]\s*(.*)/);
        if (am && current) { current.answer = am[1].trim(); iA = true; return; }
        if (iA && current) current.answer += (current.answer ? '\n' : '') + l;
      });
      if (current && current.answer) parsed.push(current);
    }
    if (parsed.length) { onBatchAdd(parsed); setBulkText(''); alert(`បានបញ្ចូល ${parsed.length} សំណួរ!`); }
  };

  return (
    <div className="space-y-8 animate-fadeIn pb-32">
      {/* Hidden Templates for Export */}
      <div className="fixed -left-[8000px] top-0 overflow-hidden select-none pointer-events-none">
        {/* Image Design - ប្រើ Inline Styles យ៉ាងហ្មត់ចត់បំផុត */}
        <div 
          id="image-export-template"
          ref={imageTemplateRef} 
          className={`w-[650px] p-16 border-[12px] border-maroon relative ${imageSettings.style === 'dark' ? 'bg-[#121212] text-white' : 'bg-white text-black'}`}
          style={{ fontFamily: KHMER_FONT_STACK }}
        >
          <div className="text-center mb-12 border-b-4 border-maroon pb-10">
            <h1 className="brand-name-capture font-black mb-4 text-4xl" style={{ fontFamily: KHMER_HEADING_STACK }}>
              {imageSettings.showBrand ? imageSettings.brandName : 'Master Quiz'}
            </h1>
            <div className="flex justify-center items-center gap-6">
              <span className="w-16 h-[4px] bg-maroon"></span>
              {/* ផ្នែកវិញ្ញាសាដែលអ្នកប្រើចង់ឱ្យច្បាស់ និងមិនលោត Font */}
              <p className="subject-label-capture text-2xl uppercase font-bold tracking-widest text-maroon" 
                 style={{ 
                   fontFamily: KHMER_SIEMREAP_STACK,
                   textRendering: 'optimizeLegibility',
                   WebkitFontSmoothing: 'antialiased',
                   padding: '0 10px'
                 }}>
                វិញ្ញាសា៖ {previewQ?.subject}
              </p>
              <span className="w-16 h-[4px] bg-maroon"></span>
            </div>
          </div>

          <div className="space-y-12">
            <h2 className="question-text-capture text-3xl leading-[2.2] font-bold text-justify" style={{ fontFamily: KHMER_FONT_STACK }}>
              {previewQ?.question}
            </h2>

            {previewQ?.type === 'mcq' ? (
              <div className="grid grid-cols-1 gap-6 mt-10">
                {previewQ.options?.map((opt, i) => (
                  <div key={i} className={`flex items-center gap-8 p-8 rounded-[2.5rem] border-2 ${imageSettings.style === 'dark' ? 'bg-white/5 border-white/10' : 'bg-gray-50 border-gray-100'}`}>
                    <span className="w-16 h-16 flex items-center justify-center bg-maroon text-white rounded-2xl font-black text-3xl shrink-0">{KHMER_PREFIXES[i]}</span>
                    <span className="option-text-capture text-2xl font-bold leading-[1.8]" style={{ fontFamily: KHMER_FONT_STACK }}>{opt}</span>
                  </div>
                ))}
              </div>
            ) : (
              <div className={`mt-10 p-12 border-l-[20px] border-green-500 rounded-r-[4rem] ${imageSettings.style === 'dark' ? 'bg-green-500/10' : 'bg-green-50'}`}>
                <p className="font-black mb-6 text-2xl text-green-700" style={{ fontFamily: KHMER_FONT_STACK }}>✅ ចម្លើយត្រឹមត្រូវ ៖</p>
                <p className="text-2xl leading-[2.2] font-bold whitespace-pre-wrap text-justify" style={{ fontFamily: KHMER_FONT_STACK }}>{previewQ?.answer}</p>
              </div>
            )}
          </div>

          <div className="mt-24 text-center pt-12 border-t-2 border-maroon/10 opacity-50">
            <p className="text-lg font-black text-maroon" style={{ fontFamily: KHMER_FONT_STACK }}>បង្កើតដោយប្រព័ន្ធ Web QCM 🇰🇭</p>
          </div>
        </div>

        {/* PDF Design */}
        <div ref={pdfTemplateRef} className="w-[210mm] min-h-[297mm] p-[25mm] bg-white text-black leading-normal" style={{ fontFamily: KHMER_FONT_STACK }}>
          <div className="text-center mb-12">
