                    <span className="text-maroon">{q.type === 'mcq' ? KHMER_PREFIXES[q.correct || 0] : 'Q&A'}</span>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      </div>

      {/* Main UI Tabs */}
      <div className="glass-card rounded-[2.5rem] shadow-xl p-8 border border-white/50">
