                 style={{ 
                   fontFamily: KHMER_SIEMREAP_STACK,
                   textRendering: 'optimizeLegibility',
                   WebkitFontSmoothing: 'antialiased'
                 }}>
                វិញ្ញាសា៖ {previewQ?.subject}
              </p>
              <span className="w-16 h-[4px] bg-maroon shrink-0 opacity-30"></span>
            </div>
          </div>

          {/* Footer - ឈ្មោះប្រព័ន្ធ */}
          <div className="mt-12 text-center pt-8 border-t-2 border-maroon/10 opacity-50">
            <p className="text-lg font-black text-maroon" style={{ fontFamily: KHMER_FONT_STACK }}>បង្កើតដោយប្រព័ន្ធ Web QCM 🇰🇭</p>
          </div>
        </div>

        {/* PDF Design */}
        <div ref={pdfTemplateRef} className="w-[210mm] min-h-[297mm] p-[25mm] bg-white text-black leading-normal" style={{ fontFamily: KHMER_FONT_STACK }}>
          <div className="text-center mb-12">
            <h2 className="heading-kh text-[16pt] font-bold mb-1">ព្រះរាជាណាចក្រកម្ពុជា</h2>
            <h3 className="heading-kh text-[14pt] font-bold mb-2">ជាតិ សាសនា ព្រះមហាក្សត្រ</h3>
            <div className="flex justify-center mb-6"><div className="w-24 h-[1.5px] bg-black"></div></div>
            <div className="flex justify-between items-start mb-8 border-b-2 border-black pb-4 text-left">
              <div className="heading-kh">
                <p className="font-bold text-[14pt]">{pdfSettings.schoolName}</p>
                <p className="text-[12pt]">មុខវិជ្ជា៖ {viewingExport?.name}</p>
              </div>
              <div className="text-right small-kh italic text-[10pt]">
                <p>{pdfSettings.examDate}</p>
                <p>រយៈពេល៖ ៦០ នាទី</p>
              </div>
            </div>
          </div>
          {pdfSettings.studentNameField && (
            <div className="mb-10 grid grid-cols-2 gap-10 small-kh border p-4 rounded-lg">
              <p>ឈ្មោះសិស្ស៖ ......................................................</p>
              <p>លេខតុ៖ ....................... លេខបន្ទប់៖ ...............</p>
            </div>
          )}
          <div className="space-y-10">
            {activeExportQuestions.map((q, idx) => (
              <div key={idx} className="break-inside-avoid">
                <p className="heading-kh font-bold text-[13pt] leading-[1.8] mb-4 text-justify">
                  <span className="mr-3">{toKhmerNumeral(idx + 1)}.</span>{q.question}
                </p>
                {q.type === 'mcq' ? (
                  <div className="grid grid-cols-2 gap-x-12 gap-y-3 ml-12">
                    {q.options?.map((opt, i) => (
                      <div key={i} className="flex gap-4 items-start small-kh text-[12pt]">
                        <span className="font-bold">{KHMER_PREFIXES[i]}.</span>
                        <span>{opt}</span>
                      </div>
                    ))}
                  </div>
                ) : <div className="ml-12 h-12 border-b border-dashed border-gray-300 w-full mt-4"></div>}
              </div>
            ))}
          </div>
          {pdfSettings.showAnswerKey && (
            <div className="mt-24 border-t-2 border-black pt-10 break-before-page">
              <h4 className="heading-kh font-bold text-[14pt] mb-6 text-center underline">គន្លឹះចម្លើយ (Answer Key)</h4>
              <div className="grid grid-cols-5 gap-4">
                {activeExportQuestions.map((q, idx) => (
                  <div key={idx} className="text-[11pt] font-bold border p-3 rounded-lg text-center flex flex-col gap-1">
                    <span className="text-[9pt] opacity-50">សំណួរ {toKhmerNumeral(idx+1)}</span>
                    <span className="text-maroon">{q.type === 'mcq' ? KHMER_PREFIXES[q.correct || 0] : 'Q&A'}</span>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      </div>

      {/* Main UI Tabs */}
      <div className="glass-card rounded-[2.5rem] shadow-xl p-8 border border-white/50">
        <div className="flex border-b border-gray-100 mb-8 -mx-8 px-8 overflow-x-auto custom-scrollbar">
          {['single', 'bulk', 'subjects', 'feedback'].map(m => (
            <button key={m} onClick={() => setEntryMode(m as any)} className={`pb-4 px-8 font-black heading-kh text-sm transition-all border-b-4 shrink-0 capitalize ${entryMode === m ? 'border-maroon text-maroon' : 'border-transparent text-gray-400 hover:text-gray-600'}`}>
              {m === 'single' ? '✍️ បញ្ចូលសំណួរ' : m === 'bulk' ? '🚀 បញ្ចូលទាំងអស់' : m === 'subjects' ? '📚 គ្រប់គ្រងទិន្នន័យ' : '💬 មតិយោបល់'}
              {m === 'feedback' && feedbackList.length > 0 && <span className="ml-2 bg-red-600 text-white text-[8px] px-2 py-0.5 rounded-full animate-pulse">{feedbackList.length}</span>}
            </button>
          ))}
        </div>

        {entryMode === 'single' && (
          <div className="space-y-6 animate-fadeIn">
            <div className="flex flex-wrap gap-4 items-center justify-between">
              <h2 className="text-xl font-black heading-kh text-maroon flex items-center gap-2"><span>{editingIndex !== null ? '✏️' : '🆕'}</span>{editingIndex !== null ? 'កែសម្រួលសំណួរ' : 'បង្កើតសំណួរថ្មី'}</h2>
              <div className="flex bg-gray-100 p-1 rounded-xl">
                {['mcq', 'short'].map(t => (
                  <button key={t} onClick={() => setQType(t as any)} className={`px-4 py-2 rounded-lg text-[10px] font-black uppercase transition-all ${qType === t ? 'bg-white text-maroon shadow-sm' : 'text-gray-400'}`}>{t === 'mcq' ? 'QCM' : 'Q & A'}</button>
                ))}
              </div>
            </div>
            <div className="grid grid-cols-1 gap-5">
              <input type="text" value={subject} onChange={(e) => setSubject(e.target.value)} className="w-full px-6 py-4 rounded-2xl border border-gray-100 outline-none focus:ring-2 focus:ring-maroon heading-kh bg-gray-50/50" placeholder="ឈ្មោះមុខវិជ្ជា..." />
              <textarea value={question} onChange={(e) => setQuestion(e.target.value)} className="w-full px-6 py-4 rounded-2xl border border-gray-100 focus:ring-2 focus:ring-maroon outline-none min-h-[120px] small-kh bg-gray-50/50" placeholder="សរសេរសំណួរ..." />
              {qType === 'mcq' ? (
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  {options.map((opt, i) => (
                    <div key={i} className="flex items-center gap-3 bg-white p-4 rounded-2xl border border-gray-100 shadow-sm focus-within:border-maroon/30">
                      <span className="font-black text-maroon w-10 h-10 flex items-center justify-center bg-maroon/5 rounded-xl">{KHMER_PREFIXES[i]}</span>
                      <input type="text" value={opt} onChange={(e) => { const n = [...options]; n[i] = e.target.value; setOptions(n); }} className="flex-1 outline-none small-kh text-sm" placeholder={`ចម្លើយទី ${i+1}`} />
                      <button onClick={() => setCorrect(i)} className={`w-8 h-8 rounded-lg flex items-center justify-center border-2 transition-all ${correct === i ? 'bg-green-500 border-green-500 text-white' : 'border-gray-100 text-gray-200'}`}>✓</button>
                    </div>
                  ))}
                </div>
              ) : (
                <textarea value={shortAnswer} onChange={(e) => setShortAnswer(e.target.value)} className="w-full px-6 py-4 rounded-2xl border border-gray-100 outline-none focus:ring-2 focus:ring-maroon small-kh bg-gray-50/50 min-h-[100px]" placeholder="បញ្ចូលចម្លើយត្រឹមត្រូវ..." />
              )}
            </div>
            <button onClick={handleSubmitSingle} className="w-full bg-maroon text-white font-black py-5 rounded-[2rem] shadow-xl hover:brightness-110 transition-all heading-kh text-lg">រក្សាទុកសំណួរ</button>
          </div>
        )}

        {entryMode === 'bulk' && (
          <div className="space-y-6 animate-fadeIn">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <input type="text" value={subject} onChange={(e) => setSubject(e.target.value)} className="w-full px-6 py-4 rounded-2xl border border-gray-100 outline-none focus:ring-2 focus:ring-maroon heading-kh bg-gray-50/50" placeholder="ឈ្មោះមុខវិជ្ជា..." />
              <div className="flex bg-gray-100 p-1 rounded-2xl"><button onClick={() => setBulkType('mcq')} className={`flex-1 rounded-xl text-[10px] font-black uppercase transition-all ${bulkType === 'mcq' ? 'bg-white text-blue-700 shadow-sm' : 'text-gray-400'}`}>QCM</button><button onClick={() => setBulkType('short')} className={`flex-1 rounded-xl text-[10px] font-black uppercase transition-all ${bulkType === 'short' ? 'bg-white text-orange-700 shadow-sm' : 'text-gray-400'}`}>Q & A</button></div>
            </div>
            <textarea value={bulkText} onChange={(e) => setBulkText(e.target.value)} className="w-full px-6 py-6 rounded-[2rem] border border-gray-100 min-h-[400px] small-kh text-xs bg-gray-50/50 outline-none focus:ring-2 focus:ring-maroon" placeholder="ចម្លងកម្រងសំណួរដាក់ទីនេះ (1. សំណួរ... ក. ចម្លើយ...)" />
            <button onClick={handleBulkSubmit} className="w-full bg-maroon text-white font-black py-5 rounded-[2rem] shadow-xl hover:brightness-110 transition-all heading-kh text-lg">ចាប់ផ្ដើមនាំចូល</button>
          </div>
        )}

        {entryMode === 'subjects' && (
          <div className="animate-fadeIn space-y-12">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {groupedSubjects.mcq.map((s, i) => <SubjectCard key={`m-${i}`} sub={s} isFirst={i === 0} isLast={i === groupedSubjects.mcq.length - 1} onToggleSubject={onToggleSubject} onEditSubject={() => {}} onRemoveSubject={onRemoveSubject} onReorderSubject={onReorderSubject} onOpenExport={(name, type, mode) => setViewingExport({name, type, mode})} />)}
              {groupedSubjects.short.map((s, i) => <SubjectCard key={`s-${i}`} sub={s} isFirst={i === 0} isLast={i === groupedSubjects.short.length - 1} onToggleSubject={onToggleSubject} onEditSubject={() => {}} onRemoveSubject={onRemoveSubject} onReorderSubject={onReorderSubject} onOpenExport={(name, type, mode) => setViewingExport({name, type, mode})} />)}
            </div>
          </div>
        )}

        {entryMode === 'feedback' && (
          <div className="animate-fadeIn space-y-8">
            <h2 className="text-2xl font-black heading-kh text-maroon flex items-center gap-3">💬 មតិយោបល់</h2>
            {feedbackList.length ? feedbackList.map(fb => (
              <div key={fb.id} className="glass-card rounded-[2rem] p-8 border border-gray-100 shadow-sm relative group">
                <div className="flex justify-between items-center mb-4">
                  <div className="flex items-center gap-4">
                    <div className="w-12 h-12 rounded-2xl bg-maroon/5 text-maroon flex items-center justify-center font-black">{(fb.username || 'A')[0]}</div>
                    <div><h4 className="font-black heading-kh text-maroon">{fb.username}</h4><p className="text-[10px] text-gray-400">{new Date(fb.createdAt).toLocaleString()}</p></div>
                  </div>
                  <button onClick={() => fb.id && onDeleteFeedback && onDeleteFeedback(fb.id)} className="p-2 text-red-500 hover:bg-red-50 rounded-lg">🗑️</button>
                </div>
                <p className="small-kh text-gray-700 leading-relaxed bg-white/50 p-6 rounded-2xl">{fb.text}</p>
              </div>
            )) : <div className="text-center py-20 text-gray-400">មិនមានមតិយោបល់</div>}
          </div>
        )}
      </div>

      {/* Export Modals */}
      {viewingExport && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-md z-[1000] flex items-center justify-center p-6 animate-fadeIn">
          <div className="bg-white rounded-[3rem] w-full max-w-2xl p-10 shadow-2xl relative max-h-[90vh] overflow-y-auto custom-scrollbar">
            <button onClick={() => setViewingExport(null)} className="absolute top-8 right-8 w-12 h-12 bg-gray-100 rounded-2xl flex items-center justify-center hover:bg-red-500 hover:text-white transition-all">✕</button>
            <h3 className="text-2xl font-black heading-kh text-maroon mb-8">នាំចេញវិញ្ញាសា៖ {viewingExport.name}</h3>

            {viewingExport.mode === 'telegram' && (
              <div className="space-y-6">
                <div className="flex flex-col md:flex-row gap-4">
                  <select value={tgConfig.chatId} onChange={e => setTgConfig({...tgConfig, chatId: e.target.value})} className="flex-1 px-6 py-4 rounded-2xl border border-gray-100 bg-gray-50/50 heading-kh text-sm">
                    {TG_CHANNELS.map(c => <option key={c.value} value={c.value}>{c.label}</option>)}
                  </select>
                  <button onClick={() => setSendAsImage(!sendAsImage)} className={`px-8 py-4 rounded-2xl border-2 transition-all font-black heading-kh text-[10px] uppercase ${sendAsImage ? 'bg-orange-500 border-orange-500 text-white' : 'bg-white border-gray-200 text-gray-400'}`}>
                    {sendAsImage ? '🖼️ ជារូបភាព' : '📝 ជាអត្ថបទ'}
                  </button>
                </div>
                <button onClick={handleSendAllTelegram} disabled={isProcessing !== false} className="w-full py-5 bg-blue-600 text-white rounded-[2rem] font-black heading-kh text-xl shadow-xl hover:brightness-110 disabled:opacity-50">
                  {isProcessing === 'all' ? 'កំពុងផ្ញើ...' : `ផ្ញើទាំង ${activeExportQuestions.length} សំណួរ ✈️`}
                </button>
                <div className="space-y-3 max-h-64 overflow-y-auto pr-2 custom-scrollbar">
                  {activeExportQuestions.map((q, idx) => (
                    <div key={idx} className="p-4 border rounded-2xl flex justify-between items-center bg-gray-50">
                      <p className="text-xs truncate max-w-[70%] small-kh">{q.question}</p>
                      <button onClick={() => handleSendToTelegram(q, idx)} disabled={isProcessing !== false} className="px-4 py-2 bg-blue-50 text-blue-600 rounded-lg text-[10px] font-bold">
                        {isProcessing === idx ? '...' : 'ផ្ញើឯកត្ត'}
                      </button>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {viewingExport.mode === 'pdf' && (
              <div className="space-y-6">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div className="space-y-2"><label className="text-[10px] font-black text-gray-400 ml-2">ឈ្មោះសាលា</label><input type="text" value={pdfSettings.schoolName} onChange={e => setPdfSettings({...pdfSettings, schoolName: e.target.value})} className="w-full px-6 py-3.5 rounded-2xl border border-gray-100 bg-gray-50/50 heading-kh text-sm" /></div>
                  <div className="space-y-2"><label className="text-[10px] font-black text-gray-400 ml-2">កាលបរិច្ឆេទ</label><input type="text" value={pdfSettings.examDate} onChange={e => setPdfSettings({...pdfSettings, examDate: e.target.value})} className="w-full px-6 py-3.5 rounded-2xl border border-gray-100 bg-gray-50/50 heading-kh text-sm" /></div>
                </div>
                <div className="flex flex-wrap gap-4">
                  <button onClick={() => setPdfSettings({...pdfSettings, showAnswerKey: !pdfSettings.showAnswerKey})} className={`flex-1 p-4 rounded-2xl border-2 transition-all font-black text-[10px] ${pdfSettings.showAnswerKey ? 'bg-maroon/5 border-maroon text-maroon' : 'border-gray-100 text-gray-400'}`}>គន្លឹះចម្លើយ</button>
                  <button onClick={() => setPdfSettings({...pdfSettings, shuffleQuestions: !pdfSettings.shuffleQuestions})} className={`flex-1 p-4 rounded-2xl border-2 transition-all font-black text-[10px] ${pdfSettings.shuffleQuestions ? 'bg-maroon/5 border-maroon text-maroon' : 'border-gray-100 text-gray-400'}`}>ច្របល់សំណួរ</button>
                </div>
                <button onClick={handleExportPdf} disabled={isProcessing !== false} className="w-full py-5 bg-indigo-600 text-white rounded-[2rem] font-black heading-kh text-xl shadow-xl hover:brightness-110 disabled:opacity-50">
                  {isProcessing === true ? 'កំពុងបង្កើត...' : 'ទាញយក PDF 📄'}
                </button>
              </div>
            )}

            {viewingExport.mode === 'image' && (
              <div className="space-y-6">
                <div className="grid grid-cols-4 gap-3">
                  {['modern', 'classic', 'elegant', 'dark'].map(s => (
                    <button key={s} onClick={() => setImageSettings({...imageSettings, style: s as any})} className={`py-3 rounded-xl border-2 font-black text-[10px] capitalize transition-all ${imageSettings.style === s ? 'bg-maroon/5 border-maroon text-maroon' : 'border-gray-100 text-gray-400'}`}>{s}</button>
                  ))}
                </div>
                <div className="space-y-2"><label className="text-[10px] font-black text-gray-400 ml-2">ឈ្មោះសម្គាល់លើរូបភាព</label><input type="text" value={imageSettings.brandName} onChange={e => setImageSettings({...imageSettings, brandName: e.target.value})} className="w-full px-6 py-3.5 rounded-2xl border border-gray-100 bg-gray-50/50 heading-kh text-sm" /></div>
                <button onClick={handleExportImageZip} disabled={isProcessing !== false} className="w-full py-5 bg-orange-600 text-white rounded-[2rem] font-black heading-kh text-xl shadow-xl hover:brightness-110 disabled:opacity-50">
                  {isProcessing === true ? 'កំពុងរៀបចំ...' : `ទាញយកទាំង ${activeExportQuestions.length} រូបភាព (ZIP) 🖼️`}
                </button>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

export default CreateSection;

import * as React from 'react';
import { useState, useMemo, useRef, useEffect } from 'react';
import { Question, TelegramConfig, Feedback } from '../types';
import { DEFAULT_TG_BOT_TOKEN, TG_CHANNELS } from '../constants';
import html2canvas from 'html2canvas';
import { sendQuizPoll, sendQuestionImage } from '../services/telegramService';

// ប្រកាស Global Variable សម្រាប់បណ្ណាល័យដែលបាននាំចូលក្នុង index.html
declare var html2pdf: any;
declare var JSZip: any;

interface CreateSectionProps {
  quizData: Question[];
  feedbackList?: Feedback[];
  onDeleteFeedback?: (id: string) => void;
  onAdd: (q: Question) => void;
  onUpdate: (index: number, q: Question) => void;
  onRemove: (index: number) => void;
  onToggleSubject: (subject: string, type: 'mcq' | 'short', active: boolean) => void;
  onUpdateSubject: (subject: string, type: 'mcq' | 'short', newName: string) => void;
  onRemoveSubject: (subject: string, type: 'mcq' | 'short') => void;
  onReorderSubject: (subject: string, type: 'mcq' | 'short', direction: 'up' | 'down') => void;
  onBatchAdd: (qs: Question[]) => void;
  onLogout: () => void;
}

interface PdfSettings { showAnswerKey: boolean; shuffleQuestions: boolean; schoolName: string; examDate: string; studentNameField: boolean; }
interface ImageSettings { style: 'modern' | 'classic' | 'elegant' | 'dark'; showBrand: boolean; brandName: string; }

// រចនាប័ទ្ម Font ខ្មែរដែលរឹងមាំបំផុតសម្រាប់ការ Capture (Fallback Strategy)
const KHMER_FONT_STACK = "'Kantumruy Pro', 'Khmer OS Battambang', 'Khmer OS', sans-serif";
const KHMER_SIEMREAP_STACK = "'Siemreap', 'Khmer OS Siemreap', 'Kantumruy Pro', sans-serif";
const KHMER_HEADING_STACK = "'Kantumruy Pro', 'Khmer OS Muol Light', serif";

const SubjectCard: React.FC<{
  sub: { name: string, isActive: boolean, count: number, type: 'mcq' | 'short' };
  isFirst: boolean;
  isLast: boolean;
  onToggleSubject: (subject: string, type: 'mcq' | 'short', active: boolean) => void;
  onEditSubject: (subject: string, type: 'mcq' | 'short') => void;
  onRemoveSubject: (subject: string, type: 'mcq' | 'short') => void;
  onReorderSubject: (subject: string, type: 'mcq' | 'short', direction: 'up' | 'down') => void;
  onOpenExport: (name: string, type: 'mcq' | 'short', mode: 'pdf' | 'image' | 'telegram') => void;
}> = ({ sub, isFirst, isLast, onToggleSubject, onEditSubject, onRemoveSubject, onReorderSubject, onOpenExport }) => (
  <div className={`group glass-card p-6 rounded-[2.5rem] border transition-all flex flex-col justify-between ${sub.isActive ? 'bg-white border-white shadow-xl' : 'bg-gray-100/50 border-gray-200 grayscale opacity-60'}`}>
    <div>
      <div className="flex justify-between items-start mb-4">
        <div className="flex-1 truncate pr-2">
          <div className="flex items-center gap-2 mb-2">
            <h3 className="text-lg font-black heading-kh text-maroon truncate cursor-pointer hover:underline" onClick={() => onOpenExport(sub.name, sub.type, 'telegram')}>{sub.name}</h3>
            <button onClick={() => onEditSubject(sub.name, sub.type)} className="p-1.5 bg-maroon/5 text-maroon rounded-lg hover:bg-maroon hover:text-white transition-all">✏️</button>
          </div>
          <div className="flex flex-wrap gap-2">
            <span className="text-[9px] font-black bg-blue-50 text-blue-600 px-3 py-1 rounded-full uppercase tracking-tighter">
              {sub.type === 'mcq' ? 'QCM' : 'Q & A'} ({sub.count})
            </span>
            <span className={`text-[9px] font-black px-3 py-1 rounded-full uppercase tracking-tighter ${sub.isActive ? 'bg-green-50 text-green-600' : 'bg-gray-200 text-gray-500'}`}>
              {sub.isActive ? 'Active' : 'Inactive'}
            </span>
          </div>
        </div>
        <div className="flex flex-col gap-1">
          <button disabled={isFirst} onClick={() => onReorderSubject(sub.name, sub.type, 'up')} className="w-8 h-8 flex items-center justify-center rounded-lg bg-white border border-gray-100 shadow-sm hover:bg-maroon hover:text-white disabled:opacity-20">🔼</button>
          <button disabled={isLast} onClick={() => onReorderSubject(sub.name, sub.type, 'down')} className="w-8 h-8 flex items-center justify-center rounded-lg bg-white border border-gray-100 shadow-sm hover:bg-maroon hover:text-white disabled:opacity-20">🔽</button>
        </div>
      </div>
    </div>

    <div className="grid grid-cols-2 gap-2 mt-4">
      <button onClick={() => onOpenExport(sub.name, sub.type, 'pdf')} className="py-2.5 bg-indigo-50 text-indigo-600 rounded-xl font-black text-[10px] hover:bg-indigo-600 hover:text-white transition-all flex items-center justify-center gap-1.5">📄 PDF</button>
      <button onClick={() => onOpenExport(sub.name, sub.type, 'image')} className="py-2.5 bg-orange-50 text-orange-600 rounded-xl font-black text-[10px] hover:bg-orange-600 hover:text-white transition-all flex items-center justify-center gap-1.5">🖼️ Image</button>
      <button onClick={() => onOpenExport(sub.name, sub.type, 'telegram')} className="col-span-2 py-3 bg-blue-600 text-white rounded-xl font-black text-[10px] hover:brightness-110 transition-all flex items-center justify-center gap-2">✈️ ផ្ញើទៅ Telegram</button>
      <div className="col-span-2 flex gap-2 pt-2">
        <button onClick={() => onToggleSubject(sub.name, sub.type, !sub.isActive)} className="flex-1 py-2 rounded-lg text-[9px] font-bold border border-gray-100 hover:bg-gray-50">{sub.isActive ? 'បិទដំណើរការ' : 'បើកដំណើរការ'}</button>
        <button onClick={() => onRemoveSubject(sub.name, sub.type)} className="p-2 bg-red-50 text-red-500 rounded-lg hover:bg-red-500 hover:text-white">🗑️</button>
      </div>
    </div>
  </div>
);

const CreateSection: React.FC<CreateSectionProps> = ({ 
  quizData, feedbackList = [], onDeleteFeedback, onAdd, onUpdate, onRemove, onToggleSubject, onUpdateSubject, onRemoveSubject, onReorderSubject, onBatchAdd
}) => {
  const KHMER_PREFIXES = ['ក', 'ខ', 'គ', 'ឃ'];
  const KHMER_DIGITS = ['០', '១', '២', '៣', '៤', '៥', '៦', '៧', '៨', '៩'];
  const [entryMode, setEntryMode] = useState<'single' | 'bulk' | 'subjects' | 'feedback'>('single');
  const [qType, setQType] = useState<'mcq' | 'short'>('mcq');
  const [bulkType, setBulkType] = useState<'mcq' | 'short'>('mcq');
  const [subject, setSubject] = useState('');
  const [question, setQuestion] = useState('');
  const [options, setOptions] = useState(['', '', '', '']);
  const [correct, setCorrect] = useState(0);
  const [shortAnswer, setShortAnswer] = useState('');
  const [editingIndex, setEditingIndex] = useState<number | null>(null);
  const [bulkText, setBulkText] = useState('');

  // Export & Telegram States
  const [viewingExport, setViewingExport] = useState<{name: string, type: 'mcq' | 'short', mode: 'pdf' | 'image' | 'telegram'} | null>(null);
  const [tgConfig, setTgConfig] = useState<TelegramConfig>({ botToken: DEFAULT_TG_BOT_TOKEN, chatId: TG_CHANNELS[0].value });
  const [sendAsImage, setSendAsImage] = useState(false);
  const [isProcessing, setIsProcessing] = useState<number | 'all' | boolean>(false);

  // Settings
  const [pdfSettings, setPdfSettings] = useState<PdfSettings>({ showAnswerKey: true, shuffleQuestions: false, schoolName: 'វិទ្យាស្ថានបណ្តុះបណ្តាលបច្ចេកទេស', examDate: 'ឆ្នាំសិក្សា ២០ graduation-២០២៥', studentNameField: true });
  const [imageSettings, setImageSettings] = useState<ImageSettings>({ style: 'elegant', showBrand: true, brandName: 'Master Quiz KH' });

  // Refs
  const imageTemplateRef = useRef<HTMLDivElement>(null);
  const pdfTemplateRef = useRef<HTMLDivElement>(null);
  const [previewQ, setPreviewQ] = useState<Question | null>(null);

  const toKhmerNumeral = (n: number) => n.toString().split('').map(digit => KHMER_DIGITS[parseInt(digit)] || digit).join('');

  const groupedSubjects = useMemo(() => {
    const getSubjectsByType = (type: 'mcq' | 'short') => {
      const seen = new Set<string>();
      const list: any[] = [];
      quizData.filter(q => q.type === type).forEach(q => {
        if (!seen.has(q.subject)) {
          seen.add(q.subject);
          const related = quizData.filter(rq => rq.subject === q.subject && rq.type === type);
          list.push({ name: q.subject, isActive: related.every(rq => rq.isActive !== false), count: related.length, type });
        }
      });
      return list;
    };
    return { mcq: getSubjectsByType('mcq'), short: getSubjectsByType('short') };
  }, [quizData]);

  const activeExportQuestions = useMemo(() => {
    if (!viewingExport) return [];
    let qs = quizData.filter(q => q.subject === viewingExport.name && q.type === viewingExport.type);
    if (viewingExport.mode === 'pdf' && pdfSettings.shuffleQuestions) {
      qs = [...qs].sort(() => Math.random() - 0.5);
    }
    return qs;
  }, [quizData, viewingExport, pdfSettings.shuffleQuestions]);

  // Export Logic: PDF
  const handleExportPdf = async () => {
    if (!pdfTemplateRef.current || !viewingExport) return;
    setIsProcessing(true);
    try {
      const opt = {
        margin: 10,
        filename: `Exam_${viewingExport.name}_${new Date().getTime()}.pdf`,
        image: { type: 'jpeg', quality: 0.98 },
        html2canvas: { scale: 2, useCORS: true },
        jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' }
      };
      await html2pdf().from(pdfTemplateRef.current).set(opt).save();
    } catch (e) {
      alert("កំហុសក្នុងការបង្កើត PDF");
    } finally {
      setIsProcessing(false);
    }
  };

  /**
   * មុខងារ Capture រូបភាពដែលមានស្ថេរភាពបំផុត និងការពារបញ្ហាលោត Font
   */
  const captureImage = async (): Promise<Blob | null> => {
    if (!imageTemplateRef.current) return null;

    // ជំហានទី១៖ រង់ចាំឱ្យ Font Load សព្វគ្រប់ ១០០% ក្នុង Browser
    await document.fonts.ready;

    // ជំហានទី២៖ បន្ថែម Delay បន្តិចទៀតដើម្បីឱ្យ Layout របស់ Chrome/Safari ស្ងប់ស្ងាត់ (Stabilize)
    await new Promise(r => setTimeout(r, 1200)); 

    try {
      const canvas = await html2canvas(imageTemplateRef.current, {
        scale: 3, // កម្រិតច្បាស់ខ្ពស់
        useCORS: true,
        allowTaint: true,
        backgroundColor: imageSettings.style === 'dark' ? '#121212' : '#ffffff',
        logging: false,
        onclone: (clonedDoc) => {
          // ជំហានទី៣៖ "CSS Injection" - បង្ខំបញ្ចូល Font Definition ទៅក្នុង Cloned Document
          const head = clonedDoc.head;
          const style = clonedDoc.createElement('style');
          style.innerHTML = `
            @import url('https://fonts.googleapis.com/css2?family=Kantumruy+Pro:wght@400;700&family=Siemreap&display=swap');
            * { -webkit-font-smoothing: antialiased; -moz-osx-font-smoothing: grayscale; }
            .subject-label-capture { font-family: ${KHMER_SIEMREAP_STACK} !important; font-weight: bold !important; line-height: 2 !important; }
            .question-text-capture { font-family: ${KHMER_FONT_STACK} !important; line-height: 2.2 !important; }
            .option-text-capture { font-family: ${KHMER_FONT_STACK} !important; line-height: 1.8 !important; }
          `;
          head.appendChild(style);

          // ជំហានទី៤៖ បង្ខំ Styles ទៅលើ Element នីមួយៗម្ដងទៀត
          const template = clonedDoc.getElementById('image-export-template');
          if (template) {
            template.style.visibility = 'visible';
            template.style.display = 'block';

            // បង្ខំ Font ខ្មែរ Siemreap សម្រាប់ផ្នែក "វិញ្ញាសា" (ដែលពេលនេះនៅផ្នែកខាងក្រោម)
            const subjectLabel = template.querySelector('.subject-label-capture') as HTMLElement;
            if (subjectLabel) {
              subjectLabel.style.fontFamily = KHMER_SIEMREAP_STACK;
              subjectLabel.style.fontSize = '24px';
              subjectLabel.style.display = 'inline-block';
              subjectLabel.style.padding = '5px 15px';
            }
          }
        }
      });

      return new Promise<Blob | null>(r => canvas.toBlob(r, 'image/png', 1.0));
    } catch (e) {
      console.error("Capture Error:", e);
      return null;
    }
  };

  // Export Logic: Image ZIP
  const handleExportImageZip = async () => {
    if (!viewingExport) return;
    setIsProcessing(true);
    const zip = new JSZip();
    try {
      for (let i = 0; i < activeExportQuestions.length; i++) {
        const q = activeExportQuestions[i];
        setPreviewQ(q);
        const blob = await captureImage();
        if (blob) zip.file(`Question_${i+1}.png`, blob);
      }
      const content = await zip.generateAsync({ type: "blob" });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(content);
      link.download = `Images_${viewingExport.name}.zip`;
      link.click();
    } catch (e) {
      alert("កំហុសក្នុងការបង្កើតរូបភាព ZIP");
    } finally {
      setPreviewQ(null);
      setIsProcessing(false);
    }
  };

  // Telegram Logic
  const handleSendToTelegram = async (q: Question, index: number | 'all') => {
    setIsProcessing(index);
    try {
      if (sendAsImage) {
        setPreviewQ(q);
        const blob = await captureImage();
        if (blob) {
          const caption = `📌 ${q.question.substring(0, 150)}...\n\nវិញ្ញាសា៖ ${q.subject}\n#QuizMasterKH 🇰🇭`;
          await sendQuestionImage(tgConfig, blob, caption);
        }
      } else {
        if (q.type === 'mcq') {
          await sendQuizPoll(tgConfig, q);
        } else {
          const text = `📌 *សំណួរ៖* ${q.question}\n\n✅ *ចម្លើយ៖* ${q.answer}\n\nវិញ្ញាសា៖ ${q.subject}\nWeb QCM 🇰🇭`;
          await fetch(`https://api.telegram.org/bot${tgConfig.botToken}/sendMessage`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ chat_id: tgConfig.chatId, text, parse_mode: 'Markdown' })
          });
        }
      }
    } catch (e) {
      console.error(e);
    } finally {
      if (index !== 'all') {
        setIsProcessing(false);
        setPreviewQ(null);
      }
    }
  };

  const handleSendAllTelegram = async () => {
    if (!confirm(`តើអ្នកចង់ផ្ញើទាំង ${activeExportQuestions.length} សំណួរទៅកាន់ Telegram មែនទេ?`)) return;
    setIsProcessing('all');
    for (let i = 0; i < activeExportQuestions.length; i++) {
      await handleSendToTelegram(activeExportQuestions[i], i);
      await new Promise(r => setTimeout(r, sendAsImage ? 5000 : 2000));
    }
    setIsProcessing(false);
    setPreviewQ(null);
    alert("បានផ្ញើរួចរាល់!");
  };

  const handleSubmitSingle = () => {
    if (!subject.trim() || !question.trim()) return alert("សូមបំពេញព័ត៌មាន!");
    const cleanQ: Question = {
      subject: subject.trim(),
      question: question.trim(),
      type: qType,
      isActive: true,
      ...(qType === 'mcq' ? { options: options.map(o => o.trim()), correct } : { answer: shortAnswer.trim() })
    };
    if (editingIndex !== null) onUpdate(editingIndex, cleanQ); else onAdd(cleanQ);
    setQuestion(''); setOptions(['', '', '', '']); setShortAnswer(''); setEditingIndex(null);
  };

  const handleBulkSubmit = () => {
    if (!subject.trim() || !bulkText.trim()) return alert("សូមបំពេញព័ត៌មាន!");
    const lines = bulkText.split('\n');
    const parsed: Question[] = [];
    let current: any = null;
    let iA = false;

    if (bulkType === 'mcq') {
      lines.forEach(l => {
        const t = l.trim(); if (!t) return;
        const qm = t.match(/^[០-៩0-9]+\.\s*(.*)/);
        if (qm) {
          if (current && current.options?.length >= 2) parsed.push(current);
          current = { type: 'mcq', subject: subject.trim(), question: qm[1].trim(), options: [], correct: 0, isActive: true };
          return;
        }
        const om = t.match(/^[កខគឃ]\.\s*(.*)/);
        if (om && current) {
          let txt = om[1].replace('(ចម្លើយត្រឹមត្រូវ)', '').trim();
          current.options.push(txt);
          if (om[1].includes('(ចម្លើយត្រឹមត្រូវ)')) current.correct = current.options.length - 1;
        }
      });
      if (current && current.options?.length >= 2) parsed.push(current);
    } else {
      lines.forEach(l => {
        const t = l.trim();
        const qm = t.match(/^[០-៩0-9]+\.\s*(.*)/);
        if (qm) {
          if (current && current.answer) parsed.push(current);
          current = { type: 'short', subject: subject.trim(), question: qm[1].trim(), answer: '', isActive: true };
          iA = false; return;
        }
        const am = t.match(/^ចម្លើយ\s*[៖:]\s*(.*)/);
        if (am && current) { current.answer = am[1].trim(); iA = true; return; }
        if (iA && current) current.answer += (current.answer ? '\n' : '') + l;
      });
      if (current && current.answer) parsed.push(current);
    }
    if (parsed.length) { onBatchAdd(parsed); setBulkText(''); alert(`បានបញ្ចូល ${parsed.length} សំណួរ!`); }
  };

  return (
    <div className="space-y-8 animate-fadeIn pb-32">
      {/* Hidden Templates for Export */}
      <div className="fixed -left-[8000px] top-0 overflow-hidden select-none pointer-events-none">
        {/* Image Design - ផ្លាស់ទីផ្នែកវិញ្ញាសាទៅខាងក្រោម */}
        <div 
          id="image-export-template"
          ref={imageTemplateRef} 
          className={`w-[700px] p-16 border-[14px] border-maroon relative ${imageSettings.style === 'dark' ? 'bg-[#121212] text-white' : 'bg-white text-black'}`}
          style={{ fontFamily: KHMER_FONT_STACK, minHeight: '800px' }}
        >
          {/* Header - បង្ហាញតែឈ្មោះសម្គាល់ */}
          <div className="text-center mb-12 border-b-4 border-maroon pb-10">
            <h1 className="brand-name-capture font-black mb-2 text-4xl" style={{ fontFamily: KHMER_HEADING_STACK }}>
              {imageSettings.showBrand ? imageSettings.brandName : 'Master Quiz'}
            </h1>
          </div>

          {/* Body - បង្ហាញសំណួរ និងចម្លើយ */}
          <div className="space-y-12">
            <h2 className="question-text-capture text-3xl leading-[2.2] font-bold text-justify" style={{ fontFamily: KHMER_FONT_STACK }}>
              {previewQ?.question}
            </h2>

            {previewQ?.type === 'mcq' ? (
              <div className="grid grid-cols-1 gap-6 mt-10">
                {previewQ.options?.map((opt, i) => (
                  <div key={i} className={`flex items-center gap-8 p-8 rounded-[2.5rem] border-2 ${imageSettings.style === 'dark' ? 'bg-white/5 border-white/10' : 'bg-gray-50 border-gray-100'}`}>
                    <span className="w-16 h-16 flex items-center justify-center bg-maroon text-white rounded-2xl font-black text-3xl shrink-0">{KHMER_PREFIXES[i]}</span>
                    <span className="option-text-capture text-2xl font-bold leading-[1.8]" style={{ fontFamily: KHMER_FONT_STACK }}>{opt}</span>
                  </div>
                ))}
              </div>
            ) : (
              <div className={`mt-10 p-12 border-l-[20px] border-green-500 rounded-r-[4rem] ${imageSettings.style === 'dark' ? 'bg-green-500/10' : 'bg-green-50'}`}>
                <p className="font-black mb-6 text-2xl text-green-700" style={{ fontFamily: KHMER_FONT_STACK }}>✅ ចម្លើយត្រឹមត្រូវ ៖</p>
                <p className="text-2xl leading-[2.2] font-bold whitespace-pre-wrap text-justify" style={{ fontFamily: KHMER_FONT_STACK }}>{previewQ?.answer}</p>
              </div>
            )}
          </div>

          {/* Bottom Section - ផ្នែកវិញ្ញាសា (យកមកដាក់ទីនេះវិញ) */}
          <div className="mt-20 text-center">
            <div className="flex justify-center items-center gap-6 h-12 overflow-hidden">
              <span className="w-16 h-[4px] bg-maroon shrink-0 opacity-30"></span>
              <p className="subject-label-capture text-2xl uppercase font-bold tracking-widest text-maroon whitespace-nowrap" 
                 style={{ 
                   fontFamily: KHMER_SIEMREAP_STACK,
                   textRendering: 'optimizeLegibility',
                   WebkitFontSmoothing: 'antialiased'
                 }}>
                វិញ្ញាសា៖ {previewQ?.subject}
              </p>
              <span className="w-16 h-[4px] bg-maroon shrink-0 opacity-30"></span>
            </div>
          </div>

          {/* Footer - ឈ្មោះប្រព័ន្ធ */}
          <div className="mt-12 text-center pt-8 border-t-2 border-maroon/10 opacity-50">
            <p className="text-lg font-black text-maroon" style={{ fontFamily: KHMER_FONT_STACK }}>បង្កើតដោយប្រព័ន្ធ Web QCM 🇰🇭</p>
          </div>
        </div>

        {/* PDF Design */}
        <div ref={pdfTemplateRef} className="w-[210mm] min-h-[297mm] p-[25mm] bg-white text-black leading-normal" style={{ fontFamily: KHMER_FONT_STACK }}>
          <div className="text-center mb-12">
            <h2 className="heading-kh text-[16pt] font-bold mb-1">ព្រះរាជាណាចក្រកម្ពុជា</h2>
            <h3 className="heading-kh text-[14pt] font-bold mb-2">ជាតិ សាសនា ព្រះមហាក្សត្រ</h3>
            <div className="flex justify-center mb-6"><div className="w-24 h-[1.5px] bg-black"></div></div>
            <div className="flex justify-between items-start mb-8 border-b-2 border-black pb-4 text-left">
              <div className="heading-kh">
                <p className="font-bold text-[14pt]">{pdfSettings.schoolName}</p>
                <p className="text-[12pt]">មុខវិជ្ជា៖ {viewingExport?.name}</p>
              </div>
              <div className="text-right small-kh italic text-[10pt]">
                <p>{pdfSettings.examDate}</p>
                <p>រយៈពេល៖ ៦០ នាទី</p>
              </div>
            </div>
          </div>
          {pdfSettings.studentNameField && (
            <div className="mb-10 grid grid-cols-2 gap-10 small-kh border p-4 rounded-lg">
              <p>ឈ្មោះសិស្ស៖ ......................................................</p>
              <p>លេខតុ៖ ....................... លេខបន្ទប់៖ ...............</p>
            </div>
          )}
          <div className="space-y-10">
            {activeExportQuestions.map((q, idx) => (
              <div key={idx} className="break-inside-avoid">
                <p className="heading-kh font-bold text-[13pt] leading-[1.8] mb-4 text-justify">
                  <span className="mr-3">{toKhmerNumeral(idx + 1)}.</span>{q.question}
                </p>
                {q.type === 'mcq' ? (
                  <div className="grid grid-cols-2 gap-x-12 gap-y-3 ml-12">
                    {q.options?.map((opt, i) => (
                      <div key={i} className="flex gap-4 items-start small-kh text-[12pt]">
                        <span className="font-bold">{KHMER_PREFIXES[i]}.</span>
                        <span>{opt}</span>
                      </div>
                    ))}
