                  <button onClick={() => setPdfSettings({...pdfSettings, shuffleQuestions: !pdfSettings.shuffleQuestions})} className={`flex-1 p-4 rounded-2xl border-2 transition-all font-black text-[10px] ${pdfSettings.shuffleQuestions ? 'bg-maroon/5 border-maroon text-maroon' : 'border-gray-100 text-gray-400'}`}>ច្របល់សំណួរ</button>
                </div>
                <button onClick={handleExportPdf} disabled={isProcessing !== false} className="w-full py-5 bg-indigo-600 text-white rounded-[2rem] font-black heading-kh text-xl shadow-xl hover:brightness-110 disabled:opacity-50">
                  {isProcessing === true ? 'កំពុងបង្កើត...' : 'ទាញយក PDF 📄'}
                </button>
              </div>
            )}

            {viewingExport.mode === 'image' && (
              <div className="space-y-6">
                <div className="grid grid-cols-4 gap-3">
                  {['modern', 'classic', 'elegant', 'dark'].map(s => (
                    <button key={s} onClick={() => setImageSettings({...imageSettings, style: s as any})} className={`py-3 rounded-xl border-2 font-black text-[10px] capitalize transition-all ${imageSettings.style === s ? 'bg-maroon/5 border-maroon text-maroon' : 'border-gray-100 text-gray-400'}`}>{s}</button>
                  ))}
                </div>
                <div className="space-y-2"><label className="text-[10px] font-black text-gray-400 ml-2">ឈ្មោះសម្គាល់លើរូបភាព</label><input type="text" value={imageSettings.brandName} onChange={e => setImageSettings({...imageSettings, brandName: e.target.value})} className="w-full px-6 py-3.5 rounded-2xl border border-gray-100 bg-gray-50/50 heading-kh text-sm" /></div>
                <button onClick={handleExportImageZip} disabled={isProcessing !== false} className="w-full py-5 bg-orange-600 text-white rounded-[2rem] font-black heading-kh text-xl shadow-xl hover:brightness-110 disabled:opacity-50">
                  {isProcessing === true ? 'កំពុងរៀបចំ...' : `ទាញយកទាំង ${activeExportQuestions.length} រូបភាព (ZIP) 🖼️`}
                </button>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

