        {entryMode === 'feedback' && (
          <div className="animate-fadeIn space-y-8">
            <h2 className="text-2xl font-black heading-kh text-maroon flex items-center gap-3">💬 មតិយោបល់</h2>
            {feedbackList.length ? feedbackList.map(fb => (
