                    <div key={i} className="flex items-center gap-3 bg-white p-4 rounded-2xl border border-gray-100 shadow-sm focus-within:border-maroon/30">
                      <span className="font-black text-maroon w-10 h-10 flex items-center justify-center bg-maroon/5 rounded-xl">{KHMER_PREFIXES[i]}</span>
                      <input type="text" value={opt} onChange={(e) => { const n = [...options]; n[i] = e.target.value; setOptions(n); }} className="flex-1 outline-none small-kh text-sm" placeholder={`ចម្លើយទី ${i+1}`} />
                      <button onClick={() => setCorrect(i)} className={`w-8 h-8 rounded-lg flex items-center justify-center border-2 transition-all ${correct === i ? 'bg-green-500 border-green-500 text-white' : 'border-gray-100 text-gray-200'}`}>✓</button>
