              {groupedSubjects.short.map((s, i) => <SubjectCard key={`s-${i}`} sub={s} isFirst={i === 0} isLast={i === groupedSubjects.short.length - 1} onToggleSubject={onToggleSubject} onEditSubject={() => {}} onRemoveSubject={onRemoveSubject} onReorderSubject={onReorderSubject} onOpenExport={(name, type, mode) => setViewingExport({name, type, mode})} />)}
