      </div>

      <div className="flex flex-wrap justify-center items-center gap-4 mb-10 w-full max-w-3xl px-4">
        <div className="group flex items-center gap-3 bg-white/10 backdrop-blur-xl px-6 py-3 rounded-2xl border border-white/20 shadow-2xl transition-all hover:bg-white/20">
          <span className="text-white/60 text-[10px] font-black uppercase tracking-[0.2em] small-kh">ទិន្នន័យសរុប</span>
          <div className="h-6 w-px bg-white/20"></div>
          <span className="text-xl font-black text-white">{totalQuestions} <span className="text-xs text-gold-light ml-1">សំណួរ</span></span>
        </div>

        <button 
          onClick={onLogout}
          className="flex items-center gap-2 text-xs font-bold bg-white/5 hover:bg-red-500/20 text-white/80 hover:text-white backdrop-blur-md px-6 py-3.5 rounded-2xl border border-white/10 transition-all duration-300 active:scale-95 small-kh"
        >
          <span>ចាកចេញពីប្រព័ន្ធ</span>
          <span className="opacity-60 text-lg">🚪</span>
        </button>
      </div>

      {role === 'admin' && (
        <div className="inline-flex p-1.5 bg-black/40 backdrop-blur-2xl rounded-3xl border border-white/10 shadow-3xl">
          <button 
            onClick={() => setMode('play')}
            className={`px-8 py-3.5 rounded-2xl font-black transition-all text-sm heading-kh ${
              mode === 'play' 
              ? 'bg-gradient-to-br from-white to-gray-200 text-maroon shadow-xl transform scale-105' 
              : 'text-white/40 hover:text-white hover:bg-white/5'
            }`}
          >
            📊 តេស្តសមត្ថភាព
          </button>
          <button 
            onClick={() => setMode('create')}
            className={`px-8 py-3.5 rounded-2xl font-black transition-all text-sm heading-kh ${
              mode === 'create' 
              ? 'bg-gradient-to-br from-white to-gray-200 text-maroon shadow-xl transform scale-105' 
              : 'text-white/40 hover:text-white hover:bg-white/5'
            }`}
          >
            ⚙️ គ្រប់គ្រងសំណួរ
          </button>
        </div>
      )}
    </div>
  );
};

export default Header;

import * as React from 'react';
import { useState } from 'react';
import { UserRole } from '../types';
import { ADMIN_CONTACTS, SECRET_CODE } from '../constants';

interface AuthSectionProps {
  onLogin: (role: UserRole, username?: string) => void;
  secretCode: string;
}

const AuthSection: React.FC<AuthSectionProps> = ({ onLogin, secretCode }) => {
  const [view, setView] = useState<'main' | 'user_login' | 'admin_login'>('main');
  const [userInput, setUserInput] = useState('');
  const [passInput, setPassInput] = useState('');

  const handleAdminVerify = () => {
    if (passInput === SECRET_CODE) {
      onLogin('admin', 'Administrator');
    } else {
      alert("លេខកូដសម្ងាត់អ្នកគ្រប់គ្រងមិនត្រឹមត្រូវ!");
    }
  };

  const handleUserVerify = () => {
    const trimmedUser = userInput.trim();
    if (!trimmedUser) return alert("សូមបញ្ចូល Username!");
    const isValidPassword = passInput.length === 6 && passInput.startsWith('20') && passInput.endsWith('26');

    if (isValidPassword) {
      onLogin('user', trimmedUser);
    } else {
      alert("Password មិនត្រឹមត្រូវ!");
    }
  };

  return (
    <div className="page-transition relative">
      {view === 'main' && (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
          {/* User Card */}
          <div className="glass-card p-10 rounded-[2.5rem] border-white/40 shadow-3xl flex flex-col items-center text-center group relative overflow-hidden">
            <div className="absolute top-0 right-0 w-32 h-32 bg-indigo-500/10 rounded-full -mr-16 -mt-16 blur-3xl group-hover:bg-indigo-500/20 transition-all"></div>
            <div className="w-20 h-20 bg-indigo-50 rounded-[2rem] flex items-center justify-center text-5xl mb-8 group-hover:scale-110 transition-transform shadow-inner">👨‍🎓</div>
            <h2 className="text-3xl font-black heading-kh text-indigo-900 mb-2">សមាជិក</h2>
            <p className="text-sm small-kh text-indigo-900/40 mb-8">សម្រាប់សិស្ស-និស្សិត ចូលធ្វើតេស្ត</p>
            <div className="space-y-4 w-full">
              <button 
                onClick={() => setView('user_login')} 
                className="w-full py-5 bg-indigo-600 text-white rounded-3xl font-black heading-kh text-base shadow-xl hover:bg-indigo-700 transition-all active:scale-95"
              >
                🔐 ចូលទៅកាន់វិញ្ញាសា
              </button>
              <div className="grid grid-cols-2 gap-3 mt-4">
                <a href={ADMIN_CONTACTS.admin1} target="_blank" className="py-4 bg-blue-50 text-blue-700 rounded-2xl font-black heading-kh text-[11px] shadow-sm hover:bg-blue-600 hover:text-white transition-all text-center">📱 អ្នកគ្រប់គ្រង</a>
                <a href={ADMIN_CONTACTS.admin2} target="_blank" className="py-4 bg-blue-50 text-blue-700 rounded-2xl font-black heading-kh text-[11px] shadow-sm hover:bg-blue-600 hover:text-white transition-all text-center">📱 Master Quiz</a>
              </div>
            </div>
          </div>

          {/* Admin Card */}
          <div 
            onClick={() => setView('admin_login')} 
            className="glass-card p-10 rounded-[2.5rem] border-white/40 shadow-3xl flex flex-col items-center text-center hover:bg-maroon/5 transition-all group cursor-pointer"
          >
            <div className="w-20 h-20 bg-maroon/5 rounded-[2rem] flex items-center justify-center text-5xl mb-8 group-hover:rotate-12 transition-transform shadow-inner">⚙️</div>
            <h2 className="text-3xl font-black heading-kh text-maroon mb-2">Admin</h2>
            <p className="text-sm small-kh text-maroon/40 mb-10">សម្រាប់រៀបចំ និងគ្រប់គ្រងសំណួរ</p>
            <div className="mt-auto w-full py-5 border-2 border-maroon/10 rounded-3xl text-maroon font-black heading-kh text-base group-hover:bg-maroon group-hover:text-white transition-all">
              ចូលផ្ទាំងគ្រប់គ្រង
            </div>
          </div>
        </div>
      )}

      {(view === 'user_login' || view === 'admin_login') && (
        <div className="glass-card rounded-[3.5rem] shadow-3xl p-10 md:p-14 text-center border-white/60 page-transition relative max-w-xl mx-auto">
          <button 
            onClick={() => { setView('main'); setUserInput(''); setPassInput(''); }}
            className="absolute top-8 left-8 w-12 h-12 flex items-center justify-center bg-gray-100 rounded-2xl hover:bg-maroon hover:text-white transition-all shadow-sm"
          >
            ←
          </button>

          <div className="w-24 h-24 bg-maroon/5 rounded-[2.5rem] flex items-center justify-center text-6xl mx-auto mb-8 shadow-inner">
            {view === 'user_login' ? '🔑' : '🔒'}
          </div>
          <h2 className={`text-3xl font-black heading-kh mb-2 ${view === 'user_login' ? 'text-indigo-900' : 'text-maroon'}`}>
            {view === 'user_login' ? 'ចូលជាសមាជិក' : 'ចូលជា Admin'}
          </h2>
          <p className="text-sm small-kh text-gray-400 mb-10">សូមបំពេញព័ត៌មានសម្ងាត់របស់អ្នក</p>

          <div className="space-y-6 mb-10 text-left">
            {view === 'user_login' && (
              <div>
                <label className="text-[10px] font-black uppercase text-gray-400 ml-4 mb-2 block tracking-widest">Username</label>
                <input 
                  type="text" 
                  value={userInput} 
                  onChange={(e) => setUserInput(e.target.value)} 
                  className="w-full px-8 py-5 rounded-3xl border-2 border-transparent bg-gray-100 outline-none focus:bg-white focus:border-indigo-500 transition-all font-bold text-indigo-900" 
                  placeholder="ឈ្មោះសមាជិក" 
                />
              </div>
            )}
            <div>
              <label className="text-[10px] font-black uppercase text-gray-400 ml-4 mb-2 block tracking-widest">
                {view === 'user_login' ? 'Password (៦ខ្ទង់)' : 'លេខកូដសម្ងាត់'}
              </label>
              <input 
                type={view === 'user_login' ? 'text' : 'password'} 
                inputMode={view === 'user_login' ? 'numeric' : 'text'}
                value={passInput} 
                onChange={(e) => setPassInput(view === 'user_login' ? e.target.value.replace(/\D/g, '').slice(0, 6) : e.target.value)} 
                className={`w-full px-8 py-5 rounded-3xl border-2 border-transparent bg-gray-100 outline-none transition-all font-bold ${view === 'admin_login' ? 'text-center tracking-[1em] text-maroon' : 'text-indigo-900'}`} 
                placeholder={view === 'user_login' ? "••••••" : "••••"}
                onKeyDown={(e) => e.key === 'Enter' && (view === 'user_login' ? handleUserVerify() : handleAdminVerify())} 
              />
            </div>
          </div>

          <button 
            onClick={view === 'user_login' ? handleUserVerify : handleAdminVerify} 
            className={`w-full text-white font-black py-5 rounded-3xl shadow-2xl hover:brightness-110 active:scale-95 transition-all heading-kh text-xl ${view === 'user_login' ? 'bg-indigo-600' : 'bg-maroon'}`}
          >
            បញ្ជាក់ការចូលប្រព័ន្ធ
