        </div>
      )}
    </div>
  );
};

export default AuthSection;

import * as React from 'react';
import { useState, useMemo } from 'react';
import { Question } from '../types';
import { ADMIN_CONTACTS } from '../constants';
import { sendFeedback } from '../services/firebaseService';

interface PlaySectionProps {
  username: string;
  quizData: Question[];
  onStartQuiz: (subject: string, partIndex: number, type: 'mcq' | 'short', customQuestions?: Question[], isMixed?: boolean) => void;
}

const PlaySection: React.FC<PlaySectionProps> = ({ username, quizData, onStartQuiz }) => {
  const [selectedSubject, setSelectedSubject] = useState<string | null>(null);
  const [activeType, setActiveType] = useState<'mcq' | 'short'>('mcq');
  const [searchQuery, setSearchQuery] = useState('');
  const [viewingFullDoc, setViewingFullDoc] = useState<{name: string, type: string, questions: Question[]} | null>(null);
  const [playMode, setPlayMode] = useState<'by-subject' | 'mixed'>('by-subject');
  const [selectedMixSubjects, setSelectedMixSubjects] = useState<string[]>([]);
  const [mixCount, setMixCount] = useState<number>(20);

  const [showFeedbackModal, setShowFeedbackModal] = useState(false);
  const [feedbackText, setFeedbackText] = useState('');
  const [isSendingFeedback, setIsSendingFeedback] = useState(false);

  const KHMER_DIGITS = ['០', '១', '២', '៣', '៤', '៥', '៦', '៧', '៨', '៩'];
  const KHMER_PREFIXES = ['ក', 'ខ', 'គ', 'ឃ'];

  const toKhmerNumeral = (n: number) => n.toString().split('').map(digit => KHMER_DIGITS[parseInt(digit)] || digit).join('');

  const activeQuestions = quizData.filter((q: Question) => q.isActive !== false);
  const subjects: string[] = Array.from(new Set(activeQuestions.filter(q => q.type === activeType).map((item: Question) => item.subject)));

  const handleSendFeedback = async () => {
    if (!feedbackText.trim()) return;
    setIsSendingFeedback(true);
    await sendFeedback(username || 'Anonymous', feedbackText);
    setIsSendingFeedback(false);
    setFeedbackText('');
    setShowFeedbackModal(false);
    alert("សូមអរគុណ! មតិយោបល់របស់អ្នកត្រូវបានផ្ញើរួចរាល់។");
  };

  const handleToggleMixSubject = (sub: string) => {
    setSelectedMixSubjects(prev => prev.includes(sub) ? prev.filter(s => s !== sub) : [...prev, sub]);
  };

  const handleStartMixedTest = () => {
    if (selectedMixSubjects.length === 0) return alert("សូមជ្រើសរើសមុខវិជ្ជាយ៉ាងហោចណាស់មួយ!");
    let pool = activeQuestions.filter(q => q.type === activeType && selectedMixSubjects.includes(q.subject));
    const shuffled = [...pool].sort(() => Math.random() - 0.5);
    onStartQuiz("តេស្តចម្រុះ", 0, activeType, shuffled.slice(0, mixCount), true);
  };

  const handleViewFullDoc = (subjectName: string) => {
    const questions = activeQuestions.filter(q => q.subject === subjectName && q.type === activeType);
    if (questions.length === 0) return alert("មិនមានសំណួរក្នុងមុខវិជ្ជានេះឡើយ!");
    setViewingFullDoc({ name: subjectName, type: activeType, questions });
  };

  const searchResults = useMemo(() => {
    if (!searchQuery.trim()) return [];
    return activeQuestions.filter(q => q.type === activeType && q.question.toLowerCase().includes(searchQuery.toLowerCase()));
  }, [activeQuestions, searchQuery, activeType]);

  if (selectedSubject) {
    const subjectQuestions = activeQuestions.filter((q: Question) => q.subject === selectedSubject && q.type === activeType);
    const totalQuestions = subjectQuestions.length;
    const totalParts = Math.ceil(totalQuestions / 10);

    return (
      <div className="page-transition space-y-8">
        <div className="glass-card p-10 rounded-[3.5rem] flex flex-col md:flex-row items-center gap-8 mb-8 border-white/60 shadow-3xl overflow-hidden relative">
          <div className="absolute top-0 right-0 w-64 h-64 bg-maroon/5 rounded-full -mr-32 -mt-32 blur-3xl"></div>
          <button onClick={() => setSelectedSubject(null)} className="w-16 h-16 bg-maroon/5 hover:bg-maroon hover:text-white rounded-[1.5rem] transition-all flex items-center justify-center shrink-0 shadow-inner">
            <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M15 19l-7-7 7-7" /></svg>
          </button>
          <div className="text-center md:text-left flex-1 relative z-10">
            <h2 className="text-4xl font-black heading-kh text-maroon mb-2">{selectedSubject}</h2>
            <div className="flex flex-wrap justify-center md:justify-start gap-3">
              <span className="px-5 py-2 bg-maroon text-white rounded-full text-[10px] font-black uppercase tracking-widest">{activeType === 'mcq' ? 'QCM' : 'Q & A'}</span>
              <span className="px-5 py-2 bg-maroon/10 text-maroon rounded-full text-[10px] font-black uppercase tracking-widest">សរុប៖ {toKhmerNumeral(totalQuestions)} សំណួរ</span>
            </div>
          </div>
          <button onClick={() => handleViewFullDoc(selectedSubject)} className="px-8 py-4 bg-white border-2 border-maroon text-maroon rounded-2xl font-black heading-kh text-sm shadow-xl hover:bg-maroon hover:text-white transition-all">📖 មើលវិញ្ញាសាទាំងស្រុង</button>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
          {Array.from({ length: totalParts }).map((_, i) => (
            <button key={i} onClick={() => onStartQuiz(selectedSubject, i, activeType)} className="glass-card p-10 rounded-[2.5rem] text-left transition-all active:scale-95 group shadow-xl border-white/60 hover:bg-white relative overflow-hidden">
              <div className="absolute bottom-0 right-0 w-24 h-24 bg-maroon/5 rounded-full -mb-12 -mr-12 group-hover:scale-150 transition-transform"></div>
              <div className="flex justify-between items-center relative z-10">
                <div>
                  <div className="flex items-center gap-3 mb-3">
                    <span className="w-12 h-12 bg-maroon/10 text-maroon rounded-xl flex items-center justify-center font-black text-xl">{toKhmerNumeral(i + 1)}</span>
                    <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest">ភាគទី</span>
                  </div>
                  <h4 className="text-2xl font-black heading-kh text-maroon">សំណួរ {toKhmerNumeral(i * 10 + 1)} ដល់ {toKhmerNumeral(Math.min((i + 1) * 10, totalQuestions))}</h4>
                </div>
                <div className="w-16 h-16 rounded-[1.5rem] bg-gray-50 flex items-center justify-center text-maroon/20 group-hover:bg-maroon group-hover:text-white transition-all shadow-inner group-hover:rotate-12">
                   🚀
                </div>
              </div>
            </button>
          ))}
        </div>
      </div>
    );
  }

  return (
    <div className="page-transition space-y-12 pb-20">
      {/* Search and Tabs */}
      <div className="flex flex-col items-center gap-8">
        <div className="bg-white/10 backdrop-blur-3xl p-2 rounded-[2.5rem] border border-white/20 shadow-2xl flex">
          <button onClick={() => setPlayMode('by-subject')} className={`px-10 py-4 rounded-[2rem] font-black heading-kh text-sm transition-all ${playMode === 'by-subject' ? 'bg-white text-maroon shadow-2xl scale-105' : 'text-white/60 hover:text-white'}`}>📚 តាមមុខវិជ្ជា</button>
          <button onClick={() => setPlayMode('mixed')} className={`px-10 py-4 rounded-[2rem] font-black heading-kh text-sm transition-all ${playMode === 'mixed' ? 'bg-white text-maroon shadow-2xl scale-105' : 'text-white/60 hover:text-white'}`}>⚡ តេស្តចម្រុះ</button>
        </div>

        <div className="w-full max-w-3xl relative group">
          <input 
            type="text" 
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            placeholder="ស្វែងរកសំណួរដែលអ្នកចង់រៀន..." 
            className="w-full pl-16 pr-8 py-6 bg-white/10 backdrop-blur-2xl border border-white/20 rounded-[2.5rem] outline-none focus:bg-white focus:ring-8 focus:ring-maroon/5 transition-all shadow-3xl heading-kh text-white group-focus-within:text-maroon placeholder:text-white/30"
          />
          <div className="absolute left-7 top-6 text-white/40 group-focus-within:text-maroon/30 transition-colors">
            <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
          </div>
        </div>
      </div>

      {playMode === 'mixed' ? (
        <div className="page-transition max-w-3xl mx-auto">
          <div className="glass-card rounded-[3.5rem] p-10 md:p-14 border-white shadow-3xl relative overflow-hidden">
            <div className="absolute top-0 left-0 w-full h-2 bg-gradient-to-r from-maroon to-gold-dark"></div>
            <h3 className="text-3xl font-black heading-kh text-maroon mb-10 text-center">រៀបចំតេស្តចម្រុះ</h3>
            <div className="space-y-10">
              <div className="flex justify-center">
                <div className="bg-gray-100 p-1.5 rounded-2xl flex">
                  <button onClick={() => setActiveType('mcq')} className={`px-10 py-3 rounded-xl text-xs font-black transition-all ${activeType === 'mcq' ? 'bg-white text-blue-700 shadow-xl' : 'text-gray-400'}`}>QCM</button>
                  <button onClick={() => setActiveType('short')} className={`px-10 py-3 rounded-xl text-xs font-black transition-all ${activeType === 'short' ? 'bg-white text-orange-700 shadow-xl' : 'text-gray-400'}`}>Q & A</button>
                </div>
              </div>

              <div className="space-y-5">
                <label className="text-[10px] font-black uppercase text-gray-400 block ml-4 tracking-[0.2em]">ជ្រើសរើសមុខវិជ្ជាចម្រុះ</label>
                <div className="grid grid-cols-2 sm:grid-cols-3 gap-4">
                  {subjects.map((sub, i) => (
                    <button key={i} onClick={() => handleToggleMixSubject(sub)} className={`p-5 rounded-3xl border-2 transition-all flex items-center justify-between group ${selectedMixSubjects.includes(sub) ? 'bg-maroon text-white border-maroon shadow-xl scale-105' : 'bg-white border-gray-100 text-gray-600 hover:border-maroon/30'}`}>
                      <span className="text-xs font-bold small-kh truncate flex-1">{sub}</span>
                      {selectedMixSubjects.includes(sub) && <span className="ml-2">✓</span>}
                    </button>
                  ))}
                </div>
              </div>

              <div className="space-y-5">
                <label className="text-[10px] font-black uppercase text-gray-400 block ml-4 tracking-[0.2em]">ចំនួនសំណួរចង់ធ្វើ</label>
                <div className="flex flex-wrap justify-center gap-3">
                  {[10, 20, 30, 50, 100].map(count => (
                    <button key={count} onClick={() => setMixCount(count)} className={`px-8 py-4 rounded-2xl font-black text-xs transition-all ${mixCount === count ? 'bg-gold-dark text-white shadow-xl scale-110' : 'bg-gray-100 text-gray-400 hover:bg-gray-200'}`}>{toKhmerNumeral(count)} សំណួរ</button>
                  ))}
                </div>
              </div>

              <div className="pt-6">
                <button onClick={handleStartMixedTest} className="w-full btn-premium py-6 rounded-[2.5rem] font-black heading-kh text-xl flex items-center justify-center gap-4">
                  ⚡ ចាប់ផ្ដើមវិញ្ញាសាចម្រុះ
                </button>
              </div>
            </div>
          </div>
        </div>
      ) : (
        <div className="space-y-12">
          <div className="flex justify-center gap-6">
            <button onClick={() => setActiveType('mcq')} className={`px-10 py-4 rounded-full font-black heading-kh text-sm transition-all shadow-xl ${activeType === 'mcq' ? 'bg-maroon text-white scale-110' : 'bg-white/10 text-white/50 border border-white/10'}`}>📑 QCM</button>
            <button onClick={() => setActiveType('short')} className={`px-10 py-4 rounded-full font-black heading-kh text-sm transition-all shadow-xl ${activeType === 'short' ? 'bg-maroon text-white scale-110' : 'bg-white/10 text-white/50 border border-white/10'}`}>🖊️ Q & A</button>
          </div>

          {searchQuery.trim() ? (
            <div className="grid grid-cols-1 gap-6 max-w-4xl mx-auto">
              {searchResults.length > 0 ? searchResults.map((q, idx) => (
