import * as React from 'react';
import { useState, useMemo, useRef, useEffect } from 'react';
import { Question, QuizState } from '../types';

interface QuizGameProps {
  subject: string;
  partIndex: number;
  type: 'mcq' | 'short';
  allSubjectQuestions: Question[];
  onExit: () => void;
  onStartNextPart?: (newPartIndex: number) => void;
}

const QuizGame: React.FC<QuizGameProps> = ({ subject, partIndex, type, allSubjectQuestions, onExit, onStartNextPart }) => {
  const KHMER_PREFIXES = ['ក', 'ខ', 'គ', 'ឃ'];
  const KHMER_DIGITS = ['០', '១', '២', '៣', '៤', '៥', '៦', '៧', '៨', '៩'];

  const toKhmerNumeral = (n: number) => n.toString().split('').map(digit => KHMER_DIGITS[parseInt(digit)] || digit).join('');

  const [isMuted, setIsMuted] = useState(false);
  const [shakeIndex, setShakeIndex] = useState<number | null>(null);
  const correctAudioRef = useRef<HTMLAudioElement | null>(null);
  const wrongAudioRef = useRef<HTMLAudioElement | null>(null);

  useEffect(() => {
    correctAudioRef.current = new Audio('https://assets.mixkit.co/active_storage/sfx/600/600-preview.mp3');
    wrongAudioRef.current = new Audio('https://assets.mixkit.co/active_storage/sfx/951/951-preview.mp3');
    return () => {
      correctAudioRef.current?.pause();
      wrongAudioRef.current?.pause();
    };
  }, []);

  const partQuestions = useMemo(() => {
    const start = partIndex * 10;
    const subset = allSubjectQuestions.slice(start, start + 10);
    if (type === 'mcq') {
      return subset.map(q => {
        if (!q.options) return q;
        const opts = q.options.map((opt, idx) => ({ text: opt, isCorrect: idx === q.correct }));
        const shuffled = [...opts].sort(() => Math.random() - 0.5);
        return { ...q, options: shuffled.map(o => o.text), correct: shuffled.findIndex(o => o.isCorrect) };
      });
    }
    return subset;
  }, [allSubjectQuestions, partIndex, type]);

  const [state, setState] = useState<QuizState>({
    currentQuestionIndex: 0,
    score: 0,
    isFinished: false,
    selectedAnswer: null,
    userInput: '',
    showCorrect: false,
    userAnswers: [],
    isReviewing: false
  });

  const totalParts = Math.ceil(allSubjectQuestions.length / 10);

  const handleMCQSelect = (idx: number) => {
    if (state.selectedAnswer !== null || state.isFinished) return;
    const isCorrect = idx === partQuestions[state.currentQuestionIndex].correct;

    if (!isMuted) {
      const audio = isCorrect ? correctAudioRef.current : wrongAudioRef.current;
      if (audio) { audio.currentTime = 0; audio.play().catch(() => {}); }
    }

    if (!isCorrect) { setShakeIndex(idx); setTimeout(() => setShakeIndex(null), 500); }

    setState(prev => ({
      ...prev,
      selectedAnswer: idx,
      showCorrect: true,
      score: isCorrect ? prev.score + 1 : prev.score,
      userAnswers: [...prev.userAnswers, idx]
    }));
  };

  const handleNext = () => {
    if (state.currentQuestionIndex + 1 < partQuestions.length) {
      setState(prev => ({ 
        ...prev, 
        currentQuestionIndex: prev.currentQuestionIndex + 1, 
        selectedAnswer: null, 
        showCorrect: false 
      }));
    } else setState(prev => ({ ...prev, isFinished: true }));
  };

  if (type === 'short') {
    return (
      <div className="page-transition space-y-8 pb-32">
        <div className="glass-card rounded-[3rem] p-8 md:p-12 flex items-center justify-between border-white shadow-3xl">
          <div className="flex items-center gap-6">
            <button onClick={onExit} className="w-14 h-14 bg-maroon/5 text-maroon rounded-2xl flex items-center justify-center hover:bg-maroon hover:text-white transition-all shadow-inner font-bold">←</button>
            <div>
              <h2 className="text-3xl font-black heading-kh text-maroon">{subject}</h2>
              <p className="text-[10px] font-black uppercase text-gray-400 tracking-widest">ភាគទី {toKhmerNumeral(partIndex + 1)} • Q & A</p>
            </div>
          </div>
          <div className="bg-maroon text-white px-8 py-3 rounded-2xl font-black text-xs uppercase shadow-2xl">សរុប៖ {toKhmerNumeral(partQuestions.length)} សំណួរ</div>
        </div>

        <div className="space-y-10">
          {partQuestions.map((q, idx) => (
            <div key={idx} className="glass-card rounded-[3.5rem] p-10 md:p-16 border-white shadow-3xl transition-all hover:scale-[1.01] page-transition">
              <div className="flex gap-6 items-start mb-10">
                <span className="w-16 h-16 bg-maroon text-white rounded-[1.5rem] flex items-center justify-center font-black text-2xl shrink-0 shadow-xl">{toKhmerNumeral(partIndex * 10 + idx + 1)}</span>
                <h3 className="text-2xl md:text-3xl font-black heading-kh text-maroon leading-[1.8] text-justify">{q.question}</h3>
              </div>
              <div className="bg-gradient-to-br from-green-50 to-emerald-50 border-l-[12px] border-green-500 rounded-r-[3rem] p-10 md:p-14 relative overflow-hidden shadow-inner">
                <div className="absolute top-0 right-0 w-32 h-32 bg-green-500/5 rounded-full -mr-16 -mt-16"></div>
                <div className="flex flex-col gap-4 relative z-10">
                  <span className="font-black text-green-700 heading-kh text-xl uppercase tracking-widest">ចម្លើយត្រឹមត្រូវ ៖</span>
                  <div className="text-gray-800 small-kh font-medium text-xl md:text-2xl leading-[2.2] whitespace-pre-wrap text-justify">{q.answer}</div>
                </div>
              </div>
            </div>
          ))}

          <div className="flex justify-center gap-6 pt-12">
            <button onClick={onExit} className="btn-premium px-16 py-6 rounded-[2.5rem] font-black heading-kh text-xl shadow-4xl">🏠 ត្រឡប់ទៅមឺនុយ</button>
          </div>
        </div>
      </div>
    );
  }

  if (state.isFinished) {
    const percentage = Math.round((state.score / partQuestions.length) * 100);
    return (
      <div className="page-transition max-w-2xl mx-auto py-10">
        <div className="glass-card rounded-[4rem] p-16 text-center border-white shadow-4xl relative overflow-hidden">
          <div className="absolute top-0 left-0 w-full h-3 bg-gradient-to-r from-maroon to-gold-dark"></div>
          <div className="text-9xl mb-10 animate-bounce">🏆</div>
          <h2 className="text-4xl font-black mb-4 heading-kh text-maroon">លទ្ធផលរបស់អ្នក</h2>
          <div className="text-[120px] leading-none font-black text-indigo-600 my-10 drop-shadow-2xl">{toKhmerNumeral(percentage)}%</div>
          <p className="text-2xl mb-16 small-kh text-gray-500 font-bold">ឆ្លើយត្រូវ {toKhmerNumeral(state.score)} លើ {toKhmerNumeral(partQuestions.length)}</p>
          <div className="flex flex-col gap-5">
            <button onClick={() => setState(prev => ({ ...prev, isReviewing: true }))} className="w-full py-6 bg-gray-100 text-gray-600 font-black rounded-3xl hover:bg-gray-200 transition-all text-xl heading-kh shadow-sm">ពិនិត្យចម្លើយឡើងវិញ 👁️</button>
            <button onClick={onExit} className="w-full btn-premium py-6 rounded-3xl font-black text-xl heading-kh shadow-2xl">ត្រឡប់ទៅកាន់ទំព័រដើម 🏠</button>
          </div>
        </div>
      </div>
    );
  }

  const currentQ = partQuestions[state.currentQuestionIndex];
  return (
    <div className="glass-card rounded-[4rem] p-10 md:p-16 page-transition border-white shadow-4xl flex flex-col min-h-[700px] relative overflow-hidden">
      <div className="absolute top-0 right-0 w-64 h-64 bg-maroon/5 rounded-full -mr-32 -mt-32 blur-3xl"></div>

      <div className="flex justify-between items-start mb-12 relative z-10">
        <div>
          <span className="text-maroon/40 font-black text-[10px] uppercase tracking-[0.3em] mb-2 block">{subject}</span>
          <div className="flex items-end gap-3">
             <span className="text-5xl font-black text-maroon">{toKhmerNumeral(state.currentQuestionIndex + 1)}</span>
             <span className="text-xl font-bold text-gray-300 mb-1">/ {toKhmerNumeral(partQuestions.length)}</span>
          </div>
        </div>

        <div className="flex items-center gap-4">
          <button onClick={() => setIsMuted(!isMuted)} className="w-14 h-14 bg-white shadow-xl rounded-2xl flex items-center justify-center text-2xl hover:scale-110 transition-all">{isMuted ? '🔇' : '🔊'}</button>
          <div className="bg-gradient-to-r from-indigo-600 to-blue-600 text-white px-10 py-4 rounded-[1.5rem] shadow-3xl font-black text-2xl tabular-nums">ពិន្ទុ៖ {toKhmerNumeral(state.score)}</div>
        </div>
      </div>

      <div className="flex-1 flex flex-col relative z-10">
        <h2 className="text-3xl md:text-4xl font-black mb-12 heading-kh text-maroon leading-[1.6] text-justify">{currentQ?.question}</h2>
        <div className="grid grid-cols-1 gap-5">
          {currentQ?.options?.map((opt, i) => {
            let style = "bg-white border-gray-100 hover:border-indigo-400 hover:shadow-2xl hover:-translate-y-1 text-gray-700";
            if (state.showCorrect) {
              if (i === currentQ.correct) style = "bg-green-600 border-green-600 text-white shadow-green-500/40 ring-8 ring-green-100";
              else if (i === state.selectedAnswer) style = "bg-red-500 border-red-500 text-white shadow-red-500/40 opacity-100";
              else style = "opacity-30 grayscale scale-[0.98]";
            }
            return (
              <button key={i} onClick={() => handleMCQSelect(i)} disabled={state.showCorrect} className={`text-left p-8 rounded-[2rem] border-2 transition-all font-bold text-xl flex items-center gap-6 small-kh ${style} ${shakeIndex === i ? 'animate-bounce' : ''}`}>
                <span className={`w-12 h-12 rounded-xl flex items-center justify-center font-black text-2xl shrink-0 shadow-inner ${state.showCorrect && i === currentQ.correct ? 'bg-white text-green-600' : 'bg-gray-50 text-maroon'}`}>{KHMER_PREFIXES[i]}</span>
                <span className="flex-1 leading-relaxed">{opt}</span>
              </button>
            );
          })}
        </div>
      </div>

      {state.showCorrect && (
        <button onClick={handleNext} className="mt-14 w-full bg-gradient-to-r from-maroon to-maroon-deep text-white font-black py-7 rounded-[2.5rem] shadow-4xl text-2xl page-transition hover:brightness-110 active:scale-95 transition-all">
          {state.currentQuestionIndex + 1 === partQuestions.length ? "បញ្ចប់ និងមើលលទ្ធផល 🏁" : "សំណួរបន្ទាប់ ✨"}
        </button>
      )}
    </div>
  );
};

