import * as React from 'react';
import { useState, useMemo, useRef, useEffect } from 'react';
import { Question, QuizState } from '../types';

interface QuizGameProps {
  subject: string;
  partIndex: number;
  type: 'mcq' | 'short';
  allSubjectQuestions: Question[];
  onExit: () => void;
  onStartNextPart?: (newPartIndex: number) => void;
}

const QuizGame: React.FC<QuizGameProps> = ({ subject, partIndex, type, allSubjectQuestions, onExit, onStartNextPart }) => {
  const KHMER_PREFIXES = ['ក', 'ខ', 'គ', 'ឃ'];
  const KHMER_DIGITS = ['០', '១', '២', '៣', '៤', '៥', '៦', '៧', '៨', '៩'];

  const toKhmerNumeral = (n: number) => n.toString().split('').map(digit => KHMER_DIGITS[parseInt(digit)] || digit).join('');

  const [isMuted, setIsMuted] = useState(false);
  const [shakeIndex, setShakeIndex] = useState<number | null>(null);
  const correctAudioRef = useRef<HTMLAudioElement | null>(null);
  const wrongAudioRef = useRef<HTMLAudioElement | null>(null);

  useEffect(() => {
    correctAudioRef.current = new Audio('https://assets.mixkit.co/active_storage/sfx/600/600-preview.mp3');
    wrongAudioRef.current = new Audio('https://assets.mixkit.co/active_storage/sfx/951/951-preview.mp3');
    return () => {
      correctAudioRef.current?.pause();
      wrongAudioRef.current?.pause();
    };
  }, []);

  const partQuestions = useMemo(() => {
    const start = partIndex * 10;
    const subset = allSubjectQuestions.slice(start, start + 10);
    if (type === 'mcq') {
      return subset.map(q => {
        if (!q.options) return q;
        const opts = q.options.map((opt, idx) => ({ text: opt, isCorrect: idx === q.correct }));
        const shuffled = [...opts].sort(() => Math.random() - 0.5);
        return { ...q, options: shuffled.map(o => o.text), correct: shuffled.findIndex(o => o.isCorrect) };
      });
    }
    return subset;
  }, [allSubjectQuestions, partIndex, type]);

  const [state, setState] = useState<QuizState>({
    currentQuestionIndex: 0,
    score: 0,
    isFinished: false,
    selectedAnswer: null,
    userInput: '',
    showCorrect: false,
    userAnswers: [],
    isReviewing: false
  });

  const handleMCQSelect = (idx: number) => {
    if (state.selectedAnswer !== null || state.isFinished) return;
    const isCorrect = idx === partQuestions[state.currentQuestionIndex].correct;

    if (!isMuted) {
      const audio = isCorrect ? correctAudioRef.current : wrongAudioRef.current;
      if (audio) { audio.currentTime = 0; audio.play().catch(() => {}); }
    }

    if (!isCorrect) { setShakeIndex(idx); setTimeout(() => setShakeIndex(null), 500); }

    setState(prev => ({
      ...prev,
      selectedAnswer: idx,
      showCorrect: true,
      score: isCorrect ? prev.score + 1 : prev.score,
      userAnswers: [...prev.userAnswers, idx]
    }));
  };

  const handleNext = () => {
    if (state.currentQuestionIndex + 1 < partQuestions.length) {
      setState(prev => ({ 
        ...prev, 
        currentQuestionIndex: prev.currentQuestionIndex + 1, 
        selectedAnswer: null, 
        showCorrect: false 
      }));
    } else setState(prev => ({ ...prev, isFinished: true }));
  };

  if (state.isFinished) {
    const percentage = Math.round((state.score / partQuestions.length) * 100);
    return (
      <div className="page-transition max-w-3xl mx-auto py-12 px-4">
        <div className="glass-card rounded-[4rem] p-16 text-center border-8 border-white shadow-5xl relative overflow-hidden">
          <div className="absolute top-0 left-0 w-full h-4 bg-gradient-to-r from-maroon to-yellow-500"></div>
          <div className="text-[120px] mb-12 animate-bounce drop-shadow-2xl">🏆</div>
          <h2 className="text-5xl font-black mb-6 heading-kh text-maroon">លទ្ធផលរបស់អ្នក</h2>
          <div className="text-[140px] leading-none font-black text-indigo-700 my-12 drop-shadow-2xl">{toKhmerNumeral(percentage)}%</div>
          <p className="text-3xl mb-16 small-kh text-gray-600 font-black">ឆ្លើយត្រូវ {toKhmerNumeral(state.score)} លើ {toKhmerNumeral(partQuestions.length)}</p>
          <div className="flex flex-col gap-6 max-w-md mx-auto">
            <button onClick={onExit} className="w-full btn-premium py-7 rounded-[2.5rem] font-black text-2xl heading-kh shadow-4xl tracking-wider">ត្រឡប់ទៅកាន់ទំព័រដើម 🏠</button>
          </div>
        </div>
      </div>
    );
  }

  const currentQ = partQuestions[state.currentQuestionIndex];
  return (
    <div className="glass-card rounded-[4rem] p-12 md:p-20 page-transition border-8 border-white shadow-5xl flex flex-col min-h-[850px] relative overflow-hidden">
      <div className="absolute top-0 right-0 w-80 h-80 bg-maroon/5 rounded-full -mr-40 -mt-40 blur-3xl"></div>

      <div className="flex justify-between items-start mb-16 relative z-10">
        <div className="flex flex-col gap-2">
          <span className="text-maroon/60 font-black text-xs uppercase tracking-[0.4em] small-kh">{subject}</span>
          <div className="flex items-end gap-4">
             <span className="text-7xl font-black text-maroon drop-shadow-sm">{toKhmerNumeral(state.currentQuestionIndex + 1)}</span>
             <span className="text-2xl font-bold text-gray-400 mb-2">/ {toKhmerNumeral(partQuestions.length)}</span>
          </div>
        </div>

        <div className="flex items-center gap-6">
          <button onClick={() => setIsMuted(!isMuted)} className="w-16 h-16 bg-white shadow-xl rounded-2xl flex items-center justify-center text-3xl hover:scale-110 transition-all border border-gray-100">{isMuted ? '🔇' : '🔊'}</button>
          <div className="bg-indigo-700 text-white px-12 py-5 rounded-[2.5rem] shadow-4xl font-black text-3xl border-4 border-white/20">ពិន្ទុ៖ {toKhmerNumeral(state.score)}</div>
        </div>
      </div>

      <div className="flex-1 flex flex-col relative z-10">
        <h2 className="text-3xl md:text-5xl font-black mb-16 heading-kh text-maroon leading-[1.5] text-justify">{currentQ?.question}</h2>
        <div className="grid grid-cols-1 gap-6">
          {currentQ?.options?.map((opt, i) => {
            let style = "bg-white border-gray-200 hover:border-indigo-500 hover:bg-indigo-50/30 text-gray-800 shadow-lg";
            if (state.showCorrect) {
              if (i === currentQ.correct) style = "bg-green-600 border-green-700 text-white shadow-2xl ring-12 ring-green-100 scale-[1.03] z-20";
              else if (i === state.selectedAnswer) style = "bg-red-500 border-red-700 text-white shadow-xl opacity-100 scale-[0.98]";
              else style = "opacity-20 grayscale scale-[0.95]";
            }
            return (
              <button key={i} onClick={() => handleMCQSelect(i)} disabled={state.showCorrect} className={`text-left p-10 rounded-[2.5rem] border-4 transition-all font-black text-2xl flex items-center gap-8 small-kh ${style} ${shakeIndex === i ? 'animate-bounce' : ''}`}>
                <span className={`w-14 h-14 rounded-2xl flex items-center justify-center font-black text-3xl shrink-0 shadow-inner ${state.showCorrect && i === currentQ.correct ? 'bg-white text-green-600' : 'bg-gray-100 text-maroon border-2 border-gray-200'}`}>{KHMER_PREFIXES[i]}</span>
                <span className="flex-1 leading-[1.6]">{opt}</span>
              </button>
            );
          })}
        </div>
      </div>

      {state.showCorrect && (
        <button onClick={handleNext} className="mt-20 w-full bg-gradient-to-r from-maroon to-maroon-deep text-white font-black py-10 rounded-[3rem] shadow-5xl text-3xl page-transition hover:brightness-125 active:scale-95 transition-all border-b-8 border-maroon-deep tracking-wider">
          {state.currentQuestionIndex + 1 === partQuestions.length ? "បញ្ចប់ និងមើលលទ្ធផល 🏁" : "សំណួរបន្ទាប់ ✨"}
        </button>
      )}
    </div>
  );
};

