import * as React from 'react';
import { useState, useMemo, useRef, useEffect } from 'react';
import { Question, QuizState } from '../types';

interface QuizGameProps {
  subject: string;
  partIndex: number;
  type: 'mcq' | 'short';
  allSubjectQuestions: Question[];
  onExit: () => void;
  onStartNextPart?: (newPartIndex: number) => void;
}

const QuizGame: React.FC<QuizGameProps> = ({ subject, partIndex, type, allSubjectQuestions, onExit, onStartNextPart }) => {
  const KHMER_PREFIXES = ['ក', 'ខ', 'គ', 'ឃ'];
  const KHMER_DIGITS = ['០', '១', '២', '៣', '៤', '៥', '៦', '៧', '៨', '៩'];

  const toKhmerNumeral = (n: number) => n.toString().split('').map(digit => KHMER_DIGITS[parseInt(digit)] || digit).join('');

  const [isMuted, setIsMuted] = useState(false);
  const [shakeIndex, setShakeIndex] = useState<number | null>(null);
  const correctAudioRef = useRef<HTMLAudioElement | null>(null);
  const wrongAudioRef = useRef<HTMLAudioElement | null>(null);

  useEffect(() => {
    correctAudioRef.current = new Audio('https://assets.mixkit.co/active_storage/sfx/600/600-preview.mp3');
    wrongAudioRef.current = new Audio('https://assets.mixkit.co/active_storage/sfx/951/951-preview.mp3');
    return () => {
      correctAudioRef.current?.pause();
      wrongAudioRef.current?.pause();
    };
  }, []);

  const partQuestions = useMemo(() => {
    const start = partIndex * 10;
    const subset = allSubjectQuestions.slice(start, start + 10);
    if (type === 'mcq') {
      return subset.map(q => {
        if (!q.options) return q;
        const opts = q.options.map((opt, idx) => ({ text: opt, isCorrect: idx === q.correct }));
        const shuffled = [...opts].sort(() => Math.random() - 0.5);
        return { ...q, options: shuffled.map(o => o.text), correct: shuffled.findIndex(o => o.isCorrect) };
      });
    }
    return subset;
  }, [allSubjectQuestions, partIndex, type]);

  const [state, setState] = useState<QuizState>({
    currentQuestionIndex: 0,
    score: 0,
    isFinished: false,
    selectedAnswer: null,
    userInput: '',
    showCorrect: false,
    userAnswers: [],
    isReviewing: false
  });

  const handleMCQSelect = (idx: number) => {
    if (state.selectedAnswer !== null || state.isFinished) return;
    const isCorrect = idx === partQuestions[state.currentQuestionIndex].correct;

    if (!isMuted) {
      const audio = isCorrect ? correctAudioRef.current : wrongAudioRef.current;
      if (audio) { audio.currentTime = 0; audio.play().catch(() => {}); }
    }

    if (!isCorrect) { setShakeIndex(idx); setTimeout(() => setShakeIndex(null), 500); }

    setState(prev => ({
      ...prev,
      selectedAnswer: idx,
      showCorrect: true,
      score: isCorrect ? prev.score + 1 : prev.score,
      userAnswers: [...prev.userAnswers, idx]
    }));
  };

  const handleNext = () => {
    if (state.currentQuestionIndex + 1 < partQuestions.length) {
      setState(prev => ({ 
        ...prev, 
        currentQuestionIndex: prev.currentQuestionIndex + 1, 
        selectedAnswer: null, 
        showCorrect: false 
      }));
    } else setState(prev => ({ ...prev, isFinished: true }));
  };

  if (state.isFinished) {
    const percentage = Math.round((state.score / partQuestions.length) * 100);
    return (
      <div className="page-transition max-w-4xl mx-auto py-16 px-4">
        <div className="glass-card rounded-[5rem] p-20 text-center border-[10px] border-white shadow-7xl relative overflow-hidden">
          <div className="absolute top-0 left-0 w-full h-6 bg-gradient-to-r from-maroon to-yellow-500"></div>
          <div className="text-[160px] mb-16 animate-bounce drop-shadow-2xl">🏆</div>
          <h2 className="text-6xl font-black mb-8 heading-kh text-maroon">លទ្ធផលរបស់អ្នក</h2>
          <div className="text-[180px] leading-none font-black text-indigo-700 my-16 drop-shadow-2xl">{toKhmerNumeral(percentage)}%</div>
          <p className="text-4xl mb-20 small-kh text-gray-700 font-black">ឆ្លើយត្រូវ {toKhmerNumeral(state.score)} លើ {toKhmerNumeral(partQuestions.length)}</p>
          <div className="flex flex-col gap-8 max-w-lg mx-auto">
            <button onClick={onExit} className="btn-solid-maroon w-full py-9 rounded-[3rem] font-black text-3xl heading-kh shadow-4xl tracking-widest uppercase">ត្រឡប់ទៅមឺនុយ 🏠</button>
          </div>
        </div>
      </div>
    );
  }

  const currentQ = partQuestions[state.currentQuestionIndex];
  return (
    <div className="glass-card rounded-[5rem] p-12 md:p-24 page-transition border-[12px] border-white shadow-7xl flex flex-col min-h-[950px] relative overflow-hidden">
      <div className="absolute top-0 right-0 w-[500px] h-[500px] bg-maroon/5 rounded-full -mr-64 -mt-64 blur-[100px]"></div>

      <div className="flex justify-between items-start mb-20 relative z-10">
        <div className="flex flex-col gap-4">
          <span className="text-maroon font-black text-sm uppercase tracking-[0.5em] small-kh bg-maroon/5 px-6 py-2 rounded-full border border-maroon/10">{subject}</span>
          <div className="flex items-end gap-6">
             <span className="text-9xl font-black text-maroon drop-shadow-xl">{toKhmerNumeral(state.currentQuestionIndex + 1)}</span>
             <span className="text-3xl font-black text-gray-300 mb-6">/ {toKhmerNumeral(partQuestions.length)}</span>
          </div>
        </div>

        <div className="flex items-center gap-8">
          <button onClick={() => setIsMuted(!isMuted)} className="w-20 h-20 bg-white shadow-2xl rounded-3xl flex items-center justify-center text-4xl hover:scale-110 transition-all border-4 border-gray-100">{isMuted ? '🔇' : '🔊'}</button>
          <div className="bg-indigo-700 text-white px-16 py-7 rounded-[3rem] shadow-5xl font-black text-4xl border-b-[10px] border-indigo-900">ពិន្ទុ៖ {toKhmerNumeral(state.score)}</div>
        </div>
      </div>

      <div className="flex-1 flex flex-col relative z-10">
        <h2 className="text-4xl md:text-6xl font-black mb-20 heading-kh text-indigo-950 leading-[1.4] text-justify">{currentQ?.question}</h2>
        <div className="grid grid-cols-1 gap-8">
          {currentQ?.options?.map((opt, i) => {
            let style = "bg-white border-4 border-gray-200 hover:border-indigo-600 hover:bg-indigo-50/50 text-indigo-950 shadow-xl";
            if (state.showCorrect) {
              if (i === currentQ.correct) style = "bg-emerald-600 border-emerald-800 text-white shadow-emerald-200 ring-[20px] ring-emerald-50 scale-[1.05] z-20";
              else if (i === state.selectedAnswer) style = "bg-rose-600 border-rose-800 text-white shadow-rose-200 opacity-100 scale-[0.98]";
              else style = "opacity-20 grayscale scale-[0.95]";
            }
            return (
              <button key={i} onClick={() => handleMCQSelect(i)} disabled={state.showCorrect} className={`text-left p-12 rounded-[3.5rem] transition-all font-black text-3xl flex items-center gap-10 small-kh ${style} ${shakeIndex === i ? 'animate-bounce' : ''}`}>
                <span className={`w-16 h-16 rounded-2xl flex items-center justify-center font-black text-4xl shrink-0 shadow-inner border-2 ${state.showCorrect && i === currentQ.correct ? 'bg-white text-emerald-600' : 'bg-gray-100 text-maroon border-gray-200'}`}>{KHMER_PREFIXES[i]}</span>
                <span className="flex-1 leading-relaxed">{opt}</span>
              </button>
            );
          })}
        </div>
      </div>

      {state.showCorrect && (
        <button onClick={handleNext} className="mt-24 w-full bg-gradient-to-r from-maroon to-maroon-deep text-white font-black py-12 rounded-[4rem] shadow-7xl text-4xl page-transition hover:brightness-125 active:scale-95 transition-all border-b-[12px] border-maroon-deep tracking-widest uppercase">
          {state.currentQuestionIndex + 1 === partQuestions.length ? "មើលលទ្ធផល 🏁" : "សំណួរបន្ទាប់ ✨"}
        </button>
      )}
    </div>
  );
};

export default QuizGame;

