                  onChange={(e) => setUserInput(e.target.value)} 
                  className="input-solid w-full px-10 py-8 rounded-[3rem] shadow-inner" 
                  placeholder="វាយឈ្មោះរបស់អ្នកនៅទីនេះ..." 
                />
              </div>
            )}
            <div>
              <label className={`text-base font-black uppercase ml-10 mb-5 block tracking-[0.2em] small-kh ${view === 'admin_login' ? 'text-maroon' : 'text-indigo-900'}`}>
                {view === 'user_login' ? 'Password (លេខសម្ងាត់ ៦ខ្ទង់)' : 'លេខកូដសម្ងាត់អ្នកគ្រប់គ្រង'}
              </label>
              <input 
                type={view === 'user_login' ? 'text' : 'password'} 
                inputMode={view === 'user_login' ? 'numeric' : 'text'}
                value={passInput} 
                onChange={(e) => setPassInput(view === 'user_login' ? e.target.value.replace(/\D/g, '').slice(0, 6) : e.target.value)} 
                className={`input-solid w-full px-10 py-8 rounded-[3rem] shadow-inner ${view === 'admin_login' ? 'text-center tracking-[1.2em]' : ''}`} 
                placeholder={view === 'user_login' ? "••••••" : "••••"}
                onKeyDown={(e) => e.key === 'Enter' && (view === 'user_login' ? handleUserVerify() : handleAdminVerify())} 
              />
            </div>
          </div>

          <button 
            onClick={view === 'user_login' ? handleUserVerify : handleAdminVerify} 
            className={`w-full py-9 rounded-[3.5rem] font-black heading-kh text-4xl shadow-4xl ${view === 'user_login' ? 'btn-blue-sharp' : 'btn-red-sharp'}`}
          >
            បញ្ជាក់ការចូលប្រព័ន្ធ 🚀
          </button>
        </div>
      )}
    </div>
  );
};

