import * as React from 'react';
import { useState, useMemo, useRef, useEffect } from 'react';
import { Question, QuizState } from '../types';

interface QuizGameProps {
  subject: string;
  partIndex: number;
  type: 'mcq' | 'short';
  allSubjectQuestions: Question[];
  onExit: () => void;
  onStartNextPart?: (newPartIndex: number) => void;
}

const QuizGame: React.FC<QuizGameProps> = ({ subject, partIndex, type, allSubjectQuestions, onExit, onStartNextPart }) => {
  const KHMER_PREFIXES = ['ក', 'ខ', 'គ', 'ឃ'];
  const KHMER_DIGITS = ['០', '១', '២', '៣', '៤', '៥', '៦', '៧', '៨', '៩'];

  const toKhmerNumeral = (n: number) => n.toString().split('').map(digit => KHMER_DIGITS[parseInt(digit)] || digit).join('');

  const [isMuted, setIsMuted] = useState(false);
  const [shakeIndex, setShakeIndex] = useState<number | null>(null);
  const correctAudioRef = useRef<HTMLAudioElement | null>(null);
  const wrongAudioRef = useRef<HTMLAudioElement | null>(null);

  useEffect(() => {
    correctAudioRef.current = new Audio('https://assets.mixkit.co/active_storage/sfx/600/600-preview.mp3');
    wrongAudioRef.current = new Audio('https://assets.mixkit.co/active_storage/sfx/951/951-preview.mp3');
    return () => {
      correctAudioRef.current?.pause();
      wrongAudioRef.current?.pause();
    };
  }, []);

  const partQuestions = useMemo(() => {
    const start = partIndex * 10;
    const subset = allSubjectQuestions.slice(start, start + 10);
    if (type === 'mcq') {
      return subset.map(q => {
        if (!q.options) return q;
        const opts = q.options.map((opt, idx) => ({ text: opt, isCorrect: idx === q.correct }));
        const shuffled = [...opts].sort(() => Math.random() - 0.5);
        return { ...q, options: shuffled.map(o => o.text), correct: shuffled.findIndex(o => o.isCorrect) };
      });
    }
    return subset;
  }, [allSubjectQuestions, partIndex, type]);

  const [state, setState] = useState<QuizState>({
    currentQuestionIndex: 0,
    score: 0,
    isFinished: false,
    selectedAnswer: null,
    userInput: '',
    showCorrect: false,
    userAnswers: [],
    isReviewing: false
  });

  const handleMCQSelect = (idx: number) => {
    if (state.selectedAnswer !== null || state.isFinished) return;
    const isCorrect = idx === partQuestions[state.currentQuestionIndex].correct;

    if (!isMuted) {
      const audio = isCorrect ? correctAudioRef.current : wrongAudioRef.current;
      if (audio) { audio.currentTime = 0; audio.play().catch(() => {}); }
    }

    if (!isCorrect) { setShakeIndex(idx); setTimeout(() => setShakeIndex(null), 500); }

    setState(prev => ({
      ...prev,
      selectedAnswer: idx,
      showCorrect: true,
      score: isCorrect ? prev.score + 1 : prev.score,
      userAnswers: [...prev.userAnswers, idx]
    }));
  };

  const handleNext = () => {
    if (state.currentQuestionIndex + 1 < partQuestions.length) {
      setState(prev => ({ 
        ...prev, 
        currentQuestionIndex: prev.currentQuestionIndex + 1, 
        selectedAnswer: null, 
        showCorrect: false 
      }));
    } else setState(prev => ({ ...prev, isFinished: true }));
  };

  if (state.isFinished) {
    const percentage = Math.round((state.score / partQuestions.length) * 100);
    return (
      <div className="page-transition max-w-5xl mx-auto py-24 px-4">
        <div className="glass-card-solid rounded-[6rem] p-24 text-center border-[15px] border-white shadow-7xl relative overflow-hidden">
          <div className="absolute top-0 left-0 w-full h-8 bg-gradient-to-r from-maroon to-yellow-500"></div>
          <div className="text-[200px] mb-20 animate-bounce drop-shadow-2xl">🏆</div>
          <h2 className="text-7xl font-black mb-12 heading-kh text-maroon">លទ្ធផលរបស់អ្នក</h2>
          <div className="text-[220px] leading-none font-black text-indigo-950 my-20 drop-shadow-2xl">{toKhmerNumeral(percentage)}%</div>
          <p className="text-5xl mb-24 small-kh text-indigo-900 font-black">ឆ្លើយត្រូវ {toKhmerNumeral(state.score)} លើ {toKhmerNumeral(partQuestions.length)}</p>
          <div className="flex flex-col gap-10 max-w-2xl mx-auto">
            <button onClick={onExit} className="btn-red-sharp w-full py-10 rounded-[4rem] font-black text-4xl heading-kh uppercase tracking-widest">ត្រឡប់ទៅមឺនុយ 🏠</button>
          </div>
        </div>
      </div>
    );
  }

  const currentQ = partQuestions[state.currentQuestionIndex];
  return (
    <div className="glass-card-solid rounded-[6rem] p-16 md:p-32 page-transition border-[18px] border-white shadow-7xl flex flex-col min-h-[1100px] relative overflow-hidden">
      <div className="flex justify-between items-start mb-24 relative z-10">
        <div className="flex flex-col gap-6">
          <span className="text-maroon font-black text-xl uppercase tracking-[0.6em] small-kh bg-red-50 px-10 py-3 rounded-full border-4 border-red-100">{subject}</span>
          <div className="flex items-end gap-8">
             <span className="text-[10rem] leading-none font-black text-indigo-950 drop-shadow-xl">{toKhmerNumeral(state.currentQuestionIndex + 1)}</span>
             <span className="text-5xl font-black text-gray-300 mb-10">/ {toKhmerNumeral(partQuestions.length)}</span>
          </div>
        </div>

        <div className="flex items-center gap-10">
          <button onClick={() => setIsMuted(!isMuted)} className="w-24 h-24 bg-white shadow-2xl rounded-[2rem] flex items-center justify-center text-5xl hover:scale-110 transition-all border-4 border-gray-100">{isMuted ? '🔇' : '🔊'}</button>
          <div className="bg-indigo-950 text-white px-20 py-8 rounded-[4rem] shadow-6xl font-black text-5xl border-b-[15px] border-black">ពិន្ទុ៖ {toKhmerNumeral(state.score)}</div>
        </div>
      </div>

      <div className="flex-1 flex flex-col relative z-10">
        <h2 className="text-5xl md:text-7xl font-black mb-28 heading-kh text-indigo-950 leading-[1.3] text-justify drop-shadow-sm">{currentQ?.question}</h2>
        <div className="grid grid-cols-1 gap-10">
          {currentQ?.options?.map((opt, i) => {
            let style = "bg-gray-50 border-8 border-gray-200 hover:border-indigo-950 hover:bg-white text-indigo-950 shadow-2xl";
            if (state.showCorrect) {
              if (i === currentQ.correct) style = "bg-emerald-600 border-emerald-950 text-white shadow-emerald-200 ring-[25px] ring-emerald-50 scale-[1.08] z-20";
              else if (i === state.selectedAnswer) style = "bg-red-700 border-red-950 text-white shadow-red-200 opacity-100 scale-[0.95]";
              else style = "opacity-10 grayscale scale-[0.9]";
            }
            return (
              <button key={i} onClick={() => handleMCQSelect(i)} disabled={state.showCorrect} className={`text-left p-14 rounded-[4.5rem] transition-all font-black text-4xl flex items-center gap-12 small-kh ${style} ${shakeIndex === i ? 'animate-bounce' : ''}`}>
                <span className={`w-24 h-24 rounded-[2rem] flex items-center justify-center font-black text-6xl shrink-0 shadow-2xl border-4 ${state.showCorrect && i === currentQ.correct ? 'bg-white text-emerald-600' : 'bg-maroon text-white border-maroon-dark'}`}>{KHMER_PREFIXES[i]}</span>
                <span className="flex-1 leading-relaxed">{opt}</span>
              </button>
            );
          })}
        </div>
      </div>

      {state.showCorrect && (
        <button onClick={handleNext} className="mt-32 w-full btn-red-sharp py-14 rounded-[5rem] text-5xl font-black heading-kh uppercase tracking-widest">
          {state.currentQuestionIndex + 1 === partQuestions.length ? "មើលលទ្ធផល 🏁" : "សំណួរបន្ទាប់ ✨"}
        </button>
      )}
    </div>
  );
};

export default QuizGame;

