import * as React from 'react';
import { useState, useMemo, useRef, useEffect } from 'react';
import { Question, QuizState } from '../types';

interface QuizGameProps {
  subject: string;
  partIndex: number;
  type: 'mcq' | 'short';
  allSubjectQuestions: Question[];
  onExit: () => void;
  onStartNextPart?: (newPartIndex: number) => void;
}

const QuizGame: React.FC<QuizGameProps> = ({ subject, partIndex, type, allSubjectQuestions, onExit, onStartNextPart }) => {
  const KHMER_PREFIXES = ['ក', 'ខ', 'គ', 'ឃ'];
  const KHMER_DIGITS = ['០', '១', '២', '៣', '៤', '៥', '៦', '៧', '៨', '៩'];
  const toKhmerNumeral = (n: number) => n.toString().split('').map(digit => KHMER_DIGITS[parseInt(digit)] || digit).join('');

  const [isMuted, setIsMuted] = useState(false);
  const correctAudioRef = useRef<HTMLAudioElement | null>(null);
  const wrongAudioRef = useRef<HTMLAudioElement | null>(null);

  useEffect(() => {
    correctAudioRef.current = new Audio('https://assets.mixkit.co/active_storage/sfx/600/600-preview.mp3');
    wrongAudioRef.current = new Audio('https://assets.mixkit.co/active_storage/sfx/951/951-preview.mp3');
    return () => {
      correctAudioRef.current?.pause();
      wrongAudioRef.current?.pause();
    };
  }, []);

  const partQuestions = useMemo(() => {
    const start = partIndex * 10;
    const subset = allSubjectQuestions.slice(start, start + 10);
    if (type === 'mcq') {
      return subset.map(q => {
        if (!q.options) return q;
        const opts = q.options.map((opt, idx) => ({ text: opt, isCorrect: idx === q.correct }));
        const shuffled = [...opts].sort(() => Math.random() - 0.5);
        return { ...q, options: shuffled.map(o => o.text), correct: shuffled.findIndex(o => o.isCorrect) };
      });
    }
    return subset;
  }, [allSubjectQuestions, partIndex, type]);

  const [state, setState] = useState<QuizState>({
    currentQuestionIndex: 0, score: 0, isFinished: false, selectedAnswer: null, userInput: '', showCorrect: false, userAnswers: [], isReviewing: false
  });

  const handleMCQSelect = (idx: number) => {
    if (state.selectedAnswer !== null || state.isFinished) return;
    const isCorrect = idx === partQuestions[state.currentQuestionIndex].correct;
    if (!isMuted) {
      const audio = isCorrect ? correctAudioRef.current : wrongAudioRef.current;
      if (audio) { audio.currentTime = 0; audio.play().catch(() => {}); }
    }
    setState(prev => ({
      ...prev, selectedAnswer: idx, showCorrect: true, score: isCorrect ? prev.score + 1 : prev.score, userAnswers: [...prev.userAnswers, idx]
    }));
  };

  const handleNext = () => {
    if (state.currentQuestionIndex + 1 < partQuestions.length) {
      setState(prev => ({ ...prev, currentQuestionIndex: prev.currentQuestionIndex + 1, selectedAnswer: null, showCorrect: false }));
    } else setState(prev => ({ ...prev, isFinished: true }));
  };

  if (state.isFinished) {
    const percentage = Math.round((state.score / partQuestions.length) * 100);
    return (
      <div className="page-transition max-w-lg mx-auto py-12 px-2">
        <div className="card-white-elegant p-10 text-center border-t-8 border-maroon">
          <div className="text-8xl mb-8 animate-bounce">🏆</div>
          <h2 className="text-3xl font-black mb-4 heading-kh text-maroon">លទ្ធផល</h2>
          <div className="text-7xl font-black text-indigo-950 my-8">{toKhmerNumeral(percentage)}%</div>
          <p className="text-lg mb-10 small-kh text-indigo-900 font-bold">ត្រូវ {toKhmerNumeral(state.score)} / {toKhmerNumeral(partQuestions.length)}</p>
          <button onClick={onExit} className="btn-red-elegant w-full py-5 rounded-2xl font-black text-xl heading-kh uppercase">មឺនុយមេ 🏠</button>
        </div>
      </div>
    );
  }

  const currentQ = partQuestions[state.currentQuestionIndex];
  return (
    <div className="card-white-elegant p-6 md:p-12 page-transition flex flex-col min-h-[650px] relative border-b-8 border-indigo-900">
      <div className="flex justify-between items-center mb-8 relative z-10 border-b border-gray-100 pb-4">
        <div className="flex flex-col">
          <span className="text-maroon font-black text-[9px] uppercase tracking-widest mb-1 px-3 py-1 bg-red-50 rounded-full w-fit">{subject}</span>
          <div className="flex items-end gap-2">
             <span className="text-5xl leading-none font-black text-indigo-950">{toKhmerNumeral(state.currentQuestionIndex + 1)}</span>
             <span className="text-xl font-black text-gray-300 mb-1">/ {toKhmerNumeral(partQuestions.length)}</span>
          </div>
        </div>

        <div className="flex items-center gap-3">
          <button onClick={() => setIsMuted(!isMuted)} className="w-10 h-10 bg-white shadow-sm rounded-lg flex items-center justify-center text-xl border border-gray-200">{isMuted ? '🔇' : '🔊'}</button>
          <div className="bg-indigo-950 text-white px-6 py-2 rounded-xl shadow-lg font-black text-xl">ពិន្ទុ៖ {toKhmerNumeral(state.score)}</div>
        </div>
      </div>

      <div className="flex-1 flex flex-col relative z-10">
        <h2 className="text-2xl md:text-3xl font-black mb-10 heading-kh text-indigo-950 leading-relaxed text-justify">{currentQ?.question}</h2>
        <div className="grid grid-cols-1 gap-4">
          {currentQ?.options?.map((opt, i) => {
            let style = "bg-gray-50 border-2 border-gray-200 text-indigo-950 shadow-sm";
            if (state.showCorrect) {
              if (i === currentQ.correct) style = "bg-emerald-600 border-emerald-700 text-white shadow-lg scale-[1.02] z-20";
              else if (i === state.selectedAnswer) style = "bg-red-700 border-red-800 text-white opacity-100";
              else style = "opacity-20 grayscale";
            }
            return (
              <button key={i} onClick={() => handleMCQSelect(i)} disabled={state.showCorrect} className={`text-left p-4 rounded-2xl transition-all font-black text-lg flex items-center gap-5 small-kh ${style}`}>
                <span className={`w-10 h-10 rounded-lg flex items-center justify-center font-black text-xl shrink-0 border-2 ${state.showCorrect && i === currentQ.correct ? 'bg-white text-emerald-600' : 'bg-maroon text-white border-maroon-dark'}`}>{KHMER_PREFIXES[i]}</span>
                <span className="flex-1 leading-snug">{opt}</span>
              </button>
            );
          })}
        </div>
      </div>

      {state.showCorrect && (
        <button onClick={handleNext} className="mt-10 w-full btn-red-elegant py-5 rounded-2xl text-2xl font-black heading-kh uppercase tracking-widest">
          {state.currentQuestionIndex + 1 === partQuestions.length ? "បញ្ចប់ 🏁" : "បន្ទាប់ ✨"}
        </button>
      )}
    </div>
  );
};

export default QuizGame;

import * as React from 'react';
import { useState, useEffect, useCallback, useRef } from 'react';
import { Question, AppMode, SelectedQuizInfo, UserRole, Feedback } from './types';
import { INITIAL_QUESTIONS, SECRET_CODE } from './constants';
import Header from './components/Header';
import AuthSection from './components/AuthSection';
import CreateSection from './components/CreateSection';
import PlaySection from './components/PlaySection';
import QuizGame from './components/QuizGame';
import { initFirebase, syncQuestionsToFirebase, listenToQuestions, listenToFeedback, removeFeedback } from './services/firebaseService';

const App: React.FC = () => {
  const [quizData, setQuizData] = useState<Question[]>([]);
  const [feedbackList, setFeedbackList] = useState<Feedback[]>([]);
  const [mode, setMode] = useState<AppMode>('play');
  const [userRole, setUserRole] = useState<UserRole>(null);
  const [username, setUsername] = useState<string>('');
  const [activeQuiz, setActiveQuiz] = useState<SelectedQuizInfo | null>(null);
  const [isInitialized, setIsInitialized] = useState(false);
  const [isCloudConnected, setIsCloudConnected] = useState<boolean | 'error'>(false);
  const isListeningRef = useRef(false);

  const sanitizeQuestions = useCallback((data: any[]): Question[] => {
    if (!Array.isArray(data)) return [];
    return data.filter(q => q && typeof q === 'object').map(q => {
      const type = q.type === 'short' ? 'short' : 'mcq';
      if (type === 'mcq') {
        return {
          subject: String(q.subject || 'មិនមានមុខវិជ្ជា'),
          question: String(q.question || ''),
          type: 'mcq',
          options: Array.isArray(q.options) ? q.options.map((o: any) => String(o || '')) : ['', '', '', ''],
          correct: typeof q.correct === 'number' ? q.correct : 0,
          isActive: q.isActive !== false
        };
      } else {
        return {
          subject: String(q.subject || 'មិនមានមុខវិជ្ជា'),
          question: String(q.question || ''),
          type: 'short',
          answer: String(q.answer || ''),
          isActive: q.isActive !== false
        };
      }
    }) as Question[];
  }, []);

  const saveToLocal = useCallback((data: Question[]) => {
    try {
      localStorage.setItem('quiz_data', JSON.stringify(sanitizeQuestions(data)));
    } catch (e) { console.error(e); }
  }, [sanitizeQuestions]);

  useEffect(() => {
    if (isListeningRef.current) return;
    isListeningRef.current = true;
    initFirebase();
    const saved = localStorage.getItem('quiz_data');
    if (saved) { try { setQuizData(sanitizeQuestions(JSON.parse(saved))); } catch(e){} }

    const unsubscribeQuestions = listenToQuestions((remoteData) => {
      const cleaned = sanitizeQuestions(remoteData);
      setQuizData(cleaned);
      saveToLocal(cleaned);
      setIsCloudConnected(true);
      setIsInitialized(true);
    }, (error) => {
      setIsCloudConnected('error');
      setIsInitialized(true);
    });

    let unsubscribeFeedback = () => {};
    if (userRole === 'admin') unsubscribeFeedback = listenToFeedback((fbs) => setFeedbackList(fbs)) || (() => {});
    return () => { unsubscribeQuestions(); unsubscribeFeedback(); isListeningRef.current = false; };
  }, [sanitizeQuestions, saveToLocal, userRole]);

  const handleSyncData = (newData: Question[]) => {
    const sanitized = sanitizeQuestions(newData);
    setQuizData(sanitized);
    saveToLocal(sanitized);
    if (userRole === 'admin') syncQuestionsToFirebase(sanitized).then(() => setIsCloudConnected(true)).catch(() => setIsCloudConnected('error'));
  };

  if (!isInitialized) return null;

  if (!userRole) {
    return (
      <div className="min-h-screen py-8 px-4 flex flex-col items-center justify-center page-transition">
        <div className="text-center mb-10">
          <h1 className="text-3xl md:text-5xl font-black heading-kh text-white leading-tight drop-shadow-xl">
             ត្រៀមប្រឡង<br/>
             <span className="text-yellow-400">ក្របខ័ណ្ឌរដ្ឋ</span>
          </h1>
          <p className="small-kh text-white/50 text-xs mt-4 uppercase tracking-[0.2em]">Master Quiz Platform</p>
        </div>
        <AuthSection onLogin={(role, uName) => { setUserRole(role); if(uName) setUsername(uName); }} secretCode={SECRET_CODE} />
      </div>
    );
  }

  return (
    <div className="min-h-screen py-6 px-4 md:py-10 page-transition">
      <div className="max-w-4xl mx-auto">
        <Header mode={mode} role={userRole} totalQuestions={quizData.length} cloudStatus={isCloudConnected} setMode={(m) => { setMode(m); setActiveQuiz(null); }} onLogout={() => { setUserRole(null); setUsername(''); }} />
        <main className="mt-6">
          {mode === 'play' ? (
            activeQuiz ? (
              <QuizGame key={`quiz-${activeQuiz.subject}-${activeQuiz.partIndex}`} subject={activeQuiz.subject} partIndex={activeQuiz.partIndex} type={activeQuiz.type} allSubjectQuestions={activeQuiz.customQuestions || quizData.filter(q => q.subject === activeQuiz.subject && q.type === activeQuiz.type)} onExit={() => setActiveQuiz(null)} onStartNextPart={(idx) => setActiveQuiz(prev => prev ? { ...prev, partIndex: idx } : null)} />
            ) : (
              <PlaySection username={username} quizData={quizData} onStartQuiz={(subject, partIndex, type, customQuestions, isMixed) => setActiveQuiz({ subject, partIndex, type, customQuestions, isMixed })} />
            )
          ) : (
            <CreateSection quizData={quizData} feedbackList={feedbackList} onDeleteFeedback={removeFeedback} onAdd={(q) => handleSyncData([...quizData, q])} onUpdate={(i, q) => handleSyncData(quizData.map((old, idx) => idx === i ? q : old))} onRemove={(i) => handleSyncData(quizData.filter((_, idx) => idx !== i))} onToggleSubject={(sub, type, act) => handleSyncData(quizData.map(q => (q.subject === sub && q.type === type) ? { ...q, isActive: act } : q))} onUpdateSubject={(old, type, newName) => handleSyncData(quizData.map(q => (q.subject === old && q.type === type) ? { ...q, subject: newName.trim() } : q))} onRemoveSubject={(sub, type) => handleSyncData(quizData.filter(q => !(q.subject === sub && q.type === type)))} onReorderSubject={(sub, type, dir) => { /* logic inside App.tsx or already exists */ }} onBatchAdd={(qs) => handleSyncData([...quizData, ...qs])} onLogout={() => { setUserRole(null); setUsername(''); }} />
          )}
        </main>
      </div>
    </div>
  );
};

export default App;

