import * as React from 'react';
import { useState, useMemo, useRef, useEffect } from 'react';
import { Question, QuizState } from '../types';

interface QuizGameProps {
  subject: string;
  partIndex: number;
  type: 'mcq' | 'short';
  allSubjectQuestions: Question[];
  onExit: () => void;
  onStartNextPart?: (newPartIndex: number) => void;
}

const QuizGame: React.FC<QuizGameProps> = ({ subject, partIndex, type, allSubjectQuestions, onExit, onStartNextPart }) => {
  const KHMER_PREFIXES = ['ក', 'ខ', 'គ', 'ឃ'];
  const KHMER_DIGITS = ['០', '១', '២', '៣', '៤', '៥', '៦', '៧', '៨', '៩'];
  const toKhmerNumeral = (n: number) => n.toString().split('').map(digit => KHMER_DIGITS[parseInt(digit)] || digit).join('');

  const [isMuted, setIsMuted] = useState(false);
  const correctAudioRef = useRef<HTMLAudioElement | null>(null);
  const wrongAudioRef = useRef<HTMLAudioElement | null>(null);

  useEffect(() => {
    correctAudioRef.current = new Audio('https://assets.mixkit.co/active_storage/sfx/600/600-preview.mp3');
    wrongAudioRef.current = new Audio('https://assets.mixkit.co/active_storage/sfx/951/951-preview.mp3');
    return () => { correctAudioRef.current?.pause(); wrongAudioRef.current?.pause(); };
  }, []);

  const partQuestions = useMemo(() => {
    const start = partIndex * 10;
    const subset = allSubjectQuestions.slice(start, start + 10);
    if (type === 'mcq') {
      return subset.map(q => {
        if (!q.options) return q;
        const opts = q.options.map((opt, idx) => ({ text: opt, isCorrect: idx === q.correct }));
        const shuffled = [...opts].sort(() => Math.random() - 0.5);
        return { ...q, options: shuffled.map(o => o.text), correct: shuffled.findIndex(o => o.isCorrect) };
      });
    }
    return subset;
  }, [allSubjectQuestions, partIndex, type]);

  const [state, setState] = useState<QuizState>({
    currentQuestionIndex: 0, score: 0, isFinished: false, selectedAnswer: null, userInput: '', showCorrect: false, userAnswers: [], isReviewing: false
  });

  const handleMCQSelect = (idx: number) => {
    if (state.selectedAnswer !== null || state.isFinished) return;
    const isCorrect = idx === partQuestions[state.currentQuestionIndex].correct;
    if (!isMuted) {
      const audio = isCorrect ? correctAudioRef.current : wrongAudioRef.current;
      if (audio) { audio.currentTime = 0; audio.play().catch(() => {}); }
    }
    setState(prev => ({
      ...prev, selectedAnswer: idx, showCorrect: true, score: isCorrect ? prev.score + 1 : prev.score, userAnswers: [...prev.userAnswers, idx]
    }));
  };

  const handleNext = () => {
    if (state.currentQuestionIndex + 1 < partQuestions.length) {
      setState(prev => ({ ...prev, currentQuestionIndex: prev.currentQuestionIndex + 1, selectedAnswer: null, showCorrect: false }));
    } else setState(prev => ({ ...prev, isFinished: true }));
  };

  if (state.isFinished) {
    const percentage = Math.round((state.score / partQuestions.length) * 100);
    return (
      <div className="page-transition max-w-md mx-auto py-10 px-2">
        <div className="card-white-elegant p-8 text-center border-t-4 border-maroon">
          <div className="text-6xl mb-6">🏆</div>
          <h2 className="text-xl font-black mb-2 heading-kh text-maroon">លទ្ធផលតេស្ត</h2>
          <div className="text-6xl font-black text-indigo-950 my-6">{toKhmerNumeral(percentage)}%</div>
          <p className="text-sm mb-8 small-kh text-indigo-900 font-bold opacity-60">ត្រូវ {toKhmerNumeral(state.score)} / {toKhmerNumeral(partQuestions.length)}</p>
          <button onClick={onExit} className="btn-red-elegant w-full py-4 text-base heading-kh">ត្រឡប់ទៅមឺនុយ 🏠</button>
        </div>
      </div>
    );
  }

  const currentQ = partQuestions[state.currentQuestionIndex];
  return (
    <div className="card-white-elegant p-5 md:p-10 page-transition flex flex-col min-h-[550px] relative border-b-4 border-indigo-900">
      <div className="flex justify-between items-center mb-6 border-b border-gray-50 pb-4">
        <div className="flex flex-col">
          <span className="text-maroon font-black text-[8px] uppercase tracking-widest bg-red-50 px-3 py-1 rounded-lg w-fit mb-1">{subject}</span>
          <div className="flex items-end gap-1">
             <span className="text-4xl leading-none font-black text-indigo-950">{toKhmerNumeral(state.currentQuestionIndex + 1)}</span>
             <span className="text-lg font-black text-gray-300">/ {toKhmerNumeral(partQuestions.length)}</span>
          </div>
        </div>
        <div className="flex items-center gap-2">
          <button onClick={() => setIsMuted(!isMuted)} className="w-8 h-8 bg-gray-50 rounded-lg flex items-center justify-center text-lg border border-gray-200">{isMuted ? '🔇' : '🔊'}</button>
          <div className="bg-indigo-950 text-white px-4 py-1.5 rounded-lg font-black text-lg">ពិន្ទុ៖ {toKhmerNumeral(state.score)}</div>
        </div>
      </div>

      <div className="flex-1 flex flex-col">
        <h2 className="text-lg md:text-2xl font-black mb-8 heading-kh text-indigo-950 leading-relaxed text-justify">{currentQ?.question}</h2>
        <div className="grid grid-cols-1 gap-3">
          {currentQ?.options?.map((opt, i) => {
            let style = "bg-gray-50 border border-gray-200 text-indigo-950";
            if (state.showCorrect) {
              if (i === currentQ.correct) style = "bg-emerald-600 border-emerald-700 text-white shadow-md scale-[1.01] z-10";
              else if (i === state.selectedAnswer) style = "bg-red-700 border-red-800 text-white opacity-100";
              else style = "opacity-25 grayscale";
            }
            return (
              <button key={i} onClick={() => handleMCQSelect(i)} disabled={state.showCorrect} className={`text-left p-3.5 rounded-xl transition-all font-black text-sm flex items-center gap-4 small-kh ${style}`}>
                <span className={`w-8 h-8 rounded-lg flex items-center justify-center font-black text-base shrink-0 border ${state.showCorrect && i === currentQ.correct ? 'bg-white text-emerald-600' : 'bg-maroon text-white border-maroon-dark'}`}>{KHMER_PREFIXES[i]}</span>
                <span className="flex-1 leading-snug">{opt}</span>
              </button>
            );
          })}
        </div>
      </div>

      {state.showCorrect && (
        <button onClick={handleNext} className="mt-8 w-full btn-red-elegant py-4 text-xl heading-kh uppercase">
          {state.currentQuestionIndex + 1 === partQuestions.length ? "មើលលទ្ធផល 🏁" : "បន្ទាប់ ✨"}
        </button>
      )}
    </div>
  );
};

