import * as React from 'react';
import { useState, useEffect, useCallback, useRef } from 'react';
import { Question, AppMode, SelectedQuizInfo, UserRole, Feedback } from './types';
import { INITIAL_QUESTIONS, SECRET_CODE } from './constants';
import Header from './components/Header';
import AuthSection from './components/AuthSection';
import CreateSection from './components/CreateSection';
import PlaySection from './components/PlaySection';
import QuizGame from './components/QuizGame';
import { initFirebase, syncQuestionsToFirebase, listenToQuestions, listenToFeedback, removeFeedback } from './services/firebaseService';

const App: React.FC = () => {
  const [quizData, setQuizData] = useState<Question[]>([]);
  const [feedbackList, setFeedbackList] = useState<Feedback[]>([]);
  const [mode, setMode] = useState<AppMode>('play');
  const [userRole, setUserRole] = useState<UserRole>(null);
  const [username, setUsername] = useState<string>('');
  const [activeQuiz, setActiveQuiz] = useState<SelectedQuizInfo | null>(null);
  const [isInitialized, setIsInitialized] = useState(false);
  const [isCloudConnected, setIsCloudConnected] = useState<boolean | 'error'>(false);
  const isListeningRef = useRef(false);

  const sanitizeQuestions = useCallback((data: any[]): Question[] => {
    if (!Array.isArray(data)) return [];
    return data.filter(q => q && typeof q === 'object').map(q => {
      const type = q.type === 'short' ? 'short' : 'mcq';
      if (type === 'mcq') {
        return {
          subject: String(q.subject || 'មិនមានមុខវិជ្ជា'),
          question: String(q.question || ''),
          type: 'mcq',
          options: Array.isArray(q.options) ? q.options.map((o: any) => String(o || '')) : ['', '', '', ''],
          correct: typeof q.correct === 'number' ? q.correct : 0,
          isActive: q.isActive !== false
        };
      } else {
        return {
          subject: String(q.subject || 'មិនមានមុខវិជ្ជា'),
          question: String(q.question || ''),
          type: 'short',
          answer: String(q.answer || ''),
          isActive: q.isActive !== false
        };
      }
    }) as Question[];
  }, []);

  const saveToLocal = useCallback((data: Question[]) => {
    try {
      localStorage.setItem('quiz_data', JSON.stringify(sanitizeQuestions(data)));
    } catch (e) { console.error(e); }
  }, [sanitizeQuestions]);

  useEffect(() => {
    if (isListeningRef.current) return;
    isListeningRef.current = true;
    initFirebase();
    const saved = localStorage.getItem('quiz_data');
    if (saved) { try { setQuizData(sanitizeQuestions(JSON.parse(saved))); } catch(e){} }

    const unsubscribeQuestions = listenToQuestions((remoteData) => {
      const cleaned = sanitizeQuestions(remoteData);
      setQuizData(cleaned);
      saveToLocal(cleaned);
      setIsCloudConnected(true);
      setIsInitialized(true);
    }, (error) => {
      setIsCloudConnected('error');
      setIsInitialized(true);
    });

    let unsubscribeFeedback = () => {};
    if (userRole === 'admin') unsubscribeFeedback = listenToFeedback((fbs) => setFeedbackList(fbs)) || (() => {});
    return () => { unsubscribeQuestions(); unsubscribeFeedback(); isListeningRef.current = false; };
  }, [sanitizeQuestions, saveToLocal, userRole]);

  const handleSyncData = (newData: Question[]) => {
    const sanitized = sanitizeQuestions(newData);
    setQuizData(sanitized);
    saveToLocal(sanitized);
    if (userRole === 'admin') syncQuestionsToFirebase(sanitized).then(() => setIsCloudConnected(true)).catch(() => setIsCloudConnected('error'));
  };

  if (!isInitialized) return null;

  if (!userRole) {
    return (
      <div className="min-h-screen py-12 px-4 flex flex-col items-center justify-center page-transition bg-slate-950">
        {/* ចំណងជើងធំលំដាប់ Hero សម្រាប់ផ្ទាំង Login */}
        <div className="text-center mb-16 relative">
          <div className="absolute -inset-10 bg-yellow-500/10 blur-[100px] rounded-full"></div>
          <h1 className="relative font-black heading-kh leading-[1] tracking-tighter">
            <span className="block text-3xl md:text-4xl text-white opacity-80 mb-2 uppercase tracking-[0.2em]">ត្រៀមប្រឡង</span>
            <span className="block text-6xl md:text-8xl bg-gradient-to-b from-yellow-200 via-yellow-400 to-yellow-600 bg-clip-text text-transparent drop-shadow-[0_8px_16px_rgba(0,0,0,0.6)]">
               ក្របខ័ណ្ឌរដ្ឋ
            </span>
          </h1>
          <div className="mt-6 flex flex-col items-center gap-3">
             <div className="h-1 w-24 bg-gradient-to-r from-transparent via-yellow-500/50 to-transparent rounded-full"></div>
             <p className="small-kh text-white/40 text-[10px] uppercase tracking-[0.4em]">Master Quiz Experience</p>
          </div>
        </div>
        <AuthSection onLogin={(role, uName) => { setUserRole(role); if(uName) setUsername(uName); }} secretCode={SECRET_CODE} />
      </div>
    );
  }

  return (
    <div className="min-h-screen py-6 px-4 md:py-10 page-transition">
      <div className="max-w-4xl mx-auto">
        <Header mode={mode} role={userRole} totalQuestions={quizData.length} cloudStatus={isCloudConnected} setMode={(m) => { setMode(m); setActiveQuiz(null); }} onLogout={() => { setUserRole(null); setUsername(''); }} />
        <main className="mt-6">
          {mode === 'play' ? (
            activeQuiz ? (
              <QuizGame key={`quiz-${activeQuiz.subject}-${activeQuiz.partIndex}`} subject={activeQuiz.subject} partIndex={activeQuiz.partIndex} type={activeQuiz.type} allSubjectQuestions={activeQuiz.customQuestions || quizData.filter(q => q.subject === activeQuiz.subject && q.type === activeQuiz.type)} onExit={() => setActiveQuiz(null)} onStartNextPart={(idx) => setActiveQuiz(prev => prev ? { ...prev, partIndex: idx } : null)} />
            ) : (
              <PlaySection username={username} quizData={quizData} onStartQuiz={(subject, partIndex, type, customQuestions, isMixed) => setActiveQuiz({ subject, partIndex, type, customQuestions, isMixed })} />
            )
          ) : (
            <CreateSection quizData={quizData} feedbackList={feedbackList} onDeleteFeedback={removeFeedback} onAdd={(q) => handleSyncData([...quizData, q])} onUpdate={(i, q) => handleSyncData(quizData.map((old, idx) => idx === i ? q : old))} onRemove={(i) => handleSyncData(quizData.filter((_, idx) => idx !== i))} onToggleSubject={(sub, type, act) => handleSyncData(quizData.map(q => (q.subject === sub && q.type === type) ? { ...q, isActive: act } : q))} onUpdateSubject={(old, type, newName) => handleSyncData(quizData.map(q => (q.subject === old && q.type === type) ? { ...q, subject: newName.trim() } : q))} onRemoveSubject={(sub, type) => handleSyncData(quizData.filter(q => !(q.subject === sub && q.type === type)))} onReorderSubject={(sub, type, dir) => { /* logic here */ }} onBatchAdd={(qs) => handleSyncData([...quizData, ...qs])} onLogout={() => { setUserRole(null); setUsername(''); }} />
          )}
        </main>
      </div>
    </div>
  );
};

export default App;

