              ? 'bg-red-700 text-white shadow-[0_0_15px_rgba(185,28,28,0.5)] scale-100' 
              : 'text-white/40 hover:text-white hover:bg-white/5'
            }`}
          >
            ⚙️ គ្រប់គ្រង
          </button>
        </div>
      )}
    </div>
  );
};

