const CreateSection: React.FC<CreateSectionProps> = ({ 
  quizData, feedbackList = [], onDeleteFeedback, onAdd, onUpdate, onRemove, onToggleSubject, onUpdateSubject, onRemoveSubject, onReorderSubject, onBatchAdd
}) => {
  const KHMER_PREFIXES = ['ក', 'ខ', 'គ', 'ឃ'];
  const KHMER_DIGITS = ['០', '១', '២', '៣', '៤', '៥', '៦', '៧', '៨', '៩'];
  const [entryMode, setEntryMode] = useState<'single' | 'bulk' | 'subjects' | 'feedback'>('single');
  const [qType, setQType] = useState<'mcq' | 'short'>('mcq');
  const [bulkType, setBulkType] = useState<'mcq' | 'short'>('mcq');
  const [subject, setSubject] = useState('');
  const [question, setQuestion] = useState('');
  const [options, setOptions] = useState(['', '', '', '']);
  const [correct, setCorrect] = useState(0);
  const [shortAnswer, setShortAnswer] = useState('');
  const [editingIndex, setEditingIndex] = useState<number | null>(null);
  const [bulkText, setBulkText] = useState('');

  // Export & Telegram States
  const [viewingExport, setViewingExport] = useState<{name: string, type: 'mcq' | 'short', mode: 'pdf' | 'image' | 'telegram'} | null>(null);
  const [tgConfig, setTgConfig] = useState<TelegramConfig>({ botToken: DEFAULT_TG_BOT_TOKEN, chatId: TG_CHANNELS[0].value });
  const [sendAsImage, setSendAsImage] = useState(false);
  const [isProcessing, setIsProcessing] = useState<number | 'all' | boolean>(false);

  // Settings
  const [pdfSettings, setPdfSettings] = useState<PdfSettings>({ showAnswerKey: true, shuffleQuestions: false, schoolName: 'វិទ្យាស្ថានបណ្តុះបណ្តាលបច្ចេកទេស', examDate: 'ឆ្នាំសិក្សា ២០ graduation-២០២៥', studentNameField: true });
  const [imageSettings, setImageSettings] = useState<ImageSettings>({ style: 'elegant', showBrand: true, brandName: 'Master Quiz KH', showAnswer: false });

  // Refs
  const imageTemplateRef = useRef<HTMLDivElement>(null);
  const pdfTemplateRef = useRef<HTMLDivElement>(null);
  const [previewQ, setPreviewQ] = useState<Question | null>(null);

  const toKhmerNumeral = (n: number) => n.toString().split('').map(digit => KHMER_DIGITS[parseInt(digit)] || digit).join('');

  const groupedSubjects = useMemo(() => {
    const getSubjectsByType = (type: 'mcq' | 'short') => {
      const seen = new Set<string>();
      const list: any[] = [];
      quizData.filter(q => q.type === type).forEach(q => {
        if (!seen.has(q.subject)) {
          seen.add(q.subject);
          const related = quizData.filter(rq => rq.subject === q.subject && rq.type === type);
          list.push({ name: q.subject, isActive: related.every(rq => rq.isActive !== false), count: related.length, type });
        }
      });
      return list;
    };
    return { mcq: getSubjectsByType('mcq'), short: getSubjectsByType('short') };
  }, [quizData]);

  const activeExportQuestions = useMemo(() => {
    if (!viewingExport) return [];
    let qs = quizData.filter(q => q.subject === viewingExport.name && q.type === viewingExport.type);
    if (viewingExport.mode === 'pdf' && pdfSettings.shuffleQuestions) {
      qs = [...qs].sort(() => Math.random() - 0.5);
    }
    return qs;
  }, [quizData, viewingExport, pdfSettings.shuffleQuestions]);

  // Export Logic: PDF
  const handleExportPdf = async () => {
    if (!pdfTemplateRef.current || !viewingExport) return;
    setIsProcessing(true);
    try {
      const opt = {
        margin: 10,
        filename: `Exam_${viewingExport.name}_${new Date().getTime()}.pdf`,
        image: { type: 'jpeg', quality: 0.98 },
        html2canvas: { scale: 2, useCORS: true },
        jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' }
      };
      await html2pdf().from(pdfTemplateRef.current).set(opt).save();
    } catch (e) {
      alert("កំហុសក្នុងការបង្កើត PDF");
    } finally {
      setIsProcessing(false);
    }
  };

  const captureImage = async (): Promise<Blob | null> => {
    if (!imageTemplateRef.current) return null;
    await document.fonts.ready;
    await new Promise(r => setTimeout(r, 1200)); 

    try {
      const canvas = await html2canvas(imageTemplateRef.current, {
        scale: 3,
        useCORS: true,
        allowTaint: true,
        backgroundColor: imageSettings.style === 'dark' ? '#121212' : '#ffffff',
        logging: false,
        onclone: (clonedDoc) => {
          const head = clonedDoc.head;
          const style = clonedDoc.createElement('style');
          style.innerHTML = `
            @import url('https://fonts.googleapis.com/css2?family=Kantumruy+Pro:wght@400;700&family=Siemreap&display=swap');
            * { -webkit-font-smoothing: antialiased; -moz-osx-font-smoothing: grayscale; }
            .question-text-capture { font-family: ${KHMER_FONT_STACK} !important; line-height: 2.2 !important; }
            .option-text-capture { font-family: ${KHMER_FONT_STACK} !important; line-height: 1.8 !important; }
          `;
          head.appendChild(style);
        }
      });
      return new Promise<Blob | null>(r => canvas.toBlob(r, 'image/png', 1.0));
    } catch (e) {
      console.error("Capture Error:", e);
      return null;
    }
  };

  const handleExportImageZip = async () => {
    if (!viewingExport) return;
    setIsProcessing(true);
    const zip = new JSZip();
    try {
      for (let i = 0; i < activeExportQuestions.length; i++) {
        const q = activeExportQuestions[i];
        setPreviewQ(q);
        const blob = await captureImage();
        if (blob) zip.file(`Question_${i+1}.png`, blob);
      }
      const content = await zip.generateAsync({ type: "blob" });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(content);
      link.download = `Images_${viewingExport.name}.zip`;
      link.click();
    } catch (e) {
      alert("កំហុសក្នុងការបង្កើតរូបភាព ZIP");
    } finally {
      setPreviewQ(null);
      setIsProcessing(false);
    }
  };

  const handleSendToTelegram = async (q: Question, index: number | 'all') => {
    setIsProcessing(index);
    try {
      if (sendAsImage) {
        setPreviewQ(q);
        const blob = await captureImage();
        if (blob) {
          const caption = `📌 ${q.question.substring(0, 150)}...\n\nវិញ្ញាសា៖ ${q.subject}\n#QuizMasterKH 🇰🇭`;
          await sendQuestionImage(tgConfig, blob, caption);
        }
      } else {
        if (q.type === 'mcq') {
          await sendQuizPoll(tgConfig, q);
        } else {
          const text = `📌 *សំណួរ៖* ${q.question}\n\n✅ *ចម្លើយ៖* ${q.answer}\n\nវិញ្ញាសា៖ ${q.subject}\nWeb QCM 🇰🇭`;
          await fetch(`https://api.telegram.org/bot${tgConfig.botToken}/sendMessage`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ chat_id: tgConfig.chatId, text, parse_mode: 'Markdown' })
          });
        }
      }
    } catch (e) {
      console.error(e);
    } finally {
      if (index !== 'all') {
        setIsProcessing(false);
        setPreviewQ(null);
      }
    }
  };

  const handleSendAllTelegram = async () => {
    if (!confirm(`តើអ្នកចង់ផ្ញើទាំង ${activeExportQuestions.length} សំណួរទៅកាន់ Telegram មែនទេ?`)) return;
    setIsProcessing('all');
    for (let i = 0; i < activeExportQuestions.length; i++) {
      await handleSendToTelegram(activeExportQuestions[i], i);
      await new Promise(r => setTimeout(r, sendAsImage ? 5000 : 2000));
    }
    setIsProcessing(false);
    setPreviewQ(null);
    alert("បានផ្ញើរួចរាល់!");
  };

  const handleSubmitSingle = () => {
    if (!subject.trim() || !question.trim()) return alert("សូមបំពេញព័ត៌មាន!");
    const cleanQ: Question = {
      subject: subject.trim(),
      question: question.trim(),
      type: qType,
      isActive: true,
      ...(qType === 'mcq' ? { options: options.map(o => o.trim()), correct } : { answer: shortAnswer.trim() })
    };
    if (editingIndex !== null) onUpdate(editingIndex, cleanQ); else onAdd(cleanQ);
    setQuestion(''); setOptions(['', '', '', '']); setShortAnswer(''); setEditingIndex(null);
  };

  const handleBulkSubmit = () => {
    if (!subject.trim() || !bulkText.trim()) return alert("សូមបំពេញព័ត៌មាន!");
    const lines = bulkText.split('\n');
    const parsed: Question[] = [];
    let current: any = null;
    let iA = false;

    if (bulkType === 'mcq') {
      lines.forEach(l => {
        const t = l.trim(); if (!t) return;
        const qm = t.match(/^[០-៩0-9]+\.\s*(.*)/);
        if (qm) {
          if (current && current.options?.length >= 2) parsed.push(current);
          current = { type: 'mcq', subject: subject.trim(), question: qm[1].trim(), options: [], correct: 0, isActive: true };
          return;
        }
        const om = t.match(/^[កខគឃ]\.\s*(.*)/);
        if (om && current) {
          let txt = om[1].replace('(ចម្លើយត្រឹមត្រូវ)', '').trim();
          current.options.push(txt);
          if (om[1].includes('(ចម្លើយត្រឹមត្រូវ)')) current.correct = current.options.length - 1;
        }
      });
      if (current && current.options?.length >= 2) parsed.push(current);
    } else {
      lines.forEach(l => {
        const t = l.trim();
        const qm = t.match(/^[០-៩0-9]+\.\s*(.*)/);
        if (qm) {
          if (current && current.answer) parsed.push(current);
          current = { type: 'short', subject: subject.trim(), question: qm[1].trim(), answer: '', isActive: true };
          iA = false; return;
        }
        const am = t.match(/^ចម្លើយ\s*[៖:]\s*(.*)/);
        if (am && current) { current.answer = am[1].trim(); iA = true; return; }
        if (iA && current) current.answer += (current.answer ? '\n' : '') + l;
      });
      if (current && current.answer) parsed.push(current);
    }
    if (parsed.length) { onBatchAdd(parsed); setBulkText(''); alert(`បានបញ្ចូល ${parsed.length} សំណួរ!`); }
  };

  return (
    <div className="space-y-8 animate-fadeIn pb-32">
      {/* Hidden Templates for Export (Same as before) */}
      <div className="fixed -left-[8000px] top-0 overflow-hidden select-none pointer-events-none">
        {/* ... (Keep existing image and pdf templates) ... */}
      </div>

      {/* Main UI Tabs - កែសម្រួលឱ្យទៅជា Bar ពណ៌ក្រហម */}
      <div className="glass-card rounded-[2.5rem] shadow-xl p-6 border border-white/50">

        {/* Tab Bar Navigation */}
        <div className="bg-gray-100/80 p-1.5 rounded-2xl flex flex-wrap md:flex-nowrap gap-1 mb-10 border border-gray-200 shadow-inner">
          {[
            { id: 'single', label: '✍️ បញ្ចូលសំណួរ' },
            { id: 'bulk', label: '🚀 បញ្ចូលទាំងអស់' },
            { id: 'subjects', label: '📚 គ្រប់គ្រងទិន្នន័យ' },
            { id: 'feedback', label: '💬 មតិយោបល់' }
          ].map(tab => (
            <button 
              key={tab.id} 
              onClick={() => setEntryMode(tab.id as any)} 
              className={`flex-1 min-w-[140px] py-3.5 px-4 rounded-xl font-black heading-kh text-[11px] transition-all duration-300 relative ${
                entryMode === tab.id 
                ? 'bg-red-700 text-white shadow-lg scale-[1.02] z-10' 
                : 'text-gray-500 hover:text-red-700 hover:bg-white/50'
              }`}
            >
              <span className="relative flex items-center justify-center gap-2">
                {tab.label}
                {tab.id === 'feedback' && feedbackList.length > 0 && (
                  <span className="bg-white text-red-700 text-[8px] px-2 py-0.5 rounded-full border border-red-700/20">
                    {feedbackList.length}
                  </span>
                )}
              </span>
            </button>
          ))}
        </div>

        {/* Tab Content */}
        <div className="px-2">
          {entryMode === 'single' && (
            <div className="space-y-6 animate-fadeIn">
              <div className="flex flex-wrap gap-4 items-center justify-between">
                <h2 className="text-xl font-black heading-kh text-maroon flex items-center gap-2"><span>{editingIndex !== null ? '✏️' : '🆕'}</span>{editingIndex !== null ? 'កែសម្រួលសំណួរ' : 'បង្កើតសំណួរថ្មី'}</h2>
                <div className="flex bg-gray-100 p-1 rounded-xl">
                  {['mcq', 'short'].map(t => (
                    <button key={t} onClick={() => setQType(t as any)} className={`px-4 py-2 rounded-lg text-[10px] font-black uppercase transition-all ${qType === t ? 'bg-white text-maroon shadow-sm' : 'text-gray-400'}`}>{t === 'mcq' ? 'QCM' : 'Q & A'}</button>
                  ))}
                </div>
              </div>
              <div className="grid grid-cols-1 gap-5">
                <input type="text" value={subject} onChange={(e) => setSubject(e.target.value)} className="w-full px-6 py-4 rounded-2xl border border-gray-100 outline-none focus:ring-2 focus:ring-maroon heading-kh bg-gray-50/50" placeholder="ឈ្មោះមុខវិជ្ជា..." />
                <textarea value={question} onChange={(e) => setQuestion(e.target.value)} className="w-full px-6 py-4 rounded-2xl border border-gray-100 focus:ring-2 focus:ring-maroon outline-none min-h-[120px] small-kh bg-gray-50/50" placeholder="សរសេរសំណួរ..." />
                {qType === 'mcq' ? (
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    {options.map((opt, i) => (
                      <div key={i} className="flex items-center gap-3 bg-white p-4 rounded-2xl border border-gray-100 shadow-sm focus-within:border-maroon/30">
                        <span className="font-black text-maroon w-10 h-10 flex items-center justify-center bg-maroon/5 rounded-xl">{KHMER_PREFIXES[i]}</span>
                        <input type="text" value={opt} onChange={(e) => { const n = [...options]; n[i] = e.target.value; setOptions(n); }} className="flex-1 outline-none small-kh text-sm" placeholder={`ចម្លើយទី ${i+1}`} />
                        <button onClick={() => setCorrect(i)} className={`w-8 h-8 rounded-lg flex items-center justify-center border-2 transition-all ${correct === i ? 'bg-green-500 border-green-500 text-white' : 'border-gray-100 text-gray-200'}`}>✓</button>
                      </div>
                    ))}
                  </div>
                ) : (
                  <textarea value={shortAnswer} onChange={(e) => setShortAnswer(e.target.value)} className="w-full px-6 py-4 rounded-2xl border border-gray-100 outline-none focus:ring-2 focus:ring-maroon small-kh bg-gray-50/50 min-h-[100px]" placeholder="បញ្ចូលចម្លើយត្រឹមត្រូវ..." />
                )}
              </div>
              <button onClick={handleSubmitSingle} className="w-full bg-maroon text-white font-black py-5 rounded-[2rem] shadow-xl hover:brightness-110 transition-all heading-kh text-lg">រក្សាទុកសំណួរ</button>
            </div>
          )}

          {entryMode === 'bulk' && (
            <div className="space-y-6 animate-fadeIn">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <input type="text" value={subject} onChange={(e) => setSubject(e.target.value)} className="w-full px-6 py-4 rounded-2xl border border-gray-100 outline-none focus:ring-2 focus:ring-maroon heading-kh bg-gray-50/50" placeholder="ឈ្មោះមុខវិជ្ជា..." />
                <div className="flex bg-gray-100 p-1 rounded-2xl"><button onClick={() => setBulkType('mcq')} className={`flex-1 rounded-xl text-[10px] font-black uppercase transition-all ${bulkType === 'mcq' ? 'bg-white text-blue-700 shadow-sm' : 'text-gray-400'}`}>QCM</button><button onClick={() => setBulkType('short')} className={`flex-1 rounded-xl text-[10px] font-black uppercase transition-all ${bulkType === 'short' ? 'bg-white text-orange-700 shadow-sm' : 'text-gray-400'}`}>Q & A</button></div>
              </div>
              <textarea value={bulkText} onChange={(e) => setBulkText(e.target.value)} className="w-full px-6 py-6 rounded-[2rem] border border-gray-100 min-h-[400px] small-kh text-xs bg-gray-50/50 outline-none focus:ring-2 focus:ring-maroon" placeholder="ចម្លងកម្រងសំណួរដាក់ទីនេះ (1. សំណួរ... ក. ចម្លើយ...)" />
              <button onClick={handleBulkSubmit} className="w-full bg-maroon text-white font-black py-5 rounded-[2rem] shadow-xl hover:brightness-110 transition-all heading-kh text-lg">ចាប់ផ្ដើមនាំចូល</button>
            </div>
          )}

          {entryMode === 'subjects' && (
            <div className="animate-fadeIn space-y-12">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                {groupedSubjects.mcq.map((s, i) => <SubjectCard key={`m-${i}`} sub={s} isFirst={i === 0} isLast={i === groupedSubjects.mcq.length - 1} onToggleSubject={onToggleSubject} onEditSubject={() => {}} onRemoveSubject={onRemoveSubject} onReorderSubject={onReorderSubject} onOpenExport={(name, type, mode) => setViewingExport({name, type, mode})} />)}
                {groupedSubjects.short.map((s, i) => <SubjectCard key={`s-${i}`} sub={s} isFirst={i === 0} isLast={i === groupedSubjects.short.length - 1} onToggleSubject={onToggleSubject} onEditSubject={() => {}} onRemoveSubject={onRemoveSubject} onReorderSubject={onReorderSubject} onOpenExport={(name, type, mode) => setViewingExport({name, type, mode})} />)}
              </div>
            </div>
          )}

          {entryMode === 'feedback' && (
            <div className="animate-fadeIn space-y-8">
              <h2 className="text-2xl font-black heading-kh text-maroon flex items-center gap-3">💬 មតិយោបល់</h2>
              {feedbackList.length ? feedbackList.map(fb => (
                <div key={fb.id} className="glass-card rounded-[2rem] p-8 border border-gray-100 shadow-sm relative group">
                  <div className="flex justify-between items-center mb-4">
                    <div className="flex items-center gap-4">
                      <div className="w-12 h-12 rounded-2xl bg-maroon/5 text-maroon flex items-center justify-center font-black">{(fb.username || 'A')[0]}</div>
                      <div><h4 className="font-black heading-kh text-maroon">{fb.username}</h4><p className="text-[10px] text-gray-400">{new Date(fb.createdAt).toLocaleString()}</p></div>
                    </div>
                    <button onClick={() => fb.id && onDeleteFeedback && onDeleteFeedback(fb.id)} className="p-2 text-red-500 hover:bg-red-50 rounded-lg">🗑️</button>
                  </div>
                  <p className="small-kh text-gray-700 leading-relaxed bg-white/50 p-6 rounded-2xl">{fb.text}</p>
                </div>
              )) : <div className="text-center py-20 text-gray-400">មិនមានមតិយោបល់</div>}
            </div>
          )}
        </div>
      </div>

      {/* Export Modals (Same as before) */}
      {viewingExport && (
        // ... (Modal code remains identical to maintain functionality)
      )}
    </div>
  );
};

