                </div>
              )) : <div className="text-center py-20 text-gray-400">មិនមានមតិយោបល់</div>}
            </div>
          )}
        </div>
      </div>

      {/* បិទ Modal Export ប្រសិនបើមិនប្រើ */}
      {viewingExport && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-[100] p-4">
          <div className="bg-white p-8 rounded-3xl max-w-sm w-full text-center">
            <h3 className="heading-kh text-xl mb-4">ការនាំចេញទិន្នន័យ</h3>
            <p className="small-kh text-gray-500 mb-6">មុខងារនាំចេញកំពុងស្ថិតក្រោមការរៀបចំ...</p>
            <button onClick={() => setViewingExport(null)} className="w-full py-3 bg-[#800000] text-white rounded-xl heading-kh">យល់ព្រម</button>
          </div>
        </div>
      )}
    </div>
  );
};

