import * as React from 'react';
import { useState, useEffect, useCallback, useRef } from 'react';
import { Question, AppMode, SelectedQuizInfo, UserRole, Feedback } from './types';
import { INITIAL_QUESTIONS, SECRET_CODE } from './constants';
import Header from './components/Header';
import AuthSection from './components/AuthSection';
import CreateSection from './components/CreateSection';
import PlaySection from './components/PlaySection';
import QuizGame from './components/QuizGame';
import { initFirebase, syncQuestionsToFirebase, listenToQuestions, listenToFeedback, removeFeedback } from './services/firebaseService';

const App: React.FC = () => {
  const [quizData, setQuizData] = useState<Question[]>([]);
  const [feedbackList, setFeedbackList] = useState<Feedback[]>([]);
  const [mode, setMode] = useState<AppMode>('play');
  const [userRole, setUserRole] = useState<UserRole>(null);
  const [username, setUsername] = useState<string>('');
  const [activeQuiz, setActiveQuiz] = useState<SelectedQuizInfo | null>(null);
  const [isInitialized, setIsInitialized] = useState(false);
  const [isCloudConnected, setIsCloudConnected] = useState<boolean | 'error'>(false);
  const isListeningRef = useRef(false);

  const APP_LOGO_URL = "https://i.postimg.cc/0ygmLdvR/3QCM_Ep4.png";

  const sanitizeQuestions = useCallback((data: any[]): Question[] => {
    if (!Array.isArray(data)) return [];
    return data.filter(q => q && typeof q === 'object').map(q => {
      const type = q.type === 'short' ? 'short' : 'mcq';
      return {
        subject: String(q.subject || 'មិនមានមុខវិជ្ជា'),
        question: String(q.question || ''),
        type,
        options: type === 'mcq' ? (Array.isArray(q.options) ? q.options.map((o: any) => String(o || '')) : ['', '', '', '']) : undefined,
        correct: type === 'mcq' ? (typeof q.correct === 'number' ? q.correct : 0) : undefined,
        answer: type === 'short' ? String(q.answer || '') : undefined,
        isActive: q.isActive !== false
      };
    }) as Question[];
  }, []);

  const saveToLocal = useCallback((data: Question[]) => {
    try {
      localStorage.setItem('quiz_data', JSON.stringify(data));
    } catch (e) { console.error(e); }
  }, []);

  useEffect(() => {
    if (isListeningRef.current) return;
    isListeningRef.current = true;
    initFirebase();
    const saved = localStorage.getItem('quiz_data');
    if (saved) { try { setQuizData(sanitizeQuestions(JSON.parse(saved))); } catch(e){} }

    const unsubscribeQuestions = listenToQuestions((remoteData) => {
      const cleaned = sanitizeQuestions(remoteData);
      setQuizData(cleaned);
      saveToLocal(cleaned);
      setIsCloudConnected(true);
      setIsInitialized(true);
    }, (error) => {
      setIsCloudConnected('error');
      setIsInitialized(true);
    });

    return () => { unsubscribeQuestions(); isListeningRef.current = false; };
  }, [sanitizeQuestions, saveToLocal]);

  useEffect(() => {
    let unsubscribeFeedback = () => {};
    if (userRole === 'admin') {
      unsubscribeFeedback = listenToFeedback((fbs) => setFeedbackList(fbs)) || (() => {});
    }
    return () => unsubscribeFeedback();
  }, [userRole]);

  const handleSyncData = (newData: Question[]) => {
    setQuizData(newData);
    saveToLocal(newData);
    if (userRole === 'admin') {
      syncQuestionsToFirebase(newData).then(() => setIsCloudConnected(true)).catch(() => setIsCloudConnected('error'));
    }
  };

  const handleReorderSubject = (subject: string, type: 'mcq' | 'short', direction: 'up' | 'down') => {
    const subjects = Array.from(new Set(quizData.filter(q => q.type === type).map(q => q.subject)));
    const index = subjects.indexOf(subject);
    if (index === -1) return;

    const newIndex = direction === 'up' ? index - 1 : index + 1;
    if (newIndex < 0 || newIndex >= subjects.length) return;

    const newSubjects = [...subjects];
    [newSubjects[index], newSubjects[newIndex]] = [newSubjects[newIndex], newSubjects[index]];

    const reorderedData: Question[] = [];
    newSubjects.forEach(s => {
      reorderedData.push(...quizData.filter(q => q.subject === s && q.type === type));
    });
    // Add back questions of other types
    reorderedData.push(...quizData.filter(q => q.type !== type));
    handleSyncData(reorderedData);
  };

  if (!isInitialized) return null;

  if (!userRole) {
    return (
      <div className="min-h-screen py-12 px-4 flex flex-col items-center justify-center page-transition bg-slate-950">
        <div className="mb-12 relative group">
          <div className="absolute inset-0 bg-red-600/30 blur-[60px] rounded-full animate-pulse"></div>
          <div className="relative w-40 h-40 md:w-48 md:h-48 bg-white p-1 rounded-full shadow-2xl border-[3px] border-red-500 transform transition-transform hover:scale-105 duration-500 animate-[bounce_3s_infinite]">
            <img src={APP_LOGO_URL} alt="Logo" className="w-full h-full object-cover rounded-full" />
          </div>
        </div>
        <div className="text-center mb-16">
          <h1 className="font-black heading-kh">
            <span className="block text-3xl md:text-4xl text-white opacity-80 mb-8 uppercase tracking-[0.25em]">ត្រៀមប្រឡង</span>
            <span className="block text-6xl md:text-8xl bg-gradient-to-b from-yellow-200 via-yellow-400 to-yellow-600 bg-clip-text text-transparent py-4">ក្របខ័ណ្ឌរដ្ឋ</span>
          </h1>
        </div>
        <AuthSection onLogin={(role, uName) => { setUserRole(role); if(uName) setUsername(uName); }} secretCode={SECRET_CODE} />
      </div>
    );
  }

  return (
    <div className="min-h-screen py-6 px-4 md:py-10 page-transition">
      <div className="max-w-4xl mx-auto">
        <Header mode={mode} role={userRole} totalQuestions={quizData.length} cloudStatus={isCloudConnected} setMode={(m) => { setMode(m); setActiveQuiz(null); }} onLogout={() => { setUserRole(null); setUsername(''); }} />
        <main className="mt-6">
          {mode === 'play' ? (
            activeQuiz ? (
              <QuizGame subject={activeQuiz.subject} partIndex={activeQuiz.partIndex} type={activeQuiz.type} allSubjectQuestions={activeQuiz.customQuestions || quizData.filter(q => q.subject === activeQuiz.subject && q.type === activeQuiz.type)} onExit={() => setActiveQuiz(null)} />
            ) : (
              <PlaySection username={username} quizData={quizData} onStartQuiz={(subject, partIndex, type, q) => setActiveQuiz({ subject, partIndex, type, customQuestions: q })} />
            )
          ) : (
            <CreateSection 
              quizData={quizData} 
              feedbackList={feedbackList} 
              onDeleteFeedback={removeFeedback} 
              onAdd={(q) => handleSyncData([...quizData, q])} 
              onUpdate={(i, q) => handleSyncData(quizData.map((old, idx) => idx === i ? q : old))} 
              onRemove={(i) => handleSyncData(quizData.filter((_, idx) => idx !== i))} 
              onToggleSubject={(sub, type, act) => handleSyncData(quizData.map(q => (q.subject === sub && q.type === type) ? { ...q, isActive: act } : q))} 
              onUpdateSubject={(old, type, newName) => handleSyncData(quizData.map(q => (q.subject === old && q.type === type) ? { ...q, subject: newName.trim() } : q))} 
              onRemoveSubject={(sub, type) => handleSyncData(quizData.filter(q => !(q.subject === sub && q.type === type)))} 
              onReorderSubject={handleReorderSubject}
              onBatchAdd={(qs) => handleSyncData([...quizData, ...qs])} 
              onLogout={() => { setUserRole(null); setUsername(''); }} 
            />
          )}
        </main>
      </div>
    </div>
  );
};

export default App;

import * as React from 'react';
import { useState, useMemo, useRef } from 'react';
import { Question, TelegramConfig, Feedback } from '../types';
import { DEFAULT_TG_BOT_TOKEN, TG_CHANNELS } from '../constants';
import html2canvas from 'html2canvas';
import { sendQuizPoll, sendQuestionImage } from '../services/telegramService';

declare var html2pdf: any;
declare var JSZip: any;

interface CreateSectionProps {
  quizData: Question[];
  feedbackList?: Feedback[];
  onDeleteFeedback?: (id: string) => void;
  onAdd: (q: Question) => void;
  onUpdate: (index: number, q: Question) => void;
  onRemove: (index: number) => void;
  onToggleSubject: (subject: string, type: 'mcq' | 'short', active: boolean) => void;
  onUpdateSubject: (subject: string, type: 'mcq' | 'short', newName: string) => void;
  onRemoveSubject: (subject: string, type: 'mcq' | 'short') => void;
  onReorderSubject: (subject: string, type: 'mcq' | 'short', direction: 'up' | 'down') => void;
  onBatchAdd: (qs: Question[]) => void;
  onLogout: () => void;
}

const SubjectCard: React.FC<{
  sub: { name: string, isActive: boolean, count: number, type: 'mcq' | 'short' };
  isFirst: boolean;
  isLast: boolean;
  onToggleSubject: (subject: string, type: 'mcq' | 'short', active: boolean) => void;
  onEditSubject: (subject: string, type: 'mcq' | 'short') => void;
  onRemoveSubject: (subject: string, type: 'mcq' | 'short') => void;
  onReorderSubject: (subject: string, type: 'mcq' | 'short', direction: 'up' | 'down') => void;
  onOpenExport: (name: string, type: 'mcq' | 'short', mode: 'pdf' | 'image' | 'telegram') => void;
}> = ({ sub, isFirst, isLast, onToggleSubject, onEditSubject, onRemoveSubject, onReorderSubject, onOpenExport }) => (
  <div className={`group glass-card p-6 rounded-[2.5rem] border transition-all flex flex-col justify-between ${sub.isActive ? 'bg-white border-white shadow-xl' : 'bg-gray-100/50 border-gray-200 grayscale opacity-60'}`}>
    <div>
      <div className="flex justify-between items-start mb-4">
        <div className="flex-1 truncate pr-2">
          <div className="flex items-center gap-2 mb-2">
            <h3 className="text-lg font-black heading-kh text-[#800000] truncate">{sub.name}</h3>
            <button onClick={() => onEditSubject(sub.name, sub.type)} className="p-1.5 bg-red-50 text-[#800000] rounded-lg hover:bg-[#800000] hover:text-white transition-all">✏️</button>
          </div>
          <div className="flex flex-wrap gap-2">
            <span className="text-[9px] font-black bg-blue-50 text-blue-600 px-3 py-1 rounded-full uppercase tracking-tighter">
              {sub.type === 'mcq' ? 'QCM' : 'Q & A'} ({sub.count})
            </span>
            <span className={`text-[9px] font-black px-3 py-1 rounded-full uppercase tracking-tighter ${sub.isActive ? 'bg-green-50 text-green-600' : 'bg-gray-200 text-gray-500'}`}>
              {sub.isActive ? 'Active' : 'Inactive'}
            </span>
          </div>
        </div>
        <div className="flex flex-col gap-1">
          <button disabled={isFirst} onClick={() => onReorderSubject(sub.name, sub.type, 'up')} className="w-8 h-8 flex items-center justify-center rounded-lg bg-white border border-gray-100 shadow-sm hover:bg-[#800000] hover:text-white disabled:opacity-20">🔼</button>
          <button disabled={isLast} onClick={() => onReorderSubject(sub.name, sub.type, 'down')} className="w-8 h-8 flex items-center justify-center rounded-lg bg-white border border-gray-100 shadow-sm hover:bg-[#800000] hover:text-white disabled:opacity-20">🔽</button>
        </div>
      </div>
    </div>

    <div className="grid grid-cols-2 gap-2 mt-4">
      <button onClick={() => onOpenExport(sub.name, sub.type, 'pdf')} className="py-2.5 bg-indigo-50 text-indigo-600 rounded-xl font-black text-[10px] hover:bg-indigo-600 hover:text-white transition-all flex items-center justify-center gap-1.5">📄 PDF</button>
      <button onClick={() => onOpenExport(sub.name, sub.type, 'image')} className="py-2.5 bg-orange-50 text-orange-600 rounded-xl font-black text-[10px] hover:bg-orange-600 hover:text-white transition-all flex items-center justify-center gap-1.5">🖼️ Image</button>
      <button onClick={() => onOpenExport(sub.name, sub.type, 'telegram')} className="col-span-2 py-3 bg-blue-600 text-white rounded-xl font-black text-[10px] hover:brightness-110 transition-all flex items-center justify-center gap-2">✈️ ផ្ញើទៅ Telegram</button>
      <div className="col-span-2 flex gap-2 pt-2">
        <button onClick={() => onToggleSubject(sub.name, sub.type, !sub.isActive)} className="flex-1 py-2 rounded-lg text-[9px] font-bold border border-gray-100 hover:bg-gray-50">{sub.isActive ? 'បិទដំណើរការ' : 'បើកដំណើរការ'}</button>
        <button onClick={() => { if(confirm('លុបវិញ្ញាសានេះ?')) onRemoveSubject(sub.name, sub.type) }} className="p-2 bg-red-50 text-red-500 rounded-lg hover:bg-red-500 hover:text-white">🗑️</button>
      </div>
    </div>
  </div>
);

const CreateSection: React.FC<CreateSectionProps> = ({ 
  quizData, feedbackList = [], onDeleteFeedback, onAdd, onUpdate, onRemove, onToggleSubject, onUpdateSubject, onRemoveSubject, onReorderSubject, onBatchAdd
}) => {
  const KHMER_PREFIXES = ['ក', 'ខ', 'គ', 'ឃ'];
  const KHMER_DIGITS = ['០', '១', '២', '៣', '៤', '៥', '៦', '៧', '៨', '៩'];
  const [entryMode, setEntryMode] = useState<'single' | 'bulk' | 'subjects' | 'feedback'>('single');
  const [qType, setQType] = useState<'mcq' | 'short'>('mcq');
  const [bulkType, setBulkType] = useState<'mcq' | 'short'>('mcq');
  const [subject, setSubject] = useState('');
  const [question, setQuestion] = useState('');
  const [options, setOptions] = useState(['', '', '', '']);
  const [correct, setCorrect] = useState(0);
  const [shortAnswer, setShortAnswer] = useState('');
  const [editingIndex, setEditingIndex] = useState<number | null>(null);
  const [bulkText, setBulkText] = useState('');
  const [viewingExport, setViewingExport] = useState<{name: string, type: 'mcq' | 'short', mode: 'pdf' | 'image' | 'telegram'} | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);

  const [tgConfig, setTgConfig] = useState<TelegramConfig>({ botToken: DEFAULT_TG_BOT_TOKEN, chatId: TG_CHANNELS[0].value });
  const [sendAsImage, setSendAsImage] = useState(false);

  const imageTemplateRef = useRef<HTMLDivElement>(null);
  const pdfTemplateRef = useRef<HTMLDivElement>(null);
  const [previewQ, setPreviewQ] = useState<Question | null>(null);

  const toKhmerNumeral = (n: number) => n.toString().split('').map(digit => KHMER_DIGITS[parseInt(digit)] || digit).join('');

  const groupedSubjects = useMemo(() => {
    const types: ('mcq' | 'short')[] = ['mcq', 'short'];
    const result = { mcq: [] as any[], short: [] as any[] };
    types.forEach(t => {
      const seen = new Set<string>();
      quizData.filter(q => q.type === t).forEach(q => {
        if (!seen.has(q.subject)) {
          seen.add(q.subject);
          const related = quizData.filter(rq => rq.subject === q.subject && rq.type === t);
          result[t].push({ name: q.subject, isActive: related.every(rq => rq.isActive !== false), count: related.length, type: t });
        }
      });
    });
    return result;
  }, [quizData]);

  const activeExportQuestions = useMemo(() => {
    if (!viewingExport) return [];
    return quizData.filter(q => q.subject === viewingExport.name && q.type === viewingExport.type);
  }, [quizData, viewingExport]);

  const handleEditSubject = (oldName: string, type: 'mcq' | 'short') => {
    const newName = prompt("បញ្ចូលឈ្មោះមុខវិជ្ជាថ្មី៖", oldName);
    if (newName && newName.trim() && newName !== oldName) {
      onUpdateSubject(oldName, type, newName.trim());
    }
  };

  const handleExportPdf = async () => {
    if (!pdfTemplateRef.current || !viewingExport) return;
    setIsProcessing(true);
    try {
      const opt = {
        margin: 10,
        filename: `Vignasa_${viewingExport.name}.pdf`,
        image: { type: 'jpeg', quality: 0.98 },
        html2canvas: { scale: 2, useCORS: true },
        jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' }
      };
      await html2pdf().from(pdfTemplateRef.current).set(opt).save();
    } catch (e) {
      alert("Error generating PDF");
    } finally {
      setIsProcessing(false);
    }
  };

  const captureImage = async (): Promise<Blob | null> => {
    if (!imageTemplateRef.current) return null;
    try {
      const canvas = await html2canvas(imageTemplateRef.current, { scale: 3, useCORS: true });
      return new Promise(r => canvas.toBlob(r, 'image/png', 1.0));
    } catch (e) { return null; }
  };

  const handleExportImageZip = async () => {
    if (!viewingExport) return;
    setIsProcessing(true);
    const zip = new JSZip();
    try {
      for (let i = 0; i < activeExportQuestions.length; i++) {
        const q = activeExportQuestions[i];
        setPreviewQ(q);
        await new Promise(r => setTimeout(r, 100)); // wait for render
        const blob = await captureImage();
        if (blob) zip.file(`Question_${i + 1}.png`, blob);
      }
      const content = await zip.generateAsync({ type: "blob" });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(content);
      link.download = `Images_${viewingExport.name}.zip`;
      link.click();
    } catch (e) {
      alert("Error generating ZIP");
    } finally {
      setPreviewQ(null);
      setIsProcessing(false);
    }
  };

  const handleSendToTelegram = async (q: Question, idx: number) => {
    try {
      if (sendAsImage) {
        setPreviewQ(q);
        await new Promise(r => setTimeout(r, 100));
        const blob = await captureImage();
        if (blob) {
          const caption = `📌 សំណួរទី ${idx + 1}\n\nវិញ្ញាសា៖ ${q.subject}\nWeb QCM 🇰🇭`;
          await sendQuestionImage(tgConfig, blob, caption);
        }
      } else {
        if (q.type === 'mcq') {
          await sendQuizPoll(tgConfig, q);
        } else {
          const text = `📌 *សំណួរ៖* ${q.question}\n\n✅ *ចម្លើយ៖* ${q.answer}\n\nវិញ្ញាសា៖ ${q.subject}`;
          await fetch(`https://api.telegram.org/bot${tgConfig.botToken}/sendMessage`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ chat_id: tgConfig.chatId, text, parse_mode: 'Markdown' })
          });
        }
      }
    } catch (e) { console.error(e); }
  };

  const handleSendAllTelegram = async () => {
    if (!confirm(`ផ្ញើទាំង ${activeExportQuestions.length} សំណួរ?`)) return;
    setIsProcessing(true);
    for (let i = 0; i < activeExportQuestions.length; i++) {
      await handleSendToTelegram(activeExportQuestions[i], i);
      await new Promise(r => setTimeout(r, 3000)); // Delay to avoid flood
    }
    setIsProcessing(false);
    setPreviewQ(null);
    alert("រួចរាល់!");
  };

  const handleSubmitSingle = () => {
    if (!subject.trim() || !question.trim()) return alert("សូមបំពេញព័ត៌មាន!");
    const cleanQ: Question = {
      subject: subject.trim(),
      question: question.trim(),
      type: qType,
      isActive: true,
      ...(qType === 'mcq' ? { options: options.map(o => o.trim()), correct } : { answer: shortAnswer.trim() })
    };
    if (editingIndex !== null) onUpdate(editingIndex, cleanQ); else onAdd(cleanQ);
    setQuestion(''); setOptions(['', '', '', '']); setShortAnswer(''); setEditingIndex(null);
    alert("រក្សាទុកជោគជ័យ!");
  };

  const handleBulkSubmit = () => {
    if (!subject.trim() || !bulkText.trim()) return alert("សូមបំពេញព័ត៌មាន!");
    const lines = bulkText.split('\n');
    const parsed: Question[] = [];
    let current: any = null;
    if (bulkType === 'mcq') {
      lines.forEach(l => {
        const t = l.trim(); if (!t) return;
        const qm = t.match(/^[០-៩0-9]+\.\s*(.*)/);
        if (qm) {
          if (current && current.options?.length >= 2) parsed.push(current);
          current = { type: 'mcq', subject: subject.trim(), question: qm[1].trim(), options: [], correct: 0, isActive: true };
          return;
        }
        const om = t.match(/^[កខគឃ]\.\s*(.*)/);
        if (om && current) {
          let txt = om[1].replace('(ចម្លើយត្រឹមត្រូវ)', '').trim();
          current.options.push(txt);
          if (om[1].includes('(ចម្លើយត្រឹមត្រូវ)')) current.correct = current.options.length - 1;
        }
      });
      if (current && current.options?.length >= 2) parsed.push(current);
    } else {
      let isAnswer = false;
      lines.forEach(l => {
        const t = l.trim(); if (!t) return;
        const qm = t.match(/^[០-៩0-9]+\.\s*(.*)/);
        if (qm) {
          if (current && current.answer) parsed.push(current);
          current = { type: 'short', subject: subject.trim(), question: qm[1].trim(), answer: '', isActive: true };
          isAnswer = false; return;
        }
        const am = t.match(/^ចម្លើយ\s*[៖:]\s*(.*)/);
        if (am && current) { current.answer = am[1].trim(); isAnswer = true; return; }
        if (isAnswer && current) current.answer += (current.answer ? '\n' : '') + l;
      });
      if (current && current.answer) parsed.push(current);
    }
    if (parsed.length) { onBatchAdd(parsed); setBulkText(''); alert(`បានបញ្ចូល ${parsed.length} សំណួរ!`); }
  };

  return (
    <div className="space-y-8 animate-fadeIn pb-32">
      {/* Hidden Templates for Export */}
      <div className="fixed -left-[8000px] top-0 pointer-events-none overflow-hidden">
        {/* PDF Template */}
        <div ref={pdfTemplateRef} style={{ width: '210mm', padding: '20mm', background: '#fff', color: '#000', fontFamily: 'Kantumruy Pro, sans-serif' }}>
          <h1 style={{ textAlign: 'center', fontSize: '24pt', marginBottom: '10mm' }}>វិញ្ញាសា៖ {viewingExport?.name}</h1>
          <hr style={{ marginBottom: '10mm' }} />
          {activeExportQuestions.map((q, i) => (
            <div key={i} style={{ marginBottom: '8mm', pageBreakInside: 'avoid' }}>
              <p style={{ fontWeight: 'bold', fontSize: '14pt' }}>សំណួរ {toKhmerNumeral(i + 1)}៖ {q.question}</p>
              {q.type === 'mcq' && q.options?.map((o, oi) => (
                <p key={oi} style={{ marginLeft: '10mm' }}>{KHMER_PREFIXES[oi]}. {o}</p>
              ))}
            </div>
          ))}
        </div>
        {/* Image Template */}
        <div ref={imageTemplateRef} style={{ width: '800px', padding: '60px', background: 'linear-gradient(135deg, #1e1b4b 0%, #020617 100%)', color: '#fff', borderRadius: '40px', border: '4px solid #800000' }}>
          <div style={{ marginBottom: '30px', display: 'flex', alignItems: 'center', gap: '20px' }}>
             <div style={{ background: '#800000', padding: '10px 20px', borderRadius: '15px', fontWeight: 'bold' }}>សំណួរ</div>
             <div style={{ fontSize: '14pt', opacity: 0.7 }}>{viewingExport?.name}</div>
          </div>
          <h2 style={{ fontSize: '28pt', marginBottom: '40px', lineHeight: 1.6 }}>{previewQ?.question}</h2>
          {previewQ?.type === 'mcq' && previewQ.options?.map((o, i) => (
            <div key={i} style={{ background: 'rgba(255,255,255,0.05)', padding: '20px', borderRadius: '20px', marginBottom: '15px', border: '1px solid rgba(255,255,255,0.1)', display: 'flex', alignItems: 'center', gap: '20px' }}>
              <span style={{ width: '40px', height: '40px', background: '#800000', display: 'flex', alignItems: 'center', justifyCenter: 'center', borderRadius: '10px' }}>{KHMER_PREFIXES[i]}</span>
              <span style={{ fontSize: '18pt' }}>{o}</span>
            </div>
          ))}
          <div style={{ marginTop: '40px', textAlign: 'center', opacity: 0.5, fontSize: '12pt' }}>Master Quiz KH | 🇰🇭 ត្រៀមប្រឡងក្របខ័ណ្ឌរដ្ឋ</div>
        </div>
      </div>

      <div className="glass-card rounded-[2.5rem] shadow-xl p-6 border border-white/50">
        <div className="bg-gray-100/80 p-1.5 rounded-2xl flex flex-wrap md:flex-nowrap gap-1 mb-10 border border-gray-200 shadow-inner">
          {[
            { id: 'single', label: '✍️ បញ្ចូលសំណួរ' },
            { id: 'bulk', label: '🚀 បញ្ចូលទាំងអស់' },
            { id: 'subjects', label: '📚 គ្រប់គ្រងទិន្នន័យ' },
            { id: 'feedback', label: '💬 មតិយោបល់' }
          ].map(tab => (
            <button key={tab.id} onClick={() => setEntryMode(tab.id as any)} className={`flex-1 min-w-[140px] py-3.5 px-4 rounded-xl font-black heading-kh text-[11px] transition-all duration-300 ${entryMode === tab.id ? 'bg-red-700 text-white shadow-lg' : 'text-gray-500 hover:text-red-700'}`}>
              {tab.label}
              {tab.id === 'feedback' && feedbackList.length > 0 && <span className="ml-2 bg-white text-red-700 px-2 py-0.5 rounded-full text-[8px]">{feedbackList.length}</span>}
            </button>
          ))}
        </div>

        <div className="px-2">
          {entryMode === 'single' && (
            <div className="space-y-6 animate-fadeIn">
              <div className="flex flex-wrap gap-4 items-center justify-between">
                <h2 className="text-xl font-black heading-kh text-[#800000]">
                  {editingIndex !== null ? '✏️ កែសម្រួលសំណួរ' : '🆕 បង្កើតសំណួរថ្មី'}
                </h2>
                <div className="flex bg-gray-100 p-1 rounded-xl">
                  {['mcq', 'short'].map(t => (
                    <button key={t} onClick={() => setQType(t as any)} className={`px-4 py-2 rounded-lg text-[10px] font-black uppercase transition-all ${qType === t ? 'bg-white text-[#800000] shadow-sm' : 'text-gray-400'}`}>{t === 'mcq' ? 'QCM' : 'Q & A'}</button>
                  ))}
                </div>
              </div>
              <div className="grid grid-cols-1 gap-5">
                <input type="text" value={subject} onChange={(e) => setSubject(e.target.value)} className="w-full px-6 py-4 rounded-2xl border border-gray-100 outline-none focus:ring-2 focus:ring-[#800000] heading-kh bg-gray-50/50" placeholder="ឈ្មោះមុខវិជ្ជា..." />
                <textarea value={question} onChange={(e) => setQuestion(e.target.value)} className="w-full px-6 py-4 rounded-2xl border border-gray-100 focus:ring-2 focus:ring-[#800000] outline-none min-h-[120px] small-kh bg-gray-50/50" placeholder="សរសេរសំណួរ..." />
                {qType === 'mcq' ? (
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    {options.map((opt, i) => (
                      <div key={i} className="flex items-center gap-3 bg-white p-4 rounded-2xl border border-gray-100 shadow-sm focus-within:border-[#800000]/30">
                        <span className="font-black text-[#800000] w-10 h-10 flex items-center justify-center bg-red-50 rounded-xl">{KHMER_PREFIXES[i]}</span>
                        <input type="text" value={opt} onChange={(e) => { const n = [...options]; n[i] = e.target.value; setOptions(n); }} className="flex-1 outline-none small-kh text-sm" placeholder={`ចម្លើយទី ${i+1}`} />
                        <button onClick={() => setCorrect(i)} className={`w-8 h-8 rounded-lg flex items-center justify-center border-2 transition-all ${correct === i ? 'bg-green-500 border-green-500 text-white' : 'border-gray-100 text-gray-200'}`}>✓</button>
                      </div>
                    ))}
                  </div>
                ) : (
                  <textarea value={shortAnswer} onChange={(e) => setShortAnswer(e.target.value)} className="w-full px-6 py-4 rounded-2xl border border-gray-100 outline-none focus:ring-2 focus:ring-[#800000] small-kh bg-gray-50/50 min-h-[100px]" placeholder="បញ្ចូលចម្លើយត្រឹមត្រូវ..." />
                )}
              </div>
              <button onClick={handleSubmitSingle} className="w-full bg-[#800000] text-white font-black py-5 rounded-[2rem] shadow-xl hover:brightness-110 transition-all heading-kh text-lg">រក្សាទុកសំណួរ</button>
            </div>
          )}

          {entryMode === 'bulk' && (
            <div className="space-y-6 animate-fadeIn">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <input type="text" value={subject} onChange={(e) => setSubject(e.target.value)} className="w-full px-6 py-4 rounded-2xl border border-gray-100 outline-none focus:ring-2 focus:ring-[#800000] heading-kh bg-gray-50/50" placeholder="ឈ្មោះមុខវិជ្ជា..." />
                <div className="flex bg-gray-100 p-1 rounded-2xl">
                  <button onClick={() => setBulkType('mcq')} className={`flex-1 rounded-xl text-[10px] font-black uppercase transition-all ${bulkType === 'mcq' ? 'bg-white text-blue-700 shadow-sm' : 'text-gray-400'}`}>QCM</button>
                  <button onClick={() => setBulkType('short')} className={`flex-1 rounded-xl text-[10px] font-black uppercase transition-all ${bulkType === 'short' ? 'bg-white text-orange-700 shadow-sm' : 'text-gray-400'}`}>Q & A</button>
                </div>
              </div>
              <textarea value={bulkText} onChange={(e) => setBulkText(e.target.value)} className="w-full px-6 py-6 rounded-[2rem] border border-gray-100 min-h-[400px] small-kh text-xs bg-gray-50/50 outline-none focus:ring-2 focus:ring-[#800000]" placeholder="ចម្លងកម្រងសំណួរដាក់ទីនេះ..." />
              <button onClick={handleBulkSubmit} className="w-full bg-[#800000] text-white font-black py-5 rounded-[2rem] shadow-xl hover:brightness-110 transition-all heading-kh text-lg">ចាប់ផ្ដើមនាំចូល</button>
            </div>
          )}

          {entryMode === 'subjects' && (
            <div className="animate-fadeIn space-y-12">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                {groupedSubjects.mcq.map((s, i) => <SubjectCard key={`m-${i}`} sub={s} isFirst={i === 0} isLast={i === groupedSubjects.mcq.length - 1} onToggleSubject={onToggleSubject} onEditSubject={() => handleEditSubject(s.name, 'mcq')} onRemoveSubject={onRemoveSubject} onReorderSubject={onReorderSubject} onOpenExport={(name, type, mode) => setViewingExport({name, type, mode})} />)}
                {groupedSubjects.short.map((s, i) => <SubjectCard key={`s-${i}`} sub={s} isFirst={i === 0} isLast={i === groupedSubjects.short.length - 1} onToggleSubject={onToggleSubject} onEditSubject={() => handleEditSubject(s.name, 'short')} onRemoveSubject={onRemoveSubject} onReorderSubject={onReorderSubject} onOpenExport={(name, type, mode) => setViewingExport({name, type, mode})} />)}
              </div>
            </div>
          )}

          {entryMode === 'feedback' && (
            <div className="animate-fadeIn space-y-8">
              {feedbackList.map(fb => (
                <div key={fb.id} className="glass-card rounded-[2rem] p-8 border border-gray-100 shadow-sm flex flex-col gap-4">
                  <div className="flex justify-between items-center">
                    <h4 className="font-black heading-kh text-[#800000]">{fb.username} <span className="text-gray-400 text-[10px]">{new Date(fb.createdAt).toLocaleString()}</span></h4>
                    <button onClick={() => fb.id && onDeleteFeedback && onDeleteFeedback(fb.id)} className="p-2 text-red-500 hover:bg-red-50 rounded-lg">🗑️</button>
                  </div>
                  <p className="small-kh text-gray-700">{fb.text}</p>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>

      {viewingExport && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex items-center justify-center z-[100] p-4 animate-fadeIn">
          <div className="bg-white p-10 rounded-[2.5rem] max-w-sm w-full shadow-2xl">
            <h3 className="heading-kh text-2xl mb-6 text-indigo-950 text-center">ការនាំចេញ៖ {viewingExport.mode.toUpperCase()}</h3>
            <div className="space-y-4">
              {viewingExport.mode === 'telegram' && (
                <div className="p-4 bg-blue-50 rounded-2xl space-y-3">
                  <p className="text-[10px] font-bold text-blue-600 uppercase">Telegram Config</p>
                  <select value={tgConfig.chatId} onChange={(e) => setTgConfig({...tgConfig, chatId: e.target.value})} className="w-full p-3 rounded-xl border-none outline-none text-xs font-bold">
                    {TG_CHANNELS.map(c => <option key={c.value} value={c.value}>{c.label}</option>)}
                  </select>
                  <label className="flex items-center gap-2 cursor-pointer">
                    <input type="checkbox" checked={sendAsImage} onChange={(e) => setSendAsImage(e.target.checked)} />
                    <span className="text-xs font-bold">ផ្ញើជារូបភាព</span>
                  </label>
                </div>
              )}
              <button 
                onClick={viewingExport.mode === 'pdf' ? handleExportPdf : viewingExport.mode === 'image' ? handleExportImageZip : handleSendAllTelegram}
                disabled={isProcessing}
                className="w-full py-4 bg-indigo-950 text-white rounded-2xl heading-kh font-bold hover:brightness-110 active:scale-95 transition-all"
              >
                {isProcessing ? 'កំពុងដំណើរការ...' : 'យល់ព្រម'}
              </button>
              <button onClick={() => setViewingExport(null)} className="w-full py-4 bg-gray-100 text-gray-600 rounded-2xl heading-kh font-bold">បោះបង់</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default CreateSection;

import * as React from 'react';
import { useState, useMemo, useRef } from 'react';
import { Question, TelegramConfig, Feedback } from '../types';
import { DEFAULT_TG_BOT_TOKEN, TG_CHANNELS } from '../constants';
import html2canvas from 'html2canvas';
import { sendQuizPoll, sendQuestionImage } from '../services/telegramService';

declare var html2pdf: any;
declare var JSZip: any;

interface CreateSectionProps {
  quizData: Question[];
  feedbackList?: Feedback[];
  onDeleteFeedback?: (id: string) => void;
  onAdd: (q: Question) => void;
  onUpdate: (index: number, q: Question) => void;
  onRemove: (index: number) => void;
  onToggleSubject: (subject: string, type: 'mcq' | 'short', active: boolean) => void;
  onUpdateSubject: (subject: string, type: 'mcq' | 'short', newName: string) => void;
  onRemoveSubject: (subject: string, type: 'mcq' | 'short') => void;
  onReorderSubject: (subject: string, type: 'mcq' | 'short', direction: 'up' | 'down') => void;
  onBatchAdd: (qs: Question[]) => void;
  onLogout: () => void;
}

const SubjectCard: React.FC<{
  sub: { name: string, isActive: boolean, count: number, type: 'mcq' | 'short' };
  isFirst: boolean;
  isLast: boolean;
  onToggleSubject: (subject: string, type: 'mcq' | 'short', active: boolean) => void;
  onEditSubject: (subject: string, type: 'mcq' | 'short') => void;
  onRemoveSubject: (subject: string, type: 'mcq' | 'short') => void;
  onReorderSubject: (subject: string, type: 'mcq' | 'short', direction: 'up' | 'down') => void;
  onOpenExport: (name: string, type: 'mcq' | 'short', mode: 'pdf' | 'image' | 'telegram') => void;
}> = ({ sub, isFirst, isLast, onToggleSubject, onEditSubject, onRemoveSubject, onReorderSubject, onOpenExport }) => (
  <div className={`group glass-card p-6 rounded-[2.5rem] border transition-all flex flex-col justify-between ${sub.isActive ? 'bg-white border-white shadow-xl' : 'bg-gray-100/50 border-gray-200 grayscale opacity-60'}`}>
    <div>
      <div className="flex justify-between items-start mb-4">
        <div className="flex-1 truncate pr-2">
          <div className="flex items-center gap-2 mb-2">
            <h3 className="text-lg font-black heading-kh text-[#800000] truncate">{sub.name}</h3>
            <button onClick={() => onEditSubject(sub.name, sub.type)} className="p-1.5 bg-red-50 text-[#800000] rounded-lg hover:bg-[#800000] hover:text-white transition-all">✏️</button>
          </div>
          <div className="flex flex-wrap gap-2">
            <span className="text-[9px] font-black bg-blue-50 text-blue-600 px-3 py-1 rounded-full uppercase tracking-tighter">
              {sub.type === 'mcq' ? 'QCM' : 'Q & A'} ({sub.count})
            </span>
            <span className={`text-[9px] font-black px-3 py-1 rounded-full uppercase tracking-tighter ${sub.isActive ? 'bg-green-50 text-green-600' : 'bg-gray-200 text-gray-500'}`}>
              {sub.isActive ? 'Active' : 'Inactive'}
            </span>
          </div>
        </div>
        <div className="flex flex-col gap-1">
          <button disabled={isFirst} onClick={() => onReorderSubject(sub.name, sub.type, 'up')} className="w-8 h-8 flex items-center justify-center rounded-lg bg-white border border-gray-100 shadow-sm hover:bg-[#800000] hover:text-white disabled:opacity-20">🔼</button>
          <button disabled={isLast} onClick={() => onReorderSubject(sub.name, sub.type, 'down')} className="w-8 h-8 flex items-center justify-center rounded-lg bg-white border border-gray-100 shadow-sm hover:bg-[#800000] hover:text-white disabled:opacity-20">🔽</button>
        </div>
      </div>
    </div>

    <div className="grid grid-cols-2 gap-2 mt-4">
      <button onClick={() => onOpenExport(sub.name, sub.type, 'pdf')} className="py-2.5 bg-indigo-50 text-indigo-600 rounded-xl font-black text-[10px] hover:bg-indigo-600 hover:text-white transition-all flex items-center justify-center gap-1.5">📄 PDF</button>
      <button onClick={() => onOpenExport(sub.name, sub.type, 'image')} className="py-2.5 bg-orange-50 text-orange-600 rounded-xl font-black text-[10px] hover:bg-orange-600 hover:text-white transition-all flex items-center justify-center gap-1.5">🖼️ Image</button>
      <button onClick={() => onOpenExport(sub.name, sub.type, 'telegram')} className="col-span-2 py-3 bg-blue-600 text-white rounded-xl font-black text-[10px] hover:brightness-110 transition-all flex items-center justify-center gap-2">✈️ ផ្ញើទៅ Telegram</button>
      <div className="col-span-2 flex gap-2 pt-2">
        <button onClick={() => onToggleSubject(sub.name, sub.type, !sub.isActive)} className="flex-1 py-2 rounded-lg text-[9px] font-bold border border-gray-100 hover:bg-gray-50">{sub.isActive ? 'បិទដំណើរការ' : 'បើកដំណើរការ'}</button>
        <button onClick={() => { if(confirm('លុបវិញ្ញាសានេះ?')) onRemoveSubject(sub.name, sub.type) }} className="p-2 bg-red-50 text-red-500 rounded-lg hover:bg-red-500 hover:text-white">🗑️</button>
      </div>
    </div>
  </div>
);

const CreateSection: React.FC<CreateSectionProps> = ({ 
  quizData, feedbackList = [], onDeleteFeedback, onAdd, onUpdate, onRemove, onToggleSubject, onUpdateSubject, onRemoveSubject, onReorderSubject, onBatchAdd
}) => {
  const KHMER_PREFIXES = ['ក', 'ខ', 'គ', 'ឃ'];
  const KHMER_DIGITS = ['០', '១', '២', '៣', '៤', '៥', '៦', '៧', '៨', '៩'];
  const [entryMode, setEntryMode] = useState<'single' | 'bulk' | 'subjects' | 'feedback'>('single');
  const [qType, setQType] = useState<'mcq' | 'short'>('mcq');
  const [bulkType, setBulkType] = useState<'mcq' | 'short'>('mcq');
  const [subject, setSubject] = useState('');
  const [question, setQuestion] = useState('');
  const [options, setOptions] = useState(['', '', '', '']);
  const [correct, setCorrect] = useState(0);
  const [shortAnswer, setShortAnswer] = useState('');
  const [editingIndex, setEditingIndex] = useState<number | null>(null);
  const [bulkText, setBulkText] = useState('');
  const [viewingExport, setViewingExport] = useState<{name: string, type: 'mcq' | 'short', mode: 'pdf' | 'image' | 'telegram'} | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);

  const [tgConfig, setTgConfig] = useState<TelegramConfig>({ botToken: DEFAULT_TG_BOT_TOKEN, chatId: TG_CHANNELS[0].value });
  const [sendAsImage, setSendAsImage] = useState(false);

  const imageTemplateRef = useRef<HTMLDivElement>(null);
  const pdfTemplateRef = useRef<HTMLDivElement>(null);
  const [previewQ, setPreviewQ] = useState<Question | null>(null);

  const toKhmerNumeral = (n: number) => n.toString().split('').map(digit => KHMER_DIGITS[parseInt(digit)] || digit).join('');

  const groupedSubjects = useMemo(() => {
    const types: ('mcq' | 'short')[] = ['mcq', 'short'];
    const result = { mcq: [] as any[], short: [] as any[] };
    types.forEach(t => {
      const seen = new Set<string>();
      quizData.filter(q => q.type === t).forEach(q => {
        if (!seen.has(q.subject)) {
          seen.add(q.subject);
          const related = quizData.filter(rq => rq.subject === q.subject && rq.type === t);
          result[t].push({ name: q.subject, isActive: related.every(rq => rq.isActive !== false), count: related.length, type: t });
        }
      });
    });
    return result;
  }, [quizData]);

  const activeExportQuestions = useMemo(() => {
    if (!viewingExport) return [];
    return quizData.filter(q => q.subject === viewingExport.name && q.type === viewingExport.type);
  }, [quizData, viewingExport]);

  const handleEditSubject = (oldName: string, type: 'mcq' | 'short') => {
    const newName = prompt("បញ្ចូលឈ្មោះមុខវិជ្ជាថ្មី៖", oldName);
    if (newName && newName.trim() && newName !== oldName) {
      onUpdateSubject(oldName, type, newName.trim());
    }
  };

  const handleExportPdf = async () => {
    if (!pdfTemplateRef.current || !viewingExport) return;
    setIsProcessing(true);
    try {
      const opt = {
        margin: 10,
        filename: `Vignasa_${viewingExport.name}.pdf`,
        image: { type: 'jpeg', quality: 0.98 },
        html2canvas: { scale: 2, useCORS: true },
        jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' }
      };
      await html2pdf().from(pdfTemplateRef.current).set(opt).save();
    } catch (e) {
      alert("Error generating PDF");
    } finally {
      setIsProcessing(false);
    }
  };

  const captureImage = async (): Promise<Blob | null> => {
    if (!imageTemplateRef.current) return null;
    try {
      const canvas = await html2canvas(imageTemplateRef.current, { scale: 3, useCORS: true });
      return new Promise(r => canvas.toBlob(r, 'image/png', 1.0));
    } catch (e) { return null; }
  };

  const handleExportImageZip = async () => {
    if (!viewingExport) return;
    setIsProcessing(true);
    const zip = new JSZip();
    try {
      for (let i = 0; i < activeExportQuestions.length; i++) {
        const q = activeExportQuestions[i];
        setPreviewQ(q);
        await new Promise(r => setTimeout(r, 100)); // wait for render
        const blob = await captureImage();
        if (blob) zip.file(`Question_${i + 1}.png`, blob);
      }
      const content = await zip.generateAsync({ type: "blob" });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(content);
      link.download = `Images_${viewingExport.name}.zip`;
      link.click();
    } catch (e) {
      alert("Error generating ZIP");
    } finally {
      setPreviewQ(null);
      setIsProcessing(false);
    }
  };

  const handleSendToTelegram = async (q: Question, idx: number) => {
    try {
      if (sendAsImage) {
        setPreviewQ(q);
        await new Promise(r => setTimeout(r, 100));
        const blob = await captureImage();
        if (blob) {
          const caption = `📌 សំណួរទី ${idx + 1}\n\nវិញ្ញាសា៖ ${q.subject}\nWeb QCM 🇰🇭`;
          await sendQuestionImage(tgConfig, blob, caption);
        }
      } else {
        if (q.type === 'mcq') {
          await sendQuizPoll(tgConfig, q);
        } else {
          const text = `📌 *សំណួរ៖* ${q.question}\n\n✅ *ចម្លើយ៖* ${q.answer}\n\nវិញ្ញាសា៖ ${q.subject}`;
          await fetch(`https://api.telegram.org/bot${tgConfig.botToken}/sendMessage`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ chat_id: tgConfig.chatId, text, parse_mode: 'Markdown' })
          });
        }
      }
    } catch (e) { console.error(e); }
  };

  const handleSendAllTelegram = async () => {
    if (!confirm(`ផ្ញើទាំង ${activeExportQuestions.length} សំណួរ?`)) return;
    setIsProcessing(true);
    for (let i = 0; i < activeExportQuestions.length; i++) {
      await handleSendToTelegram(activeExportQuestions[i], i);
      await new Promise(r => setTimeout(r, 3000)); // Delay to avoid flood
    }
    setIsProcessing(false);
    setPreviewQ(null);
    alert("រួចរាល់!");
  };

  const handleSubmitSingle = () => {
    if (!subject.trim() || !question.trim()) return alert("សូមបំពេញព័ត៌មាន!");
    const cleanQ: Question = {
      subject: subject.trim(),
      question: question.trim(),
      type: qType,
      isActive: true,
      ...(qType === 'mcq' ? { options: options.map(o => o.trim()), correct } : { answer: shortAnswer.trim() })
    };
    if (editingIndex !== null) onUpdate(editingIndex, cleanQ); else onAdd(cleanQ);
    setQuestion(''); setOptions(['', '', '', '']); setShortAnswer(''); setEditingIndex(null);
    alert("រក្សាទុកជោគជ័យ!");
  };

  const handleBulkSubmit = () => {
    if (!subject.trim() || !bulkText.trim()) return alert("សូមបំពេញព័ត៌មាន!");
    const lines = bulkText.split('\n');
    const parsed: Question[] = [];
    let current: any = null;
    if (bulkType === 'mcq') {
      lines.forEach(l => {
        const t = l.trim(); if (!t) return;
        const qm = t.match(/^[០-៩0-9]+\.\s*(.*)/);
        if (qm) {
          if (current && current.options?.length >= 2) parsed.push(current);
          current = { type: 'mcq', subject: subject.trim(), question: qm[1].trim(), options: [], correct: 0, isActive: true };
          return;
        }
        const om = t.match(/^[កខគឃ]\.\s*(.*)/);
        if (om && current) {
          let txt = om[1].replace('(ចម្លើយត្រឹមត្រូវ)', '').trim();
          current.options.push(txt);
          if (om[1].includes('(ចម្លើយត្រឹមត្រូវ)')) current.correct = current.options.length - 1;
        }
      });
      if (current && current.options?.length >= 2) parsed.push(current);
    } else {
      let isAnswer = false;
      lines.forEach(l => {
        const t = l.trim(); if (!t) return;
        const qm = t.match(/^[០-៩0-9]+\.\s*(.*)/);
        if (qm) {
          if (current && current.answer) parsed.push(current);
          current = { type: 'short', subject: subject.trim(), question: qm[1].trim(), answer: '', isActive: true };
          isAnswer = false; return;
        }
        const am = t.match(/^ចម្លើយ\s*[៖:]\s*(.*)/);
        if (am && current) { current.answer = am[1].trim(); isAnswer = true; return; }
        if (isAnswer && current) current.answer += (current.answer ? '\n' : '') + l;
      });
      if (current && current.answer) parsed.push(current);
    }
    if (parsed.length) { onBatchAdd(parsed); setBulkText(''); alert(`បានបញ្ចូល ${parsed.length} សំណួរ!`); }
  };

  return (
    <div className="space-y-8 animate-fadeIn pb-32">
      {/* Hidden Templates for Export */}
      <div className="fixed -left-[8000px] top-0 pointer-events-none overflow-hidden">
        {/* PDF Template */}
        <div ref={pdfTemplateRef} style={{ width: '210mm', padding: '20mm', background: '#fff', color: '#000', fontFamily: 'Kantumruy Pro, sans-serif' }}>
          <h1 style={{ textAlign: 'center', fontSize: '24pt', marginBottom: '10mm' }}>វិញ្ញាសា៖ {viewingExport?.name}</h1>
          <hr style={{ marginBottom: '10mm' }} />
          {activeExportQuestions.map((q, i) => (
            <div key={i} style={{ marginBottom: '8mm', pageBreakInside: 'avoid' }}>
              <p style={{ fontWeight: 'bold', fontSize: '14pt' }}>សំណួរ {toKhmerNumeral(i + 1)}៖ {q.question}</p>
              {q.type === 'mcq' && q.options?.map((o, oi) => (
                <p key={oi} style={{ marginLeft: '10mm' }}>{KHMER_PREFIXES[oi]}. {o}</p>
              ))}
            </div>
          ))}
        </div>
        {/* Image Template */}
        <div ref={imageTemplateRef} style={{ width: '800px', padding: '60px', background: 'linear-gradient(135deg, #1e1b4b 0%, #020617 100%)', color: '#fff', borderRadius: '40px', border: '4px solid #800000' }}>
          <div style={{ marginBottom: '30px', display: 'flex', alignItems: 'center', gap: '20px' }}>
             <div style={{ background: '#800000', padding: '10px 20px', borderRadius: '15px', fontWeight: 'bold' }}>សំណួរ</div>
             <div style={{ fontSize: '14pt', opacity: 0.7 }}>{viewingExport?.name}</div>
          </div>
          <h2 style={{ fontSize: '28pt', marginBottom: '40px', lineHeight: 1.6 }}>{previewQ?.question}</h2>
          {previewQ?.type === 'mcq' && previewQ.options?.map((o, i) => (
            <div key={i} style={{ background: 'rgba(255,255,255,0.05)', padding: '20px', borderRadius: '20px', marginBottom: '15px', border: '1px solid rgba(255,255,255,0.1)', display: 'flex', alignItems: 'center', gap: '20px' }}>
              {/* Fix: Changed justifyCenter to justifyContent to resolve TypeScript property error */}
              <span style={{ width: '40px', height: '40px', background: '#800000', display: 'flex', alignItems: 'center', justifyContent: 'center', borderRadius: '10px' }}>{KHMER_PREFIXES[i]}</span>
              <span style={{ fontSize: '18pt' }}>{o}</span>
            </div>
          ))}
          <div style={{ marginTop: '40px', textAlign: 'center', opacity: 0.5, fontSize: '12pt' }}>Master Quiz KH | 🇰🇭 ត្រៀមប្រឡងក្របខ័ណ្ឌរដ្ឋ</div>
        </div>
      </div>

      <div className="glass-card rounded-[2.5rem] shadow-xl p-6 border border-white/50">
        <div className="bg-gray-100/80 p-1.5 rounded-2xl flex flex-wrap md:flex-nowrap gap-1 mb-10 border border-gray-200 shadow-inner">
          {[
            { id: 'single', label: '✍️ បញ្ចូលសំណួរ' },
            { id: 'bulk', label: '🚀 បញ្ចូលទាំងអស់' },
            { id: 'subjects', label: '📚 គ្រប់គ្រងទិន្នន័យ' },
