              <button onClick={handleBulkSubmit} className="w-full bg-[#800000] text-white font-black py-5 rounded-[2rem] shadow-xl hover:brightness-110 active:scale-[0.98] transition-all heading-kh text-lg">ចាប់ផ្ដើមនាំចូលទាំងអស់</button>
            </div>
          )}

          {entryMode === 'subjects' && (
            <div className="animate-fadeIn space-y-12">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                {groupedSubjects.mcq.map((s, i) => <SubjectCard key={`m-${i}`} sub={s} isFirst={i === 0} isLast={i === groupedSubjects.mcq.length - 1} onToggleSubject={onToggleSubject} onEditSubject={() => handleEditSubject(s.name, 'mcq')} onRemoveSubject={onRemoveSubject} onReorderSubject={onReorderSubject} onOpenExport={(name, type, mode) => setViewingExport({name, type, mode})} />)}
                {groupedSubjects.short.map((s, i) => <SubjectCard key={`s-${i}`} sub={s} isFirst={i === 0} isLast={i === groupedSubjects.short.length - 1} onToggleSubject={onToggleSubject} onEditSubject={() => handleEditSubject(s.name, 'short')} onRemoveSubject={onRemoveSubject} onReorderSubject={onReorderSubject} onOpenExport={(name, type, mode) => setViewingExport({name, type, mode})} />)}
                {groupedSubjects.mcq.length === 0 && groupedSubjects.short.length === 0 && (
                   <div className="col-span-2 py-20 text-center text-gray-400 italic">មិនមានទិន្នន័យមុខវិជ្ជា</div>
                )}
              </div>
            </div>
          )}

          {entryMode === 'feedback' && (
            <div className="animate-fadeIn space-y-8">
              <h2 className="text-2xl font-black heading-kh text-[#800000] flex items-center gap-3">💬 មតិយោបល់</h2>
              {feedbackList.length ? feedbackList.map(fb => (
                <div key={fb.id} className="glass-card rounded-[2rem] p-8 border border-gray-100 shadow-sm relative group overflow-hidden">
                  <div className="absolute top-0 left-0 w-1.5 h-full bg-red-700"></div>
                  <div className="flex justify-between items-center mb-4">
                    <div className="flex items-center gap-4">
                      <div className="w-12 h-12 rounded-2xl bg-red-50 text-[#800000] flex items-center justify-center font-black text-xl shadow-inner border border-red-100">{(fb.username || 'A')[0]}</div>
                      <div>
                        <h4 className="font-black heading-kh text-[#800000]">{fb.username}</h4>
                        <p className="text-[10px] text-gray-400 font-bold">{new Date(fb.createdAt).toLocaleString('km-KH')}</p>
                      </div>
                    </div>
                    <button onClick={() => fb.id && onDeleteFeedback && onDeleteFeedback(fb.id)} className="p-2 text-red-500 hover:bg-red-50 rounded-lg transition-all opacity-40 group-hover:opacity-100">🗑️ លុប</button>
                  </div>
                  <p className="small-kh text-gray-700 leading-relaxed bg-gray-50/50 p-6 rounded-2xl border border-white">{fb.text}</p>
                </div>
              )) : <div className="text-center py-20 text-gray-400 italic">មិនមានមតិយោបល់នៅឡើយទេ</div>}
            </div>
          )}
        </div>
      </div>

      {/* Universal Modern Export Modal */}
      {viewingExport && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex items-center justify-center z-[100] p-4 animate-fadeIn">
          <div className="bg-white p-10 rounded-[3rem] max-w-sm w-full shadow-2xl border border-white/20 relative overflow-hidden">
            <div className="absolute top-0 left-0 w-full h-2 bg-gradient-to-r from-blue-600 via-red-700 to-indigo-900"></div>

            <div className="text-center mb-8">
              <div className="w-20 h-20 bg-gray-50 rounded-3xl flex items-center justify-center text-4xl mx-auto mb-6 shadow-inner border border-gray-100">
                {viewingExport.mode === 'pdf' ? '📄' : viewingExport.mode === 'image' ? '🖼️' : '✈️'}
              </div>
              <h3 className="heading-kh text-2xl font-black text-indigo-950">ការនាំចេញ៖ {viewingExport.mode.toUpperCase()}</h3>
              <p className="small-kh text-gray-500 text-xs mt-2">វិញ្ញាសា៖ <span className="text-[#800000] font-black">{viewingExport.name}</span></p>
            </div>

            <div className="space-y-4">
              {viewingExport.mode === 'telegram' && (
                <div className="p-6 bg-blue-50/50 rounded-3xl space-y-4 border border-blue-100">
                  <div className="space-y-2">
                    <p className="text-[10px] font-black text-blue-800 uppercase tracking-widest ml-1">ជ្រើសរើស Channel</p>
                    <select 
                      value={tgConfig.chatId} 
                      onChange={(e) => setTgConfig({...tgConfig, chatId: e.target.value})} 
                      className="w-full p-4 rounded-2xl bg-white border border-blue-100 outline-none text-[11px] font-black shadow-sm"
                    >
                      {TG_CHANNELS.map(c => <option key={c.value} value={c.value}>{c.label}</option>)}
                    </select>
                  </div>
                  <label className="flex items-center gap-3 cursor-pointer group p-2 rounded-xl hover:bg-white/50 transition-all">
                    <div className={`w-12 h-6 rounded-full relative transition-all duration-300 ${sendAsImage ? 'bg-blue-600' : 'bg-gray-300'}`}>
                      <div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-all duration-300 ${sendAsImage ? 'left-7' : 'left-1'}`}></div>
                    </div>
                    <input 
                      type="checkbox" 
                      className="hidden" 
                      checked={sendAsImage} 
                      onChange={(e) => setSendAsImage(e.target.checked)} 
                    />
                    <span className="text-[11px] font-black text-indigo-950 group-hover:text-blue-600 transition-colors">ផ្ញើជារូបភាព (High Quality)</span>
                  </label>
                </div>
              )}

              {isProcessing && (
                <div className="space-y-3 py-4">
                  <div className="w-full h-3 bg-gray-100 rounded-full overflow-hidden shadow-inner">
                    <div 
                      className="h-full bg-gradient-to-r from-blue-600 to-red-700 transition-all duration-300" 
                      style={{ width: `${(currentProcessIndex / activeExportQuestions.length) * 100}%` }}
                    ></div>
                  </div>
                  <p className="text-center text-[10px] font-black text-gray-400 small-kh">
                    កំពុងដំណើរការ៖ {toKhmerNumeral(currentProcessIndex)} / {toKhmerNumeral(activeExportQuestions.length)}
                  </p>
                </div>
              )}

              <div className="flex flex-col gap-2">
                <button 
                  onClick={viewingExport.mode === 'pdf' ? handleExportPdf : viewingExport.mode === 'image' ? handleExportImageZip : handleSendAllTelegram}
                  disabled={isProcessing}
                  className="w-full py-4.5 bg-indigo-950 text-white rounded-2xl heading-kh font-black shadow-lg hover:brightness-110 active:scale-[0.98] transition-all disabled:opacity-50 flex items-center justify-center gap-2"
                >
                  {isProcessing ? (
                    <>
                      <div className="w-5 h-5 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
                      សូមរង់ចាំ...
                    </>
                  ) : 'យល់ព្រម និងបន្ត'}
                </button>
                <button 
                  onClick={() => !isProcessing && setViewingExport(null)} 
                  disabled={isProcessing}
                  className="w-full py-4.5 bg-gray-100 text-gray-600 rounded-2xl heading-kh font-black hover:bg-gray-200 transition-all active:scale-[0.98] disabled:opacity-30"
                >
                  បោះបង់
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default CreateSection;

import * as React from 'react';
import { useState, useMemo, useRef } from 'react';
import { Question, TelegramConfig, Feedback } from '../types';
import { DEFAULT_TG_BOT_TOKEN, TG_CHANNELS } from '../constants';
import html2canvas from 'html2canvas';
import { sendQuizPoll, sendQuestionImage } from '../services/telegramService';

declare var html2pdf: any;
declare var JSZip: any;

interface CreateSectionProps {
  quizData: Question[];
  feedbackList?: Feedback[];
  onDeleteFeedback?: (id: string) => void;
  onAdd: (q: Question) => void;
  onUpdate: (index: number, q: Question) => void;
  onRemove: (index: number) => void;
  onToggleSubject: (subject: string, type: 'mcq' | 'short', active: boolean) => void;
  onUpdateSubject: (subject: string, type: 'mcq' | 'short', newName: string) => void;
  onRemoveSubject: (subject: string, type: 'mcq' | 'short') => void;
  onReorderSubject: (subject: string, type: 'mcq' | 'short', direction: 'up' | 'down') => void;
  onBatchAdd: (qs: Question[]) => void;
  onLogout: () => void;
}

type ExportTemplate = 'classic' | 'royal' | 'vivid';

const CreateSection: React.FC<CreateSectionProps> = ({ 
  quizData, feedbackList = [], onDeleteFeedback, onAdd, onUpdate, onRemove, onToggleSubject, onUpdateSubject, onRemoveSubject, onReorderSubject, onBatchAdd
}) => {
  const APP_LOGO_URL = "https://i.postimg.cc/0ygmLdvR/3QCM_Ep4.png";
  const KHMER_PREFIXES = ['ក', 'ខ', 'គ', 'ឃ'];
  const KHMER_DIGITS = ['០', '១', '២', '៣', '៤', '៥', '៦', '៧', '៨', '៩'];

  const [entryMode, setEntryMode] = useState<'single' | 'bulk' | 'subjects' | 'feedback'>('single');
  const [qType, setQType] = useState<'mcq' | 'short'>('mcq');
  const [bulkType, setBulkType] = useState<'mcq' | 'short'>('mcq');
  const [subject, setSubject] = useState('');
  const [question, setQuestion] = useState('');
  const [options, setOptions] = useState(['', '', '', '']);
  const [correct, setCorrect] = useState(0);
  const [shortAnswer, setShortAnswer] = useState('');
  const [editingIndex, setEditingIndex] = useState<number | null>(null);
  const [bulkText, setBulkText] = useState('');

  const [viewingExport, setViewingExport] = useState<{name: string, type: 'mcq' | 'short', mode: 'pdf' | 'image' | 'telegram'} | null>(null);
  const [selectedTemplate, setSelectedTemplate] = useState<ExportTemplate>('classic');
  const [isProcessing, setIsProcessing] = useState(false);
  const [currentProcessIndex, setCurrentProcessIndex] = useState(0);

  const [tgConfig, setTgConfig] = useState<TelegramConfig>({ botToken: DEFAULT_TG_BOT_TOKEN, chatId: TG_CHANNELS[0].value });
  const [sendAsImage, setSendAsImage] = useState(false);

  const imageTemplateRef = useRef<HTMLDivElement>(null);
  const pdfTemplateRef = useRef<HTMLDivElement>(null);
  const [previewQ, setPreviewQ] = useState<Question | null>(null);

  const toKhmerNumeral = (n: number) => n.toString().split('').map(digit => KHMER_DIGITS[parseInt(digit)] || digit).join('');

  const groupedSubjects = useMemo(() => {
    const types: ('mcq' | 'short')[] = ['mcq', 'short'];
    const result = { mcq: [] as any[], short: [] as any[] };
    types.forEach(t => {
      const seen = new Set<string>();
      quizData.filter(q => q.type === t).forEach(q => {
        if (!seen.has(q.subject)) {
          seen.add(q.subject);
          const related = quizData.filter(rq => rq.subject === q.subject && rq.type === t);
          result[t].push({ name: q.subject, isActive: related.every(rq => rq.isActive !== false), count: related.length, type: t });
        }
      });
    });
    return result;
  }, [quizData]);

  const activeExportQuestions = useMemo(() => {
    if (!viewingExport) return [];
    return quizData.filter(q => q.subject === viewingExport.name && q.type === viewingExport.type);
  }, [quizData, viewingExport]);

  const handleEditSubject = (oldName: string, type: 'mcq' | 'short') => {
    const newName = prompt("បញ្ចូលឈ្មោះមុខវិជ្ជាថ្មី៖", oldName);
    if (newName && newName.trim() && newName !== oldName) {
      onUpdateSubject(oldName, type, newName.trim());
    }
  };

  const handleExportPdf = async () => {
    if (!pdfTemplateRef.current || !viewingExport) return;
    setIsProcessing(true);
    try {
      const opt = {
        margin: 10,
        filename: `Vignasa_${viewingExport.name}.pdf`,
        image: { type: 'jpeg', quality: 0.98 },
        html2canvas: { scale: 2, useCORS: true },
        jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' }
      };
      await html2pdf().from(pdfTemplateRef.current).set(opt).save();
    } catch (e) {
      alert("Error generating PDF");
    } finally {
      setIsProcessing(false);
    }
  };

  const captureImageBlob = async (): Promise<Blob | null> => {
    if (!imageTemplateRef.current) return null;
    try {
      const canvas = await html2canvas(imageTemplateRef.current, { scale: 2, useCORS: true, backgroundColor: null });
      return new Promise(r => canvas.toBlob(r, 'image/png', 1.0));
    } catch (e) { return null; }
  };

  const handleExportImageZip = async () => {
    if (!viewingExport) return;
    setIsProcessing(true);
    setCurrentProcessIndex(0);
    const zip = new JSZip();
    try {
      for (let i = 0; i < activeExportQuestions.length; i++) {
        const q = activeExportQuestions[i];
        setPreviewQ(q);
        setCurrentProcessIndex(i + 1);
        await new Promise(r => setTimeout(r, 200));
        const blob = await captureImageBlob();
        if (blob) zip.file(`Question_${toKhmerNumeral(i + 1)}.png`, blob);
      }
      const content = await zip.generateAsync({ type: "blob" });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(content);
      link.download = `Images_${viewingExport.name}_${selectedTemplate}.zip`;
      link.click();
    } catch (e) {
      alert("Error generating ZIP");
    } finally {
      setPreviewQ(null);
      setIsProcessing(false);
    }
  };

  const handleSendToTelegram = async (q: Question, idx: number) => {
    try {
      if (sendAsImage) {
        setPreviewQ(q);
        await new Promise(r => setTimeout(r, 200));
        const blob = await captureImageBlob();
        if (blob) {
          const caption = `📌 *សំណួរទី ${toKhmerNumeral(idx + 1)}*\n\n📋 វិញ្ញាសា៖ ${q.subject}\n✨ ផ្តល់ជូនដោយ Web QCM 🇰🇭`;
          await sendQuestionImage(tgConfig, blob, caption);
        }
      } else {
        if (q.type === 'mcq') {
          await sendQuizPoll(tgConfig, q);
        } else {
          const text = `📌 *សំណួរ៖* ${q.question}\n\n✅ *ចម្លើយ៖* ${q.answer}\n\n📋 វិញ្ញាសា៖ ${q.subject}`;
          await fetch(`https://api.telegram.org/bot${tgConfig.botToken}/sendMessage`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ chat_id: tgConfig.chatId, text, parse_mode: 'Markdown' })
          });
        }
      }
    } catch (e) { console.error(e); }
  };

  const handleSendAllTelegram = async () => {
    if (!confirm(`ផ្ញើទាំង ${toKhmerNumeral(activeExportQuestions.length)} សំណួរ?`)) return;
    setIsProcessing(true);
    setCurrentProcessIndex(0);
    for (let i = 0; i < activeExportQuestions.length; i++) {
      setCurrentProcessIndex(i + 1);
      await handleSendToTelegram(activeExportQuestions[i], i);
      await new Promise(r => setTimeout(r, 3000));
    }
    setIsProcessing(false);
    setPreviewQ(null);
    alert("រួចរាល់!");
  };

  const handleSubmitSingle = () => {
    if (!subject.trim() || !question.trim()) return alert("សូមបំពេញព័ត៌មាន!");
    const cleanQ: Question = {
      subject: subject.trim(),
      question: question.trim(),
      type: qType,
      isActive: true,
      ...(qType === 'mcq' ? { options: options.map(o => o.trim()), correct } : { answer: shortAnswer.trim() })
    };
    if (editingIndex !== null) onUpdate(editingIndex, cleanQ); else onAdd(cleanQ);
    setQuestion(''); setOptions(['', '', '', '']); setShortAnswer(''); setEditingIndex(null);
    alert("រក្សាទុកជោគជ័យ!");
  };

  const handleBulkSubmit = () => {
    if (!subject.trim() || !bulkText.trim()) return alert("សូមបំពេញព័ត៌មាន!");
    const lines = bulkText.split('\n');
    const parsed: Question[] = [];
    let current: any = null;
    if (bulkType === 'mcq') {
      lines.forEach(l => {
        const t = l.trim(); if (!t) return;
        const qm = t.match(/^[០-៩0-9]+\.\s*(.*)/);
        if (qm) {
          if (current && current.options?.length >= 2) parsed.push(current);
          current = { type: 'mcq', subject: subject.trim(), question: qm[1].trim(), options: [], correct: 0, isActive: true };
          return;
        }
        const om = t.match(/^[កខគឃ]\.\s*(.*)/);
        if (om && current) {
          let txt = om[1].replace('(ចម្លើយត្រឹមត្រូវ)', '').trim();
          current.options.push(txt);
          if (om[1].includes('(ចម្លើយត្រឹមត្រូវ)')) current.correct = current.options.length - 1;
        }
      });
      if (current && current.options?.length >= 2) parsed.push(current);
    } else {
      let isAnswer = false;
      lines.forEach(l => {
        const t = l.trim(); if (!t) return;
        const qm = t.match(/^[០-៩0-9]+\.\s*(.*)/);
        if (qm) {
          if (current && current.answer) parsed.push(current);
          current = { type: 'short', subject: subject.trim(), question: qm[1].trim(), answer: '', isActive: true };
          isAnswer = false; return;
        }
        const am = t.match(/^ចម្លើយ\s*[៖:]\s*(.*)/);
        if (am && current) { current.answer = am[1].trim(); isAnswer = true; return; }
        if (isAnswer && current) current.answer += (current.answer ? '\n' : '') + l;
      });
      if (current && current.answer) parsed.push(current);
    }
    if (parsed.length) { onBatchAdd(parsed); setBulkText(''); alert(`បានបញ្ចូល ${parsed.length} សំណួរ!`); }
  };

  return (
    <div className="space-y-8 animate-fadeIn pb-32">
      {/* Hidden Templates for Export */}
      <div className="fixed -left-[9999px] top-0 pointer-events-none overflow-hidden">
        {/* PDF Template */}
        <div ref={pdfTemplateRef} style={{ width: '210mm', padding: '15mm 20mm', background: '#fff', color: '#000', fontFamily: 'Kantumruy Pro, sans-serif' }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '10mm', borderBottom: '2px solid #800000', paddingBottom: '5mm' }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: '10mm' }}>
               <img src={APP_LOGO_URL} style={{ height: '25mm' }} alt="Logo" />
               <div>
                  <h1 style={{ fontSize: '20pt', fontWeight: 'bold', margin: 0 }}>វិញ្ញាសា៖ {viewingExport?.name}</h1>
                  <p style={{ margin: '2mm 0', opacity: 0.6 }}>ប្រភេទ៖ {viewingExport?.type.toUpperCase()}</p>
               </div>
            </div>
            <div style={{ textAlign: 'right' }}>
              <p style={{ fontWeight: 'bold', margin: 0 }}>Web QCM 🇰🇭</p>
              <p style={{ margin: '1mm 0', fontSize: '10pt' }}>{new Date().toLocaleDateString('km-KH')}</p>
            </div>
          </div>
          {activeExportQuestions.map((q, i) => (
            <div key={i} style={{ marginBottom: '8mm', pageBreakInside: 'avoid' }}>
              <p style={{ fontWeight: 'bold', fontSize: '14pt', lineHeight: 1.4 }}>សំណួរ {toKhmerNumeral(i + 1)}៖ {q.question}</p>
              {q.type === 'mcq' ? (
                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '5mm', marginTop: '3mm', paddingLeft: '8mm' }}>
                  {q.options?.map((o, oi) => <p key={oi} style={{ margin: 0 }}>{KHMER_PREFIXES[oi]}. {o}</p>)}
                </div>
              ) : (
                <p style={{ fontStyle: 'italic', opacity: 0.6, marginTop: '3mm', paddingLeft: '8mm' }}>ចម្លើយ៖ .................................................................................</p>
              )}
            </div>
          ))}
        </div>

        {/* IMAGE TEMPLATE ENGINE */}
        <div ref={imageTemplateRef} style={{ 
          width: '1080px', height: '1080px', padding: '100px', borderRadius: '60px', overflow: 'hidden', position: 'relative', display: 'flex', flexDirection: 'column',
          ...(selectedTemplate === 'classic' ? { background: '#fff', color: '#000', border: '15px solid #800000' } : 
             selectedTemplate === 'royal' ? { background: 'linear-gradient(135deg, #1e1b4b 0%, #020617 100%)', color: '#fff', border: '10px solid #800000' } :
             { background: 'linear-gradient(135deg, #800000 0%, #5e0000 100%)', color: '#fff', border: '10px solid #fff' })
        }}>
          {/* Logo Section */}
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '60px' }}>
            <img src={APP_LOGO_URL} style={{ height: '140px', filter: selectedTemplate === 'classic' ? 'none' : 'drop-shadow(0 5px 15px rgba(0,0,0,0.5))' }} />
            <div style={{ textAlign: 'right' }}>
               <div style={{ 
                 padding: '10px 30px', borderRadius: '15px', fontWeight: 'bold', fontSize: '20pt', 
                 ...(selectedTemplate === 'classic' ? { background: '#800000', color: '#fff' } : { background: '#fff', color: '#800000' })
               }}>សំណួរទី {toKhmerNumeral(currentProcessIndex)}</div>
               <div style={{ fontSize: '16pt', marginTop: '10px', opacity: 0.6 }}>វិញ្ញាសា៖ {viewingExport?.name}</div>
            </div>
          </div>

          <div style={{ flex: 1, display: 'flex', flexDirection: 'column', justifyContent: 'center' }}>
            <h2 style={{ fontSize: '38pt', fontWeight: 'bold', lineHeight: 1.5, marginBottom: '80px', textAlign: 'justify' }}>{previewQ?.question}</h2>
            {previewQ?.type === 'mcq' && (
              <div style={{ display: 'grid', gridTemplateColumns: '1fr', gap: '25px' }}>
                {previewQ.options?.map((o, i) => (
                  <div key={i} style={{ 
                    padding: '30px 40px', borderRadius: '25px', display: 'flex', alignItems: 'center', gap: '30px', fontSize: '26pt', fontWeight: '500',
                    ...(selectedTemplate === 'classic' ? { background: '#f8fafc', border: '2px solid #e2e8f0' } : { background: 'rgba(255,255,255,0.05)', border: '1px solid rgba(255,255,255,0.1)' })
                  }}>
                    <span style={{ 
                      width: '60px', height: '60px', borderRadius: '15px', display: 'flex', alignItems: 'center', justifyContent: 'center', fontWeight: 'bold',
                      background: selectedTemplate === 'classic' ? '#800000' : '#fff', color: selectedTemplate === 'classic' ? '#fff' : '#800000'
                    }}>{KHMER_PREFIXES[i]}</span>
                    <span>{o}</span>
                  </div>
                ))}
              </div>
            )}
          </div>

          <div style={{ marginTop: '60px', paddingTop: '40px', borderTop: '1px solid rgba(128,128,128,0.2)', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
            <span style={{ fontSize: '20pt', fontWeight: 'bold', opacity: 0.5 }}>WEB QCM 🇰🇭</span>
            <span style={{ fontSize: '18pt', fontWeight: '500', ...(selectedTemplate === 'classic' ? { color: '#800000' } : { color: '#fbbf24' }) }}>t.me/qcm_and_q_a</span>
          </div>
        </div>
      </div>

      <div className="glass-card rounded-[2.5rem] shadow-xl p-6 border border-white/50">
        <div className="bg-gray-100/80 p-1.5 rounded-2xl flex flex-wrap md:flex-nowrap gap-1 mb-10 border border-gray-200 shadow-inner">
          {[
            { id: 'single', label: '✍️ បញ្ចូលសំណួរ' },
            { id: 'bulk', label: '🚀 បញ្ចូលទាំងអស់' },
            { id: 'subjects', label: '📚 គ្រប់គ្រងទិន្នន័យ' },
            { id: 'feedback', label: '💬 មតិយោបល់' }
          ].map(tab => (
            <button key={tab.id} onClick={() => setEntryMode(tab.id as any)} className={`flex-1 min-w-[140px] py-3.5 px-4 rounded-xl font-black heading-kh text-[11px] transition-all duration-300 ${entryMode === tab.id ? 'bg-red-700 text-white shadow-lg' : 'text-gray-500 hover:text-red-700'}`}>
              {tab.label}
              {tab.id === 'feedback' && feedbackList.length > 0 && <span className="ml-2 bg-white text-red-700 px-2 py-0.5 rounded-full text-[8px]">{feedbackList.length}</span>}
            </button>
          ))}
        </div>

        <div className="px-2">
          {entryMode === 'single' && (
            <div className="space-y-6 animate-fadeIn">
               <div className="flex flex-wrap gap-4 items-center justify-between">
                <h2 className="text-xl font-black heading-kh text-[#800000]">{editingIndex !== null ? '✏️ កែសម្រួលសំណួរ' : '🆕 បង្កើតសំណួរថ្មី'}</h2>
                <div className="flex bg-gray-100 p-1 rounded-xl">
                  {['mcq', 'short'].map(t => (
                    <button key={t} onClick={() => setQType(t as any)} className={`px-4 py-2 rounded-lg text-[10px] font-black uppercase transition-all ${qType === t ? 'bg-white text-[#800000] shadow-sm' : 'text-gray-400'}`}>{t === 'mcq' ? 'QCM' : 'Q & A'}</button>
                  ))}
                </div>
              </div>
              <div className="grid grid-cols-1 gap-5">
                <input type="text" value={subject} onChange={(e) => setSubject(e.target.value)} className="w-full px-6 py-4 rounded-2xl border border-gray-100 outline-none focus:ring-2 focus:ring-[#800000] heading-kh bg-gray-50/50" placeholder="ឈ្មោះមុខវិជ្ជា..." />
                <textarea value={question} onChange={(e) => setQuestion(e.target.value)} className="w-full px-6 py-4 rounded-2xl border border-gray-100 focus:ring-2 focus:ring-[#800000] outline-none min-h-[120px] small-kh bg-gray-50/50" placeholder="សរសេរសំណួរ..." />
                {qType === 'mcq' ? (
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    {options.map((opt, i) => (
                      <div key={i} className="flex items-center gap-3 bg-white p-4 rounded-2xl border border-gray-100 shadow-sm focus-within:border-[#800000]/30">
                        <span className="font-black text-[#800000] w-10 h-10 flex items-center justify-center bg-red-50 rounded-xl">{KHMER_PREFIXES[i]}</span>
                        <input type="text" value={opt} onChange={(e) => { const n = [...options]; n[i] = e.target.value; setOptions(n); }} className="flex-1 outline-none small-kh text-sm" placeholder={`ចម្លើយទី ${i+1}`} />
                        <button onClick={() => setCorrect(i)} className={`w-8 h-8 rounded-lg flex items-center justify-center border-2 transition-all ${correct === i ? 'bg-green-500 border-green-500 text-white' : 'border-gray-100 text-gray-200'}`}>✓</button>
                      </div>
                    ))}
                  </div>
                ) : (
                  <textarea value={shortAnswer} onChange={(e) => setShortAnswer(e.target.value)} className="w-full px-6 py-4 rounded-2xl border border-gray-100 outline-none focus:ring-2 focus:ring-[#800000] small-kh bg-gray-50/50 min-h-[100px]" placeholder="បញ្ចូលចម្លើយត្រឹមត្រូវ..." />
                )}
              </div>
              <button onClick={handleSubmitSingle} className="w-full bg-[#800000] text-white font-black py-5 rounded-[2rem] shadow-xl hover:brightness-110 transition-all heading-kh text-lg">រក្សាទុកសំណួរ</button>
            </div>
          )}

          {entryMode === 'bulk' && (
            <div className="space-y-6 animate-fadeIn">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <input type="text" value={subject} onChange={(e) => setSubject(e.target.value)} className="w-full px-6 py-4 rounded-2xl border border-gray-100 outline-none focus:ring-2 focus:ring-[#800000] heading-kh bg-gray-50/50" placeholder="ឈ្មោះមុខវិជ្ជា..." />
                <div className="flex bg-gray-100 p-1 rounded-2xl">
                  <button onClick={() => setBulkType('mcq')} className={`flex-1 rounded-xl text-[10px] font-black uppercase transition-all ${bulkType === 'mcq' ? 'bg-white text-blue-700 shadow-sm' : 'text-gray-400'}`}>QCM</button>
                  <button onClick={() => setBulkType('short')} className={`flex-1 rounded-xl text-[10px] font-black uppercase transition-all ${bulkType === 'short' ? 'bg-white text-orange-700 shadow-sm' : 'text-gray-400'}`}>Q & A</button>
                </div>
              </div>
              <textarea value={bulkText} onChange={(e) => setBulkText(e.target.value)} className="w-full px-6 py-6 rounded-[2rem] border border-gray-100 min-h-[400px] small-kh text-xs bg-gray-50/50 outline-none focus:ring-2 focus:ring-[#800000]" placeholder="ចម្លងកម្រងសំណួរដាក់ទីនេះ..." />
              <button onClick={handleBulkSubmit} className="w-full bg-[#800000] text-white font-black py-5 rounded-[2rem] shadow-xl hover:brightness-110 transition-all heading-kh text-lg">ចាប់ផ្ដើមនាំចូល</button>
            </div>
          )}

          {entryMode === 'subjects' && (
            <div className="animate-fadeIn space-y-12">
               <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                {groupedSubjects.mcq.map((s, i) => (
                  <div key={`m-${i}`} className={`group glass-card p-6 rounded-[2.5rem] border transition-all flex flex-col justify-between ${s.isActive ? 'bg-white border-white shadow-xl' : 'bg-gray-100/50 border-gray-200 grayscale opacity-60'}`}>
                    <div>
                      <div className="flex justify-between items-start mb-4">
                        <div className="flex-1 truncate pr-2">
                          <div className="flex items-center gap-2 mb-2">
                            <h3 className="text-lg font-black heading-kh text-[#800000] truncate">{s.name}</h3>
                            <button onClick={() => handleEditSubject(s.name, 'mcq')} className="p-1.5 bg-red-50 text-[#800000] rounded-lg hover:bg-[#800000] hover:text-white transition-all shadow-sm">✏️</button>
                          </div>
                          <div className="flex flex-wrap gap-2">
                            <span className="text-[9px] font-black bg-blue-50 text-blue-600 px-3 py-1 rounded-full uppercase">QCM ({s.count})</span>
                            <span className={`text-[9px] font-black px-3 py-1 rounded-full uppercase ${s.isActive ? 'bg-green-50 text-green-600' : 'bg-gray-200 text-gray-500'}`}>{s.isActive ? 'Active' : 'Inactive'}</span>
                          </div>
                        </div>
                        <div className="flex flex-col gap-1">
                          <button disabled={i === 0} onClick={() => onReorderSubject(s.name, 'mcq', 'up')} className="w-8 h-8 flex items-center justify-center rounded-lg bg-white border border-gray-100 shadow-sm hover:bg-[#800000] hover:text-white disabled:opacity-20 transition-all">🔼</button>
                          <button disabled={i === groupedSubjects.mcq.length - 1} onClick={() => onReorderSubject(s.name, 'mcq', 'down')} className="w-8 h-8 flex items-center justify-center rounded-lg bg-white border border-gray-100 shadow-sm hover:bg-[#800000] hover:text-white disabled:opacity-20 transition-all">🔽</button>
                        </div>
                      </div>
                    </div>
                    <div className="grid grid-cols-2 gap-2 mt-4">
                      <button onClick={() => setViewingExport({ name: s.name, type: 'mcq', mode: 'pdf' })} className="py-2.5 bg-indigo-50 text-indigo-600 rounded-xl font-black text-[10px] hover:bg-indigo-600 hover:text-white transition-all shadow-sm">📄 PDF</button>
                      <button onClick={() => setViewingExport({ name: s.name, type: 'mcq', mode: 'image' })} className="py-2.5 bg-orange-50 text-orange-600 rounded-xl font-black text-[10px] hover:bg-orange-600 hover:text-white transition-all shadow-sm">🖼️ Image</button>
                      <button onClick={() => setViewingExport({ name: s.name, type: 'mcq', mode: 'telegram' })} className="col-span-2 py-3 bg-blue-600 text-white rounded-xl font-black text-[10px] hover:brightness-110 transition-all shadow-md">✈️ Telegram</button>
                      <div className="col-span-2 flex gap-2 pt-2">
                        <button onClick={() => onToggleSubject(s.name, 'mcq', !s.isActive)} className="flex-1 py-2 rounded-lg text-[9px] font-bold border border-gray-100 hover:bg-gray-50">{s.isActive ? 'បិទដំណើរការ' : 'បើកដំណើរការ'}</button>
                        <button onClick={() => { if(confirm('លុប?')) onRemoveSubject(s.name, 'mcq') }} className="p-2 bg-red-50 text-red-500 rounded-lg hover:bg-red-500 hover:text-white">🗑️</button>
                      </div>
                    </div>
                  </div>
                ))}
                {groupedSubjects.short.map((s, i) => (
                  <div key={`s-${i}`} className={`group glass-card p-6 rounded-[2.5rem] border transition-all flex flex-col justify-between ${s.isActive ? 'bg-white border-white shadow-xl' : 'bg-gray-100/50 border-gray-200 grayscale opacity-60'}`}>
                    <div>
                       <div className="flex justify-between items-start mb-4">
                        <div className="flex-1 truncate pr-2">
                          <div className="flex items-center gap-2 mb-2">
                            <h3 className="text-lg font-black heading-kh text-[#800000] truncate">{s.name}</h3>
                            <button onClick={() => handleEditSubject(s.name, 'short')} className="p-1.5 bg-red-50 text-[#800000] rounded-lg hover:bg-[#800000] hover:text-white transition-all shadow-sm">✏️</button>
                          </div>
                          <div className="flex flex-wrap gap-2">
                            <span className="text-[9px] font-black bg-orange-50 text-orange-600 px-3 py-1 rounded-full uppercase">Q & A ({s.count})</span>
                            <span className={`text-[9px] font-black px-3 py-1 rounded-full uppercase ${s.isActive ? 'bg-green-50 text-green-600' : 'bg-gray-200 text-gray-500'}`}>{s.isActive ? 'Active' : 'Inactive'}</span>
                          </div>
                        </div>
                        <div className="flex flex-col gap-1">
                          <button disabled={i === 0} onClick={() => onReorderSubject(s.name, 'short', 'up')} className="w-8 h-8 flex items-center justify-center rounded-lg bg-white border border-gray-100 shadow-sm hover:bg-[#800000] hover:text-white disabled:opacity-20 transition-all">🔼</button>
                          <button disabled={i === groupedSubjects.short.length - 1} onClick={() => onReorderSubject(s.name, 'short', 'down')} className="w-8 h-8 flex items-center justify-center rounded-lg bg-white border border-gray-100 shadow-sm hover:bg-[#800000] hover:text-white disabled:opacity-20 transition-all">🔽</button>
                        </div>
                      </div>
                    </div>
                    <div className="grid grid-cols-2 gap-2 mt-4">
                      <button onClick={() => setViewingExport({ name: s.name, type: 'short', mode: 'pdf' })} className="py-2.5 bg-indigo-50 text-indigo-600 rounded-xl font-black text-[10px] hover:bg-indigo-600 hover:text-white transition-all shadow-sm">📄 PDF</button>
                      <button onClick={() => setViewingExport({ name: s.name, type: 'short', mode: 'image' })} className="py-2.5 bg-orange-50 text-orange-600 rounded-xl font-black text-[10px] hover:bg-orange-600 hover:text-white transition-all shadow-sm">🖼️ Image</button>
                      <button onClick={() => setViewingExport({ name: s.name, type: 'short', mode: 'telegram' })} className="col-span-2 py-3 bg-blue-600 text-white rounded-xl font-black text-[10px] hover:brightness-110 transition-all shadow-md">✈️ Telegram</button>
                      <div className="col-span-2 flex gap-2 pt-2">
                        <button onClick={() => onToggleSubject(s.name, 'short', !s.isActive)} className="flex-1 py-2 rounded-lg text-[9px] font-bold border border-gray-100 hover:bg-gray-50">{s.isActive ? 'បិទដំណើរការ' : 'បើកដំណើរការ'}</button>
                        <button onClick={() => { if(confirm('លុប?')) onRemoveSubject(s.name, 'short') }} className="p-2 bg-red-50 text-red-500 rounded-lg hover:bg-red-500 hover:text-white">🗑️</button>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {entryMode === 'feedback' && (
            <div className="animate-fadeIn space-y-8">
              {feedbackList.map(fb => (
                <div key={fb.id} className="glass-card rounded-[2rem] p-8 border border-gray-100 shadow-sm flex flex-col gap-4 relative">
                  <div className="flex justify-between items-center">
                    <h4 className="font-black heading-kh text-[#800000]">{fb.username} <span className="text-gray-400 text-[10px]">{new Date(fb.createdAt).toLocaleString()}</span></h4>
                    <button onClick={() => fb.id && onDeleteFeedback && onDeleteFeedback(fb.id)} className="p-2 text-red-500 hover:bg-red-50 rounded-lg">🗑️</button>
                  </div>
                  <p className="small-kh text-gray-700">{fb.text}</p>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>

      {/* Universal Modern Export Modal */}
      {viewingExport && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex items-center justify-center z-[100] p-4 animate-fadeIn">
          <div className="bg-white p-10 rounded-[3rem] max-w-sm w-full shadow-2xl relative overflow-hidden">
            <div className="absolute top-0 left-0 w-full h-2 bg-gradient-to-r from-blue-600 via-red-700 to-indigo-900"></div>

            <h3 className="heading-kh text-2xl mb-8 text-indigo-950 text-center font-black">ការនាំចេញ៖ {viewingExport.mode.toUpperCase()}</h3>

            <div className="space-y-6">
              {viewingExport.mode === 'image' && (
                <div className="space-y-3">
                  <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">ជ្រើសរើស Template រូបភាព</p>
                  <div className="grid grid-cols-3 gap-2">
                    {['classic', 'royal', 'vivid'].map(temp => (
                      <button 
                        key={temp} 
                        onClick={() => setSelectedTemplate(temp as ExportTemplate)}
                        className={`py-3 rounded-xl border-2 transition-all text-[9px] font-black uppercase ${selectedTemplate === temp ? 'border-indigo-900 bg-indigo-50 text-indigo-950' : 'border-gray-100 text-gray-400'}`}
                      >
                        {temp}
                      </button>
                    ))}
                  </div>
                </div>
              )}

              {viewingExport.mode === 'telegram' && (
                <div className="p-5 bg-blue-50/50 rounded-2xl space-y-4 border border-blue-100">
                  <div className="space-y-2">
                    <p className="text-[10px] font-black text-blue-800 uppercase tracking-widest">ជ្រើសរើស Channel</p>
                    <select value={tgConfig.chatId} onChange={(e) => setTgConfig({...tgConfig, chatId: e.target.value})} className="w-full p-3.5 rounded-xl border-none outline-none text-[11px] font-black shadow-sm bg-white">
                      {TG_CHANNELS.map(c => <option key={c.value} value={c.value}>{c.label}</option>)}
                    </select>
                  </div>
                  <label className="flex items-center gap-3 cursor-pointer group">
                    <div className={`w-12 h-6 rounded-full relative transition-all ${sendAsImage ? 'bg-blue-600' : 'bg-gray-300'}`}>
                      <div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-all ${sendAsImage ? 'left-7' : 'left-1'}`}></div>
                    </div>
                    <input type="checkbox" className="hidden" checked={sendAsImage} onChange={(e) => setSendAsImage(e.target.checked)} />
                    <span className="text-[11px] font-black text-indigo-950">ផ្ញើជារូបភាព</span>
                  </label>
                  {sendAsImage && (
                     <div className="pt-2 border-t border-blue-100">
                        <p className="text-[10px] font-black text-blue-800 uppercase mb-2">ម៉ូដរូបភាព</p>
                        <div className="grid grid-cols-3 gap-1">
                          {['classic', 'royal', 'vivid'].map(temp => (
                            <button key={temp} onClick={() => setSelectedTemplate(temp as ExportTemplate)} className={`py-2 rounded-lg text-[8px] font-black transition-all ${selectedTemplate === temp ? 'bg-blue-600 text-white' : 'bg-white text-gray-400'}`}>{temp}</button>
                          ))}
                        </div>
                     </div>
                  )}
                </div>
              )}

              {isProcessing && (
                <div className="space-y-2">
                   <div className="w-full h-2 bg-gray-100 rounded-full overflow-hidden">
                      <div className="h-full bg-indigo-900 transition-all duration-300" style={{ width: `${(currentProcessIndex / activeExportQuestions.length) * 100}%` }}></div>
                   </div>
                   <p className="text-center text-[10px] font-black text-gray-400">ដំណើរការ៖ {toKhmerNumeral(currentProcessIndex)} / {toKhmerNumeral(activeExportQuestions.length)}</p>
                </div>
              )}

              <div className="flex flex-col gap-2 pt-4">
                <button 
                  onClick={viewingExport.mode === 'pdf' ? handleExportPdf : viewingExport.mode === 'image' ? handleExportImageZip : handleSendAllTelegram}
                  disabled={isProcessing}
                  className="w-full py-4 bg-indigo-950 text-white rounded-2xl heading-kh font-black shadow-lg hover:brightness-110 active:scale-95 transition-all disabled:opacity-50"
                >
                  {isProcessing ? 'កំពុងដំណើរការ...' : 'យល់ព្រម និងបន្ត'}
                </button>
                <button onClick={() => !isProcessing && setViewingExport(null)} disabled={isProcessing} className="w-full py-4 bg-gray-100 text-gray-600 rounded-2xl heading-kh font-black active:scale-95 transition-all disabled:opacity-30">បោះបង់</button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default CreateSection;

import * as React from 'react';
import { useState, useMemo, useRef } from 'react';
import { Question, TelegramConfig, Feedback } from '../types';
import { DEFAULT_TG_BOT_TOKEN, TG_CHANNELS } from '../constants';
import html2canvas from 'html2canvas';
import { sendQuizPoll, sendQuestionImage } from '../services/telegramService';

declare var html2pdf: any;
declare var JSZip: any;

interface CreateSectionProps {
  quizData: Question[];
  feedbackList?: Feedback[];
  onDeleteFeedback?: (id: string) => void;
  onAdd: (q: Question) => void;
  onUpdate: (index: number, q: Question) => void;
  onRemove: (index: number) => void;
  onToggleSubject: (subject: string, type: 'mcq' | 'short', active: boolean) => void;
  onUpdateSubject: (subject: string, type: 'mcq' | 'short', newName: string) => void;
  onRemoveSubject: (subject: string, type: 'mcq' | 'short') => void;
  onReorderSubject: (subject: string, type: 'mcq' | 'short', direction: 'up' | 'down') => void;
  onBatchAdd: (qs: Question[]) => void;
  onLogout: () => void;
}

type ExportTemplate = 'classic' | 'royal' | 'vivid';
type TelegramSendMode = 'poll' | 'image' | 'text';

const CreateSection: React.FC<CreateSectionProps> = ({ 
  quizData, feedbackList = [], onDeleteFeedback, onAdd, onUpdate, onRemove, onToggleSubject, onUpdateSubject, onRemoveSubject, onReorderSubject, onBatchAdd
}) => {
  const APP_LOGO_URL = "https://i.postimg.cc/0ygmLdvR/3QCM_Ep4.png";
  const KHMER_PREFIXES = ['ក', 'ខ', 'គ', 'ឃ'];
  const KHMER_DIGITS = ['០', '១', '២', '៣', '៤', '៥', '៦', '៧', '៨', '៩'];

  const [entryMode, setEntryMode] = useState<'single' | 'bulk' | 'subjects' | 'feedback'>('single');
  const [qType, setQType] = useState<'mcq' | 'short'>('mcq');
  const [bulkType, setBulkType] = useState<'mcq' | 'short'>('mcq');
  const [subject, setSubject] = useState('');
  const [question, setQuestion] = useState('');
  const [options, setOptions] = useState(['', '', '', '']);
  const [correct, setCorrect] = useState(0);
  const [shortAnswer, setShortAnswer] = useState('');
  const [editingIndex, setEditingIndex] = useState<number | null>(null);
  const [bulkText, setBulkText] = useState('');

  const [viewingExport, setViewingExport] = useState<{name: string, type: 'mcq' | 'short', mode: 'pdf' | 'image' | 'telegram'} | null>(null);
  const [viewingQuestions, setViewingQuestions] = useState<{name: string, type: 'mcq' | 'short'} | null>(null);
  const [selectedTemplate, setSelectedTemplate] = useState<ExportTemplate>('classic');
  const [isProcessing, setIsProcessing] = useState(false);
  const [currentProcessIndex, setCurrentProcessIndex] = useState(0);

  const [tgConfig, setTgConfig] = useState<TelegramConfig>({ botToken: DEFAULT_TG_BOT_TOKEN, chatId: TG_CHANNELS[0].value });
  const [individualSendMode, setIndividualSendMode] = useState<TelegramSendMode>('poll');

  const imageTemplateRef = useRef<HTMLDivElement>(null);
  const pdfTemplateRef = useRef<HTMLDivElement>(null);
  const [previewQ, setPreviewQ] = useState<Question | null>(null);

  const toKhmerNumeral = (n: number) => n.toString().split('').map(digit => KHMER_DIGITS[parseInt(digit)] || digit).join('');

  const groupedSubjects = useMemo(() => {
    const getList = (type: 'mcq' | 'short') => {
      const seen = new Set<string>();
      const list: any[] = [];
      quizData.filter(q => q.type === type).forEach(q => {
        if (!seen.has(q.subject)) {
          seen.add(q.subject);
          const related = quizData.filter(rq => rq.subject === q.subject && rq.type === type);
          list.push({ name: q.subject, isActive: related.every(rq => rq.isActive !== false), count: related.length, type });
        }
      });
      return list;
    };
    return { mcq: getList('mcq'), short: getList('short') };
  }, [quizData]);

  const activeExportQuestions = useMemo(() => {
    const target = viewingExport || viewingQuestions;
    if (!target) return [];
    return quizData.filter(q => q.subject === target.name && q.type === target.type);
  }, [quizData, viewingExport, viewingQuestions]);

  const handleEditSubject = (oldName: string, type: 'mcq' | 'short') => {
    const newName = prompt("បញ្ចូលឈ្មោះមុខវិជ្ជាថ្មី៖", oldName);
    if (newName && newName.trim() && newName !== oldName) {
      onUpdateSubject(oldName, type, newName.trim());
    }
  };

  const captureImageBlob = async (): Promise<Blob | null> => {
    if (!imageTemplateRef.current) return null;
    try {
      const canvas = await html2canvas(imageTemplateRef.current, { scale: 2, useCORS: true, backgroundColor: null });
      return new Promise(r => canvas.toBlob(r, 'image/png', 1.0));
    } catch (e) { return null; }
  };

  const handleExportPdf = async () => {
    if (!pdfTemplateRef.current || !viewingExport) return;
    setIsProcessing(true);
    try {
      const opt = {
        margin: 10,
        filename: `Vignasa_${viewingExport.name}.pdf`,
        image: { type: 'jpeg', quality: 0.98 },
        html2canvas: { scale: 2, useCORS: true },
        jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' }
      };
      await html2pdf().from(pdfTemplateRef.current).set(opt).save();
    } catch (e) {
      alert("កំហុសក្នុងការបង្កើត PDF");
    } finally {
      setIsProcessing(false);
    }
  };

  const handleExportImageZip = async () => {
    if (!viewingExport) return;
    setIsProcessing(true);
    setCurrentProcessIndex(0);
    const zip = new JSZip();
    try {
      for (let i = 0; i < activeExportQuestions.length; i++) {
        const q = activeExportQuestions[i];
        setPreviewQ(q);
        setCurrentProcessIndex(i + 1);
        await new Promise(r => setTimeout(r, 200));
        const blob = await captureImageBlob();
        if (blob) zip.file(`Question_${toKhmerNumeral(i + 1)}.png`, blob);
      }
      const content = await zip.generateAsync({ type: "blob" });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(content);
      link.download = `Images_${viewingExport.name}_${selectedTemplate}.zip`;
      link.click();
    } catch (e) {
      alert("កំហុសក្នុងការបង្កើត ZIP");
    } finally {
      setPreviewQ(null);
      setIsProcessing(false);
    }
  };

  const handleSendTelegramAction = async (q: Question, idx: number, mode: TelegramSendMode) => {
    try {
      if (mode === 'image') {
        setPreviewQ(q);
        setCurrentProcessIndex(idx + 1);
        await new Promise(r => setTimeout(r, 200));
        const blob = await captureImageBlob();
        if (blob) {
          const caption = `📌 *សំណួរទី ${toKhmerNumeral(idx + 1)}*\n\n📋 វិញ្ញាសា៖ ${q.subject}\n✨ ផ្តល់ជូនដោយ Web QCM 🇰🇭`;
          const res = await sendQuestionImage(tgConfig, blob, caption);
          return res.ok;
        }
      } else if (mode === 'poll' && q.type === 'mcq') {
        const res = await sendQuizPoll(tgConfig, q);
        return res.ok;
      } else {
        // Mode Text
        let text = `📌 *សំណួរ៖* ${q.question}\n\n`;
        if (q.type === 'mcq' && q.options) {
          q.options.forEach((o, i) => { text += `${KHMER_PREFIXES[i]}. ${o}\n`; });
        } else {
          text += `✅ *ចម្លើយ៖* ${q.answer}\n`;
        }
        text += `\n📋 វិញ្ញាសា៖ ${q.subject}\n✨ Web QCM 🇰🇭`;

        const response = await fetch(`https://api.telegram.org/bot${tgConfig.botToken}/sendMessage`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ chat_id: tgConfig.chatId, text, parse_mode: 'Markdown' })
        });
        const data = await response.json();
        return data.ok;
      }
    } catch (e) { console.error(e); return false; }
    return false;
  };

  const [confirmIndividualSend, setConfirmIndividualSend] = useState<{q: Question, idx: number} | null>(null);

  const handleSendAllTelegram = async () => {
    if (!confirm(`ផ្ញើទាំង ${toKhmerNumeral(activeExportQuestions.length)} សំណួរ?`)) return;
    setIsProcessing(true);
    setCurrentProcessIndex(0);
    const mode = individualSendMode; 
    for (let i = 0; i < activeExportQuestions.length; i++) {
      setCurrentProcessIndex(i + 1);
      await handleSendTelegramAction(activeExportQuestions[i], i, mode);
      await new Promise(r => setTimeout(r, 3000));
    }
    setIsProcessing(false);
    setPreviewQ(null);
    alert("រួចរាល់!");
  };

  const handleSubmitSingle = () => {
    if (!subject.trim() || !question.trim()) return alert("សូមបំពេញព័ត៌មាន!");
    const cleanQ: Question = {
      subject: subject.trim(),
      question: question.trim(),
      type: qType,
      isActive: true,
      ...(qType === 'mcq' ? { options: options.map(o => o.trim()), correct } : { answer: shortAnswer.trim() })
    };
    if (editingIndex !== null) onUpdate(editingIndex, cleanQ); else onAdd(cleanQ);
    setQuestion(''); setOptions(['', '', '', '']); setShortAnswer(''); setEditingIndex(null);
    alert("រក្សាទុកជោគជ័យ!");
  };

  const handleBulkSubmit = () => {
    if (!subject.trim() || !bulkText.trim()) return alert("សូមបំពេញព័ត៌មាន!");
    const lines = bulkText.split('\n');
    const parsed: Question[] = [];
    let current: any = null;
    if (bulkType === 'mcq') {
      lines.forEach(l => {
        const t = l.trim(); if (!t) return;
        const qm = t.match(/^[០-៩0-9]+\.\s*(.*)/);
        if (qm) {
          if (current && current.options?.length >= 2) parsed.push(current);
          current = { type: 'mcq', subject: subject.trim(), question: qm[1].trim(), options: [], correct: 0, isActive: true };
          return;
        }
        const om = t.match(/^[កខគឃ]\.\s*(.*)/);
        if (om && current) {
          let txt = om[1].replace('(ចម្លើយត្រឹមត្រូវ)', '').trim();
          current.options.push(txt);
          if (om[1].includes('(ចម្លើយត្រឹមត្រូវ)')) current.correct = current.options.length - 1;
        }
      });
      if (current && current.options?.length >= 2) parsed.push(current);
    } else {
      let isAnswer = false;
      lines.forEach(l => {
        const t = l.trim(); if (!t) return;
        const qm = t.match(/^[០-៩0-9]+\.\s*(.*)/);
        if (qm) {
          if (current && current.answer) parsed.push(current);
          current = { type: 'short', subject: subject.trim(), question: qm[1].trim(), answer: '', isActive: true };
          isAnswer = false; return;
        }
        const am = t.match(/^ចម្លើយ\s*[៖:]\s*(.*)/);
        if (am && current) { current.answer = am[1].trim(); isAnswer = true; return; }
        if (isAnswer && current) current.answer += (current.answer ? '\n' : '') + l;
      });
      if (current && current.answer) parsed.push(current);
    }
    if (parsed.length) { onBatchAdd(parsed); setBulkText(''); alert(`បានបញ្ចូល ${parsed.length} សំណួរ!`); }
  };

  const SubjectActionCard = ({ s, type, i }: { s: any, type: 'mcq' | 'short', i: number }) => (
    <div key={`${type}-${i}`} className={`group glass-card p-6 rounded-[2.5rem] border transition-all flex flex-col justify-between ${s.isActive ? 'bg-white border-white shadow-xl' : 'bg-gray-100/50 border-gray-200 grayscale opacity-60'}`}>
      <div>
        <div className="flex justify-between items-start mb-4">
          <div className="flex-1 truncate pr-2">
            <div className="flex items-center gap-2 mb-2">
              <h3 className="text-lg font-black heading-kh text-[#800000] truncate">{s.name}</h3>
              <button onClick={() => handleEditSubject(s.name, type)} className="p-1.5 bg-red-50 text-[#800000] rounded-lg hover:bg-[#800000] hover:text-white transition-all shadow-sm">✏️</button>
            </div>
            <div className="flex flex-wrap gap-2">
              <span className={`text-[9px] font-black px-3 py-1 rounded-full uppercase ${type === 'mcq' ? 'bg-blue-50 text-blue-600' : 'bg-orange-50 text-orange-600'}`}>{type.toUpperCase()} ({s.count})</span>
              <span className={`text-[9px] font-black px-3 py-1 rounded-full uppercase ${s.isActive ? 'bg-green-50 text-green-600' : 'bg-gray-200 text-gray-500'}`}>{s.isActive ? 'Active' : 'Inactive'}</span>
            </div>
          </div>
          <div className="flex flex-col gap-1">
            <button disabled={i === 0} onClick={() => onReorderSubject(s.name, type, 'up')} className="w-8 h-8 flex items-center justify-center rounded-lg bg-white border border-gray-100 shadow-sm hover:bg-[#800000] hover:text-white disabled:opacity-20 transition-all">🔼</button>
            <button disabled={i === groupedSubjects[type].length - 1} onClick={() => onReorderSubject(s.name, type, 'down')} className="w-8 h-8 flex items-center justify-center rounded-lg bg-white border border-gray-100 shadow-sm hover:bg-[#800000] hover:text-white disabled:opacity-20 transition-all">🔽</button>
          </div>
        </div>
      </div>
      <div className="grid grid-cols-2 gap-2 mt-4">
        <button onClick={() => setViewingQuestions({ name: s.name, type })} className="col-span-2 py-2.5 bg-gray-50 text-indigo-900 rounded-xl font-black text-[10px] border border-gray-100 hover:bg-indigo-900 hover:text-white transition-all">👁️ មើលសំណួរ</button>
        <button onClick={() => setViewingExport({ name: s.name, type, mode: 'pdf' })} className="py-2.5 bg-indigo-50 text-indigo-600 rounded-xl font-black text-[10px] hover:bg-indigo-600 hover:text-white transition-all">📄 PDF</button>
        <button onClick={() => setViewingExport({ name: s.name, type, mode: 'image' })} className="py-2.5 bg-orange-50 text-orange-600 rounded-xl font-black text-[10px] hover:bg-orange-600 hover:text-white transition-all">🖼️ Image</button>
        <button onClick={() => setViewingExport({ name: s.name, type, mode: 'telegram' })} className="col-span-2 py-3 bg-blue-600 text-white rounded-xl font-black text-[10px] hover:brightness-110 transition-all shadow-md">✈️ ផ្ញើទៅ Telegram</button>
        <div className="col-span-2 flex gap-2 pt-2">
          <button onClick={() => onToggleSubject(s.name, type, !s.isActive)} className="flex-1 py-2 rounded-lg text-[9px] font-bold border border-gray-100 hover:bg-gray-50">{s.isActive ? 'បិទដំណើរការ' : 'បើកដំណើរការ'}</button>
          <button onClick={() => { if(confirm('លុប?')) onRemoveSubject(s.name, type) }} className="p-2 bg-red-50 text-red-500 rounded-lg hover:bg-red-500 hover:text-white">🗑️</button>
        </div>
      </div>
    </div>
  );

  return (
    <div className="space-y-8 animate-fadeIn pb-32">
      {/* Hidden Templates for Export */}
      <div className="fixed -left-[9999px] top-0 pointer-events-none overflow-hidden">
        {/* PDF Template */}
        <div ref={pdfTemplateRef} style={{ width: '210mm', padding: '15mm 20mm', background: '#fff', color: '#000', fontFamily: 'Kantumruy Pro, sans-serif' }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '10mm', borderBottom: '2px solid #800000', paddingBottom: '5mm' }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: '10mm' }}>
               <img src={APP_LOGO_URL} style={{ height: '25mm' }} alt="Logo" />
               <div>
                  <h1 style={{ fontSize: '20pt', fontWeight: 'bold', margin: 0 }}>វិញ្ញាសា៖ {viewingExport?.name || viewingQuestions?.name}</h1>
                  <p style={{ margin: '2mm 0', opacity: 0.6 }}>ប្រភេទ៖ {viewingExport?.type.toUpperCase() || viewingQuestions?.type.toUpperCase()}</p>
               </div>
            </div>
            <div style={{ textAlign: 'right' }}>
              <p style={{ fontWeight: 'bold', margin: 0 }}>Web QCM 🇰🇭</p>
              <p style={{ margin: '1mm 0', fontSize: '10pt' }}>{new Date().toLocaleDateString('km-KH')}</p>
            </div>
          </div>
          {activeExportQuestions.map((q, i) => (
            <div key={i} style={{ marginBottom: '8mm', pageBreakInside: 'avoid' }}>
              <p style={{ fontWeight: 'bold', fontSize: '14pt', lineHeight: 1.4 }}>សំណួរ {toKhmerNumeral(i + 1)}៖ {q.question}</p>
              {q.type === 'mcq' ? (
                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '5mm', marginTop: '3mm', paddingLeft: '8mm' }}>
                  {q.options?.map((o, oi) => <p key={oi} style={{ margin: 0 }}>{KHMER_PREFIXES[oi]}. {o}</p>)}
                </div>
              ) : (
                <p style={{ fontStyle: 'italic', opacity: 0.6, marginTop: '3mm', paddingLeft: '8mm' }}>ចម្លើយ៖ .................................................................................</p>
              )}
            </div>
          ))}
        </div>

        {/* IMAGE TEMPLATE ENGINE */}
        <div ref={imageTemplateRef} style={{ 
          width: '1080px', height: '1080px', padding: '100px', borderRadius: '60px', overflow: 'hidden', position: 'relative', display: 'flex', flexDirection: 'column',
          ...(selectedTemplate === 'classic' ? { background: '#fff', color: '#000', border: '15px solid #800000' } : 
             selectedTemplate === 'royal' ? { background: 'linear-gradient(135deg, #1e1b4b 0%, #020617 100%)', color: '#fff', border: '10px solid #800000' } :
             { background: 'linear-gradient(135deg, #800000 0%, #5e0000 100%)', color: '#fff', border: '10px solid #fff' })
        }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '60px' }}>
            <img src={APP_LOGO_URL} style={{ height: '140px' }} />
            <div style={{ textAlign: 'right' }}>
               <div style={{ 
                 padding: '10px 30px', borderRadius: '15px', fontWeight: 'bold', fontSize: '24pt', 
                 ...(selectedTemplate === 'classic' ? { background: '#800000', color: '#fff' } : { background: '#fff', color: '#800000' })
               }}>សំណួរទី {toKhmerNumeral(currentProcessIndex)}</div>
               <div style={{ fontSize: '18pt', marginTop: '10px', opacity: 0.6 }}>វិញ្ញាសា៖ {viewingExport?.name || viewingQuestions?.name}</div>
            </div>
          </div>
          <div style={{ flex: 1, display: 'flex', flexDirection: 'column', justifyContent: 'center' }}>
            <h2 style={{ fontSize: '38pt', fontWeight: 'bold', lineHeight: 1.5, marginBottom: '80px' }}>{previewQ?.question}</h2>
            {previewQ?.type === 'mcq' && (
              <div style={{ display: 'grid', gridTemplateColumns: '1fr', gap: '25px' }}>
                {previewQ.options?.map((o, i) => (
                  <div key={i} style={{ 
                    padding: '30px 40px', borderRadius: '25px', display: 'flex', alignItems: 'center', gap: '30px', fontSize: '26pt', fontWeight: '500',
                    ...(selectedTemplate === 'classic' ? { background: '#f8fafc', border: '2px solid #e2e8f0' } : { background: 'rgba(255,255,255,0.05)', border: '1px solid rgba(255,255,255,0.1)' })
                  }}>
                    <span style={{ 
                      width: '65px', height: '65px', borderRadius: '15px', display: 'flex', alignItems: 'center', justifyContent: 'center', fontWeight: 'bold',
                      background: selectedTemplate === 'classic' ? '#800000' : '#fff', color: selectedTemplate === 'classic' ? '#fff' : '#800000'
                    }}>{KHMER_PREFIXES[i]}</span>
                    <span>{o}</span>
                  </div>
                ))}
              </div>
            )}
          </div>
          <div style={{ marginTop: '60px', paddingTop: '40px', borderTop: '1px solid rgba(128,128,128,0.2)', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
            <span style={{ fontSize: '22pt', fontWeight: 'bold', opacity: 0.5 }}>WEB QCM 🇰🇭</span>
            <span style={{ fontSize: '20pt', fontWeight: '500' }}>t.me/web_qcm_q_and_a</span>
          </div>
        </div>
      </div>

      <div className="glass-card rounded-[2.5rem] shadow-xl p-6 border border-white/50">
        <div className="bg-gray-100/80 p-1.5 rounded-2xl flex flex-wrap md:flex-nowrap gap-1 mb-10 border border-gray-200 shadow-inner">
          {[
            { id: 'single', label: '✍️ បញ្ចូលសំណួរ' },
            { id: 'bulk', label: '🚀 បញ្ចូលទាំងអស់' },
            { id: 'subjects', label: '📚 គ្រប់គ្រងទិន្នន័យ' },
            { id: 'feedback', label: '💬 មតិយោបល់' }
          ].map(tab => (
            <button key={tab.id} onClick={() => setEntryMode(tab.id as any)} className={`flex-1 min-w-[140px] py-3.5 px-4 rounded-xl font-black heading-kh text-[11px] transition-all duration-300 ${entryMode === tab.id ? 'bg-red-700 text-white shadow-lg' : 'text-gray-500 hover:text-red-700'}`}>
              {tab.label}
              {tab.id === 'feedback' && feedbackList.length > 0 && <span className="ml-2 bg-white text-red-700 px-2 py-0.5 rounded-full text-[8px]">{feedbackList.length}</span>}
            </button>
          ))}
        </div>

        <div className="px-2">
          {entryMode === 'single' && (
            <div className="space-y-6 animate-fadeIn">
               {/* Form Single - keep current */}
               <div className="flex flex-wrap gap-4 items-center justify-between">
                <h2 className="text-xl font-black heading-kh text-[#800000]">{editingIndex !== null ? '✏️ កែសម្រួលសំណួរ' : '🆕 បង្កើតសំណួរថ្មី'}</h2>
                <div className="flex bg-gray-100 p-1 rounded-xl">
                  {['mcq', 'short'].map(t => (
                    <button key={t} onClick={() => setQType(t as any)} className={`px-4 py-2 rounded-lg text-[10px] font-black uppercase transition-all ${qType === t ? 'bg-white text-[#800000] shadow-sm' : 'text-gray-400'}`}>{t === 'mcq' ? 'QCM' : 'Q & A'}</button>
                  ))}
                </div>
              </div>
              <div className="grid grid-cols-1 gap-5">
                <input type="text" value={subject} onChange={(e) => setSubject(e.target.value)} className="w-full px-6 py-4 rounded-2xl border border-gray-100 outline-none focus:ring-2 focus:ring-[#800000] heading-kh bg-gray-50/50" placeholder="ឈ្មោះមុខវិជ្ជា..." />
                <textarea value={question} onChange={(e) => setQuestion(e.target.value)} className="w-full px-6 py-4 rounded-2xl border border-gray-100 focus:ring-2 focus:ring-[#800000] outline-none min-h-[120px] small-kh bg-gray-50/50" placeholder="សរសេរសំណួរ..." />
                {qType === 'mcq' ? (
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    {options.map((opt, i) => (
                      <div key={i} className="flex items-center gap-3 bg-white p-4 rounded-2xl border border-gray-100 shadow-sm focus-within:border-[#800000]/30">
                        <span className="font-black text-[#800000] w-10 h-10 flex items-center justify-center bg-red-50 rounded-xl">{KHMER_PREFIXES[i]}</span>
                        <input type="text" value={opt} onChange={(e) => { const n = [...options]; n[i] = e.target.value; setOptions(n); }} className="flex-1 outline-none small-kh text-sm" placeholder={`ចម្លើយទី ${i+1}`} />
                        <button onClick={() => setCorrect(i)} className={`w-8 h-8 rounded-lg flex items-center justify-center border-2 transition-all ${correct === i ? 'bg-green-500 border-green-500 text-white' : 'border-gray-100 text-gray-200'}`}>✓</button>
                      </div>
                    ))}
                  </div>
                ) : (
                  <textarea value={shortAnswer} onChange={(e) => setShortAnswer(e.target.value)} className="w-full px-6 py-4 rounded-2xl border border-gray-100 outline-none focus:ring-2 focus:ring-[#800000] small-kh bg-gray-50/50 min-h-[100px]" placeholder="បញ្ចូលចម្លើយត្រឹមត្រូវ..." />
                )}
              </div>
              <button onClick={handleSubmitSingle} className="w-full bg-[#800000] text-white font-black py-5 rounded-[2rem] shadow-xl hover:brightness-110 transition-all heading-kh text-lg">រក្សាទុកសំណួរ</button>
            </div>
          )}

          {entryMode === 'bulk' && (
            <div className="space-y-6 animate-fadeIn">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <input type="text" value={subject} onChange={(e) => setSubject(e.target.value)} className="w-full px-6 py-4 rounded-2xl border border-gray-100 outline-none focus:ring-2 focus:ring-[#800000] heading-kh bg-gray-50/50" placeholder="ឈ្មោះមុខវិជ្ជា..." />
                <div className="flex bg-gray-100 p-1 rounded-2xl">
                  <button onClick={() => setBulkType('mcq')} className={`flex-1 rounded-xl text-[10px] font-black uppercase transition-all ${bulkType === 'mcq' ? 'bg-white text-blue-700 shadow-sm' : 'text-gray-400'}`}>QCM</button>
                  <button onClick={() => setBulkType('short')} className={`flex-1 rounded-xl text-[10px] font-black uppercase transition-all ${bulkType === 'short' ? 'bg-white text-orange-700 shadow-sm' : 'text-gray-400'}`}>Q & A</button>
                </div>
              </div>
              <textarea value={bulkText} onChange={(e) => setBulkText(e.target.value)} className="w-full px-6 py-6 rounded-[2rem] border border-gray-100 min-h-[400px] small-kh text-xs bg-gray-50/50 outline-none focus:ring-2 focus:ring-[#800000]" placeholder="ចម្លងកម្រងសំណួរដាក់ទីនេះ..." />
              <button onClick={handleBulkSubmit} className="w-full bg-[#800000] text-white font-black py-5 rounded-[2rem] shadow-xl hover:brightness-110 transition-all heading-kh text-lg">ចាប់ផ្ដើមនាំចូល</button>
            </div>
          )}

          {entryMode === 'subjects' && (
            <div className="animate-fadeIn space-y-12">
               <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                {groupedSubjects.mcq.map((s, i) => <SubjectActionCard key={`m-${i}`} s={s} type="mcq" i={i} />)}
                {groupedSubjects.short.map((s, i) => <SubjectActionCard key={`s-${i}`} s={s} type="short" i={i} />)}
              </div>
            </div>
          )}

          {entryMode === 'feedback' && (
            <div className="animate-fadeIn space-y-8">
              {feedbackList.map(fb => (
                <div key={fb.id} className="glass-card rounded-[2rem] p-8 border border-gray-100 shadow-sm flex flex-col gap-4 relative">
                  <div className="flex justify-between items-center">
                    <h4 className="font-black heading-kh text-[#800000]">{fb.username} <span className="text-gray-400 text-[10px]">{new Date(fb.createdAt).toLocaleString()}</span></h4>
                    <button onClick={() => fb.id && onDeleteFeedback && onDeleteFeedback(fb.id)} className="p-2 text-red-500 hover:bg-red-50 rounded-lg">🗑️</button>
                  </div>
                  <p className="small-kh text-gray-700">{fb.text}</p>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>

      {/* Viewing Questions Modal */}
      {viewingQuestions && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex items-center justify-center z-[110] p-4 animate-fadeIn">
          <div className="bg-white p-6 md:p-10 rounded-[3rem] max-w-4xl w-full max-h-[90vh] overflow-y-auto shadow-2xl border border-white/20">
            <div className="flex justify-between items-center mb-8 pb-4 border-bottom border-gray-100">
               <h3 className="heading-kh text-2xl font-black text-indigo-950 truncate pr-4">{viewingQuestions.name} ({activeExportQuestions.length})</h3>
               <button onClick={() => setViewingQuestions(null)} className="w-10 h-10 bg-gray-100 rounded-xl hover:bg-red-500 hover:text-white transition-all flex items-center justify-center text-xl">✕</button>
            </div>

            <div className="space-y-4">
              {activeExportQuestions.map((q, idx) => (
                <div key={idx} className="p-6 bg-gray-50 rounded-[2rem] border border-gray-100 flex flex-col md:flex-row gap-6 items-start md:items-center group">
                  <span className="w-10 h-10 bg-white rounded-xl shadow-inner border border-gray-200 flex items-center justify-center font-black text-[#800000] shrink-0">{toKhmerNumeral(idx + 1)}</span>
                  <p className="flex-1 heading-kh text-sm text-indigo-950 leading-relaxed line-clamp-2 md:line-clamp-none">{q.question}</p>
                  <div className="flex gap-2 shrink-0">
                    <button onClick={() => setConfirmIndividualSend({q, idx})} className="px-4 py-2 bg-blue-600 text-white rounded-xl text-[10px] font-black hover:brightness-110 shadow-sm">✈️ ផ្ញើទៅ Telegram</button>
                    <button onClick={() => {
                        const originalIdx = quizData.findIndex(item => item === q);
                        if(originalIdx !== -1) {
                          setSubject(q.subject);
                          setQuestion(q.question);
                          setQType(q.type);
                          if(q.type === 'mcq') {
                            setOptions(q.options || ['', '', '', '']);
                            setCorrect(q.correct || 0);
                          } else {
                            setShortAnswer(q.answer || '');
                          }
                          setEditingIndex(originalIdx);
                          setEntryMode('single');
                          setViewingQuestions(null);
                        }
                    }} className="p-2 bg-indigo-50 text-indigo-600 rounded-xl hover:bg-indigo-600 hover:text-white transition-all">✏️</button>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}

      {/* Individual Question Send Config Modal */}
      {confirmIndividualSend && (
        <div className="fixed inset-0 bg-black/80 backdrop-blur-md flex items-center justify-center z-[150] p-4 animate-fadeIn">
          <div className="bg-white p-10 rounded-[3rem] max-w-sm w-full shadow-2xl border border-white/20">
            <h3 className="heading-kh text-xl mb-6 text-indigo-950 text-center font-black">ជ្រើសរើសទម្រង់ផ្ញើ</h3>
            <div className="p-4 bg-gray-50 rounded-2xl mb-6 space-y-2">
              <p className="text-[10px] font-black text-gray-400 uppercase">Channel</p>
              <select value={tgConfig.chatId} onChange={(e) => setTgConfig({...tgConfig, chatId: e.target.value})} className="w-full p-3 rounded-xl border-none outline-none text-[11px] font-black shadow-sm bg-white">
                {TG_CHANNELS.map(c => <option key={c.value} value={c.value}>{c.label}</option>)}
              </select>
            </div>

            <div className="grid grid-cols-1 gap-2 mb-8">
              {[
                { id: 'poll', label: '📊 ផ្ញើជា Poll', desc: '(សំណួរពហុចម្លើយ)' },
                { id: 'image', label: '🖼️ ផ្ញើជារូបភាព', desc: '(Template ទំនើប)' },
                { id: 'text', label: '📝 ផ្ញើជា Text', desc: '(Markdown ស្អាត)' }
              ].map(mode => (
                <button 
                  key={mode.id} 
                  onClick={() => setIndividualSendMode(mode.id as any)}
                  className={`p-4 rounded-2xl border-2 text-left transition-all ${individualSendMode === mode.id ? 'border-[#800000] bg-red-50' : 'border-gray-100 hover:border-gray-200'}`}
                >
                  <p className="font-black text-xs text-indigo-950">{mode.label}</p>
                  <p className="text-[8px] opacity-50">{mode.desc}</p>
                </button>
              ))}
            </div>

            <div className="flex flex-col gap-2">
               <button 
                onClick={async () => {
                   setIsProcessing(true);
                   const success = await handleSendTelegramAction(confirmIndividualSend.q, confirmIndividualSend.idx, individualSendMode);
                   setIsProcessing(false);
                   if (success) { setConfirmIndividualSend(null); alert("ផ្ញើរួចរាល់!"); }
                   else alert("កំហុសក្នុងការផ្ញើ!");
                }}
                disabled={isProcessing}
                className="w-full py-4 bg-[#800000] text-white rounded-2xl heading-kh font-black shadow-lg hover:brightness-110 active:scale-95 transition-all disabled:opacity-50"
              >
                {isProcessing ? 'កំពុងផ្ញើ...' : 'យល់ព្រមផ្ញើ'}
              </button>
              <button onClick={() => setConfirmIndividualSend(null)} disabled={isProcessing} className="w-full py-4 bg-gray-100 text-gray-600 rounded-2xl heading-kh font-black">បោះបង់</button>
            </div>
          </div>
        </div>
      )}

      {/* Universal Modal for Bulk Export - keep current */}
      {viewingExport && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex items-center justify-center z-[110] p-4 animate-fadeIn">
          <div className="bg-white p-10 rounded-[3rem] max-w-sm w-full shadow-2xl relative overflow-hidden">
            <div className="absolute top-0 left-0 w-full h-2 bg-gradient-to-r from-blue-600 via-red-700 to-indigo-900"></div>
            <h3 className="heading-kh text-2xl mb-8 text-indigo-950 text-center font-black">ការនាំចេញ៖ {viewingExport.mode.toUpperCase()}</h3>

            <div className="space-y-6">
              {viewingExport.mode === 'image' && (
                <div className="space-y-3">
                  <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">ជ្រើសរើស Template រូបភាព</p>
                  <div className="grid grid-cols-3 gap-2">
                    {['classic', 'royal', 'vivid'].map(temp => (
                      <button key={temp} onClick={() => setSelectedTemplate(temp as ExportTemplate)} className={`py-3 rounded-xl border-2 transition-all text-[9px] font-black uppercase ${selectedTemplate === temp ? 'border-indigo-900 bg-indigo-50 text-indigo-950' : 'border-gray-100 text-gray-400'}`}>{temp}</button>
                    ))}
                  </div>
                </div>
              )}

              {viewingExport.mode === 'telegram' && (
                <div className="p-5 bg-blue-50/50 rounded-2xl space-y-4 border border-blue-100">
                  <p className="text-[10px] font-black text-blue-800 uppercase tracking-widest ml-1">Channel៖ {TG_CHANNELS.find(c => c.value === tgConfig.chatId)?.label}</p>
                  <div className="grid grid-cols-1 gap-2">
                    <p className="text-[10px] font-black text-gray-400 uppercase">ទម្រង់ផ្ញើសំណួរ (សម្រាប់ទាំងអស់)</p>
                    <div className="grid grid-cols-3 gap-1">
                      {['poll', 'image', 'text'].map(m => (
                        <button key={m} onClick={() => setIndividualSendMode(m as any)} className={`py-2 rounded-lg text-[8px] font-black transition-all ${individualSendMode === m ? 'bg-blue-600 text-white' : 'bg-white text-gray-400'}`}>{m}</button>
                      ))}
                    </div>
                  </div>
                </div>
              )}

              {isProcessing && (
                <div className="space-y-2">
                   <div className="w-full h-2 bg-gray-100 rounded-full overflow-hidden shadow-inner">
                      <div className="h-full bg-indigo-900 transition-all duration-300" style={{ width: `${(currentProcessIndex / activeExportQuestions.length) * 100}%` }}></div>
                   </div>
                   <p className="text-center text-[10px] font-black text-gray-400">ដំណើរការ៖ {toKhmerNumeral(currentProcessIndex)} / {toKhmerNumeral(activeExportQuestions.length)}</p>
                </div>
              )}

              <div className="flex flex-col gap-2 pt-4">
                <button 
                  onClick={viewingExport.mode === 'pdf' ? handleExportPdf : viewingExport.mode === 'image' ? handleExportImageZip : handleSendAllTelegram}
                  disabled={isProcessing}
                  className="w-full py-4 bg-indigo-950 text-white rounded-2xl heading-kh font-black shadow-lg hover:brightness-110 active:scale-95 transition-all disabled:opacity-50"
                >
                  {isProcessing ? 'កំពុងដំណើរការ...' : 'យល់ព្រម និងបន្ត'}
                </button>
                <button onClick={() => !isProcessing && setViewingExport(null)} disabled={isProcessing} className="w-full py-4 bg-gray-100 text-gray-600 rounded-2xl heading-kh font-black">បោះបង់</button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default CreateSection;

import * as React from 'react';
import { useState, useMemo, useRef } from 'react';
import { Question, TelegramConfig, Feedback } from '../types';
import { DEFAULT_TG_BOT_TOKEN, TG_CHANNELS } from '../constants';
import html2canvas from 'html2canvas';
import { sendQuizPoll, sendQuestionImage } from '../services/telegramService';

declare var html2pdf: any;
declare var JSZip: any;

interface CreateSectionProps {
  quizData: Question[];
  feedbackList?: Feedback[];
  onDeleteFeedback?: (id: string) => void;
  onAdd: (q: Question) => void;
  onUpdate: (index: number, q: Question) => void;
  onRemove: (index: number) => void;
  onToggleSubject: (subject: string, type: 'mcq' | 'short', active: boolean) => void;
  onUpdateSubject: (subject: string, type: 'mcq' | 'short', newName: string) => void;
  onRemoveSubject: (subject: string, type: 'mcq' | 'short') => void;
  onReorderSubject: (subject: string, type: 'mcq' | 'short', direction: 'up' | 'down') => void;
  onBatchAdd: (qs: Question[]) => void;
  onLogout: () => void;
}

type ExportTemplate = 'classic' | 'royal' | 'vivid';
type TelegramSendMode = 'poll' | 'image' | 'text';

const CreateSection: React.FC<CreateSectionProps> = ({ 
  quizData, feedbackList = [], onDeleteFeedback, onAdd, onUpdate, onRemove, onToggleSubject, onUpdateSubject, onRemoveSubject, onReorderSubject, onBatchAdd
}) => {
  const APP_LOGO_URL = "https://i.postimg.cc/0ygmLdvR/3QCM_Ep4.png";
  const KHMER_PREFIXES = ['ក', 'ខ', 'គ', 'ឃ'];
  const KHMER_DIGITS = ['០', '១', '២', '៣', '៤', '៥', '៦', '៧', '៨', '៩'];

  const [entryMode, setEntryMode] = useState<'single' | 'bulk' | 'subjects' | 'feedback'>('single');
  const [qType, setQType] = useState<'mcq' | 'short'>('mcq');
  const [bulkType, setBulkType] = useState<'mcq' | 'short'>('mcq');
  const [subject, setSubject] = useState('');
  const [question, setQuestion] = useState('');
  const [options, setOptions] = useState(['', '', '', '']);
  const [correct, setCorrect] = useState(0);
  const [shortAnswer, setShortAnswer] = useState('');
  const [editingIndex, setEditingIndex] = useState<number | null>(null);
  const [bulkText, setBulkText] = useState('');

  const [viewingExport, setViewingExport] = useState<{name: string, type: 'mcq' | 'short', mode: 'pdf' | 'image'} | null>(null);
  const [viewingQuestions, setViewingQuestions] = useState<{name: string, type: 'mcq' | 'short'} | null>(null);
  const [selectedTemplate, setSelectedTemplate] = useState<ExportTemplate>('classic');
  const [isProcessing, setIsProcessing] = useState(false);
  const [currentProcessIndex, setCurrentProcessIndex] = useState(0);

  const [tgConfig, setTgConfig] = useState<TelegramConfig>({ botToken: DEFAULT_TG_BOT_TOKEN, chatId: TG_CHANNELS[0].value });
  const [individualSendMode, setIndividualSendMode] = useState<TelegramSendMode>('poll');
  const [confirmIndividualSend, setConfirmIndividualSend] = useState<{q: Question, idx: number} | null>(null);

  const imageTemplateRef = useRef<HTMLDivElement>(null);
  const pdfTemplateRef = useRef<HTMLDivElement>(null);
  const [previewQ, setPreviewQ] = useState<Question | null>(null);

  const toKhmerNumeral = (n: number) => n.toString().split('').map(digit => KHMER_DIGITS[parseInt(digit)] || digit).join('');

  const groupedSubjects = useMemo(() => {
    const getList = (type: 'mcq' | 'short') => {
      const seen = new Set<string>();
      const list: any[] = [];
      quizData.filter(q => q.type === type).forEach(q => {
        if (!seen.has(q.subject)) {
          seen.add(q.subject);
          const related = quizData.filter(rq => rq.subject === q.subject && rq.type === type);
          list.push({ name: q.subject, isActive: related.every(rq => rq.isActive !== false), count: related.length, type });
        }
      });
      return list;
    };
    return { mcq: getList('mcq'), short: getList('short') };
  }, [quizData]);

  const activeQuestionsInView = useMemo(() => {
    const target = viewingExport || viewingQuestions;
    if (!target) return [];
    return quizData.filter(q => q.subject === target.name && q.type === target.type);
  }, [quizData, viewingExport, viewingQuestions]);

  const handleEditSubject = (oldName: string, type: 'mcq' | 'short') => {
    const newName = prompt("បញ្ចូលឈ្មោះមុខវិជ្ជាថ្មី៖", oldName);
    if (newName && newName.trim() && newName !== oldName) {
      onUpdateSubject(oldName, type, newName.trim());
    }
  };

  const captureImageBlob = async (): Promise<Blob | null> => {
    if (!imageTemplateRef.current) return null;
    try {
      const canvas = await html2canvas(imageTemplateRef.current, { scale: 2, useCORS: true, backgroundColor: null });
      return new Promise(r => canvas.toBlob(r, 'image/png', 1.0));
    } catch (e) { return null; }
  };

  const handleExportPdf = async () => {
    if (!pdfTemplateRef.current || !viewingExport) return;
    setIsProcessing(true);
    try {
      const opt = {
        margin: 10,
        filename: `Vignasa_${viewingExport.name}.pdf`,
        image: { type: 'jpeg', quality: 0.98 },
        html2canvas: { scale: 2, useCORS: true },
        jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' }
      };
      await html2pdf().from(pdfTemplateRef.current).set(opt).save();
    } catch (e) {
      alert("កំហុសក្នុងការបង្កើត PDF");
    } finally {
      setIsProcessing(false);
    }
  };

  const handleExportImageZip = async () => {
    if (!viewingExport) return;
    setIsProcessing(true);
    setCurrentProcessIndex(0);
    const zip = new JSZip();
    try {
      const questions = activeQuestionsInView;
      for (let i = 0; i < questions.length; i++) {
        const q = questions[i];
        setPreviewQ(q);
        setCurrentProcessIndex(i + 1);
        await new Promise(r => setTimeout(r, 200));
        const blob = await captureImageBlob();
        if (blob) zip.file(`Question_${toKhmerNumeral(i + 1)}.png`, blob);
      }
      const content = await zip.generateAsync({ type: "blob" });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(content);
      link.download = `Images_${viewingExport.name}_${selectedTemplate}.zip`;
      link.click();
    } catch (e) {
      alert("កំហុសក្នុងការបង្កើត ZIP");
    } finally {
      setPreviewQ(null);
      setIsProcessing(false);
    }
  };

  const handleSendTelegramAction = async (q: Question, idx: number, mode: TelegramSendMode) => {
    try {
      if (mode === 'image') {
        setPreviewQ(q);
        setCurrentProcessIndex(idx + 1);
        await new Promise(r => setTimeout(r, 200));
        const blob = await captureImageBlob();
        if (blob) {
          const caption = `📌 *សំណួរទី ${toKhmerNumeral(idx + 1)}*\n\n📋 វិញ្ញាសា៖ ${q.subject}\n✨ ផ្តល់ជូនដោយ Web QCM 🇰🇭`;
          const res = await sendQuestionImage(tgConfig, blob, caption);
          return res.ok;
        }
      } else if (mode === 'poll' && q.type === 'mcq') {
        const res = await sendQuizPoll(tgConfig, q);
        return res.ok;
      } else {
        // Mode Text
        let text = `📌 *សំណួរ៖* ${q.question}\n\n`;
        if (q.type === 'mcq' && q.options) {
          q.options.forEach((o, i) => { text += `${KHMER_PREFIXES[i]}. ${o}\n`; });
        } else {
          text += `✅ *ចម្លើយ៖* ${q.answer}\n`;
        }
        text += `\n📋 វិញ្ញាសា៖ ${q.subject}\n✨ Web QCM 🇰🇭`;

        const response = await fetch(`https://api.telegram.org/bot${tgConfig.botToken}/sendMessage`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ chat_id: tgConfig.chatId, text, parse_mode: 'Markdown' })
        });
        const data = await response.json();
        return data.ok;
      }
    } catch (e) { console.error(e); return false; }
    return false;
  };

  const handleSubmitSingle = () => {
    if (!subject.trim() || !question.trim()) return alert("សូមបំពេញព័ត៌មាន!");
    const cleanQ: Question = {
      subject: subject.trim(),
      question: question.trim(),
      type: qType,
      isActive: true,
      ...(qType === 'mcq' ? { options: options.map(o => o.trim()), correct } : { answer: shortAnswer.trim() })
    };
    if (editingIndex !== null) onUpdate(editingIndex, cleanQ); else onAdd(cleanQ);
    setQuestion(''); setOptions(['', '', '', '']); setShortAnswer(''); setEditingIndex(null);
    alert("រក្សាទុកជោគជ័យ!");
  };

  const handleBulkSubmit = () => {
    if (!subject.trim() || !bulkText.trim()) return alert("សូមបំពេញព័ត៌មាន!");
    const lines = bulkText.split('\n');
    const parsed: Question[] = [];
    let current: any = null;
    if (bulkType === 'mcq') {
      lines.forEach(l => {
        const t = l.trim(); if (!t) return;
        const qm = t.match(/^[០-៩0-9]+\.\s*(.*)/);
        if (qm) {
          if (current && current.options?.length >= 2) parsed.push(current);
          current = { type: 'mcq', subject: subject.trim(), question: qm[1].trim(), options: [], correct: 0, isActive: true };
          return;
        }
        const om = t.match(/^[កខគឃ]\.\s*(.*)/);
        if (om && current) {
          let txt = om[1].replace('(ចម្លើយត្រឹមត្រូវ)', '').trim();
          current.options.push(txt);
          if (om[1].includes('(ចម្លើយត្រឹមត្រូវ)')) current.correct = current.options.length - 1;
        }
      });
      if (current && current.options?.length >= 2) parsed.push(current);
    } else {
      let isAnswer = false;
      lines.forEach(l => {
        const t = l.trim(); if (!t) return;
        const qm = t.match(/^[០-៩0-9]+\.\s*(.*)/);
        if (qm) {
          if (current && current.answer) parsed.push(current);
          current = { type: 'short', subject: subject.trim(), question: qm[1].trim(), answer: '', isActive: true };
          isAnswer = false; return;
        }
        const am = t.match(/^ចម្លើយ\s*[៖:]\s*(.*)/);
        if (am && current) { current.answer = am[1].trim(); isAnswer = true; return; }
        if (isAnswer && current) current.answer += (current.answer ? '\n' : '') + l;
      });
      if (current && current.answer) parsed.push(current);
    }
    if (parsed.length) { onBatchAdd(parsed); setBulkText(''); alert(`បានបញ្ចូល ${parsed.length} សំណួរ!`); }
  };

  const SubjectActionCard = ({ s, type, i }: { s: any, type: 'mcq' | 'short', i: number }) => (
    <div key={`${type}-${i}`} className={`group glass-card p-6 rounded-[2.5rem] border transition-all flex flex-col justify-between ${s.isActive ? 'bg-white border-white shadow-xl' : 'bg-gray-100/50 border-gray-200 grayscale opacity-60'}`}>
      <div>
        <div className="flex justify-between items-start mb-4">
          <div className="flex-1 truncate pr-2">
            <div className="flex items-center gap-2 mb-2">
              <h3 className="text-lg font-black heading-kh text-[#800000] truncate">{s.name}</h3>
              <button onClick={() => handleEditSubject(s.name, type)} className="p-1.5 bg-red-50 text-[#800000] rounded-lg hover:bg-[#800000] hover:text-white transition-all shadow-sm">✏️</button>
            </div>
            <div className="flex flex-wrap gap-2">
              <span className={`text-[9px] font-black px-3 py-1 rounded-full uppercase ${type === 'mcq' ? 'bg-blue-50 text-blue-600' : 'bg-orange-50 text-orange-600'}`}>{type.toUpperCase()} ({s.count})</span>
              <span className={`text-[9px] font-black px-3 py-1 rounded-full uppercase ${s.isActive ? 'bg-green-50 text-green-600' : 'bg-gray-200 text-gray-500'}`}>{s.isActive ? 'Active' : 'Inactive'}</span>
            </div>
          </div>
          <div className="flex flex-col gap-1">
            <button disabled={i === 0} onClick={() => onReorderSubject(s.name, type, 'up')} className="w-8 h-8 flex items-center justify-center rounded-lg bg-white border border-gray-100 shadow-sm hover:bg-[#800000] hover:text-white disabled:opacity-20 transition-all">🔼</button>
            <button disabled={i === groupedSubjects[type].length - 1} onClick={() => onReorderSubject(s.name, type, 'down')} className="w-8 h-8 flex items-center justify-center rounded-lg bg-white border border-gray-100 shadow-sm hover:bg-[#800000] hover:text-white disabled:opacity-20 transition-all">🔽</button>
          </div>
        </div>
      </div>
      <div className="grid grid-cols-2 gap-2 mt-4">
        <button onClick={() => setViewingQuestions({ name: s.name, type })} className="col-span-2 py-3 bg-indigo-950 text-white rounded-xl font-black text-[11px] shadow-md hover:brightness-110 transition-all">👁️ មើលសំណួរ & ផ្ញើ Telegram</button>
        <button onClick={() => setViewingExport({ name: s.name, type, mode: 'pdf' })} className="py-2.5 bg-indigo-50 text-indigo-600 rounded-xl font-black text-[10px] hover:bg-indigo-600 hover:text-white transition-all">📄 PDF</button>
        <button onClick={() => setViewingExport({ name: s.name, type, mode: 'image' })} className="py-2.5 bg-orange-50 text-orange-600 rounded-xl font-black text-[10px] hover:bg-orange-600 hover:text-white transition-all">🖼️ Image</button>
        <div className="col-span-2 flex gap-2 pt-2">
          <button onClick={() => onToggleSubject(s.name, type, !s.isActive)} className="flex-1 py-2 rounded-lg text-[9px] font-bold border border-gray-100 hover:bg-gray-50">{s.isActive ? 'បិទដំណើរការ' : 'បើកដំណើរការ'}</button>
          <button onClick={() => { if(confirm('លុប?')) onRemoveSubject(s.name, type) }} className="p-2 bg-red-50 text-red-500 rounded-lg hover:bg-red-500 hover:text-white">🗑️</button>
        </div>
      </div>
    </div>
  );

  return (
    <div className="space-y-8 animate-fadeIn pb-32">
      {/* Hidden Templates for Export */}
      <div className="fixed -left-[9999px] top-0 pointer-events-none overflow-hidden">
        {/* PDF Template */}
        <div ref={pdfTemplateRef} style={{ width: '210mm', padding: '15mm 20mm', background: '#fff', color: '#000', fontFamily: 'Kantumruy Pro, sans-serif' }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '10mm', borderBottom: '2px solid #800000', paddingBottom: '5mm' }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: '10mm' }}>
               <img src={APP_LOGO_URL} style={{ height: '25mm' }} alt="Logo" />
               <div>
                  <h1 style={{ fontSize: '20pt', fontWeight: 'bold', margin: 0 }}>វិញ្ញាសា៖ {viewingExport?.name || viewingQuestions?.name}</h1>
                  <p style={{ margin: '2mm 0', opacity: 0.6 }}>ប្រភេទ៖ {viewingExport?.type.toUpperCase() || viewingQuestions?.type.toUpperCase()}</p>
               </div>
            </div>
            <div style={{ textAlign: 'right' }}>
              <p style={{ fontWeight: 'bold', margin: 0 }}>Web QCM 🇰🇭</p>
              <p style={{ margin: '1mm 0', fontSize: '10pt' }}>{new Date().toLocaleDateString('km-KH')}</p>
            </div>
          </div>
          {activeQuestionsInView.map((q, i) => (
            <div key={i} style={{ marginBottom: '8mm', pageBreakInside: 'avoid' }}>
              <p style={{ fontWeight: 'bold', fontSize: '14pt', lineHeight: 1.4 }}>សំណួរ {toKhmerNumeral(i + 1)}៖ {q.question}</p>
              {q.type === 'mcq' ? (
                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '5mm', marginTop: '3mm', paddingLeft: '8mm' }}>
                  {q.options?.map((o, oi) => <p key={oi} style={{ margin: 0 }}>{KHMER_PREFIXES[oi]}. {o}</p>)}
                </div>
              ) : (
                <p style={{ fontStyle: 'italic', opacity: 0.6, marginTop: '3mm', paddingLeft: '8mm' }}>ចម្លើយ៖ .................................................................................</p>
              )}
            </div>
          ))}
        </div>

        {/* IMAGE TEMPLATE ENGINE with LOGO */}
        <div ref={imageTemplateRef} style={{ 
          width: '1080px', height: '1080px', padding: '100px', borderRadius: '60px', overflow: 'hidden', position: 'relative', display: 'flex', flexDirection: 'column',
          ...(selectedTemplate === 'classic' ? { background: '#fff', color: '#000', border: '15px solid #800000' } : 
             selectedTemplate === 'royal' ? { background: 'linear-gradient(135deg, #1e1b4b 0%, #020617 100%)', color: '#fff', border: '10px solid #800000' } :
             { background: 'linear-gradient(135deg, #800000 0%, #5e0000 100%)', color: '#fff', border: '10px solid #fff' })
        }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '60px' }}>
            <img src={APP_LOGO_URL} style={{ height: '150px' }} />
            <div style={{ textAlign: 'right' }}>
               <div style={{ 
                 padding: '10px 30px', borderRadius: '15px', fontWeight: 'bold', fontSize: '24pt', 
                 ...(selectedTemplate === 'classic' ? { background: '#800000', color: '#fff' } : { background: '#fff', color: '#800000' })
               }}>សំណួរទី {toKhmerNumeral(currentProcessIndex)}</div>
               <div style={{ fontSize: '18pt', marginTop: '10px', opacity: 0.6 }}>វិញ្ញាសា៖ {viewingExport?.name || viewingQuestions?.name}</div>
            </div>
          </div>
          <div style={{ flex: 1, display: 'flex', flexDirection: 'column', justifyContent: 'center' }}>
            <h2 style={{ fontSize: '38pt', fontWeight: 'bold', lineHeight: 1.5, marginBottom: '80px' }}>{previewQ?.question}</h2>
            {previewQ?.type === 'mcq' && (
              <div style={{ display: 'grid', gridTemplateColumns: '1fr', gap: '25px' }}>
                {previewQ.options?.map((o, i) => (
                  <div key={i} style={{ 
                    padding: '30px 40px', borderRadius: '25px', display: 'flex', alignItems: 'center', gap: '30px', fontSize: '26pt', fontWeight: '500',
                    ...(selectedTemplate === 'classic' ? { background: '#f8fafc', border: '2px solid #e2e8f0' } : { background: 'rgba(255,255,255,0.05)', border: '1px solid rgba(255,255,255,0.1)' })
                  }}>
                    <span style={{ 
                      width: '65px', height: '65px', borderRadius: '15px', display: 'flex', alignItems: 'center', justifyContent: 'center', fontWeight: 'bold',
                      background: selectedTemplate === 'classic' ? '#800000' : '#fff', color: selectedTemplate === 'classic' ? '#fff' : '#800000'
                    }}>{KHMER_PREFIXES[i]}</span>
                    <span>{o}</span>
                  </div>
                ))}
              </div>
            )}
          </div>
          <div style={{ marginTop: '60px', paddingTop: '40px', borderTop: '1px solid rgba(128,128,128,0.2)', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
            <span style={{ fontSize: '22pt', fontWeight: 'bold', opacity: 0.5 }}>WEB QCM 🇰🇭</span>
            <span style={{ fontSize: '20pt', fontWeight: '500' }}>t.me/web_qcm_q_and_a</span>
          </div>
        </div>
      </div>

      <div className="glass-card rounded-[2.5rem] shadow-xl p-6 border border-white/50">
        <div className="bg-gray-100/80 p-1.5 rounded-2xl flex flex-wrap md:flex-nowrap gap-1 mb-10 border border-gray-200 shadow-inner">
          {[
            { id: 'single', label: '✍️ បញ្ចូលសំណួរ' },
            { id: 'bulk', label: '🚀 បញ្ចូលទាំងអស់' },
            { id: 'subjects', label: '📚 គ្រប់គ្រងទិន្នន័យ' },
            { id: 'feedback', label: '💬 មតិយោបល់' }
          ].map(tab => (
            <button key={tab.id} onClick={() => setEntryMode(tab.id as any)} className={`flex-1 min-w-[140px] py-3.5 px-4 rounded-xl font-black heading-kh text-[11px] transition-all duration-300 ${entryMode === tab.id ? 'bg-red-700 text-white shadow-lg' : 'text-gray-500 hover:text-red-700'}`}>
              {tab.label}
              {tab.id === 'feedback' && feedbackList.length > 0 && <span className="ml-2 bg-white text-red-700 px-2 py-0.5 rounded-full text-[8px]">{feedbackList.length}</span>}
            </button>
          ))}
        </div>

        <div className="px-2">
          {entryMode === 'single' && (
            <div className="space-y-6 animate-fadeIn">
               <div className="flex flex-wrap gap-4 items-center justify-between">
                <h2 className="text-xl font-black heading-kh text-[#800000]">{editingIndex !== null ? '✏️ កែសម្រួលសំណួរ' : '🆕 បង្កើតសំណួរថ្មី'}</h2>
                <div className="flex bg-gray-100 p-1 rounded-xl">
                  {['mcq', 'short'].map(t => (
                    <button key={t} onClick={() => setQType(t as any)} className={`px-4 py-2 rounded-lg text-[10px] font-black uppercase transition-all ${qType === t ? 'bg-white text-[#800000] shadow-sm' : 'text-gray-400'}`}>{t === 'mcq' ? 'QCM' : 'Q & A'}</button>
                  ))}
                </div>
              </div>
              <div className="grid grid-cols-1 gap-5">
                <input type="text" value={subject} onChange={(e) => setSubject(e.target.value)} className="w-full px-6 py-4 rounded-2xl border border-gray-100 outline-none focus:ring-2 focus:ring-[#800000] heading-kh bg-gray-50/50" placeholder="ឈ្មោះមុខវិជ្ជា..." />
                <textarea value={question} onChange={(e) => setQuestion(e.target.value)} className="w-full px-6 py-4 rounded-2xl border border-gray-100 focus:ring-2 focus:ring-[#800000] outline-none min-h-[120px] small-kh bg-gray-50/50" placeholder="សរសេរសំណួរ..." />
                {qType === 'mcq' ? (
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    {options.map((opt, i) => (
                      <div key={i} className="flex items-center gap-3 bg-white p-4 rounded-2xl border border-gray-100 shadow-sm focus-within:border-[#800000]/30">
                        <span className="font-black text-[#800000] w-10 h-10 flex items-center justify-center bg-red-50 rounded-xl">{KHMER_PREFIXES[i]}</span>
                        <input type="text" value={opt} onChange={(e) => { const n = [...options]; n[i] = e.target.value; setOptions(n); }} className="flex-1 outline-none small-kh text-sm" placeholder={`ចម្លើយទី ${i+1}`} />
                        <button onClick={() => setCorrect(i)} className={`w-8 h-8 rounded-lg flex items-center justify-center border-2 transition-all ${correct === i ? 'bg-green-500 border-green-500 text-white' : 'border-gray-100 text-gray-200'}`}>✓</button>
                      </div>
                    ))}
                  </div>
                ) : (
                  <textarea value={shortAnswer} onChange={(e) => setShortAnswer(e.target.value)} className="w-full px-6 py-4 rounded-2xl border border-gray-100 outline-none focus:ring-2 focus:ring-[#800000] small-kh bg-gray-50/50 min-h-[100px]" placeholder="បញ្ចូលចម្លើយត្រឹមត្រូវ..." />
                )}
              </div>
              <button onClick={handleSubmitSingle} className="w-full bg-[#800000] text-white font-black py-5 rounded-[2rem] shadow-xl hover:brightness-110 transition-all heading-kh text-lg">រក្សាទុកសំណួរ</button>
            </div>
          )}

          {entryMode === 'bulk' && (
            <div className="space-y-6 animate-fadeIn">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <input type="text" value={subject} onChange={(e) => setSubject(e.target.value)} className="w-full px-6 py-4 rounded-2xl border border-gray-100 outline-none focus:ring-2 focus:ring-[#800000] heading-kh bg-gray-50/50" placeholder="ឈ្មោះមុខវិជ្ជា..." />
                <div className="flex bg-gray-100 p-1 rounded-2xl">
                  <button onClick={() => setBulkType('mcq')} className={`flex-1 rounded-xl text-[10px] font-black uppercase transition-all ${bulkType === 'mcq' ? 'bg-white text-blue-700 shadow-sm' : 'text-gray-400'}`}>QCM</button>
                  <button onClick={() => setBulkType('short')} className={`flex-1 rounded-xl text-[10px] font-black uppercase transition-all ${bulkType === 'short' ? 'bg-white text-orange-700 shadow-sm' : 'text-gray-400'}`}>Q & A</button>
                </div>
              </div>
              <textarea value={bulkText} onChange={(e) => setBulkText(e.target.value)} className="w-full px-6 py-6 rounded-[2rem] border border-gray-100 min-h-[400px] small-kh text-xs bg-gray-50/50 outline-none focus:ring-2 focus:ring-[#800000]" placeholder="ចម្លងកម្រងសំណួរដាក់ទីនេះ..." />
              <button onClick={handleBulkSubmit} className="w-full bg-[#800000] text-white font-black py-5 rounded-[2rem] shadow-xl hover:brightness-110 transition-all heading-kh text-lg">ចាប់ផ្ដើមនាំចូល</button>
            </div>
          )}

          {entryMode === 'subjects' && (
            <div className="animate-fadeIn space-y-12">
               <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                {groupedSubjects.mcq.map((s, i) => <SubjectActionCard key={`m-${i}`} s={s} type="mcq" i={i} />)}
                {groupedSubjects.short.map((s, i) => <SubjectActionCard key={`s-${i}`} s={s} type="short" i={i} />)}
              </div>
            </div>
          )}

          {entryMode === 'feedback' && (
            <div className="animate-fadeIn space-y-8">
              {feedbackList.map(fb => (
                <div key={fb.id} className="glass-card rounded-[2rem] p-8 border border-gray-100 shadow-sm flex flex-col gap-4 relative">
                  <div className="flex justify-between items-center">
                    <h4 className="font-black heading-kh text-[#800000]">{fb.username} <span className="text-gray-400 text-[10px]">{new Date(fb.createdAt).toLocaleString()}</span></h4>
                    <button onClick={() => fb.id && onDeleteFeedback && onDeleteFeedback(fb.id)} className="p-2 text-red-500 hover:bg-red-50 rounded-lg">🗑️</button>
                  </div>
                  <p className="small-kh text-gray-700">{fb.text}</p>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>

      {/* Viewing Questions Modal - Where Telegram Send is located */}
      {viewingQuestions && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex items-center justify-center z-[110] p-4 animate-fadeIn">
          <div className="bg-white p-6 md:p-10 rounded-[3rem] max-w-4xl w-full max-h-[90vh] overflow-y-auto shadow-2xl border border-white/20">
            <div className="flex justify-between items-center mb-8 pb-4 border-b border-gray-100">
               <h3 className="heading-kh text-2xl font-black text-indigo-950 truncate pr-4">{viewingQuestions.name} ({activeQuestionsInView.length})</h3>
               <button onClick={() => setViewingQuestions(null)} className="w-10 h-10 bg-gray-100 rounded-xl hover:bg-red-500 hover:text-white transition-all flex items-center justify-center text-xl">✕</button>
            </div>

            <div className="space-y-4">
              {activeQuestionsInView.map((q, idx) => (
                <div key={idx} className="p-6 bg-gray-50 rounded-[2rem] border border-gray-100 flex flex-col md:flex-row gap-6 items-start md:items-center group">
                  <span className="w-10 h-10 bg-white rounded-xl shadow-inner border border-gray-200 flex items-center justify-center font-black text-[#800000] shrink-0">{toKhmerNumeral(idx + 1)}</span>
                  <p className="flex-1 heading-kh text-sm text-indigo-950 leading-relaxed">{q.question}</p>
                  <div className="flex gap-2 shrink-0">
                    <button onClick={() => setConfirmIndividualSend({q, idx})} className="px-5 py-2.5 bg-blue-600 text-white rounded-xl text-[10px] font-black hover:brightness-110 shadow-sm transition-all flex items-center gap-2">✈️ Telegram</button>
                    <button onClick={() => {
                        const originalIdx = quizData.findIndex(item => item === q);
                        if(originalIdx !== -1) {
                          setSubject(q.subject);
                          setQuestion(q.question);
                          setQType(q.type);
                          if(q.type === 'mcq') {
                            setOptions(q.options || ['', '', '', '']);
                            setCorrect(q.correct || 0);
                          } else {
                            setShortAnswer(q.answer || '');
                          }
                          setEditingIndex(originalIdx);
                          setEntryMode('single');
                          setViewingQuestions(null);
                        }
                    }} className="p-2.5 bg-indigo-50 text-indigo-600 rounded-xl hover:bg-indigo-600 hover:text-white transition-all">✏️</button>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}

      {/* Individual Question Send Config Modal */}
      {confirmIndividualSend && (
        <div className="fixed inset-0 bg-black/80 backdrop-blur-md flex items-center justify-center z-[150] p-4 animate-fadeIn">
          <div className="bg-white p-10 rounded-[3rem] max-w-sm w-full shadow-2xl border border-white/20">
            <h3 className="heading-kh text-xl mb-6 text-indigo-950 text-center font-black">ជ្រើសរើសទម្រង់ផ្ញើ</h3>

            <div className="p-4 bg-gray-50 rounded-2xl mb-6 space-y-2">
              <p className="text-[10px] font-black text-gray-400 uppercase">Channel</p>
              <select value={tgConfig.chatId} onChange={(e) => setTgConfig({...tgConfig, chatId: e.target.value})} className="w-full p-3 rounded-xl border-none outline-none text-[11px] font-black shadow-sm bg-white">
                {TG_CHANNELS.map(c => <option key={c.value} value={c.value}>{c.label}</option>)}
              </select>
            </div>

            <div className="grid grid-cols-1 gap-2 mb-8">
              {[
                { id: 'poll', label: '📊 ផ្ញើជា Poll', desc: '(សំណួរពហុចម្លើយ)' },
                { id: 'image', label: '🖼️ ផ្ញើជារូបភាព', desc: '(ជាមួយ Logo កម្មវិធី)' },
                { id: 'text', label: '📝 ផ្ញើជា Text', desc: '(អត្ថបទ Markdown)' }
              ].map(mode => (
                <button 
                  key={mode.id} 
                  onClick={() => setIndividualSendMode(mode.id as any)}
                  className={`p-4 rounded-2xl border-2 text-left transition-all ${individualSendMode === mode.id ? 'border-[#800000] bg-red-50' : 'border-gray-100 hover:border-gray-200'}`}
                >
                  <p className="font-black text-xs text-indigo-950">{mode.label}</p>
                  <p className="text-[8px] opacity-50">{mode.desc}</p>
                </button>
              ))}
            </div>

            {individualSendMode === 'image' && (
              <div className="mb-6 p-4 bg-gray-50 rounded-2xl">
                 <p className="text-[10px] font-black text-gray-400 uppercase mb-3 text-center">ជ្រើសរើស Template</p>
                 <div className="grid grid-cols-3 gap-1">
                   {['classic', 'royal', 'vivid'].map(t => (
                     <button key={t} onClick={() => setSelectedTemplate(t as any)} className={`py-2 rounded-lg text-[8px] font-black transition-all ${selectedTemplate === t ? 'bg-indigo-950 text-white' : 'bg-white text-gray-400'}`}>{t.toUpperCase()}</button>
                   ))}
                 </div>
              </div>
            )}

            <div className="flex flex-col gap-2">
               <button 
                onClick={async () => {
                   setIsProcessing(true);
                   const success = await handleSendTelegramAction(confirmIndividualSend.q, confirmIndividualSend.idx, individualSendMode);
                   setIsProcessing(false);
                   if (success) { setConfirmIndividualSend(null); alert("ផ្ញើរួចរាល់!"); }
                   else alert("កំហុសក្នុងការផ្ញើ!");
                }}
                disabled={isProcessing}
                className="w-full py-4 bg-[#800000] text-white rounded-2xl heading-kh font-black shadow-lg hover:brightness-110 active:scale-95 transition-all disabled:opacity-50"
              >
                {isProcessing ? 'កំពុងផ្ញើ...' : 'យល់ព្រមផ្ញើ'}
              </button>
              <button onClick={() => setConfirmIndividualSend(null)} disabled={isProcessing} className="w-full py-4 bg-gray-100 text-gray-600 rounded-2xl heading-kh font-black">បោះបង់</button>
            </div>
          </div>
        </div>
      )}

      {/* Bulk Export Modal for PDF/Image */}
      {viewingExport && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex items-center justify-center z-[110] p-4 animate-fadeIn">
          <div className="bg-white p-10 rounded-[3rem] max-w-sm w-full shadow-2xl relative overflow-hidden">
            <div className="absolute top-0 left-0 w-full h-2 bg-gradient-to-r from-blue-600 via-red-700 to-indigo-900"></div>
            <h3 className="heading-kh text-2xl mb-8 text-indigo-950 text-center font-black">ការនាំចេញ៖ {viewingExport.mode.toUpperCase()}</h3>

            <div className="space-y-6">
              {viewingExport.mode === 'image' && (
                <div className="space-y-3">
                  <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1 text-center">រចនាបថរូបភាព</p>
                  <div className="grid grid-cols-3 gap-2">
                    {['classic', 'royal', 'vivid'].map(temp => (
                      <button key={temp} onClick={() => setSelectedTemplate(temp as ExportTemplate)} className={`py-3 rounded-xl border-2 transition-all text-[9px] font-black uppercase ${selectedTemplate === temp ? 'border-indigo-900 bg-indigo-50 text-indigo-950' : 'border-gray-100 text-gray-400'}`}>{temp}</button>
                    ))}
                  </div>
                </div>
              )}

              {isProcessing && (
                <div className="space-y-2">
                   <div className="w-full h-2 bg-gray-100 rounded-full overflow-hidden shadow-inner">
                      <div className="h-full bg-indigo-900 transition-all duration-300" style={{ width: `${(currentProcessIndex / activeQuestionsInView.length) * 100}%` }}></div>
                   </div>
                   <p className="text-center text-[10px] font-black text-gray-400">ដំណើរការ៖ {toKhmerNumeral(currentProcessIndex)} / {toKhmerNumeral(activeQuestionsInView.length)}</p>
                </div>
              )}

              <div className="flex flex-col gap-2 pt-4">
                <button 
                  onClick={viewingExport.mode === 'pdf' ? handleExportPdf : handleExportImageZip}
                  disabled={isProcessing}
                  className="w-full py-4 bg-indigo-950 text-white rounded-2xl heading-kh font-black shadow-lg hover:brightness-110 active:scale-95 transition-all disabled:opacity-50"
                >
                  {isProcessing ? 'កំពុងនាំចេញ...' : 'ទាញយកទាំងអស់'}
                </button>
                <button onClick={() => !isProcessing && setViewingExport(null)} disabled={isProcessing} className="w-full py-4 bg-gray-100 text-gray-600 rounded-2xl heading-kh font-black">បោះបង់</button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default CreateSection;

import * as React from 'react';
import { useState, useMemo, useRef } from 'react';
import { Question, TelegramConfig, Feedback } from '../types';
import { DEFAULT_TG_BOT_TOKEN, TG_CHANNELS } from '../constants';
import html2canvas from 'html2canvas';
import { sendQuizPoll, sendQuestionImage } from '../services/telegramService';

declare var html2pdf: any;
declare var JSZip: any;

interface CreateSectionProps {
  quizData: Question[];
  feedbackList?: Feedback[];
  onDeleteFeedback?: (id: string) => void;
  onAdd: (q: Question) => void;
  onUpdate: (index: number, q: Question) => void;
  onRemove: (index: number) => void;
  onToggleSubject: (subject: string, type: 'mcq' | 'short', active: boolean) => void;
  onUpdateSubject: (subject: string, type: 'mcq' | 'short', newName: string) => void;
  onRemoveSubject: (subject: string, type: 'mcq' | 'short') => void;
  onReorderSubject: (subject: string, type: 'mcq' | 'short', direction: 'up' | 'down') => void;
  onBatchAdd: (qs: Question[]) => void;
  onLogout: () => void;
}

type ExportTemplate = 'classic' | 'royal' | 'vivid';
type TelegramSendMode = 'poll' | 'image' | 'text';

const CreateSection: React.FC<CreateSectionProps> = ({ 
  quizData, feedbackList = [], onDeleteFeedback, onAdd, onUpdate, onRemove, onToggleSubject, onUpdateSubject, onRemoveSubject, onReorderSubject, onBatchAdd
}) => {
  const APP_LOGO_URL = "https://i.postimg.cc/0ygmLdvR/3QCM_Ep4.png";
  const KHMER_PREFIXES = ['ក', 'ខ', 'គ', 'ឃ'];
  const KHMER_DIGITS = ['០', '១', '២', '៣', '៤', '៥', '៦', '៧', '៨', '៩'];

  const [entryMode, setEntryMode] = useState<'single' | 'bulk' | 'subjects' | 'feedback'>('single');
  const [qType, setQType] = useState<'mcq' | 'short'>('mcq');
  const [bulkType, setBulkType] = useState<'mcq' | 'short'>('mcq');
  const [subject, setSubject] = useState('');
  const [question, setQuestion] = useState('');
  const [options, setOptions] = useState(['', '', '', '']);
  const [correct, setCorrect] = useState(0);
  const [shortAnswer, setShortAnswer] = useState('');
  const [editingIndex, setEditingIndex] = useState<number | null>(null);
  const [bulkText, setBulkText] = useState('');

  const [viewingExport, setViewingExport] = useState<{name: string, type: 'mcq' | 'short', mode: 'pdf' | 'image'} | null>(null);
  const [viewingQuestions, setViewingQuestions] = useState<{name: string, type: 'mcq' | 'short'} | null>(null);
  const [selectedTemplate, setSelectedTemplate] = useState<ExportTemplate>('classic');
  const [includeAnswer, setIncludeAnswer] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [currentProcessIndex, setCurrentProcessIndex] = useState(0);

  const [tgConfig, setTgConfig] = useState<TelegramConfig>({ botToken: DEFAULT_TG_BOT_TOKEN, chatId: TG_CHANNELS[0].value });
  const [individualSendMode, setIndividualSendMode] = useState<TelegramSendMode>('poll');
  const [confirmIndividualSend, setConfirmIndividualSend] = useState<{q: Question, idx: number} | null>(null);

  const imageTemplateRef = useRef<HTMLDivElement>(null);
  const pdfTemplateRef = useRef<HTMLDivElement>(null);
  const [previewQ, setPreviewQ] = useState<Question | null>(null);

  const toKhmerNumeral = (n: number) => n.toString().split('').map(digit => KHMER_DIGITS[parseInt(digit)] || digit).join('');

  const groupedSubjects = useMemo(() => {
    const getList = (type: 'mcq' | 'short') => {
      const seen = new Set<string>();
      const list: any[] = [];
      quizData.filter(q => q.type === type).forEach(q => {
        if (!seen.has(q.subject)) {
          seen.add(q.subject);
          const related = quizData.filter(rq => rq.subject === q.subject && rq.type === type);
          list.push({ name: q.subject, isActive: related.every(rq => rq.isActive !== false), count: related.length, type });
        }
      });
      return list;
    };
    return { mcq: getList('mcq'), short: getList('short') };
  }, [quizData]);

  const activeQuestionsInView = useMemo(() => {
    const target = viewingExport || viewingQuestions;
    if (!target) return [];
    return quizData.filter(q => q.subject === target.name && q.type === target.type);
  }, [quizData, viewingExport, viewingQuestions]);

  const captureImageBlob = async (): Promise<Blob | null> => {
    if (!imageTemplateRef.current) return null;
    try {
      const canvas = await html2canvas(imageTemplateRef.current, { scale: 2, useCORS: true, backgroundColor: null, logging: false });
      return new Promise(r => canvas.toBlob(r, 'image/png', 1.0));
    } catch (e) { return null; }
  };

  const handleExportPdf = async () => {
    if (!pdfTemplateRef.current || !viewingExport) return;
    setIsProcessing(true);
    try {
      const opt = {
        margin: 10,
        filename: `Vignasa_${viewingExport.name}.pdf`,
        image: { type: 'jpeg', quality: 0.98 },
        html2canvas: { scale: 2, useCORS: true },
        jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' }
      };
      await html2pdf().from(pdfTemplateRef.current).set(opt).save();
    } catch (e) { alert("កំហុស PDF"); } finally { setIsProcessing(false); }
  };

  const handleExportImageZip = async () => {
    if (!viewingExport) return;
    setIsProcessing(true);
    setCurrentProcessIndex(0);
    const zip = new JSZip();
    try {
      const questions = activeQuestionsInView;
      for (let i = 0; i < questions.length; i++) {
        const q = questions[i];
        setPreviewQ(q);
        setCurrentProcessIndex(i + 1);
        await new Promise(r => setTimeout(r, 250));
        const blob = await captureImageBlob();
        if (blob) zip.file(`Question_${toKhmerNumeral(i + 1)}.png`, blob);
      }
      const content = await zip.generateAsync({ type: "blob" });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(content);
      link.download = `Images_${viewingExport.name}_${selectedTemplate}.zip`;
      link.click();
    } catch (e) { alert("កំហុស ZIP"); } finally { setPreviewQ(null); setIsProcessing(false); }
  };

  const handleSendTelegramAction = async (q: Question, idx: number, mode: TelegramSendMode) => {
    try {
      if (mode === 'image') {
        setPreviewQ(q);
        setCurrentProcessIndex(idx + 1);
        await new Promise(r => setTimeout(r, 250));
        const blob = await captureImageBlob();
        if (blob) {
          const caption = `📌 *សំណួរទី ${toKhmerNumeral(idx + 1)}*\n\n📋 វិញ្ញាសា៖ ${q.subject}\n✨ ផ្តល់ជូនដោយ Web QCM 🇰🇭`;
          const res = await sendQuestionImage(tgConfig, blob, caption);
          return res.ok;
        }
      } else if (mode === 'poll' && q.type === 'mcq') {
        const res = await sendQuizPoll(tgConfig, q);
        return res.ok;
      } else {
        let text = `📌 *សំណួរ៖* ${q.question}\n\n`;
        if (q.type === 'mcq' && q.options) {
          q.options.forEach((o, i) => { text += `${KHMER_PREFIXES[i]}. ${o}${includeAnswer && i === q.correct ? ' ✅' : ''}\n`; });
        } else {
          text += `✅ *ចម្លើយ៖* ${q.answer}\n`;
        }
        text += `\n📋 វិញ្ញាសា៖ ${q.subject}\n✨ Web QCM 🇰🇭`;
        const response = await fetch(`https://api.telegram.org/bot${tgConfig.botToken}/sendMessage`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ chat_id: tgConfig.chatId, text, parse_mode: 'Markdown' })
        });
        const data = await response.json();
        return data.ok;
      }
    } catch (e) { return false; }
    return false;
  };

  const handleSubmitSingle = () => {
    if (!subject.trim() || !question.trim()) return alert("សូមបំពេញព័ត៌មាន!");
    const cleanQ: Question = {
      subject: subject.trim(),
      question: question.trim(),
      type: qType,
      isActive: true,
      ...(qType === 'mcq' ? { options: options.map(o => o.trim()), correct } : { answer: shortAnswer.trim() })
    };
    if (editingIndex !== null) onUpdate(editingIndex, cleanQ); else onAdd(cleanQ);
    setQuestion(''); setOptions(['', '', '', '']); setShortAnswer(''); setEditingIndex(null);
    alert("រក្សាទុកជោគជ័យ!");
  };

  const handleBulkSubmit = () => {
    if (!subject.trim() || !bulkText.trim()) return alert("សូមបំពេញព័ត៌មាន!");
    const parsed: Question[] = [];
    const lines = bulkText.split('\n');
    let current: any = null;
    if (bulkType === 'mcq') {
      lines.forEach(l => {
        const t = l.trim(); if (!t) return;
        const qm = t.match(/^[០-៩0-9]+\.\s*(.*)/);
        if (qm) {
          if (current && current.options?.length >= 2) parsed.push(current);
          current = { type: 'mcq', subject: subject.trim(), question: qm[1].trim(), options: [], correct: 0, isActive: true };
          return;
        }
        const om = t.match(/^[កខគឃ]\.\s*(.*)/);
        if (om && current) {
          let txt = om[1].replace('(ចម្លើយត្រឹមត្រូវ)', '').trim();
          current.options.push(txt);
          if (om[1].includes('(ចម្លើយត្រឹមត្រូវ)')) current.correct = current.options.length - 1;
        }
      });
      if (current && current.options?.length >= 2) parsed.push(current);
    } else {
      let isAnswer = false;
      lines.forEach(l => {
        const t = l.trim(); if (!t) return;
        const qm = t.match(/^[០-៩0-9]+\.\s*(.*)/);
        if (qm) {
          if (current && current.answer) parsed.push(current);
          current = { type: 'short', subject: subject.trim(), question: qm[1].trim(), answer: '', isActive: true };
          isAnswer = false; return;
        }
        const am = t.match(/^ចម្លើយ\s*[៖:]\s*(.*)/);
        if (am && current) { current.answer = am[1].trim(); isAnswer = true; return; }
        if (isAnswer && current) current.answer += (current.answer ? '\n' : '') + l;
      });
      if (current && current.answer) parsed.push(current);
    }
    if (parsed.length) { onBatchAdd(parsed); setBulkText(''); alert(`បាននាំចូល ${parsed.length} សំណួរ!`); }
