                        </div>
                      </div>
                      <div className="grid grid-cols-2 gap-2 mt-4">
                        <button onClick={() => setViewingQuestions({ name: s.name, type: 'short' })} className="col-span-2 py-3 bg-indigo-950 text-white rounded-xl font-black text-[11px] shadow-md">👁️ មើលសំណួរ & Telegram</button>
