            <div className="absolute top-0 left-0 w-full h-2 bg-blue-600"></div>
            <h3 className="heading-kh text-xl mb-6 text-indigo-950 text-center font-black">ជ្រើសរើសទម្រង់ផ្ញើ</h3>

            <div className="grid grid-cols-1 gap-3 mb-8">
              {[
                { id: 'poll', label: '📊 ផ្ញើជា Poll (MCQ)', desc: 'ផ្ញើជាលក្ខណៈស្ទង់មតិ' },
                { id: 'image', label: '🖼️ ផ្ញើជារូបភាព', desc: 'ប្រើ Template ជាមួយឡូហ្គោ' },
