                  <input type="checkbox" className="hidden" checked={includeAnswer} onChange={(e) => setIncludeAnswer(e.target.checked)} />
                  <span className="text-[11px] font-black text-indigo-950">ភ្ជាប់ជាមួយចម្លើយត្រឹមត្រូវ</span>
               </label>
               {individualSendMode === 'image' && (
                  <div className="p-4 bg-indigo-50/50 rounded-2xl border border-indigo-100">
                    <p className="text-[10px] font-black text-indigo-400 uppercase mb-3 text-center">ជ្រើសរើស Template</p>
                    <div className="grid grid-cols-3 gap-1">
                      {['classic', 'royal', 'vivid'].map(t => (
                        <button key={t} onClick={() => setSelectedTemplate(t as any)} className={`py-2 rounded-lg text-[9px] font-black transition-all ${selectedTemplate === t ? 'bg-indigo-950 text-white' : 'bg-white text-gray-400'}`}>{t.toUpperCase()}</button>
                      ))}
                    </div>
                  </div>
               )}
            </div>

            <div className="flex flex-col gap-2">
               <button 
                onClick={async () => {
                   setIsProcessing(true);
                   const success = await handleSendTelegramAction(confirmIndividualSend.q, confirmIndividualSend.idx, individualSendMode);
                   setIsProcessing(false);
                   if (success) { setConfirmIndividualSend(null); alert("ផ្ញើរួចរាល់!"); }
                   else alert("កំហុសក្នុងការផ្ញើ!");
                }}
                disabled={isProcessing}
                className="w-full py-4 bg-indigo-950 text-white rounded-2xl heading-kh font-black shadow-lg hover:brightness-110 active:scale-95 transition-all"
              >
                {isProcessing ? 'កំពុងផ្ញើ...' : 'យល់ព្រមផ្ញើ'}
              </button>
              <button onClick={() => setConfirmIndividualSend(null)} disabled={isProcessing} className="w-full py-4 bg-gray-100 text-gray-600 rounded-2xl heading-kh font-black">បោះបង់</button>
            </div>
          </div>
        </div>
      )}

      {viewingExport && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-[110] flex items-center justify-center p-4 animate-fadeIn">
          <div className="bg-white p-10 rounded-[3rem] max-w-sm w-full shadow-2xl relative border border-white/20">
            <h3 className="heading-kh text-2xl mb-8 text-indigo-950 text-center font-black">ការនាំចេញ៖ {viewingExport.mode.toUpperCase()}</h3>

            <div className="space-y-6">
               <label className="flex items-center gap-3 p-4 bg-gray-50 rounded-2xl border border-gray-100 cursor-pointer group">
                  <div className={`w-12 h-6 rounded-full relative transition-all ${includeAnswer ? 'bg-green-600' : 'bg-gray-300'}`}>
                    <div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-all ${includeAnswer ? 'left-7' : 'left-1'}`}></div>
                  </div>
                  <input type="checkbox" className="hidden" checked={includeAnswer} onChange={(e) => setIncludeAnswer(e.target.checked)} />
                  <span className="text-[11px] font-black text-indigo-950">ភ្ជាប់ជាមួយចម្លើយត្រឹមត្រូវ</span>
               </label>

              {viewingExport.mode === 'image' && (
                <div className="space-y-3">
                  <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest text-center">រចនាបថរូបភាព</p>
                  <div className="grid grid-cols-3 gap-2">
                    {['classic', 'royal', 'vivid'].map(temp => (
                      <button key={temp} onClick={() => setSelectedTemplate(temp as ExportTemplate)} className={`py-3 rounded-xl border-2 transition-all text-[9px] font-black uppercase ${selectedTemplate === temp ? 'border-indigo-950 bg-indigo-50 text-indigo-950' : 'border-gray-100 text-gray-400'}`}>{temp}</button>
                    ))}
                  </div>
                </div>
              )}

              {isProcessing && (
                <div className="space-y-2">
                   <div className="w-full h-2 bg-gray-100 rounded-full overflow-hidden shadow-inner">
                      <div className="h-full bg-indigo-900 transition-all duration-300" style={{ width: `${(currentProcessIndex / activeQuestionsInView.length) * 100}%` }}></div>
                   </div>
                   <p className="text-center text-[10px] font-black text-gray-400">កំពុងរៀបចំ៖ {toKhmerNumeral(currentProcessIndex)} / {toKhmerNumeral(activeQuestionsInView.length)}</p>
                </div>
              )}

              <div className="flex flex-col gap-2 pt-4">
                <button 
                  onClick={viewingExport.mode === 'pdf' ? handleExportPdf : handleExportImageZip}
                  disabled={isProcessing}
                  className="w-full py-4 bg-indigo-950 text-white rounded-2xl heading-kh font-black shadow-lg"
                >
                  {isProcessing ? 'កំពុងនាំចេញ...' : 'ទាញយកទាំងអស់'}
                </button>
                <button onClick={() => !isProcessing && setViewingExport(null)} disabled={isProcessing} className="w-full py-4 bg-gray-100 text-gray-600 rounded-2xl heading-kh font-black">បោះបង់</button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

