                  <div className="flex gap-2 shrink-0">
                    <button onClick={() => setConfirmIndividualSend({q, idx})} className="px-6 py-3 bg-blue-600 text-white rounded-2xl text-[10px] font-black shadow-lg">✈️ Telegram</button>
                    <button onClick={() => {
                        const originalIdx = quizData.findIndex(item => item === q);
                        if(originalIdx !== -1) {
                          setSubject(q.subject); setQuestion(q.question); setQType(q.type);
                          if(q.type === 'mcq') { setOptions(q.options || ['', '', '', '']); setCorrect(q.correct || 0); }
                          else setShortAnswer(q.answer || '');
                          setEditingIndex(originalIdx); setEntryMode('single'); setViewingQuestions(null);
                        }
                    }} className="p-3 bg-indigo-50 text-indigo-600 rounded-2xl border border-indigo-100 hover:bg-indigo-600 hover:text-white transition-all">✏️</button>
                  </div>
                </div>
              ))}
