      )}

      {/* INDIVIDUAL SEND MODAL WITH TELEGRAM SELECTION */}
      {confirmIndividualSend && (
        <div className="fixed inset-0 bg-black/80 backdrop-blur-md z-[150] flex items-center justify-center p-4 animate-fadeIn">
          <div className="bg-white p-10 rounded-[3rem] max-w-sm w-full shadow-2xl relative border border-white/20 overflow-hidden">
