            {/* 1. SELECT TELEGRAM CHANNEL */}
            <div className="mb-8">
              <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-3 ml-1">១. ជ្រើសរើស Telegram Channel</p>
              <div className="grid grid-cols-1 gap-2 max-h-[160px] overflow-y-auto p-1 custom-scrollbar">
                {TG_CHANNELS.map(c => (
                  <button 
                    key={c.value} 
                    onClick={() => setTgConfig({...tgConfig, chatId: c.value})}
                    className={`p-3 rounded-xl border-2 text-left transition-all flex items-center justify-between ${tgConfig.chatId === c.value ? 'border-blue-600 bg-blue-50' : 'border-gray-50 bg-gray-50/50'}`}
                  >
                    <span className={`text-[10px] font-black ${tgConfig.chatId === c.value ? 'text-blue-700' : 'text-gray-500'}`}>{c.label}</span>
                    {tgConfig.chatId === c.value && <span className="text-blue-600">✓</span>}
