import * as React from 'react';
import { useState, useMemo } from 'react';
import { Question } from '../types';
import { ADMIN_CONTACTS } from '../constants';
import { sendFeedback } from '../services/firebaseService';

interface PlaySectionProps {
  username: string;
  quizData: Question[];
  onStartQuiz: (subject: string, partIndex: number, type: 'mcq' | 'short', customQuestions?: Question[], isMixed?: boolean) => void;
}

const PlaySection: React.FC<PlaySectionProps> = ({ username, quizData, onStartQuiz }) => {
  const [selectedSubject, setSelectedSubject] = useState<string | null>(null);
  const [activeType, setActiveType] = useState<'mcq' | 'short'>('mcq');
  const [searchQuery, setSearchQuery] = useState('');
  const [playMode, setPlayMode] = useState<'by-subject' | 'mixed'>('by-subject');

  const [showFeedbackModal, setShowFeedbackModal] = useState(false);
  const [feedbackText, setFeedbackText] = useState('');
  const [isSendingFeedback, setIsSendingFeedback] = useState(false);

  const KHMER_DIGITS = ['០', '១', '២', '៣', '៤', '៥', '៦', '៧', '៨', '៩'];
  const toKhmerNumeral = (n: number) => n.toString().split('').map(digit => KHMER_DIGITS[parseInt(digit)] || digit).join('');

  const activeQuestions = quizData.filter((q: Question) => q.isActive !== false);

  // មុខងារស្វែងរក និងចម្រាញ់មុខវិជ្ជា
  const filteredSubjects: string[] = useMemo(() => {
    // បញ្ជាក់ប្រភេទទិន្នន័យអោយច្បាស់ដើម្បីជៀសវាង Error TypeScript 'unknown'
    const allSubjects = Array.from(new Set(activeQuestions.filter(q => q.type === activeType).map((item: Question) => item.subject))) as string[];
    if (!searchQuery.trim()) return allSubjects;
    return allSubjects.filter((sub: string) => 
      sub.toLowerCase().includes(searchQuery.toLowerCase())
    );
  }, [activeQuestions, activeType, searchQuery]);

  const handleSendFeedback = async () => {
    if (!feedbackText.trim()) return;
    setIsSendingFeedback(true);
    await sendFeedback(username || 'Anonymous', feedbackText);
    setIsSendingFeedback(false);
    setFeedbackText('');
    setShowFeedbackModal(false);
    alert("អរគុណ! មតិរបស់អ្នកត្រូវបានផ្ញើ។");
  };

  if (selectedSubject) {
    const subjectQuestions = activeQuestions.filter((q: Question) => q.subject === selectedSubject && q.type === activeType);
    const totalQuestions = subjectQuestions.length;
    const totalParts = Math.ceil(totalQuestions / 10);

    return (
      <div className="page-transition space-y-6 px-2">
        <div className="card-white-elegant p-6 flex flex-col sm:flex-row items-center gap-6 border-b-4 border-maroon">
          <button onClick={() => setSelectedSubject(null)} className="w-12 h-12 bg-gray-100 text-maroon rounded-xl transition-all flex items-center justify-center shrink-0 font-black text-xl shadow-sm border border-gray-200">
            ←
          </button>
          <div className="text-center sm:text-left flex-1">
            <h2 className="text-2xl font-black heading-kh text-maroon mb-1">{selectedSubject}</h2>
            <div className="flex flex-wrap justify-center sm:justify-start gap-2">
              <span className="px-4 py-1 bg-indigo-900 text-white rounded-lg text-[9px] font-black uppercase tracking-widest">{activeType === 'mcq' ? 'QCM' : 'Q & A'}</span>
              <span className="px-4 py-1 bg-white text-maroon rounded-lg text-[9px] font-black border border-maroon/20">សរុប៖ {toKhmerNumeral(totalQuestions)} សំណួរ</span>
            </div>
          </div>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
          {Array.from({ length: totalParts }).map((_, i) => (
            <button key={i} onClick={() => onStartQuiz(selectedSubject, i, activeType)} className="card-white-elegant p-6 text-left transition-all active:scale-[0.98] group hover:border-indigo-900">
              <div className="flex justify-between items-center">
                <div className="flex-1">
                  <div className="flex items-center gap-3 mb-2">
                    <span className="w-10 h-10 bg-indigo-900 text-white rounded-lg flex items-center justify-center font-black text-lg shadow-md">{toKhmerNumeral(i + 1)}</span>
                    <span className="text-[10px] font-black text-indigo-900 uppercase small-kh">ភាគទី</span>
                  </div>
                  <h4 className="text-lg font-black heading-kh text-indigo-950">សំណួរ {toKhmerNumeral(i * 10 + 1)} - {toKhmerNumeral(Math.min((i + 1) * 10, totalQuestions))}</h4>
                </div>
                <div className="w-14 h-14 rounded-xl bg-indigo-50 flex items-center justify-center text-3xl group-hover:bg-indigo-900 group-hover:text-white transition-all">🚀</div>
              </div>
            </button>
          ))}
        </div>
      </div>
    );
  }

  return (
    <div className="page-transition space-y-10 pb-24 px-2">
      <div className="flex flex-col items-center gap-6">
        <div className="bg-white/10 backdrop-blur-md p-1.5 rounded-2xl border border-white/20 shadow-xl flex gap-1 w-full max-w-sm">
          <button onClick={() => setPlayMode('by-subject')} className={`flex-1 py-3 rounded-xl font-black heading-kh text-xs transition-all ${playMode === 'by-subject' ? 'bg-indigo-900 text-white shadow-md' : 'text-white/60'}`}>📚 តាមវិញ្ញាសា</button>
          <button onClick={() => setPlayMode('mixed')} className={`flex-1 py-3 rounded-xl font-black heading-kh text-xs transition-all ${playMode === 'mixed' ? 'bg-indigo-900 text-white shadow-md' : 'text-white/60'}`}>⚡ ចម្រុះ</button>
        </div>

        <div className="w-full max-w-2xl relative">
          <input 
            type="text" 
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            placeholder="ស្វែងរកវិញ្ញាសា..." 
            className="w-full pl-14 pr-6 py-4 bg-white border-2 border-indigo-900 rounded-2xl outline-none shadow-xl heading-kh text-indigo-950 text-lg font-black transition-all focus:ring-4 focus:ring-indigo-900/10"
          />
          <div className="absolute left-6 top-4 text-indigo-900/40">
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
          </div>
        </div>
      </div>

      <div className="space-y-8">
        <div className="flex justify-center gap-3">
          <button onClick={() => setActiveType('mcq')} className={`px-10 py-3.5 rounded-xl font-black heading-kh text-sm transition-all border-b-4 ${activeType === 'mcq' ? 'bg-maroon text-white border-maroon-dark shadow-lg' : 'bg-white text-gray-400 border-gray-200'}`}>📑 QCM</button>
          <button onClick={() => setActiveType('short')} className={`px-10 py-3.5 rounded-xl font-black heading-kh text-sm transition-all border-b-4 ${activeType === 'short' ? 'bg-maroon text-white border-maroon-dark shadow-lg' : 'bg-white text-gray-400 border-gray-200'}`}>🖊️ Q & A</button>
        </div>

        {filteredSubjects.length > 0 ? (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            {filteredSubjects.map((sub, i) => {
              const count = activeQuestions.filter(q => q.subject === sub && q.type === activeType).length;
              return (
                <div key={i} className="card-white-elegant p-6 flex flex-col group relative transition-all hover:border-maroon">
                  <div onClick={() => setSelectedSubject(sub)} className="cursor-pointer">
                    <div className="flex items-center gap-4 mb-4">
                      <div className="w-14 h-14 bg-gray-50 rounded-xl flex items-center justify-center text-3xl border border-gray-100">
                         {activeType === 'mcq' ? '📑' : '🖊️'}
                      </div>
                      <div className="flex-1 min-w-0">
                        <h3 className="text-xl font-black heading-kh text-indigo-950 truncate leading-tight">{sub}</h3>
                        <p className={`text-[9px] font-black uppercase tracking-widest ${activeType === 'mcq' ? 'text-indigo-600' : 'text-orange-600'}`}>
                          {toKhmerNumeral(count)} សំណួរ
                        </p>
                      </div>
                    </div>
                  </div>
                  <div className="mt-auto flex gap-3 pt-4 border-t border-gray-50">
                    <button onClick={() => setSelectedSubject(sub)} className="btn-red-elegant flex-[3] py-4 text-sm uppercase">ចូលរៀន 🚀</button>
                    <button onClick={() => setSelectedSubject(sub)} className="flex-1 py-4 bg-gray-100 text-indigo-950 rounded-xl font-black text-2xl border border-gray-200">👁️</button>
                  </div>
                </div>
              );
            })}
          </div>
        ) : (
          <div className="py-24 text-center card-white-elegant bg-white/50 border-dashed border-4 border-indigo-900">
            <div className="text-8xl mb-6 opacity-10">📭</div>
            <h3 className="text-2xl font-black heading-kh text-indigo-950/20 tracking-widest">រកមិនឃើញមុខវិជ្ជា {searchQuery ? `"${searchQuery}"` : ''}</h3>
          </div>
        )}
      </div>

      <div className="fixed bottom-6 right-6 z-[50]">
        <button 
          onClick={() => setShowFeedbackModal(true)}
          className="w-14 h-14 bg-yellow-500 text-indigo-950 rounded-full shadow-2xl flex items-center justify-center text-2xl border-4 border-white animate-bounce"
        >
          💬
        </button>
      </div>
    </div>
  );
};

export default PlaySection;

import * as React from 'react';
import { useState, useMemo, useRef } from 'react';
import { Question, TelegramConfig, Feedback } from '../types';
import { DEFAULT_TG_BOT_TOKEN, TG_CHANNELS } from '../constants';
import html2canvas from 'html2canvas';
import { sendQuizPoll, sendQuestionImage } from '../services/telegramService';

declare var html2pdf: any;
declare var JSZip: any;

interface CreateSectionProps {
  quizData: Question[];
  feedbackList?: Feedback[];
  onDeleteFeedback?: (id: string) => void;
  onAdd: (q: Question) => void;
  onUpdate: (index: number, q: Question) => void;
  onRemove: (index: number) => void;
  onToggleSubject: (subject: string, type: 'mcq' | 'short', active: boolean) => void;
  onUpdateSubject: (subject: string, type: 'mcq' | 'short', newName: string) => void;
  onRemoveSubject: (subject: string, type: 'mcq' | 'short') => void;
  onReorderSubject: (subject: string, type: 'mcq' | 'short', direction: 'up' | 'down') => void;
  onBatchAdd: (qs: Question[]) => void;
  onLogout: () => void;
}

type ExportTemplate = 'classic' | 'royal' | 'vivid';
type TelegramSendMode = 'poll' | 'image' | 'text';

const CreateSection: React.FC<CreateSectionProps> = ({ 
  quizData, feedbackList = [], onDeleteFeedback, onAdd, onUpdate, onRemove, onToggleSubject, onUpdateSubject, onRemoveSubject, onReorderSubject, onBatchAdd
}) => {
  const APP_LOGO_URL = "https://i.postimg.cc/0ygmLdvR/3QCM_Ep4.png";
  const KHMER_PREFIXES = ['ក', 'ខ', 'គ', 'ឃ'];
  const KHMER_DIGITS = ['០', '១', '២', '៣', '៤', '៥', '៦', '៧', '៨', '៩'];
  const CAMBODIA_TITLE = "ព្រះរាជាណាចក្រកម្ពុជា";
  const CAMBODIA_MOTTO = "ជាតិ សាសនា ព្រះមហាក្សត្រ";

  const [entryMode, setEntryMode] = useState<'single' | 'bulk' | 'subjects' | 'feedback'>('single');
  const [qType, setQType] = useState<'mcq' | 'short'>('mcq');
  const [bulkType, setBulkType] = useState<'mcq' | 'short'>('mcq');
  const [subject, setSubject] = useState('');
  const [question, setQuestion] = useState('');
  const [options, setOptions] = useState(['', '', '', '']);
  const [correct, setCorrect] = useState(0);
  const [shortAnswer, setShortAnswer] = useState('');
  const [editingIndex, setEditingIndex] = useState<number | null>(null);
  const [bulkText, setBulkText] = useState('');

  const [viewingExport, setViewingExport] = useState<{name: string, type: 'mcq' | 'short', mode: 'pdf' | 'image'} | null>(null);
  const [viewingQuestions, setViewingQuestions] = useState<{name: string, type: 'mcq' | 'short'} | null>(null);
  const [selectedTemplate, setSelectedTemplate] = useState<ExportTemplate>('classic');
  const [includeAnswer, setIncludeAnswer] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [currentProcessIndex, setCurrentProcessIndex] = useState(0);
  const [subjectSearch, setSubjectSearch] = useState('');
  const [questionSearch, setQuestionSearch] = useState('');

  // State for Subject Editing Modal
  const [editingSubject, setEditingSubject] = useState<{oldName: string, type: 'mcq' | 'short', newName: string} | null>(null);

  // States for dynamic footer
  const [footerLeft, setFooterLeft] = useState('WEB QCM 🇰🇭');
  const [footerRightTop, setFooterRightTop] = useState('t.me/web_qcm_q_and_a');
  const [footerRightBottom, setFooterRightBottom] = useState('ប្រព័ន្ធរៀបចំវិញ្ញាសាដោយស្វ័យប្រវត្តិ');

  const [tgConfig, setTgConfig] = useState<TelegramConfig>({ botToken: DEFAULT_TG_BOT_TOKEN, chatId: TG_CHANNELS[0].value });
  const [individualSendMode, setIndividualSendMode] = useState<TelegramSendMode>('poll');
  const [confirmIndividualSend, setConfirmIndividualSend] = useState<{q: Question, idx: number} | null>(null);

  const imageTemplateRef = useRef<HTMLDivElement>(null);
  const pdfTemplateRef = useRef<HTMLDivElement>(null);
  const [previewQ, setPreviewQ] = useState<Question | null>(null);

  const toKhmerNumeral = (n: number) => n.toString().split('').map(digit => KHMER_DIGITS[parseInt(digit)] || digit).join('');

  const groupedSubjects = useMemo(() => {
    const getList = (type: 'mcq' | 'short') => {
      const seen = new Set<string>();
      const list: any[] = [];
      quizData.filter(q => q.type === type).forEach(q => {
        if (!seen.has(q.subject)) {
          seen.add(q.subject);
          const related = quizData.filter(rq => rq.subject === q.subject && rq.type === type);
          list.push({ name: q.subject, isActive: related.every(rq => rq.isActive !== false), count: related.length, type });
        }
      });
      if (!subjectSearch.trim()) return list;
      return list.filter(item => item.name.toLowerCase().includes(subjectSearch.toLowerCase()));
    };
    return { mcq: getList('mcq'), short: getList('short') };
  }, [quizData, subjectSearch]);

  const activeQuestionsInView = useMemo(() => {
    const target = viewingExport || viewingQuestions;
    if (!target) return [];
    let qs = quizData.filter(q => q.subject === target.name && q.type === target.type);
    if (questionSearch.trim()) {
      qs = qs.filter(q => q.question.toLowerCase().includes(questionSearch.toLowerCase()));
    }
    return qs;
  }, [quizData, viewingExport, viewingQuestions, questionSearch]);

  const captureImageBlob = async (): Promise<Blob | null> => {
    if (!imageTemplateRef.current) return null;
    try {
      const canvas = await html2canvas(imageTemplateRef.current, { 
        scale: 2, 
        useCORS: true, 
        backgroundColor: null, 
        logging: false,
        width: 1080,
      });
      return new Promise(r => canvas.toBlob(r, 'image/png', 1.0));
    } catch (e) { return null; }
  };

  const handleExportPdf = async () => {
    if (!pdfTemplateRef.current || !viewingExport) return;
    setIsProcessing(true);
    try {
      const opt = {
        margin: 10,
        filename: `Vignasa_${viewingExport.name}.pdf`,
        image: { type: 'jpeg', quality: 0.98 },
        html2canvas: { scale: 2, useCORS: true },
        jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' }
      };
      await html2pdf().from(pdfTemplateRef.current).set(opt).save();
    } catch (e) { alert("កំហុស PDF"); } finally { setIsProcessing(false); }
  };

  const handleExportImageZip = async () => {
    if (!viewingExport) return;
    setIsProcessing(true);
    setCurrentProcessIndex(0);
    const zip = new JSZip();
    try {
      const questions = activeQuestionsInView;
      for (let i = 0; i < questions.length; i++) {
        const q = questions[i];
        setPreviewQ(q);
        setCurrentProcessIndex(i + 1);
        await new Promise(r => setTimeout(r, 300));
        const blob = await captureImageBlob();
        if (blob) zip.file(`Question_${toKhmerNumeral(i + 1)}.png`, blob);
      }
      const content = await zip.generateAsync({ type: "blob" });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(content);
      link.download = `Images_${viewingExport.name}_${selectedTemplate}.zip`;
      link.click();
    } catch (e) { alert("កំហុស ZIP"); } finally { setPreviewQ(null); setIsProcessing(false); }
  };

  const handleSendTelegramAction = async (q: Question, idx: number, mode: TelegramSendMode) => {
    try {
      if (mode === 'image') {
        setPreviewQ(q);
        setCurrentProcessIndex(idx + 1);
        await new Promise(r => setTimeout(r, 300));
        const blob = await captureImageBlob();
        if (blob) {
          const caption = `📌 *សំណួរទី ${toKhmerNumeral(idx + 1)}*\n\n📋 វិញ្ញាសា៖ ${q.subject}\n✨ ផ្តល់ជូនដោយ Web QCM 🇰🇭`;
          const res = await sendQuestionImage(tgConfig, blob, caption);
          return res.ok;
        }
      } else if (mode === 'poll' && q.type === 'mcq') {
        const res = await sendQuizPoll(tgConfig, q);
        return res.ok;
      } else {
        let text = `📌 *សំណួរ៖* ${q.question}\n\n`;
        if (q.type === 'mcq' && q.options) {
          q.options.forEach((o, i) => { text += `${KHMER_PREFIXES[i]}. ${o}${includeAnswer && i === q.correct ? ' ✅' : ''}\n`; });
        } else {
          text += `✅ *ចម្លើយ៖* ${q.answer}\n`;
        }
        text += `\n📋 វិញ្ញាសា៖ ${q.subject}\n✨ Web QCM 🇰🇭`;
        const response = await fetch(`https://api.telegram.org/bot${tgConfig.botToken}/sendMessage`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ chat_id: tgConfig.chatId, text, parse_mode: 'Markdown' })
        });
        const data = await response.json();
        return data.ok;
      }
    } catch (e) { return false; }
    return false;
  };

  const handleEditSubject = (oldName: string, type: 'mcq' | 'short') => {
    setEditingSubject({ oldName, type, newName: oldName });
  };

  const saveSubjectNameUpdate = () => {
    if (editingSubject && editingSubject.newName.trim() && editingSubject.newName.trim() !== editingSubject.oldName) {
      onUpdateSubject(editingSubject.oldName, editingSubject.type, editingSubject.newName.trim());
    }
    setEditingSubject(null);
  };

  const handleSubmitSingle = () => {
    if (!subject.trim() || !question.trim()) return alert("សូមបំពេញព័ត៌មាន!");
    const cleanQ: Question = {
      subject: subject.trim(),
      question: question.trim(),
      type: qType,
      isActive: true,
      ...(qType === 'mcq' ? { options: options.map(o => o.trim()), correct } : { answer: shortAnswer.trim() })
    };
    if (editingIndex !== null) onUpdate(editingIndex, cleanQ); else onAdd(cleanQ);
    setQuestion(''); setOptions(['', '', '', '']); setShortAnswer(''); setEditingIndex(null);
    alert("រក្សាទុកជោគជ័យ!");
  };

  const handleBulkSubmit = () => {
    if (!subject.trim() || !bulkText.trim()) return alert("សូមបំពេញព័ត៌មាន!");
    const parsed: Question[] = [];
    const lines = bulkText.split('\n');
    let current: any = null;
    if (bulkType === 'mcq') {
      lines.forEach(l => {
        const t = l.trim(); if (!t) return;
        const qm = t.match(/^[០-៩0-9]+\.\s*(.*)/);
        if (qm) {
          if (current && current.options?.length >= 2) parsed.push(current);
          current = { type: 'mcq', subject: subject.trim(), question: qm[1].trim(), options: [], correct: 0, isActive: true };
          return;
        }
        const om = t.match(/^[កខគឃ]\.\s*(.*)/);
        if (om && current) {
          let txt = om[1].replace('(ចម្លើយត្រឹមត្រូវ)', '').trim();
          current.options.push(txt);
          if (om[1].includes('(ចម្លើយត្រឹមត្រូវ)')) current.correct = current.options.length - 1;
        }
      });
      if (current && current.options?.length >= 2) parsed.push(current);
    } else {
      let isAnswer = false;
      lines.forEach(l => {
        const t = l.trim(); if (!t) return;
        const qm = t.match(/^[០-៩0-9]+\.\s*(.*)/);
        if (qm) {
          if (current && current.answer) parsed.push(current);
          current = { type: 'short', subject: subject.trim(), question: qm[1].trim(), answer: '', isActive: true };
          isAnswer = false; return;
        }
        const am = t.match(/^ចម្លើយ\s*[៖:]\s*(.*)/);
        if (am && current) { current.answer = am[1].trim(); isAnswer = true; return; }
        if (isAnswer && current) current.answer += (current.answer ? '\n' : '') + l;
      });
      if (current && current.answer) parsed.push(current);
    }
    if (parsed.length) { onBatchAdd(parsed); setBulkText(''); alert(`បាននាំចូល ${parsed.length} សំណួរ!`); }
  };

  return (
    <div className="space-y-8 animate-fadeIn pb-32">
      {/* EXPORT ENGINE (HIDDEN) */}
      <div className="fixed -left-[9999px] top-0 pointer-events-none">
        {/* PDF TEMPLATE */}
        <div ref={pdfTemplateRef} style={{ width: '210mm', padding: '20mm', background: '#fff', color: '#000', fontFamily: 'Kantumruy Pro, sans-serif' }}>
