                      <div className="h-[2px] w-12 bg-gray-100 rounded-full"></div>
                      {/* បង្ហាញចម្លើយត្រឹមត្រូវនៅក្នុងការមើល PDF */}
                      <div className="p-6 bg-emerald-50 rounded-2xl border border-emerald-100">
                        <p className="text-[10px] font-black text-emerald-600 uppercase tracking-widest mb-2 opacity-70">ចម្លើយត្រឹមត្រូវ៖</p>
                        <p className="text-emerald-950 font-bold text-lg heading-kh">
                          {q.answer}
