                      </div>
                    </div>
                  </div>
                ))}
              </div>

              {/* Footer PDF */}
              <div className="mt-20 pt-10 border-t border-gray-100 flex flex-col md:flex-row justify-between items-center gap-4">
                <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest italic">ប្រព័ន្ធរៀបចំវិញ្ញាសាដោយស្វ័យប្រវត្តិតាម Web App</p>
