              <span className="px-4 py-1 bg-white text-maroon rounded-lg text-[9px] font-black border border-maroon/20">សរុប៖ {toKhmerNumeral(totalQuestions)} សំណួរ</span>
            </div>
          </div>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
          {Array.from({ length: totalParts }).map((_, i) => (
            <button key={i} onClick={() => onStartQuiz(selectedSubject, i, activeType)} className="card-white-elegant p-6 text-left transition-all active:scale-[0.98] group hover:border-indigo-900">
