          </div>
          {searchQuery.trim() && (
            <button 
              onClick={() => setSearchQuery('')}
              className="absolute right-4 top-4 w-8 h-8 bg-gray-100 rounded-full flex items-center justify-center text-gray-400 hover:text-red-500 transition-colors"
            >
              ✕
            </button>
          )}
        </div>
      </div>

      <div className="space-y-8">
        <div className="flex justify-center gap-3">
          <button onClick={() => setActiveType('mcq')} className={`px-10 py-3.5 rounded-xl font-black heading-kh text-sm transition-all border-b-4 ${activeType === 'mcq' ? 'bg-maroon text-white border-maroon-dark shadow-lg' : 'bg-white text-gray-400 border-gray-200'}`}>📑 QCM</button>
          <button onClick={() => setActiveType('short')} className={`px-10 py-3.5 rounded-xl font-black heading-kh text-sm transition-all border-b-4 ${activeType === 'short' ? 'bg-maroon text-white border-maroon-dark shadow-lg' : 'bg-white text-gray-400 border-gray-200'}`}>🖊️ Q & A</button>
        </div>

        {searchQuery.trim() ? (
          <div className="space-y-4">
            <div className="flex justify-between items-center px-4">
               <h3 className="heading-kh text-white/70 text-sm">លទ្ធផលស្វែងរក៖ {toKhmerNumeral(searchedQuestions.length)} សំណួរ</h3>
            </div>
            <div className="grid grid-cols-1 gap-4">
               {searchedQuestions.map((q, idx) => (
                 <button 
                  key={idx} 
                  onClick={() => onStartQuiz(q.subject, 0, q.type, [q])}
                  className="card-white-elegant p-6 text-left hover:border-maroon transition-all group"
                 >
                    <div className="flex gap-4 items-start">
                       <div className="w-10 h-10 bg-red-50 text-maroon rounded-xl flex items-center justify-center shrink-0 font-black border border-red-100 group-hover:bg-maroon group-hover:text-white transition-colors">
                          {toKhmerNumeral(idx + 1)}
                       </div>
                       <div className="flex-1">
                          <span className="text-[8px] font-black uppercase bg-indigo-50 text-indigo-600 px-2 py-0.5 rounded mb-2 inline-block tracking-widest">{q.subject}</span>
                          <p className="heading-kh text-indigo-950 text-sm leading-relaxed line-clamp-2">{q.question}</p>
                       </div>
                       <div className="text-2xl opacity-0 group-hover:opacity-100 transition-opacity">🚀</div>
                    </div>
                 </button>
               ))}
               {searchedQuestions.length === 0 && (
                 <div className="py-24 text-center card-white-elegant bg-white/5 opacity-50 border-dashed border-2 border-white/20">
                   <div className="text-6xl mb-4">🔍</div>
                   <h3 className="heading-kh text-white/50">មិនមានសំណួរត្រូវនឹង "{searchQuery}"</h3>
                 </div>
               )}
            </div>
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            {filteredSubjects.map((sub, i) => {
              const count = activeQuestions.filter(q => q.subject === sub && q.type === activeType).length;
              return (
                <div key={i} className="card-white-elegant p-6 flex flex-col group relative transition-all hover:border-maroon">
                  <div onClick={() => setSelectedSubject(sub)} className="cursor-pointer">
                    <div className="flex items-center gap-4 mb-4">
                      <div className="w-14 h-14 bg-gray-50 rounded-xl flex items-center justify-center text-3xl border border-gray-100 group-hover:bg-red-50 transition-colors">
                         {activeType === 'mcq' ? '📑' : '🖊️'}
                      </div>
                      <div className="flex-1 min-w-0">
                        <h3 className="text-xl font-black heading-kh text-indigo-950 truncate leading-tight">{sub}</h3>
                        <p className={`text-[9px] font-black uppercase tracking-widest ${activeType === 'mcq' ? 'text-indigo-600' : 'text-orange-600'}`}>
                          {toKhmerNumeral(count)} សំណួរ
                        </p>
                      </div>
                    </div>
                  </div>
                  <div className="mt-auto flex gap-3 pt-4 border-t border-gray-50">
                    <button onClick={() => setSelectedSubject(sub)} className="btn-red-elegant flex-[3] py-4 text-sm uppercase">ចូលមើលវិញ្ញាសា 🚀</button>
                    <button onClick={() => setSelectedSubject(sub)} className="flex-1 py-4 bg-gray-100 text-indigo-950 rounded-xl font-black text-2xl border border-gray-200 hover:bg-indigo-900 hover:text-white transition-all">👁️</button>
                  </div>
                </div>
              );
            })}
            {filteredSubjects.length === 0 && (
              <div className="col-span-full py-24 text-center card-white-elegant bg-white/5 opacity-50 border-dashed border-2 border-white/20">
                <div className="text-6xl mb-4">📭</div>
                <h3 className="heading-kh text-white/50">មិនទាន់មានវិញ្ញាសានៅឡើយ</h3>
              </div>
            )}
          </div>
        )}
      </div>

      <div className="fixed bottom-6 right-6 z-[50]">
        <button 
          onClick={() => setShowFeedbackModal(true)}
          className="w-14 h-14 bg-yellow-500 text-indigo-950 rounded-full shadow-2xl flex items-center justify-center text-2xl border-4 border-white animate-bounce hover:scale-110 transition-transform"
        >
          💬
        </button>
      </div>

      {showFeedbackModal && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-[100] flex items-center justify-center p-6">
           <div className="bg-white rounded-[2rem] p-8 max-w-sm w-full shadow-2xl animate-fadeIn">
              <h3 className="heading-kh text-xl text-indigo-950 mb-4 font-black">បញ្ជូនមតិយោបល់</h3>
              <textarea 
                value={feedbackText}
                onChange={(e) => setFeedbackText(e.target.value)}
                className="w-full h-32 p-4 bg-gray-50 border border-gray-100 rounded-2xl outline-none focus:ring-2 focus:ring-yellow-500 small-kh text-blue-600"
                placeholder="សរសេរមតិរបស់អ្នកនៅទីនេះ..."
              />
              <div className="flex gap-2 mt-6">
                 <button 
                  onClick={handleSendFeedback}
                  disabled={isSendingFeedback || !feedbackText.trim()}
                  className="flex-1 btn-blue-elegant py-3 rounded-xl heading-kh disabled:opacity-50"
                 >
                    {isSendingFeedback ? 'កំពុងផ្ញើ...' : 'ផ្ញើមតិ'}
                 </button>
                 <button 
                  onClick={() => setShowFeedbackModal(false)}
                  className="flex-1 py-3 bg-gray-100 text-gray-500 rounded-xl heading-kh"
                 >
                    បោះបង់
                 </button>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default PlaySection;

import * as React from 'react';
import { useState, useMemo, useRef } from 'react';
import { Question } from '../types';
import { ADMIN_CONTACTS } from '../constants';
import { sendFeedback } from '../services/firebaseService';

declare var html2pdf: any;

interface PlaySectionProps {
  username: string;
  quizData: Question[];
  isAdmin?: boolean;
  onStartQuiz: (subject: string, partIndex: number, type: 'mcq' | 'short', customQuestions?: Question[], isMixed?: boolean) => void;
}

const PlaySection: React.FC<PlaySectionProps> = ({ username, quizData, isAdmin, onStartQuiz }) => {
  const [selectedSubject, setSelectedSubject] = useState<string | null>(null);
  const [activeType, setActiveType] = useState<'mcq' | 'short'>('mcq');
  const [searchQuery, setSearchQuery] = useState('');
  const [playMode, setPlayMode] = useState<'by-subject' | 'mixed'>('by-subject');

  const [showFeedbackModal, setShowFeedbackModal] = useState(false);
  const [feedbackText, setFeedbackText] = useState('');
  const [isSendingFeedback, setIsSendingFeedback] = useState(false);
  const [isGeneratingPdf, setIsGeneratingPdf] = useState(false);

  const pdfRef = useRef<HTMLDivElement>(null);

  const KHMER_DIGITS = ['០', '១', '២', '៣', '៤', '៥', '៦', '៧', '៨', '៩'];
  const toKhmerNumeral = (n: number) => n.toString().split('').map(digit => KHMER_DIGITS[parseInt(digit)] || digit).join('');
  const APP_LOGO_URL = "https://i.postimg.cc/0ygmLdvR/3QCM_Ep4.png";

  const activeQuestions = useMemo(() => quizData.filter((q: Question) => q.isActive !== false), [quizData]);

  const filteredSubjects: string[] = useMemo(() => {
    return Array.from(new Set(activeQuestions.filter(q => q.type === activeType).map((item: Question) => item.subject))) as string[];
  }, [activeQuestions, activeType]);

  const searchedQuestions = useMemo(() => {
    if (!searchQuery.trim()) return [];
    return activeQuestions.filter(q => 
      q.type === activeType && 
      (q.question.toLowerCase().includes(searchQuery.toLowerCase()) || 
       q.subject.toLowerCase().includes(searchQuery.toLowerCase()))
    );
  }, [activeQuestions, searchQuery, activeType]);

  const handleDownloadPdf = () => {
    if (!pdfRef.current || !selectedSubject || !isAdmin) return;
    setIsGeneratingPdf(true);
    const element = pdfRef.current;
    const opt = {
      margin: 10,
      filename: `Vignasa_${selectedSubject}.pdf`,
      image: { type: 'jpeg', quality: 0.98 },
      html2canvas: { scale: 2, useCORS: true },
      jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' }
    };

    html2pdf().from(element).set(opt).save().then(() => {
      setIsGeneratingPdf(false);
    }).catch(() => {
      setIsGeneratingPdf(false);
      alert("មានបញ្ហាក្នុងការទាញយក PDF");
    });
  };

  const handleSendFeedback = async () => {
    if (!feedbackText.trim()) return;
    setIsSendingFeedback(true);
    await sendFeedback(username || 'Anonymous', feedbackText);
    setIsSendingFeedback(false);
    setFeedbackText('');
    setShowFeedbackModal(false);
    alert("អរគុណ! មតិរបស់អ្នកត្រូវបានផ្ញើ។");
  };

  if (selectedSubject) {
    const subjectQuestions = activeQuestions.filter((q: Question) => q.subject === selectedSubject && q.type === activeType);
    const totalQuestions = subjectQuestions.length;
    const totalParts = Math.ceil(totalQuestions / 10);

    if (activeType === 'short') {
      return (
        <div className="page-transition space-y-8 px-2 pb-20">
          <div className="flex flex-col sm:flex-row items-center justify-between gap-4 mb-6">
            <button 
              onClick={() => setSelectedSubject(null)} 
              className="px-6 py-3 bg-white/10 hover:bg-white/20 text-white rounded-2xl flex items-center gap-2 transition-all font-black heading-kh text-sm"
            >
              ← ត្រឡប់ក្រោយ
            </button>
            <div className="flex gap-2">
              {isAdmin && (
                <button 
                  onClick={handleDownloadPdf}
                  disabled={isGeneratingPdf}
                  className="btn-blue-elegant px-8 py-3 text-xs heading-kh shadow-xl"
                >
                  {isGeneratingPdf ? '⏳ កំពុងទាញយក...' : '📥 ទាញយក PDF'}
                </button>
              )}
              <button 
                onClick={() => onStartQuiz(selectedSubject, 0, activeType)}
                className="btn-red-elegant px-8 py-3 text-xs heading-kh shadow-xl"
              >
                🚀 ចាប់ផ្តើមធ្វើតេស្ត
              </button>
            </div>
          </div>

          <div className="max-w-4xl mx-auto">
            <div 
              ref={pdfRef}
              className="bg-white text-indigo-950 p-10 md:p-16 rounded-[2.5rem] shadow-2xl border-t-[12px] border-red-600 overflow-hidden relative"
            >
              <div className="flex flex-col md:flex-row justify-between items-center mb-16 border-b-2 border-gray-100 pb-10 gap-8">
                <div className="flex items-center gap-6">
                  <div className="w-24 h-24 rounded-full border-4 border-red-600/20 p-1 bg-white shadow-lg overflow-hidden shrink-0">
                    <img src={APP_LOGO_URL} alt="Logo" className="w-full h-full object-cover rounded-full" />
                  </div>
                  <div>
                    <h1 className="text-2xl font-black heading-kh text-red-600 mb-1">វិញ្ញាសាត្រៀមប្រឡង</h1>
                    <p className="text-[10px] font-black uppercase text-gray-400 tracking-widest">Master Quiz Platform 🇰🇭</p>
                  </div>
                </div>
                <div className="text-center md:text-right">
                  <h2 className="text-xl font-black heading-kh text-indigo-950 mb-1">{selectedSubject}</h2>
                  <div className="inline-flex items-center gap-2 px-4 py-1.5 bg-indigo-50 text-indigo-600 rounded-full text-[10px] font-black uppercase tracking-widest border border-indigo-100">
                    ប្រភេទ៖ Q & A
                  </div>
                </div>
              </div>

              <div className="space-y-12">
                {subjectQuestions.map((q, idx) => (
                  <div key={idx} className="relative pl-14 animate-fadeIn" style={{ animationDelay: `${idx * 0.05}s` }}>
                    {/* លេខរៀងសំណួរពណ៌ក្រហម */}
