               <h3 className="heading-kh text-white/70 text-sm">លទ្ធផលស្វែងរក៖ {toKhmerNumeral(searchedQuestions.length)} សំណួរ</h3>
            </div>
            <div className="grid grid-cols-1 gap-4">
               {searchedQuestions.map((q, idx) => (
                 <button 
                  key={idx} 
                  onClick={() => onStartQuiz(q.subject, 0, q.type, [q])}
                  className="card-white-elegant p-6 text-left hover:border-red-600 transition-all group"
                 >
                    <div className="flex gap-4 items-start">
                       <div className="w-10 h-10 bg-red-50 text-red-600 rounded-xl flex items-center justify-center shrink-0 font-black border border-red-100 group-hover:bg-red-600 group-hover:text-white transition-colors">
                          {toKhmerNumeral(idx + 1)}
                       </div>
                       <div className="flex-1">
                          <span className="text-[8px] font-black uppercase bg-indigo-50 text-indigo-600 px-2 py-0.5 rounded mb-2 inline-block tracking-widest">{q.subject}</span>
