                  </div>

                  <div className="space-y-5">
                    <h3 className="text-xl font-bold heading-kh leading-relaxed text-justify">
                      {q.question}
                    </h3>

                    {q.type === 'mcq' ? (
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mt-4">
                        {q.options?.map((opt, i) => (
                          <div key={i} className={`flex items-start gap-4 p-4 rounded-xl border transition-all ${i === q.correct ? 'bg-green-600/10 border-green-500 shadow-sm' : 'bg-indigo-900/5 border-indigo-900/10'}`}>
                             <span className={`w-8 h-8 rounded-lg flex items-center justify-center font-black text-sm shrink-0 ${i === q.correct ? 'bg-green-600 text-white' : 'bg-white text-indigo-950/40 border border-indigo-900/10'}`}>
                                {KHMER_PREFIXES[i]}
                             </span>
                             <p 
                               className={`text-base leading-relaxed flex-1 ${i === q.correct ? 'text-green-900 font-bold' : 'text-indigo-950 opacity-80'}`}
                               style={{ fontFamily: "'Siemreap', cursive" }}
                             >
                               {opt} {i === q.correct && <span className="ml-2">✓</span>}
                             </p>
                          </div>
                        ))}
                      </div>
                    ) : (
                      <div className="p-6 bg-green-600/5 rounded-2xl border border-green-500/20 relative overflow-hidden">
                        <p className="text-[10px] font-black text-green-700 uppercase tracking-widest mb-4 opacity-80 heading-kh">
                          ចម្លើយត្រឹមត្រូវ៖
                        </p>
                        <div className="space-y-3">
                          {q.answer?.split('\n').map((line, lineIdx) => (
                            <div key={lineIdx} className="flex items-start">
                               <p 
                                 className="text-indigo-950 font-medium text-lg leading-relaxed whitespace-pre-wrap"
                                 style={{ fontFamily: "'Siemreap', cursive" }}
                               >
                                 {line}
                               </p>
                            </div>
                          ))}
                        </div>
                      </div>
                    )}
                  </div>
                </div>
              ))}
            </div>

            <div className="mt-20 pt-10 border-t border-indigo-900/10 flex flex-col md:flex-row justify-between items-center gap-4">
              <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest italic">ប្រព័ន្ធរៀបចំវិញ្ញាសាដោយស្វ័យប្រវត្តិតាម Web App</p>
              <p className="text-[10px] font-black text-red-600 uppercase tracking-widest font-bold">តេឡេក្រាម៖ t.me/web_qcm_q_and_a</p>
            </div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="page-transition space-y-10 pb-24 px-2">
      <div className="flex flex-col items-center gap-6">
        <div className="bg-white/10 backdrop-blur-md p-1.5 rounded-2xl border border-white/20 shadow-xl flex gap-1 w-full max-sm">
          <button onClick={() => { setPlayMode('by-subject'); }} className={`flex-1 py-3 rounded-xl font-black heading-kh text-xs transition-all ${playMode === 'by-subject' ? 'bg-indigo-900 text-white shadow-md' : 'text-white/60'}`}>📚 តាមវិញ្ញាសា</button>
          <button onClick={() => { setPlayMode('mixed'); }} className={`flex-1 py-3 rounded-xl font-black heading-kh text-xs transition-all ${playMode === 'mixed' ? 'bg-indigo-900 text-white shadow-md' : 'text-white/60'}`}>⚡ ចម្រុះ</button>
        </div>

        <div className="w-full max-w-2xl relative">
          <input 
            type="text" 
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            placeholder="ស្វែងរកសំណួរទូទាំងកម្មវិធី..." 
            className="w-full pl-14 pr-6 py-4 bg-white border-2 border-indigo-900 rounded-2xl outline-none shadow-xl heading-kh text-blue-600 text-lg font-black transition-all focus:ring-4 focus:ring-indigo-900/10"
          />
          <div className="absolute left-6 top-4 text-indigo-900/40">
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
          </div>
        </div>
      </div>

      <div className="space-y-8">
        <div className="flex justify-center gap-3">
          <button onClick={() => setActiveType('mcq')} className={`px-10 py-3.5 rounded-xl font-black heading-kh text-sm transition-all border-b-4 ${activeType === 'mcq' ? 'bg-red-600 text-white border-red-800 shadow-lg' : 'bg-white text-gray-400 border-gray-200'}`}>📑 QCM</button>
          <button onClick={() => setActiveType('short')} className={`px-10 py-3.5 rounded-xl font-black heading-kh text-sm transition-all border-b-4 ${activeType === 'short' ? 'bg-red-600 text-white border-red-800 shadow-lg' : 'bg-white text-gray-400 border-gray-200'}`}>🖊️ Q & A</button>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          {filteredSubjects.map((sub, i) => {
            const count = activeQuestions.filter(q => q.subject === sub && q.type === activeType).length;
            return (
              <div key={i} className="card-white-elegant p-6 flex flex-col group relative transition-all hover:border-red-600">
                <div onClick={() => setSelectedSubjectForQuiz(sub)} className="cursor-pointer">
                  <div className="flex items-center gap-4 mb-4">
                    <div className="w-14 h-14 bg-gray-50 rounded-xl flex items-center justify-center text-3xl border border-gray-100 group-hover:bg-red-50 transition-colors">
                       {activeType === 'mcq' ? '📑' : '🖊️'}
                    </div>
                    <div className="flex-1 min-w-0">
                      <h3 className="text-xl font-black heading-kh text-indigo-950 truncate leading-tight">{sub}</h3>
                      <p className={`text-[9px] font-black uppercase tracking-widest ${activeType === 'mcq' ? 'text-indigo-600' : 'text-orange-600'}`}>
                        {toKhmerNumeral(count)} សំណួរ
                      </p>
                    </div>
                  </div>
                </div>
                <div className="mt-auto flex gap-3 pt-4 border-t border-gray-50">
                  <button onClick={() => setSelectedSubjectForQuiz(sub)} className="btn-red-elegant flex-[3] py-4 text-sm uppercase">ចូលធ្វើតេស្ត 🚀</button>
                  <button onClick={() => setSelectedSubject(sub)} className="flex-1 py-4 bg-gray-100 text-indigo-950 rounded-xl font-black text-2xl border border-gray-200 hover:bg-indigo-900 hover:text-white transition-all">👁️</button>
                </div>
              </div>
            );
          })}
        </div>
      </div>

      <div className="fixed bottom-6 right-6 z-[50]">
        <button 
          onClick={() => setShowFeedbackModal(true)}
          className="w-14 h-14 bg-yellow-500 text-indigo-950 rounded-full shadow-2xl flex items-center justify-center text-2xl border-4 border-white animate-bounce hover:scale-110 transition-transform"
        >
          💬
        </button>
      </div>

      {showFeedbackModal && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-[100] flex items-center justify-center p-6">
           <div className="bg-white rounded-[2rem] p-8 max-w-sm w-full shadow-2xl animate-fadeIn">
              <h3 className="heading-kh text-xl text-indigo-950 mb-4 font-black">បញ្ជូនមតិយោបល់</h3>
              <textarea 
                value={feedbackText}
                onChange={(e) => setFeedbackText(e.target.value)}
                className="w-full h-32 p-4 bg-gray-50 border border-gray-100 rounded-2xl outline-none focus:ring-2 focus:ring-yellow-500 small-kh text-blue-600"
                placeholder="សរសេរមតិរបស់អ្នកនៅទីនេះ..."
              />
              <div className="flex gap-2 mt-6">
                 <button 
                  onClick={handleSendFeedback}
                  disabled={isSendingFeedback || !feedbackText.trim()}
                  className="flex-1 btn-blue-elegant py-3 rounded-xl heading-kh disabled:opacity-50"
                 >
                    {isSendingFeedback ? 'កំពុងផ្ញើ...' : 'ផ្ញើមតិ'}
                 </button>
                 <button 
                  onClick={() => setShowFeedbackModal(false)}
                  className="flex-1 py-3 bg-gray-100 text-gray-500 rounded-xl heading-kh"
                 >
                    បោះបង់
                 </button>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default PlaySection;

import * as React from 'react';
import { useState, useMemo, useRef, useEffect } from 'react';
import { Question, QuizState } from '../types';

interface QuizGameProps {
  subject: string;
  partIndex: number;
  type: 'mcq' | 'short';
  allSubjectQuestions: Question[];
  onExit: () => void;
  onStartNextPart?: (newPartIndex: number) => void;
}

const QuizGame: React.FC<QuizGameProps> = ({ subject, partIndex, type, allSubjectQuestions, onExit, onStartNextPart }) => {
  const KHMER_PREFIXES = ['ក', 'ខ', 'គ', 'ឃ'];
  const KHMER_DIGITS = ['០', '១', '២', '៣', '៤', '៥', '៦', '៧', '៨', '៩'];
  const toKhmerNumeral = (n: number) => n.toString().split('').map(digit => KHMER_DIGITS[parseInt(digit)] || digit).join('');

  const [isMuted, setIsMuted] = useState(false);
  const correctAudioRef = useRef<HTMLAudioElement | null>(null);
  const wrongAudioRef = useRef<HTMLAudioElement | null>(null);

  useEffect(() => {
    correctAudioRef.current = new Audio('https://assets.mixkit.co/active_storage/sfx/600/600-preview.mp3');
    wrongAudioRef.current = new Audio('https://assets.mixkit.co/active_storage/sfx/951/951-preview.mp3');
    return () => { correctAudioRef.current?.pause(); wrongAudioRef.current?.pause(); };
  }, []);

  // រៀបចំសំណួរសម្រាប់ភាគនីមួយៗ (១០ សំណួរ)
  const partQuestions = useMemo(() => {
    const start = partIndex * 10;
    const subset = allSubjectQuestions.slice(start, start + 10);
    if (type === 'mcq') {
      return subset.map(q => {
        if (!q.options) return q;
        const opts = q.options.map((opt, idx) => ({ text: opt, isCorrect: idx === q.correct }));
        // កុំឱ្យ Shuffle ពេល Review ដើម្បីកុំឱ្យច្រឡំ
        return { ...q, options: opts.map(o => o.text), correct: opts.findIndex(o => o.isCorrect) };
      });
    }
    return subset;
  }, [allSubjectQuestions, partIndex, type]);

  const [state, setState] = useState<QuizState>({
    currentQuestionIndex: 0, 
    score: 0, 
    isFinished: false, 
    selectedAnswer: null, 
    userInput: '', 
    showCorrect: false, 
    userAnswers: [], 
    isReviewing: false
  });

  const hasNextPart = (partIndex + 1) * 10 < allSubjectQuestions.length;

  const handleMCQSelect = (idx: number) => {
    if (state.selectedAnswer !== null || state.isFinished) return;
    const isCorrect = idx === partQuestions[state.currentQuestionIndex].correct;
    if (!isMuted) {
      const audio = isCorrect ? correctAudioRef.current : wrongAudioRef.current;
      if (audio) { audio.currentTime = 0; audio.play().catch(() => {}); }
    }
    setState(prev => ({
      ...prev, 
      selectedAnswer: idx, 
      showCorrect: true, 
      score: isCorrect ? prev.score + 1 : prev.score, 
      userAnswers: [...prev.userAnswers, idx]
    }));
  };

  const handleShowShortAnswer = () => {
    if (!isMuted && correctAudioRef.current) {
      correctAudioRef.current.currentTime = 0;
      correctAudioRef.current.play().catch(() => {});
    }
    setState(prev => ({ 
      ...prev, 
      showCorrect: true, 
      score: prev.score + 1,
      userAnswers: [...prev.userAnswers, 'seen'] // សម្គាល់ថាបានមើលចម្លើយ
    }));
  };

  const handleNext = () => {
    if (state.currentQuestionIndex + 1 < partQuestions.length) {
      setState(prev => ({ ...prev, currentQuestionIndex: prev.currentQuestionIndex + 1, selectedAnswer: null, showCorrect: false, userInput: '' }));
    } else setState(prev => ({ ...prev, isFinished: true }));
  };

  const toggleReviewMode = () => {
    setState(prev => ({ ...prev, isReviewing: !prev.isReviewing }));
  };

  // ផ្ទាំងពិនិត្យចម្លើយឡើងវិញ (Review Mode)
  if (state.isFinished && state.isReviewing) {
    return (
      <div className="page-transition space-y-8 pb-20">
        <div className="flex items-center justify-between sticky top-0 z-10 bg-[#020617]/80 backdrop-blur-md py-4 px-2 border-b border-white/10">
          <button 
            onClick={toggleReviewMode}
            className="px-6 py-3 bg-white/10 hover:bg-white/20 text-white rounded-2xl font-black heading-kh text-sm flex items-center gap-2"
          >
            ← ត្រឡប់ទៅលទ្ធផល
          </button>
          <div className="text-right">
            <h3 className="heading-kh text-white font-black">ពិនិត្យចម្លើយឡើងវិញ</h3>
            <p className="text-[10px] text-emerald-400 font-bold uppercase tracking-widest">ភាគ {toKhmerNumeral(partIndex + 1)}</p>
          </div>
        </div>

        <div className="space-y-6 max-w-3xl mx-auto px-2">
          {partQuestions.map((q, qIdx) => {
            const userAnswer = state.userAnswers[qIdx];
            const isCorrect = q.type === 'mcq' ? userAnswer === q.correct : true;

            return (
              <div key={qIdx} className="card-white-elegant p-6 md:p-8 border-l-8 border-indigo-900 shadow-xl animate-fadeIn">
                <div className="flex items-start gap-4 mb-6">
                  <span className="w-10 h-10 bg-indigo-900 text-white rounded-xl flex items-center justify-center font-black shrink-0 shadow-md">
                    {toKhmerNumeral(qIdx + 1)}
                  </span>
                  <h4 className="heading-kh text-lg md:text-xl text-indigo-950 text-justify leading-relaxed">
                    {q.question}
                  </h4>
                </div>

                {q.type === 'mcq' ? (
                  <div className="grid grid-cols-1 gap-3 pl-0 md:pl-14">
                    {q.options?.map((opt, oIdx) => {
                      const isUserChoice = userAnswer === oIdx;
                      const isCorrectChoice = q.correct === oIdx;

                      let style = "bg-gray-50 border-gray-100 opacity-60";
                      if (isCorrectChoice) style = "bg-emerald-50 border-emerald-500 text-emerald-950 opacity-100 ring-2 ring-emerald-500/10";
                      else if (isUserChoice && !isCorrectChoice) style = "bg-red-50 border-red-500 text-red-950 opacity-100";

                      return (
                        <div key={oIdx} className={`p-4 rounded-xl border flex items-center gap-4 transition-all ${style}`}>
                          <span className={`w-8 h-8 rounded-lg flex items-center justify-center font-black text-sm shrink-0 ${isCorrectChoice ? 'bg-emerald-600 text-white' : isUserChoice ? 'bg-red-600 text-white' : 'bg-white text-gray-400'}`}>
                            {KHMER_PREFIXES[oIdx]}
                          </span>
                          <span className="flex-1 font-bold small-kh">{opt}</span>
                          {isCorrectChoice && <span className="text-emerald-600 text-xl">✓</span>}
                          {isUserChoice && !isCorrectChoice && <span className="text-red-600 text-xl">✕</span>}
                        </div>
                      );
                    })}
                  </div>
                ) : (
                  <div className="pl-0 md:pl-14">
                    <div className="p-6 bg-emerald-50 border border-emerald-500/20 rounded-2xl relative overflow-hidden">
                       <p className="text-[10px] font-black text-emerald-700 uppercase mb-3">ចម្លើយត្រឹមត្រូវ៖</p>
                       <p className="small-kh text-indigo-950 font-bold text-lg leading-relaxed whitespace-pre-wrap">{q.answer}</p>
                    </div>
                  </div>
                )}
              </div>
            );
          })}
        </div>

        <div className="flex justify-center p-10">
           <button 
             onClick={onExit}
             className="btn-blue-elegant px-10 py-5 heading-kh text-lg shadow-2xl"
           >
             ត្រឡប់ទៅមឺនុយដើម 🏠
           </button>
        </div>
      </div>
    );
  }

  if (state.isFinished) {
    const percentage = Math.round((state.score / partQuestions.length) * 100);
    return (
      <div className="page-transition max-w-md mx-auto py-10 px-2">
        <div className="card-white-elegant p-10 text-center border-t-8 border-indigo-900 overflow-hidden relative shadow-2xl">
          <div className="absolute top-0 left-0 w-full h-2 bg-gradient-to-r from-indigo-900 via-blue-500 to-indigo-900"></div>
          <div className="text-7xl mb-6">🏆</div>
          <h2 className="text-2xl font-black mb-2 heading-kh text-indigo-950">បញ្ចប់ការធ្វើតេស្ត</h2>
          <div className="text-7xl font-black text-indigo-900 my-8 drop-shadow-sm">{toKhmerNumeral(percentage)}%</div>

          <div className="flex justify-center gap-8 mb-10">
            <div className="text-center">
              <p className="text-[10px] uppercase font-black text-gray-400 mb-1">ត្រឹមត្រូវ</p>
              <p className="text-2xl font-black text-emerald-600">{toKhmerNumeral(state.score)}</p>
            </div>
            <div className="h-10 w-[1px] bg-gray-100"></div>
            <div className="text-center">
              <p className="text-[10px] uppercase font-black text-gray-400 mb-1">សំណួរសរុប</p>
              <p className="text-2xl font-black text-indigo-950">{toKhmerNumeral(partQuestions.length)}</p>
            </div>
          </div>

          <div className="space-y-3">
            <button 
              onClick={toggleReviewMode}
              className="w-full py-4 bg-indigo-50 text-indigo-950 border-2 border-indigo-100 rounded-2xl font-black heading-kh hover:bg-indigo-900 hover:text-white transition-all shadow-sm"
            >
              👁️ ពិនិត្យចម្លើយឡើងវិញ
            </button>

            {hasNextPart && onStartNextPart && (
              <button 
                onClick={() => onStartNextPart(partIndex + 1)}
                className="w-full btn-red-elegant py-5 text-lg heading-kh shadow-xl active:scale-95 transition-all"
              >
                ភាគបន្ទាប់ ➡️
              </button>
            )}

            <button 
              onClick={onExit} 
              className="w-full btn-blue-elegant py-5 text-lg heading-kh shadow-xl hover:brightness-110 active:scale-95 transition-all"
            >
              ត្រឡប់ទៅមឺនុយដើម 🏠
            </button>
          </div>
        </div>
      </div>
    );
  }

  const currentQ = partQuestions[state.currentQuestionIndex];
  const progress = ((state.currentQuestionIndex + 1) / partQuestions.length) * 100;

  return (
    <div className="card-white-elegant p-6 md:p-12 page-transition flex flex-col min-h-[600px] relative border-b-8 border-indigo-900 shadow-2xl overflow-hidden">
      {/* Progress Bar */}
      <div className="absolute top-0 left-0 w-full h-2 bg-gray-100">
        <div 
          className="h-full bg-gradient-to-r from-indigo-600 to-blue-400 transition-all duration-500 ease-out"
          style={{ width: `${progress}%` }}
        ></div>
      </div>

      <div className="flex justify-between items-start mb-10 mt-2">
        <div className="flex flex-col">
          <div className="flex gap-2 mb-3">
            <button 
              onClick={onExit}
              className="px-3 py-1 bg-indigo-50 text-indigo-900 rounded-lg text-[10px] font-black heading-kh hover:bg-indigo-900 hover:text-white transition-all shadow-sm"
            >
              ← ត្រឡប់ក្រោយ
            </button>
            <span className="text-indigo-900 font-black text-[9px] uppercase tracking-[0.2em] bg-indigo-50 px-4 py-1.5 rounded-full w-fit border border-indigo-100">
              {subject} - ភាគ {toKhmerNumeral(partIndex + 1)}
            </span>
          </div>
          <div className="flex items-baseline gap-2">
             <span className="text-5xl font-black text-indigo-950 leading-none">{toKhmerNumeral(state.currentQuestionIndex + 1)}</span>
             <span className="text-xl font-black text-gray-300">/ {toKhmerNumeral(partQuestions.length)}</span>
          </div>
        </div>
        <div className="flex items-center gap-3">
          <button 
            onClick={() => setIsMuted(!isMuted)} 
            className={`w-12 h-12 rounded-2xl flex items-center justify-center text-xl border transition-all ${isMuted ? 'bg-gray-100 border-gray-200 text-gray-400' : 'bg-white border-indigo-100 text-indigo-900 shadow-sm hover:bg-indigo-50'}`}
          >
            {isMuted ? '🔇' : '🔊'}
          </button>
          <div className="bg-indigo-950 text-white px-6 py-3 rounded-2xl font-black text-xl shadow-lg flex items-center gap-3">
            <span className="text-xs opacity-50 font-medium">ពិន្ទុ</span>
            <span>{toKhmerNumeral(state.score)}</span>
          </div>
        </div>
      </div>

      <div className="flex-1 flex flex-col">
        <div className="mb-10">
          <h2 className="text-xl md:text-3xl font-black heading-kh text-indigo-950 leading-[1.6] text-justify">
            {currentQ?.question}
          </h2>
        </div>

        {currentQ?.type === 'mcq' ? (
          <div className="grid grid-cols-1 gap-4">
            {currentQ?.options?.map((opt, i) => {
              let containerStyle = "bg-white border-2 border-gray-100 hover:border-indigo-200 hover:bg-indigo-50/30 text-indigo-950 shadow-sm";
              let prefixStyle = "bg-indigo-900 text-white shadow-md"; 

              if (state.showCorrect) {
                if (i === currentQ.correct) {
                  containerStyle = "bg-emerald-50 border-emerald-500 text-emerald-900 shadow-lg scale-[1.02] ring-4 ring-emerald-500/10";
                  prefixStyle = "bg-emerald-600 text-white";
                } else if (i === state.selectedAnswer) {
                  containerStyle = "bg-red-50 border-red-500 text-red-900 opacity-100";
                  prefixStyle = "bg-red-600 text-white";
                } else {
                  containerStyle = "opacity-40 grayscale-[0.5] border-gray-100";
                  prefixStyle = "bg-gray-400 text-white";
                }
              }

              return (
                <button 
                  key={i} 
                  onClick={() => handleMCQSelect(i)} 
                  disabled={state.showCorrect} 
                  className={`text-left p-4.5 md:p-5 rounded-2xl transition-all duration-300 font-bold text-base md:text-lg flex items-center gap-5 small-kh group ${containerStyle}`}
                >
                  <span className={`w-10 h-10 md:w-12 md:h-12 rounded-xl flex items-center justify-center font-black text-lg md:text-xl shrink-0 transition-transform group-active:scale-90 ${prefixStyle}`}>
                    {KHMER_PREFIXES[i]}
                  </span>
                  <span className="flex-1 leading-relaxed">{opt}</span>
                </button>
              );
            })}
          </div>
        ) : (
          <div className="space-y-6">
            {!state.showCorrect ? (
              <button 
                onClick={handleShowShortAnswer}
                className="w-full py-10 bg-indigo-50 border-4 border-dashed border-indigo-200 rounded-[2.5rem] flex flex-col items-center justify-center gap-4 group hover:bg-indigo-100 hover:border-indigo-300 transition-all"
              >
                <div className="text-5xl animate-bounce">🤔</div>
                <span className="heading-kh text-indigo-900 font-black text-xl">ចុចដើម្បីបង្ហាញចម្លើយ</span>
              </button>
            ) : (
              <div className="p-8 md:p-10 bg-emerald-50 border-2 border-emerald-500 rounded-[2.5rem] animate-fadeIn shadow-lg relative overflow-hidden">
                <div className="absolute top-0 right-0 w-24 h-24 bg-emerald-500/10 rounded-bl-[4rem] flex items-center justify-center text-4xl">
                  ✅
                </div>
                <div className="flex items-center gap-3 mb-6">
                  <span className="px-4 py-1.5 bg-emerald-600 text-white rounded-lg text-xs font-black uppercase small-kh shadow-md">ចម្លើយត្រឹមត្រូវ</span>
                </div>
                <p className="small-kh text-emerald-950 text-xl md:text-2xl font-bold leading-relaxed whitespace-pre-wrap">
                  {currentQ.answer}
                </p>
              </div>
            )}
          </div>
        )}
      </div>

      {state.showCorrect && (
        <div className="mt-12 animate-fadeIn">
          <button 
            onClick={handleNext} 
            className="w-full btn-blue-elegant py-5 text-xl heading-kh uppercase tracking-wider shadow-[0_10px_30px_rgba(30,27,75,0.3)] hover:brightness-110 active:scale-[0.98] transition-all"
          >
            {state.currentQuestionIndex + 1 === partQuestions.length ? "បញ្ចប់ និងមើលលទ្ធផល 🏁" : "សំណួរបន្ទាប់ ✨"}
          </button>
        </div>
      )}
    </div>
  );
};

export default QuizGame;

import * as React from 'react';
import { useState, useEffect, useCallback, useRef } from 'react';
import { Question, AppMode, SelectedQuizInfo, UserRole, Feedback } from './types';
import { INITIAL_QUESTIONS, SECRET_CODE } from './constants';
import Header from './components/Header';
import AuthSection from './components/AuthSection';
import CreateSection from './components/CreateSection';
import PlaySection from './components/PlaySection';
import QuizGame from './components/QuizGame';
import { initFirebase, syncQuestionsToFirebase, listenToQuestions, listenToFeedback, removeFeedback } from './services/firebaseService';

const App: React.FC = () => {
  const [quizData, setQuizData] = useState<Question[]>([]);
  const [feedbackList, setFeedbackList] = useState<Feedback[]>([]);
  const [mode, setMode] = useState<AppMode>('play');
  const [userRole, setUserRole] = useState<UserRole>(null);
  const [username, setUsername] = useState<string>('');
  const [activeQuiz, setActiveQuiz] = useState<SelectedQuizInfo | null>(null);
  const [isInitialized, setIsInitialized] = useState(false);
  const [isCloudConnected, setIsCloudConnected] = useState<boolean | 'error'>(false);
  const isListeningRef = useRef(false);

  const APP_LOGO_URL = "https://i.postimg.cc/0ygmLdvR/3QCM_Ep4.png";

  const sanitizeQuestions = useCallback((data: any[]): Question[] => {
    if (!Array.isArray(data)) return [];
    return data.filter(q => q && typeof q === 'object').map(q => {
      const type = q.type === 'short' ? 'short' : 'mcq';
      return {
        subject: String(q.subject || 'មិនមានមុខវិជ្ជា'),
        question: String(q.question || ''),
        type,
        options: type === 'mcq' ? (Array.isArray(q.options) ? q.options.map((o: any) => String(o || '')) : ['', '', '', '']) : undefined,
        correct: type === 'mcq' ? (typeof q.correct === 'number' ? q.correct : 0) : undefined,
        answer: type === 'short' ? String(q.answer || '') : undefined,
        isActive: q.isActive !== false
      };
    }) as Question[];
  }, []);

  const saveToLocal = useCallback((data: Question[]) => {
    try {
      localStorage.setItem('quiz_data', JSON.stringify(data));
    } catch (e) { console.error(e); }
  }, []);

  useEffect(() => {
    if (isListeningRef.current) return;
    isListeningRef.current = true;
    initFirebase();
    const saved = localStorage.getItem('quiz_data');
    if (saved) { try { setQuizData(sanitizeQuestions(JSON.parse(saved))); } catch(e){} }

    const unsubscribeQuestions = listenToQuestions((remoteData) => {
      const cleaned = sanitizeQuestions(remoteData);
      setQuizData(cleaned);
      saveToLocal(cleaned);
      setIsCloudConnected(true);
      setIsInitialized(true);
    }, (error) => {
      setIsCloudConnected('error');
      setIsInitialized(true);
    });

    return () => { unsubscribeQuestions(); isListeningRef.current = false; };
  }, [sanitizeQuestions, saveToLocal]);

  useEffect(() => {
    let unsubscribeFeedback = () => {};
    if (userRole === 'admin') {
      unsubscribeFeedback = listenToFeedback((fbs) => setFeedbackList(fbs)) || (() => {});
    }
    return () => unsubscribeFeedback();
  }, [userRole]);

  const handleSyncData = (newData: Question[]) => {
    setQuizData(newData);
    saveToLocal(newData);
    if (userRole === 'admin') {
      syncQuestionsToFirebase(newData).then(() => setIsCloudConnected(true)).catch(() => setIsCloudConnected('error'));
    }
  };

  const handleReorderSubject = (subject: string, type: 'mcq' | 'short', direction: 'up' | 'down') => {
    const subjects = Array.from(new Set(quizData.filter(q => q.type === type).map(q => q.subject)));
    const index = subjects.indexOf(subject);
    if (index === -1) return;

    const newIndex = direction === 'up' ? index - 1 : index + 1;
    if (newIndex < 0 || newIndex >= subjects.length) return;

    const newSubjects = [...subjects];
    [newSubjects[index], newSubjects[newIndex]] = [newSubjects[newIndex], newSubjects[index]];

    const reorderedData: Question[] = [];
    newSubjects.forEach(s => {
      reorderedData.push(...quizData.filter(q => q.subject === s && q.type === type));
    });
    // Add back questions of other types
    reorderedData.push(...quizData.filter(q => q.type !== type));
    handleSyncData(reorderedData);
  };

  const handleNextPart = (newPartIndex: number) => {
    if (activeQuiz) {
      setActiveQuiz({
        ...activeQuiz,
        partIndex: newPartIndex
      });
    }
  };

  if (!isInitialized) return null;

  if (!userRole) {
    return (
      <div className="min-h-screen py-12 px-4 flex flex-col items-center justify-center page-transition bg-slate-950">
        <div className="mb-12 relative group">
          <div className="absolute inset-0 bg-red-600/30 blur-[60px] rounded-full animate-pulse"></div>
          <div className="relative w-40 h-40 md:w-48 md:h-48 bg-white p-1 rounded-full shadow-2xl border-[3px] border-red-500 transform transition-transform hover:scale-105 duration-500 animate-[bounce_3s_infinite]">
            <img src={APP_LOGO_URL} alt="Logo" className="w-full h-full object-cover rounded-full" />
          </div>
        </div>
        <div className="text-center mb-16">
          <h1 className="font-black heading-kh">
            <span className="block text-3xl md:text-4xl text-white opacity-80 mb-8 uppercase tracking-[0.25em]">ត្រៀមប្រឡង</span>
            <span className="block text-6xl md:text-8xl bg-gradient-to-b from-yellow-200 via-yellow-400 to-yellow-600 bg-clip-text text-transparent py-4">ក្របខ័ណ្ឌរដ្ឋ</span>
          </h1>
        </div>
        <AuthSection onLogin={(role, uName) => { setUserRole(role); if(uName) setUsername(uName); }} secretCode={SECRET_CODE} />
      </div>
    );
  }

  return (
    <div className="min-h-screen py-6 px-4 md:py-10 page-transition">
      <div className="max-w-4xl mx-auto">
        <Header mode={mode} role={userRole} totalQuestions={quizData.length} cloudStatus={isCloudConnected} setMode={(m) => { setMode(m); setActiveQuiz(null); }} onLogout={() => { setUserRole(null); setUsername(''); }} />
        <main className="mt-6">
          {mode === 'play' ? (
            activeQuiz ? (
              <QuizGame 
                subject={activeQuiz.subject} 
                partIndex={activeQuiz.partIndex} 
                type={activeQuiz.type} 
                allSubjectQuestions={activeQuiz.customQuestions || quizData.filter(q => q.subject === activeQuiz.subject && q.type === activeQuiz.type)} 
                onExit={() => setActiveQuiz(null)}
                onStartNextPart={handleNextPart}
              />
            ) : (
              <PlaySection isAdmin={userRole === 'admin'} username={username} quizData={quizData} onStartQuiz={(subject, partIndex, type, q) => setActiveQuiz({ subject, partIndex, type, customQuestions: q })} />
            )
          ) : (
            <CreateSection 
              quizData={quizData} 
              feedbackList={feedbackList} 
              onDeleteFeedback={removeFeedback} 
              onAdd={(q) => handleSyncData([...quizData, q])} 
              onUpdate={(i, q) => handleSyncData(quizData.map((old, idx) => idx === i ? q : old))} 
              onRemove={(i) => handleSyncData(quizData.filter((_, idx) => idx !== i))} 
              onToggleSubject={(sub, type, act) => handleSyncData(quizData.map(q => (q.subject === sub && q.type === type) ? { ...q, isActive: act } : q))} 
              onUpdateSubject={(old, type, newName) => handleSyncData(quizData.map(q => (q.subject === old && q.type === type) ? { ...q, subject: newName.trim() } : q))} 
              onRemoveSubject={(sub, type) => handleSyncData(quizData.filter(q => !(q.subject === sub && q.type === type)))} 
              onReorderSubject={handleReorderSubject}
              onBatchAdd={(qs) => handleSyncData([...quizData, ...qs])} 
              onLogout={() => { setUserRole(null); setUsername(''); }} 
            />
          )}
        </main>
      </div>
    </div>
  );
};

export default App;

import * as React from 'react';
import { useState, useMemo, useRef, useEffect } from 'react';
import { Question, QuizState } from '../types';

interface QuizGameProps {
  subject: string;
  partIndex: number;
  type: 'mcq' | 'short';
  allSubjectQuestions: Question[];
  onExit: () => void;
  onStartNextPart?: (newPartIndex: number) => void;
}

const QuizGame: React.FC<QuizGameProps> = ({ subject, partIndex, type, allSubjectQuestions, onExit, onStartNextPart }) => {
  const KHMER_PREFIXES = ['ក', 'ខ', 'គ', 'ឃ'];
  const KHMER_DIGITS = ['០', '១', '២', '៣', '៤', '៥', '៦', '៧', '៨', '៩'];
  const toKhmerNumeral = (n: number) => n.toString().split('').map(digit => KHMER_DIGITS[parseInt(digit)] || digit).join('');

  const [isMuted, setIsMuted] = useState(false);
  const correctAudioRef = useRef<HTMLAudioElement | null>(null);
  const wrongAudioRef = useRef<HTMLAudioElement | null>(null);

  useEffect(() => {
    correctAudioRef.current = new Audio('https://assets.mixkit.co/active_storage/sfx/600/600-preview.mp3');
    wrongAudioRef.current = new Audio('https://assets.mixkit.co/active_storage/sfx/951/951-preview.mp3');
    return () => { correctAudioRef.current?.pause(); wrongAudioRef.current?.pause(); };
  }, []);

  // រៀបចំសំណួរសម្រាប់ភាគនីមួយៗ (១០ សំណួរ)
  const partQuestions = useMemo(() => {
    const start = partIndex * 10;
    const subset = allSubjectQuestions.slice(start, start + 10);
    if (type === 'mcq') {
      return subset.map(q => {
        if (!q.options) return q;
        const opts = q.options.map((opt, idx) => ({ text: opt, isCorrect: idx === q.correct }));
        // កុំឱ្យ Shuffle ពេល Review ដើម្បីកុំឱ្យច្រឡំ
        return { ...q, options: opts.map(o => o.text), correct: opts.findIndex(o => o.isCorrect) };
      });
    }
    return subset;
  }, [allSubjectQuestions, partIndex, type]);

  const [state, setState] = useState<QuizState>({
    currentQuestionIndex: 0, 
    score: 0, 
    isFinished: false, 
    selectedAnswer: null, 
    userInput: '', 
    showCorrect: false, 
    userAnswers: [], 
    isReviewing: false
  });

  // Reset state ពេលប្តូរភាគ ឬមុខវិជ្ជា
  useEffect(() => {
    setState({
      currentQuestionIndex: 0, 
      score: 0, 
      isFinished: false, 
      selectedAnswer: null, 
      userInput: '', 
      showCorrect: false, 
      userAnswers: [], 
      isReviewing: false
    });
  }, [subject, partIndex, type]);

  const hasNextPart = (partIndex + 1) * 10 < allSubjectQuestions.length;

  const handleMCQSelect = (idx: number) => {
    if (state.selectedAnswer !== null || state.isFinished) return;
    const isCorrect = idx === partQuestions[state.currentQuestionIndex].correct;
    if (!isMuted) {
      const audio = isCorrect ? correctAudioRef.current : wrongAudioRef.current;
      if (audio) { audio.currentTime = 0; audio.play().catch(() => {}); }
    }
    setState(prev => ({
      ...prev, 
      selectedAnswer: idx, 
      showCorrect: true, 
      score: isCorrect ? prev.score + 1 : prev.score, 
      userAnswers: [...prev.userAnswers, idx]
    }));
  };

  const handleShowShortAnswer = () => {
    if (!isMuted && correctAudioRef.current) {
      correctAudioRef.current.currentTime = 0;
      correctAudioRef.current.play().catch(() => {});
    }
    setState(prev => ({ 
      ...prev, 
      showCorrect: true, 
      score: prev.score + 1,
      userAnswers: [...prev.userAnswers, 'seen'] // សម្គាល់ថាបានមើលចម្លើយ
    }));
  };

  const handleNext = () => {
    if (state.currentQuestionIndex + 1 < partQuestions.length) {
      setState(prev => ({ ...prev, currentQuestionIndex: prev.currentQuestionIndex + 1, selectedAnswer: null, showCorrect: false, userInput: '' }));
    } else setState(prev => ({ ...prev, isFinished: true }));
  };

  const toggleReviewMode = () => {
    setState(prev => ({ ...prev, isReviewing: !prev.isReviewing }));
  };

  // ផ្ទាំងពិនិត្យចម្លើយឡើងវិញ (Review Mode)
  if (state.isFinished && state.isReviewing) {
    return (
      <div className="page-transition space-y-8 pb-20">
        <div className="flex items-center justify-between sticky top-0 z-10 bg-[#020617]/80 backdrop-blur-md py-4 px-2 border-b border-white/10">
          <button 
            onClick={toggleReviewMode}
            className="px-6 py-3 bg-white/10 hover:bg-white/20 text-white rounded-2xl font-black heading-kh text-sm flex items-center gap-2"
          >
            ← ត្រឡប់ទៅលទ្ធផល
          </button>
          <div className="text-right">
            <h3 className="heading-kh text-white font-black">ពិនិត្យចម្លើយឡើងវិញ</h3>
            <p className="text-[10px] text-emerald-400 font-bold uppercase tracking-widest">ភាគ {toKhmerNumeral(partIndex + 1)}</p>
          </div>
        </div>

        <div className="space-y-6 max-w-3xl mx-auto px-2">
          {partQuestions.map((q, qIdx) => {
            const userAnswer = state.userAnswers[qIdx];
            const isCorrect = q.type === 'mcq' ? userAnswer === q.correct : true;

            return (
              <div key={qIdx} className="card-white-elegant p-6 md:p-8 border-l-8 border-indigo-900 shadow-xl animate-fadeIn">
                <div className="flex items-start gap-4 mb-6">
                  <span className="w-10 h-10 bg-indigo-900 text-white rounded-xl flex items-center justify-center font-black shrink-0 shadow-md">
                    {toKhmerNumeral(qIdx + 1)}
                  </span>
                  <h4 className="heading-kh text-lg md:text-xl text-indigo-950 text-justify leading-relaxed">
                    {q.question}
                  </h4>
                </div>

                {q.type === 'mcq' ? (
                  <div className="grid grid-cols-1 gap-3 pl-0 md:pl-14">
                    {q.options?.map((opt, oIdx) => {
                      const isUserChoice = userAnswer === oIdx;
                      const isCorrectChoice = q.correct === oIdx;

                      let style = "bg-gray-50 border-gray-100 opacity-60";
                      if (isCorrectChoice) style = "bg-emerald-50 border-emerald-500 text-emerald-950 opacity-100 ring-2 ring-emerald-500/10";
                      else if (isUserChoice && !isCorrectChoice) style = "bg-red-50 border-red-500 text-red-950 opacity-100";

                      return (
                        <div key={oIdx} className={`p-4 rounded-xl border flex items-center gap-4 transition-all ${style}`}>
                          <span className={`w-8 h-8 rounded-lg flex items-center justify-center font-black text-sm shrink-0 ${isCorrectChoice ? 'bg-emerald-600 text-white' : isUserChoice ? 'bg-red-600 text-white' : 'bg-white text-gray-400'}`}>
                            {KHMER_PREFIXES[oIdx]}
                          </span>
                          <span className="flex-1 font-bold small-kh">{opt}</span>
                          {isCorrectChoice && <span className="text-emerald-600 text-xl">✓</span>}
                          {isUserChoice && !isCorrectChoice && <span className="text-red-600 text-xl">✕</span>}
                        </div>
                      );
                    })}
                  </div>
                ) : (
                  <div className="pl-0 md:pl-14">
                    <div className="p-6 bg-emerald-50 border border-emerald-500/20 rounded-2xl relative overflow-hidden">
                       <p className="text-[10px] font-black text-emerald-700 uppercase mb-3">ចម្លើយត្រឹមត្រូវ៖</p>
                       <p className="small-kh text-indigo-950 font-bold text-lg leading-relaxed whitespace-pre-wrap">{q.answer}</p>
                    </div>
                  </div>
                )}
              </div>
            );
          })}
        </div>

        <div className="flex justify-center p-10">
           <button 
             onClick={onExit}
             className="btn-blue-elegant px-10 py-5 heading-kh text-lg shadow-2xl"
           >
             ត្រឡប់ទៅមឺនុយដើម 🏠
           </button>
        </div>
      </div>
    );
  }

  if (state.isFinished) {
    const percentage = Math.round((state.score / partQuestions.length) * 100);
    return (
      <div className="page-transition max-w-md mx-auto py-10 px-2">
        <div className="card-white-elegant p-10 text-center border-t-8 border-indigo-900 overflow-hidden relative shadow-2xl">
          <div className="absolute top-0 left-0 w-full h-2 bg-gradient-to-r from-indigo-900 via-blue-500 to-indigo-900"></div>
          <div className="text-7xl mb-6">🏆</div>
          <h2 className="text-2xl font-black mb-2 heading-kh text-indigo-950">បញ្ចប់ការធ្វើតេស្ត</h2>
          <div className="text-7xl font-black text-indigo-900 my-8 drop-shadow-sm">{toKhmerNumeral(percentage)}%</div>

          <div className="flex justify-center gap-8 mb-10">
            <div className="text-center">
              <p className="text-[10px] uppercase font-black text-gray-400 mb-1">ត្រឹមត្រូវ</p>
              <p className="text-2xl font-black text-emerald-600">{toKhmerNumeral(state.score)}</p>
            </div>
            <div className="h-10 w-[1px] bg-gray-100"></div>
            <div className="text-center">
              <p className="text-[10px] uppercase font-black text-gray-400 mb-1">សំណួរសរុប</p>
              <p className="text-2xl font-black text-indigo-950">{toKhmerNumeral(partQuestions.length)}</p>
            </div>
          </div>

          <div className="space-y-3">
            <button 
              onClick={toggleReviewMode}
              className="w-full py-4 bg-indigo-50 text-indigo-950 border-2 border-indigo-100 rounded-2xl font-black heading-kh hover:bg-indigo-900 hover:text-white transition-all shadow-sm"
            >
              👁️ ពិនិត្យចម្លើយឡើងវិញ
            </button>

            {hasNextPart && onStartNextPart && (
              <button 
                onClick={() => onStartNextPart(partIndex + 1)}
                className="w-full btn-red-elegant py-5 text-lg heading-kh shadow-xl active:scale-95 transition-all"
              >
                ភាគបន្ទាប់ ➡️
              </button>
            )}

            <button 
              onClick={onExit} 
              className="w-full btn-blue-elegant py-5 text-lg heading-kh shadow-xl hover:brightness-110 active:scale-95 transition-all"
            >
              ត្រឡប់ទៅមឺនុយដើម 🏠
            </button>
          </div>
        </div>
      </div>
    );
  }

  const currentQ = partQuestions[state.currentQuestionIndex];
  const progress = ((state.currentQuestionIndex + 1) / partQuestions.length) * 100;

  return (
    <div className="card-white-elegant p-6 md:p-12 page-transition flex flex-col min-h-[600px] relative border-b-8 border-indigo-900 shadow-2xl overflow-hidden">
      {/* Progress Bar */}
      <div className="absolute top-0 left-0 w-full h-2 bg-gray-100">
        <div 
          className="h-full bg-gradient-to-r from-indigo-600 to-blue-400 transition-all duration-500 ease-out"
          style={{ width: `${progress}%` }}
        ></div>
      </div>

      <div className="flex justify-between items-start mb-10 mt-2">
        <div className="flex flex-col">
          <div className="flex gap-2 mb-3">
            <button 
              onClick={onExit}
              className="px-3 py-1 bg-indigo-50 text-indigo-900 rounded-lg text-[10px] font-black heading-kh hover:bg-indigo-900 hover:text-white transition-all shadow-sm"
            >
              ← ត្រឡប់ក្រោយ
            </button>
            <span className="text-indigo-900 font-black text-[9px] uppercase tracking-[0.2em] bg-indigo-50 px-4 py-1.5 rounded-full w-fit border border-indigo-100">
              {subject} - ភាគ {toKhmerNumeral(partIndex + 1)}
            </span>
          </div>
          <div className="flex items-baseline gap-2">
             <span className="text-5xl font-black text-indigo-950 leading-none">{toKhmerNumeral(state.currentQuestionIndex + 1)}</span>
             <span className="text-xl font-black text-gray-300">/ {toKhmerNumeral(partQuestions.length)}</span>
          </div>
        </div>
        <div className="flex items-center gap-3">
          <button 
            onClick={() => setIsMuted(!isMuted)} 
            className={`w-12 h-12 rounded-2xl flex items-center justify-center text-xl border transition-all ${isMuted ? 'bg-gray-100 border-gray-200 text-gray-400' : 'bg-white border-indigo-100 text-indigo-900 shadow-sm hover:bg-indigo-50'}`}
          >
            {isMuted ? '🔇' : '🔊'}
          </button>
          <div className="bg-indigo-950 text-white px-6 py-3 rounded-2xl font-black text-xl shadow-lg flex items-center gap-3">
            <span className="text-xs opacity-50 font-medium">ពិន្ទុ</span>
            <span>{toKhmerNumeral(state.score)}</span>
          </div>
        </div>
      </div>

      <div className="flex-1 flex flex-col">
        <div className="mb-10">
          <h2 className="text-xl md:text-3xl font-black heading-kh text-indigo-950 leading-[1.6] text-justify">
            {currentQ?.question}
          </h2>
        </div>

        {currentQ?.type === 'mcq' ? (
          <div className="grid grid-cols-1 gap-4">
            {currentQ?.options?.map((opt, i) => {
              let containerStyle = "bg-white border-2 border-gray-100 hover:border-indigo-200 hover:bg-indigo-50/30 text-indigo-950 shadow-sm";
              let prefixStyle = "bg-indigo-900 text-white shadow-md"; 

              if (state.showCorrect) {
                if (i === currentQ.correct) {
                  containerStyle = "bg-emerald-50 border-emerald-500 text-emerald-900 shadow-lg scale-[1.02] ring-4 ring-emerald-500/10";
                  prefixStyle = "bg-emerald-600 text-white";
                } else if (i === state.selectedAnswer) {
                  containerStyle = "bg-red-50 border-red-500 text-red-900 opacity-100";
                  prefixStyle = "bg-red-600 text-white";
                } else {
                  containerStyle = "opacity-40 grayscale-[0.5] border-gray-100";
                  prefixStyle = "bg-gray-400 text-white";
                }
              }

              return (
                <button 
                  key={i} 
                  onClick={() => handleMCQSelect(i)} 
                  disabled={state.showCorrect} 
                  className={`text-left p-4.5 md:p-5 rounded-2xl transition-all duration-300 font-bold text-base md:text-lg flex items-center gap-5 small-kh group ${containerStyle}`}
                >
                  <span className={`w-10 h-10 md:w-12 md:h-12 rounded-xl flex items-center justify-center font-black text-lg md:text-xl shrink-0 transition-transform group-active:scale-90 ${prefixStyle}`}>
                    {KHMER_PREFIXES[i]}
                  </span>
                  <span className="flex-1 leading-relaxed">{opt}</span>
                </button>
              );
            })}
          </div>
        ) : (
          <div className="space-y-6">
            {!state.showCorrect ? (
              <button 
                onClick={handleShowShortAnswer}
                className="w-full py-10 bg-indigo-50 border-4 border-dashed border-indigo-200 rounded-[2.5rem] flex flex-col items-center justify-center gap-4 group hover:bg-indigo-100 hover:border-indigo-300 transition-all"
              >
                <div className="text-5xl animate-bounce">🤔</div>
                <span className="heading-kh text-indigo-900 font-black text-xl">ចុចដើម្បីបង្ហាញចម្លើយ</span>
              </button>
            ) : (
              <div className="p-8 md:p-10 bg-emerald-50 border-2 border-emerald-500 rounded-[2.5rem] animate-fadeIn shadow-lg relative overflow-hidden">
                <div className="absolute top-0 right-0 w-24 h-24 bg-emerald-500/10 rounded-bl-[4rem] flex items-center justify-center text-4xl">
                  ✅
                </div>
                <div className="flex items-center gap-3 mb-6">
                  <span className="px-4 py-1.5 bg-emerald-600 text-white rounded-lg text-xs font-black uppercase small-kh shadow-md">ចម្លើយត្រឹមត្រូវ</span>
                </div>
                <p className="small-kh text-emerald-950 text-xl md:text-2xl font-bold leading-relaxed whitespace-pre-wrap">
                  {currentQ.answer}
                </p>
              </div>
            )}
          </div>
        )}
      </div>

      {state.showCorrect && (
        <div className="mt-12 animate-fadeIn">
          <button 
            onClick={handleNext} 
            className="w-full btn-blue-elegant py-5 text-xl heading-kh uppercase tracking-wider shadow-[0_10px_30px_rgba(30,27,75,0.3)] hover:brightness-110 active:scale-[0.98] transition-all"
          >
            {state.currentQuestionIndex + 1 === partQuestions.length ? "បញ្ចប់ និងមើលលទ្ធផល 🏁" : "សំណួរបន្ទាប់ ✨"}
          </button>
        </div>
      )}
    </div>
  );
};

