import { initializeApp, getApps, getApp, FirebaseApp } from 'firebase/app';
import { 
  initializeFirestore, 
  doc, 
  setDoc, 
  onSnapshot, 
  Firestore, 
  getFirestore, 
  collection, 
  addDoc, 
  query, 
  orderBy, 
  deleteDoc 
} from 'firebase/firestore';
import { Question, Feedback } from '../types';

const firebaseConfig = {
  apiKey: "AIzaSyDw5UkwT6ab4rlel-g6KSmaKM9MgjUnIOs",
  authDomain: "quiz-master-kh.firebaseapp.com",
  projectId: "quiz-master-kh",
  storageBucket: "quiz-master-kh.firebasestorage.app",
  messagingSenderId: "1030981971798",
  appId: "1:1030981971798:web:5a7e6e86c0c593dca830f7",
  measurementId: "G-MQJYZ5ME91"
};

// Singleton pattern for Firebase App and Firestore
let appInstance: FirebaseApp;
let dbInstance: Firestore;

export const initFirebase = (): Firestore => {
  if (dbInstance) return dbInstance;

  try {
    const apps = getApps();
    appInstance = apps.length === 0 ? initializeApp(firebaseConfig) : apps[0];

    // Using standard getFirestore for better compatibility with esm.sh bundles
    dbInstance = getFirestore(appInstance);

    return dbInstance;
  } catch (e) {
    console.error("Firebase initialization failed:", e);
    // Fallback attempts if needed, but standard init is preferred
    appInstance = getApp();
    dbInstance = getFirestore(appInstance);
    return dbInstance;
  }
};

/**
 * Clean data before sending to Firestore to avoid circular references or complex objects
 */
const prepareDataForFirestore = (questions: Question[]): any[] => {
  if (!Array.isArray(questions)) return [];

  return questions.map(q => {
    const type = q.type === 'short' ? 'short' : 'mcq';
    const base = {
      subject: String(q.subject || ''),
      question: String(q.question || ''),
      type: type,
      isActive: q.isActive !== false
    };

    if (type === 'mcq') {
      return {
        ...base,
        options: Array.isArray(q.options) ? q.options.map(o => String(o)) : ["", "", "", ""],
        correct: typeof q.correct === 'number' ? q.correct : 0,
      };
    } else {
      return {
        ...base,
        answer: String(q.answer || ''),
      };
    }
  });
};

export const syncQuestionsToFirebase = async (questions: Question[]) => {
  const database = initFirebase();
  try {
    const quizRef = doc(database, 'config', 'questions_data');
    const dataToSync = prepareDataForFirestore(questions);

    await setDoc(quizRef, { 
      questions: dataToSync, 
      updatedAt: new Date().toISOString() 
    });
  } catch (err) {
    console.error("Sync to Firebase failed:", err);
    throw err;
  }
};

export const listenToQuestions = (
  onUpdate: (questions: Question[]) => void, 
  onError: (error: any) => void
) => {
  const database = initFirebase();
  const quizRef = doc(database, 'config', 'questions_data');

  return onSnapshot(quizRef, 
    (docSnap) => {
      if (docSnap.exists()) {
        const data = docSnap.data();
        // Return only the plain data array to prevent circular structure leaks
        onUpdate(data.questions || []);
      } else {
        onUpdate([]);
      }
    },
    (error) => {
      console.error("Firestore real-time error:", error);
      onError(error);
    }
  );
};

export const sendFeedback = async (username: string, text: string) => {
  const database = initFirebase();
  try {
    const feedbackCol = collection(database, 'feedback');
    await addDoc(feedbackCol, {
      username: String(username),
      text: String(text),
      createdAt: new Date().toISOString()
    });
  } catch (e) {
    console.error("Error sending feedback:", e);
  }
};

export const listenToFeedback = (onUpdate: (feedback: Feedback[]) => void) => {
  const database = initFirebase();
  const feedbackCol = collection(database, 'feedback');
  const q = query(feedbackCol, orderBy('createdAt', 'desc'));

  return onSnapshot(q, (snapshot) => {
    const fbList = snapshot.docs.map(doc => {
      const data = doc.data();
      return {
        id: doc.id,
        username: String(data.username || 'Anonymous'),
        text: String(data.text || ''),
        createdAt: String(data.createdAt || new Date().toISOString())
      };
    }) as Feedback[];
    onUpdate(fbList);
  });
};

export const removeFeedback = async (id: string) => {
  const database = initFirebase();
  try {
    await deleteDoc(doc(database, 'feedback', id));
  } catch (e) {
    console.error("Error deleting feedback:", e);
  }
};

import * as React from 'react';
import { useState, useMemo, useRef, useEffect } from 'react';
import { Question, QuizState } from '../types';

interface QuizGameProps {
  subject: string;
  partIndex: number;
  type: 'mcq' | 'short';
  allSubjectQuestions: Question[];
  onExit: () => void;
  onStartNextPart?: (newPartIndex: number) => void;
}

const QuizGame: React.FC<QuizGameProps> = ({ subject, partIndex, type, allSubjectQuestions, onExit, onStartNextPart }) => {
  const KHMER_PREFIXES = ['ក', 'ខ', 'គ', 'ឃ'];
  const KHMER_DIGITS = ['០', '១', '២', '៣', '៤', '៥', '៦', '៧', '៨', '៩'];
  const toKhmerNumeral = (n: number) => n.toString().split('').map(digit => KHMER_DIGITS[parseInt(digit)] || digit).join('');

  const [isMuted, setIsMuted] = useState(false);
  const correctAudioRef = useRef<HTMLAudioElement | null>(null);
  const wrongAudioRef = useRef<HTMLAudioElement | null>(null);

  useEffect(() => {
    correctAudioRef.current = new Audio('https://assets.mixkit.co/active_storage/sfx/600/600-preview.mp3');
    wrongAudioRef.current = new Audio('https://assets.mixkit.co/active_storage/sfx/951/951-preview.mp3');
    return () => { correctAudioRef.current?.pause(); wrongAudioRef.current?.pause(); };
  }, []);

  // Questions for the current part (10 questions per part)
  const partQuestions = useMemo(() => {
    const start = partIndex * 10;
    const subset = allSubjectQuestions.slice(start, start + 10);
    if (type === 'mcq') {
      return subset.map(q => {
        if (!q.options) return q;
        // Map to standard object structure for the game
        const opts = q.options.map((opt, idx) => ({ text: opt, isCorrect: idx === q.correct }));
        return { ...q, options: opts.map(o => o.text), correct: opts.findIndex(o => o.isCorrect) };
      });
    }
    return subset;
  }, [allSubjectQuestions, partIndex, type]);

  const [state, setState] = useState<QuizState>({
    currentQuestionIndex: 0, 
    score: 0, 
    isFinished: false, 
    selectedAnswer: null, 
    userInput: '', 
    showCorrect: false, 
    userAnswers: [], 
    isReviewing: false
  });

  // CRITICAL: Reset the entire game state when the part index, subject, or type changes
  // This allows the "Next Part" button to function correctly.
  useEffect(() => {
    setState({
      currentQuestionIndex: 0, 
      score: 0, 
      isFinished: false, 
      selectedAnswer: null, 
      userInput: '', 
      showCorrect: false, 
      userAnswers: [], 
      isReviewing: false
    });
    // Scroll to top when moving to next part
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }, [subject, partIndex, type]);

  const hasNextPart = (partIndex + 1) * 10 < allSubjectQuestions.length;

  const handleMCQSelect = (idx: number) => {
    if (state.selectedAnswer !== null || state.isFinished) return;
    const isCorrect = idx === partQuestions[state.currentQuestionIndex].correct;
    if (!isMuted) {
      const audio = isCorrect ? correctAudioRef.current : wrongAudioRef.current;
      if (audio) { audio.currentTime = 0; audio.play().catch(() => {}); }
    }
    setState(prev => ({
      ...prev, 
      selectedAnswer: idx, 
      showCorrect: true, 
      score: isCorrect ? prev.score + 1 : prev.score, 
      userAnswers: [...prev.userAnswers, idx]
    }));
  };

  const handleShowShortAnswer = () => {
    if (!isMuted && correctAudioRef.current) {
      correctAudioRef.current.currentTime = 0;
      correctAudioRef.current.play().catch(() => {});
    }
    setState(prev => ({ 
      ...prev, 
      showCorrect: true, 
      score: prev.score + 1,
      userAnswers: [...prev.userAnswers, 'seen']
    }));
  };

  const handleNext = () => {
    if (state.currentQuestionIndex + 1 < partQuestions.length) {
      setState(prev => ({ ...prev, currentQuestionIndex: prev.currentQuestionIndex + 1, selectedAnswer: null, showCorrect: false, userInput: '' }));
      window.scrollTo({ top: 0, behavior: 'smooth' });
    } else {
      setState(prev => ({ ...prev, isFinished: true }));
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  };

  const toggleReviewMode = () => {
    setState(prev => ({ ...prev, isReviewing: !prev.isReviewing }));
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  // Review Answers View
  if (state.isFinished && state.isReviewing) {
    return (
      <div className="page-transition space-y-8 pb-20 px-2">
        <div className="flex items-center justify-between sticky top-0 z-10 bg-slate-950/80 backdrop-blur-md py-4 px-4 rounded-b-2xl border-b border-white/10 mb-6">
          <button 
            onClick={toggleReviewMode}
            className="px-6 py-3 bg-white/10 hover:bg-white/20 text-white rounded-2xl font-black heading-kh text-sm flex items-center gap-2 transition-all"
          >
            ← ត្រឡប់ក្រោយ
          </button>
          <div className="text-right">
            <h3 className="heading-kh text-white font-black text-sm">ពិនិត្យចម្លើយឡើងវិញ</h3>
            <p className="text-[10px] text-emerald-400 font-bold uppercase tracking-widest">ភាគ {toKhmerNumeral(partIndex + 1)}</p>
          </div>
        </div>

        <div className="space-y-6 max-w-3xl mx-auto">
          {partQuestions.map((q, qIdx) => {
            const userAnswer = state.userAnswers[qIdx];
            return (
              <div key={qIdx} className="card-white-elegant p-6 md:p-8 border-l-8 border-indigo-950 shadow-xl animate-fadeIn">
                <div className="flex items-start gap-4 mb-6">
                  <span className="w-10 h-10 bg-indigo-950 text-white rounded-xl flex items-center justify-center font-black shrink-0 shadow-md">
                    {toKhmerNumeral(qIdx + 1)}
                  </span>
                  <h4 className="heading-kh text-lg md:text-xl text-indigo-950 text-justify leading-relaxed">
                    {q.question}
                  </h4>
                </div>

                {q.type === 'mcq' ? (
                  <div className="grid grid-cols-1 gap-3 pl-0 md:pl-14">
                    {q.options?.map((opt, oIdx) => {
                      const isUserChoice = userAnswer === oIdx;
                      const isCorrectChoice = q.correct === oIdx;

                      let style = "bg-gray-50 border-gray-100 opacity-60";
                      if (isCorrectChoice) style = "bg-emerald-50 border-emerald-500 text-emerald-950 opacity-100 ring-2 ring-emerald-500/10";
                      else if (isUserChoice && !isCorrectChoice) style = "bg-red-50 border-red-500 text-red-950 opacity-100";

                      return (
                        <div key={oIdx} className={`p-4 rounded-xl border flex items-center gap-4 transition-all ${style}`}>
                          <span className={`w-8 h-8 rounded-lg flex items-center justify-center font-black text-sm shrink-0 ${isCorrectChoice ? 'bg-emerald-600 text-white' : isUserChoice ? 'bg-red-600 text-white' : 'bg-white text-gray-400'}`}>
                            {KHMER_PREFIXES[oIdx]}
                          </span>
                          <span className="flex-1 font-bold small-kh text-sm md:text-base">{opt}</span>
                          {isCorrectChoice && <span className="text-emerald-600 text-xl font-bold">✓</span>}
                          {isUserChoice && !isCorrectChoice && <span className="text-red-600 text-xl font-bold">✕</span>}
                        </div>
                      );
                    })}
                  </div>
                ) : (
                  <div className="pl-0 md:pl-14">
                    <div className="p-6 bg-emerald-50 border border-emerald-500/20 rounded-2xl relative overflow-hidden">
                       <p className="text-[10px] font-black text-emerald-700 uppercase mb-3 tracking-widest">ចម្លើយត្រឹមត្រូវ៖</p>
                       <p className="small-kh text-indigo-950 font-bold text-lg leading-relaxed whitespace-pre-wrap">{q.answer}</p>
                    </div>
                  </div>
                )}
              </div>
            );
          })}
        </div>

        <div className="flex justify-center py-12">
           <button 
             onClick={onExit}
             className="btn-blue-elegant px-10 py-5 heading-kh text-lg shadow-2xl active:scale-95 transition-all"
           >
             ត្រឡប់ទៅមឺនុយដើម 🏠
           </button>
        </div>
      </div>
    );
  }

  // Quiz Results View
  if (state.isFinished) {
    const percentage = Math.round((state.score / partQuestions.length) * 100);
    return (
      <div className="page-transition max-w-md mx-auto py-10 px-4">
        <div className="card-white-elegant p-10 text-center border-t-8 border-indigo-950 overflow-hidden relative shadow-2xl">
          <div className="absolute top-0 left-0 w-full h-2 bg-gradient-to-r from-indigo-950 via-blue-500 to-indigo-950"></div>
          <div className="text-7xl mb-6">🏆</div>
          <h2 className="text-2xl font-black mb-2 heading-kh text-indigo-950">បញ្ចប់ការធ្វើតេស្ត</h2>
          <div className="text-7xl font-black text-indigo-950 my-8 drop-shadow-sm">{toKhmerNumeral(percentage)}%</div>

          <div className="flex justify-center gap-8 mb-10">
            <div className="text-center">
              <p className="text-[10px] uppercase font-black text-gray-400 mb-1 tracking-widest">ត្រឹមត្រូវ</p>
              <p className="text-2xl font-black text-emerald-600">{toKhmerNumeral(state.score)}</p>
            </div>
            <div className="h-10 w-[1px] bg-gray-100"></div>
            <div className="text-center">
              <p className="text-[10px] uppercase font-black text-gray-400 mb-1 tracking-widest">សំណួរសរុប</p>
              <p className="text-2xl font-black text-indigo-950">{toKhmerNumeral(partQuestions.length)}</p>
            </div>
          </div>

          <div className="space-y-4">
            <button 
              onClick={toggleReviewMode}
              className="w-full py-4 bg-indigo-50 text-indigo-950 border-2 border-indigo-100 rounded-2xl font-black heading-kh hover:bg-indigo-950 hover:text-white transition-all shadow-sm"
            >
              👁️ ពិនិត្យចម្លើយឡើងវិញ
            </button>

            {hasNextPart && onStartNextPart && (
              <button 
                onClick={() => onStartNextPart(partIndex + 1)}
                className="w-full btn-red-elegant py-5 text-lg heading-kh shadow-xl active:scale-95 transition-all"
              >
                ភាគបន្ទាប់ ➡️
              </button>
            )}

            <button 
              onClick={onExit} 
              className="w-full btn-blue-elegant py-5 text-lg heading-kh shadow-xl hover:brightness-110 active:scale-95 transition-all"
            >
              ត្រឡប់ទៅមឺនុយដើម 🏠
            </button>
          </div>
        </div>
      </div>
    );
  }

  // Active Quiz View
  const currentQ = partQuestions[state.currentQuestionIndex];
  const progress = ((state.currentQuestionIndex + 1) / partQuestions.length) * 100;

  return (
    <div className="card-white-elegant p-6 md:p-12 page-transition flex flex-col min-h-[600px] relative border-b-8 border-indigo-950 shadow-2xl overflow-hidden">
      {/* Progress Bar */}
      <div className="absolute top-0 left-0 w-full h-2 bg-gray-100">
        <div 
          className="h-full bg-gradient-to-r from-indigo-600 to-blue-400 transition-all duration-500 ease-out"
          style={{ width: `${progress}%` }}
        ></div>
      </div>

      <div className="flex justify-between items-start mb-10 mt-2">
        <div className="flex flex-col">
          <div className="flex flex-wrap gap-2 mb-3">
            <button 
              onClick={onExit}
              className="px-3 py-1 bg-indigo-50 text-indigo-950 rounded-lg text-[10px] font-black heading-kh hover:bg-indigo-950 hover:text-white transition-all shadow-sm"
            >
              ← ចាកចេញ
            </button>
            <span className="text-indigo-950 font-black text-[9px] uppercase tracking-[0.2em] bg-indigo-50 px-4 py-1.5 rounded-full w-fit border border-indigo-100">
              {subject} - ភាគ {toKhmerNumeral(partIndex + 1)}
            </span>
          </div>
          <div className="flex items-baseline gap-2">
             <span className="text-5xl font-black text-indigo-950 leading-none">{toKhmerNumeral(state.currentQuestionIndex + 1)}</span>
             <span className="text-xl font-black text-gray-300">/ {toKhmerNumeral(partQuestions.length)}</span>
          </div>
        </div>
        <div className="flex items-center gap-3">
          <button 
            onClick={() => setIsMuted(!isMuted)} 
            className={`w-12 h-12 rounded-2xl flex items-center justify-center text-xl border transition-all ${isMuted ? 'bg-gray-100 border-gray-200 text-gray-400' : 'bg-white border-indigo-100 text-indigo-950 shadow-sm hover:bg-indigo-50'}`}
          >
            {isMuted ? '🔇' : '🔊'}
          </button>
          <div className="bg-indigo-950 text-white px-5 md:px-6 py-3 rounded-2xl font-black text-xl shadow-lg flex items-center gap-3">
            <span className="text-[10px] opacity-50 font-medium uppercase tracking-widest hidden sm:inline">ពិន្ទុ</span>
            <span>{toKhmerNumeral(state.score)}</span>
          </div>
        </div>
      </div>

      <div className="flex-1 flex flex-col">
        <div className="mb-10">
          <h2 className="text-xl md:text-3xl font-black heading-kh text-indigo-950 leading-[1.6] text-justify">
            {currentQ?.question}
          </h2>
        </div>

        {currentQ?.type === 'mcq' ? (
          <div className="grid grid-cols-1 gap-4">
            {currentQ?.options?.map((opt, i) => {
              let containerStyle = "bg-white border-2 border-gray-100 hover:border-indigo-200 hover:bg-indigo-50/30 text-indigo-950 shadow-sm";
              let prefixStyle = "bg-indigo-950 text-white shadow-md"; 

              if (state.showCorrect) {
                if (i === currentQ.correct) {
                  containerStyle = "bg-emerald-50 border-emerald-500 text-emerald-900 shadow-lg scale-[1.02] ring-4 ring-emerald-500/10";
                  prefixStyle = "bg-emerald-600 text-white";
                } else if (i === state.selectedAnswer) {
                  containerStyle = "bg-red-50 border-red-500 text-red-900 opacity-100";
                  prefixStyle = "bg-red-600 text-white";
                } else {
                  containerStyle = "opacity-40 grayscale-[0.5] border-gray-100";
                  prefixStyle = "bg-gray-400 text-white";
                }
              }

              return (
                <button 
                  key={i} 
                  onClick={() => handleMCQSelect(i)} 
                  disabled={state.showCorrect} 
                  className={`text-left p-4 md:p-5 rounded-2xl transition-all duration-300 font-bold text-base md:text-lg flex items-center gap-5 small-kh group ${containerStyle}`}
                >
                  <span className={`w-10 h-10 md:w-12 md:h-12 rounded-xl flex items-center justify-center font-black text-lg md:text-xl shrink-0 transition-transform group-active:scale-90 ${prefixStyle}`}>
                    {KHMER_PREFIXES[i]}
                  </span>
                  <span className="flex-1 leading-relaxed text-sm md:text-lg">{opt}</span>
                </button>
              );
            })}
          </div>
        ) : (
          <div className="space-y-6">
            {!state.showCorrect ? (
