                <p className="mt-6 text-[9px] font-bold text-gray-300 uppercase tracking-widest italic">
                  សរុបមាន {toKhmerNumeral(activeQuestions.filter(q => q.type === activeType).length)} សំណួរក្នុងប្រព័ន្ធ
                </p>
