               <span style={{ fontSize: '22pt', fontWeight: '600', color: selectedTemplate === 'vivid' ? '#fbbf24' : 'inherit' }}>{footerRightTop}</span>
               <span style={{ fontSize: '16pt', opacity: 0.5, marginTop: '5px' }}>{footerRightBottom}</span>
            </div>
