import * as React from 'react';
import { useState, useEffect, useCallback, useRef } from 'react';
import { Question, AppMode, SelectedQuizInfo, UserRole, Feedback } from './types';
import { SECRET_CODE } from './constants';
import Header from './components/Header';
import AuthSection from './components/AuthSection';
import CreateSection from './components/CreateSection';
import PlaySection from './components/PlaySection';
import QuizGame from './components/QuizGame';
import { initFirebase, syncQuestionsToFirebase, listenToQuestions, listenToFeedback, removeFeedback } from './services/firebaseService';

const App: React.FC = () => {
  const [quizData, setQuizData] = useState<Question[]>([]);
  const [feedbackList, setFeedbackList] = useState<Feedback[]>([]);
  const [mode, setMode] = useState<AppMode>('play');
  const [userRole, setUserRole] = useState<UserRole>(null);
  const [username, setUsername] = useState<string>('');
  const [activeQuiz, setActiveQuiz] = useState<SelectedQuizInfo | null>(null);
  const [isInitialized, setIsInitialized] = useState(false);
  const [isCloudConnected, setIsCloudConnected] = useState<boolean | 'error'>(false);
  const isListeningRef = useRef(false);

  const APP_LOGO_URL = "https://i.postimg.cc/0ygmLdvR/3QCM_Ep4.png";

  /**
   * Strictly reconstructs objects to ensure they are plain POJOs
   * by aggressively casting all properties to primitives.
   * This prevents circular structure errors from hidden Firestore class properties.
   */
  const sanitizeQuestions = useCallback((data: any[]): Question[] => {
    if (!Array.isArray(data)) return [];

    return data.filter(q => q && typeof q === 'object').map(q => {
      // Determine type safely
      let type: 'mcq' | 'short' | 'explanation' = 'mcq';
      if (q.type === 'short') type = 'short';
      if (q.type === 'explanation') type = 'explanation';

      const cleanObj: Question = {
        subject: String(q.subject || 'មិនមានមុខវិជ្ជា'),
        question: String(q.question || ''),
        type: type,
        isActive: q.isActive !== false
      };

      if (type === 'mcq') {
        cleanObj.options = Array.isArray(q.options) 
          ? q.options.map((o: any) => String(o || '')) 
          : ['', '', '', ''];
        cleanObj.correct = typeof q.correct === 'number' ? q.correct : 0;
      } else {
        cleanObj.answer = String(q.answer || '');
      }

      return cleanObj;
    });
  }, []);

  const saveToLocal = useCallback((data: Question[]) => {
    try {
      // Create a completely fresh array of fresh objects to be absolutely safe
      const cleanData = data.map(q => {
        const base = {
          subject: String(q.subject),
          question: String(q.question),
          type: q.type,
          isActive: Boolean(q.isActive)
        };
        if (q.type === 'mcq') {
          return {
            ...base,
            options: Array.isArray(q.options) ? q.options.map(o => String(o)) : [],
            correct: Number(q.correct)
          };
        }
        return {
          ...base,
          answer: String(q.answer)
        };
      });
      localStorage.setItem('quiz_data', JSON.stringify(cleanData));
    } catch (e: any) { 
      console.error("Storage error:", e?.message); 
    }
  }, []);

  useEffect(() => {
    if (isListeningRef.current) return;
    isListeningRef.current = true;

    // Core initialization
    initFirebase();

    const saved = localStorage.getItem('quiz_data');
    if (saved) { 
      try { 
        setQuizData(sanitizeQuestions(JSON.parse(saved))); 
      } catch(e){} 
    }

    const unsubscribeQuestions = listenToQuestions((remoteData) => {
      const cleaned = sanitizeQuestions(remoteData);
      setQuizData(cleaned);
      saveToLocal(cleaned);
      setIsCloudConnected(true);
      setIsInitialized(true);
    }, (error) => {
      // Avoid circular error in logs by only printing message
      console.warn("Cloud connection error:", error?.message || "Unknown error");
      setIsCloudConnected('error');
      setIsInitialized(true);
    });

    return () => { 
      unsubscribeQuestions(); 
      isListeningRef.current = false; 
    };
  }, [sanitizeQuestions, saveToLocal]);

  useEffect(() => {
    let unsubscribeFeedback = () => {};
    if (userRole === 'admin') {
      unsubscribeFeedback = listenToFeedback((fbs) => setFeedbackList(fbs)) || (() => {});
    }
    return () => unsubscribeFeedback();
  }, [userRole]);

  const handleSyncData = (newData: Question[]) => {
    const cleaned = sanitizeQuestions(newData);
    setQuizData(cleaned);
    saveToLocal(cleaned);
    if (userRole === 'admin') {
      syncQuestionsToFirebase(cleaned)
        .then(() => setIsCloudConnected(true))
        .catch((e) => {
          console.error("Firebase sync failed:", e?.message);
          setIsCloudConnected('error');
        });
    }
  };

  const handleReorderSubject = (subject: string, type: 'mcq' | 'short' | 'explanation', direction: 'up' | 'down') => {
    const subjects = Array.from(new Set(quizData.filter(q => q.type === type).map(q => q.subject)));
    const index = subjects.indexOf(subject);
    if (index === -1) return;

    const newIndex = direction === 'up' ? index - 1 : index + 1;
    if (newIndex < 0 || newIndex >= subjects.length) return;

    const newSubjects = [...subjects];
    [newSubjects[index], newSubjects[newIndex]] = [newSubjects[newIndex], newSubjects[index]];

    const reorderedData: Question[] = [];
    newSubjects.forEach(s => {
      reorderedData.push(...quizData.filter(q => q.subject === s && q.type === type));
    });
    reorderedData.push(...quizData.filter(q => q.type !== type));
    handleSyncData(reorderedData);
  };

  const handleStartNextPart = (newPartIndex: number) => {
    if (activeQuiz) {
      setActiveQuiz({
        ...activeQuiz,
        partIndex: newPartIndex
      });
    }
  };

  if (!isInitialized) return null;

  if (!userRole) {
    return (
      <div className="min-h-screen py-12 px-4 flex flex-col items-center justify-center page-transition bg-slate-950">
        <div className="mb-12 relative group">
          <div className="absolute inset-0 bg-red-600/30 blur-[60px] rounded-full animate-pulse"></div>
          <div className="relative w-40 h-40 md:w-48 md:h-48 bg-white p-1 rounded-full shadow-2xl border-[3px] border-red-500 transform transition-transform hover:scale-105 duration-500 animate-[bounce_3s_infinite]">
            <img src={APP_LOGO_URL} alt="Logo" className="w-full h-full object-cover rounded-full" />
          </div>
        </div>
        <div className="text-center mb-16">
          <h1 className="font-black heading-kh">
            <span className="block text-3xl md:text-4xl text-white opacity-80 mb-8 uppercase tracking-[0.25em]">ត្រៀមប្រឡង</span>
            <span className="block text-6xl md:text-8xl bg-gradient-to-b from-yellow-200 via-yellow-400 to-yellow-600 bg-clip-text text-transparent py-4">ក្របខ័ណ្ឌរដ្ឋ</span>
          </h1>
        </div>
        <AuthSection onLogin={(role, uName) => { setUserRole(role); if(uName) setUsername(uName); }} secretCode={SECRET_CODE} />
      </div>
    );
  }

  return (
    <div className="min-h-screen py-6 px-4 md:py-10 page-transition">
      <div className="max-w-4xl mx-auto">
        <Header 
          mode={mode} 
          role={userRole} 
          totalQuestions={quizData.length} 
          cloudStatus={isCloudConnected} 
          setMode={(m) => { setMode(m); setActiveQuiz(null); }} 
          onLogout={() => { setUserRole(null); setUsername(''); }} 
        />
        <main className="mt-6">
          {mode === 'play' ? (
            activeQuiz ? (
              <QuizGame 
                subject={activeQuiz.subject} 
                partIndex={activeQuiz.partIndex} 
                type={activeQuiz.type} 
                allSubjectQuestions={activeQuiz.customQuestions || quizData.filter(q => q.subject === activeQuiz.subject && q.type === activeQuiz.type)} 
                onExit={() => setActiveQuiz(null)} 
                onStartNextPart={handleStartNextPart}
              />
            ) : (
              <PlaySection 
                isAdmin={userRole === 'admin'} 
                username={username} 
                quizData={quizData} 
                onStartQuiz={(subject, partIndex, type, q) => setActiveQuiz({ subject, partIndex, type, customQuestions: q })} 
              />
            )
          ) : (
            <CreateSection 
              quizData={quizData} 
              feedbackList={feedbackList} 
              onDeleteFeedback={removeFeedback} 
              onAdd={(q) => handleSyncData([...quizData, q])} 
              onUpdate={(i, q) => handleSyncData(quizData.map((old, idx) => idx === i ? q : old))} 
              onRemove={(i) => handleSyncData(quizData.filter((_, idx) => idx !== i))} 
              onToggleSubject={(sub, type, act) => handleSyncData(quizData.map(q => (q.subject === sub && q.type === type) ? { ...q, isActive: act } : q))} 
              onUpdateSubject={(old, type, newName) => handleSyncData(quizData.map(q => (q.subject === old && q.type === type) ? { ...q, subject: newName.trim() } : q))} 
              onRemoveSubject={(sub, type) => handleSyncData(quizData.filter(q => !(q.subject === sub && q.type === type)))} 
              onReorderSubject={handleReorderSubject}
              onBatchAdd={(qs) => handleSyncData([...quizData, ...qs])} 
              onLogout={() => { setUserRole(null); setUsername(''); }} 
            />
          )}
        </main>
      </div>
    </div>
  );
};

export default App;

import * as React from 'react';
import { useState, useMemo, useRef } from 'react';
import { Question, TelegramConfig, Feedback } from '../types';
import { DEFAULT_TG_BOT_TOKEN, TG_CHANNELS } from '../constants';
import html2canvas from 'html2canvas';
import { sendQuizPoll, sendQuestionImage } from '../services/telegramService';

declare var html2pdf: any;
declare var JSZip: any;

interface CreateSectionProps {
  quizData: Question[];
  feedbackList?: Feedback[];
  onDeleteFeedback?: (id: string) => void;
  onAdd: (q: Question) => void;
  onUpdate: (index: number, q: Question) => void;
  onRemove: (index: number) => void;
  onToggleSubject: (subject: string, type: 'mcq' | 'short' | 'explanation', active: boolean) => void;
  onUpdateSubject: (subject: string, type: 'mcq' | 'short' | 'explanation', newName: string) => void;
  onRemoveSubject: (subject: string, type: 'mcq' | 'short' | 'explanation') => void;
  onReorderSubject: (subject: string, type: 'mcq' | 'short' | 'explanation', direction: 'up' | 'down') => void;
  onBatchAdd: (qs: Question[]) => void;
  onLogout: () => void;
}

type ExportTemplate = 'classic' | 'royal' | 'vivid';
type TelegramSendMode = 'poll' | 'image' | 'text';

const CreateSection: React.FC<CreateSectionProps> = ({ 
  quizData, feedbackList = [], onDeleteFeedback, onAdd, onUpdate, onRemove, onToggleSubject, onUpdateSubject, onRemoveSubject, onReorderSubject, onBatchAdd
}) => {
  const APP_LOGO_URL = "https://i.postimg.cc/0ygmLdvR/3QCM_Ep4.png";
  const KHMER_PREFIXES = ['ក', 'ខ', 'គ', 'ឃ'];
  const KHMER_DIGITS = ['០', '១', '២', '៣', '៤', '៥', '៦', '៧', '៨', '៩'];
  const CAMBODIA_TITLE = "ព្រះរាជាណាចក្រកម្ពុជា";
  const CAMBODIA_MOTTO = "ជាតិ សាសនា ព្រះមហាក្សត្រ";

  const [entryMode, setEntryMode] = useState<'single' | 'bulk' | 'subjects' | 'feedback'>('single');
  const [qType, setQType] = useState<'mcq' | 'short' | 'explanation'>('mcq');
  const [bulkType, setBulkType] = useState<'mcq' | 'short' | 'explanation'>('mcq');
  const [subject, setSubject] = useState('');
  const [question, setQuestion] = useState('');
  const [options, setOptions] = useState(['', '', '', '']);
  const [correct, setCorrect] = useState(0);
  const [shortAnswer, setShortAnswer] = useState('');
  const [editingIndex, setEditingIndex] = useState<number | null>(null);
  const [bulkText, setBulkText] = useState('');

  const [viewingExport, setViewingExport] = useState<{name: string, type: 'mcq' | 'short' | 'explanation', mode: 'pdf' | 'image'} | null>(null);
  const [viewingQuestions, setViewingQuestions] = useState<{name: string, type: 'mcq' | 'short' | 'explanation'} | null>(null);
  const [selectedTemplate, setSelectedTemplate] = useState<ExportTemplate>('classic');
  const [includeAnswer, setIncludeAnswer] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [currentProcessIndex, setCurrentProcessIndex] = useState(0);

  const [globalSearch, setGlobalSearch] = useState('');
  const [questionSearch, setQuestionSearch] = useState('');

  const [editingSubject, setEditingSubject] = useState<{oldName: string, type: 'mcq' | 'short' | 'explanation', newName: string} | null>(null);

  const [footerLeft, setFooterLeft] = useState('WEB QCM 🇰🇭');
  const [footerRightTop, setFooterRightTop] = useState('t.me/web_qcm_q_and_a');
  const [footerRightBottom, setFooterRightBottom] = useState('ប្រព័ន្ធរៀបចំវិញ្ញាសាដោយស្វ័យប្រវត្តិ');

  const [tgConfig, setTgConfig] = useState<TelegramConfig>({ botToken: DEFAULT_TG_BOT_TOKEN, chatId: TG_CHANNELS[0].value });
  const [individualSendMode, setIndividualSendMode] = useState<TelegramSendMode>('poll');
  const [confirmIndividualSend, setConfirmIndividualSend] = useState<{q: Question, idx: number} | null>(null);

  const imageTemplateRef = useRef<HTMLDivElement>(null);
  const posterTemplateRef = useRef<HTMLDivElement>(null);
  const pdfTemplateRef = useRef<HTMLDivElement>(null);
  const [previewQ, setPreviewQ] = useState<Question | null>(null);

  const toKhmerNumeral = (n: number) => n.toString().split('').map(digit => KHMER_DIGITS[parseInt(digit)] || digit).join('');

  const filteredGlobalQuestions = useMemo(() => {
    if (!globalSearch.trim()) return [];
    return quizData
      .map((q, idx) => ({ ...q, originalIndex: idx }))
      .filter(q => 
        q.question.toLowerCase().includes(globalSearch.toLowerCase()) || 
        q.subject.toLowerCase().includes(globalSearch.toLowerCase())
      );
  }, [quizData, globalSearch]);

  const groupedSubjects = useMemo(() => {
    const getList = (type: 'mcq' | 'short' | 'explanation') => {
      const seen = new Set<string>();
      const list: any[] = [];
      quizData.filter(q => q.type === type).forEach(q => {
        if (!seen.has(q.subject)) {
          seen.add(q.subject);
          const related = quizData.filter(rq => rq.subject === q.subject && rq.type === type);
          list.push({ name: q.subject, isActive: related.every(rq => rq.isActive !== false), count: related.length, type });
        }
      });
      return list;
    };
    return { 
      mcq: getList('mcq'), 
      short: getList('short'),
      explanation: getList('explanation')
    };
  }, [quizData]);

  const activeQuestionsInView = useMemo(() => {
    const target = viewingExport || viewingQuestions;
    if (!target) return [];
    let qs = quizData.filter(q => q.subject === target.name && q.type === target.type);
    if (questionSearch.trim()) {
      qs = qs.filter(q => q.question.toLowerCase().includes(questionSearch.toLowerCase()));
    }
    return qs;
  }, [quizData, viewingExport, viewingQuestions, questionSearch]);

  const captureElementBlob = async (element: HTMLElement | null): Promise<Blob | null> => {
    if (!element) return null;
    try {
      const canvas = await html2canvas(element, { 
        scale: 2, 
        useCORS: true, 
        backgroundColor: null, 
        logging: false,
        width: 1080,
      });
      return new Promise(r => canvas.toBlob(r, 'image/png', 1.0));
    } catch (e) { return null; }
  };

  const handleExportPdf = async () => {
    if (!pdfTemplateRef.current || !viewingExport) return;
    setIsProcessing(true);
    try {
      const opt = {
        margin: 10,
        filename: `Vignasa_${viewingExport.name}.pdf`,
        image: { type: 'jpeg', quality: 0.98 },
        html2canvas: { scale: 2, useCORS: true },
        jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' }
      };
      await html2pdf().from(pdfTemplateRef.current).set(opt).save();
    } catch (e) { alert("កំហុស PDF"); } finally { setIsProcessing(false); }
  };

  const handleExportImageZip = async () => {
    if (!viewingExport) return;
    setIsProcessing(true);
    setCurrentProcessIndex(0);
    const zip = new JSZip();
    try {
      // Step 1: Export Poster first
      const posterBlob = await captureElementBlob(posterTemplateRef.current);
      if (posterBlob) zip.file(`00_Poster_Official.png`, posterBlob);

      // Step 2: Export Questions
      const questions = activeQuestionsInView;
      for (let i = 0; i < questions.length; i++) {
        const q = questions[i];
        setPreviewQ(q);
        setCurrentProcessIndex(i + 1);
        await new Promise(r => setTimeout(r, 400)); // Delay for rendering
        const blob = await captureElementBlob(imageTemplateRef.current);
        if (blob) zip.file(`Question_${toKhmerNumeral(i + 1)}.png`, blob);
      }

      const content = await zip.generateAsync({ type: "blob" });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(content);
      link.download = `Images_${viewingExport.name}_${selectedTemplate}.zip`;
      link.click();
    } catch (e) { alert("កំហុស ZIP"); } finally { setPreviewQ(null); setIsProcessing(false); }
  };

  const handleSendTelegramAction = async (q: Question, idx: number, mode: TelegramSendMode) => {
    try {
      if (mode === 'image') {
        setPreviewQ(q);
        setCurrentProcessIndex(idx + 1);
        await new Promise(r => setTimeout(r, 300));
        const blob = await captureElementBlob(imageTemplateRef.current);
        if (blob) {
          const label = q.type === 'explanation' ? 'ពាក្យ' : 'សំណួរ';
          const caption = `📌 *${label}ទី ${toKhmerNumeral(idx + 1)}*\n\n📋 វិញ្ញាសា៖ ${q.subject}\n✨ ផ្តល់ជូនដោយ Web QCM 🇰🇭`;
          const res = await sendQuestionImage(tgConfig, blob, caption);
          return res.ok;
        }
      } else if (mode === 'poll' && q.type === 'mcq') {
        const res = await sendQuizPoll(tgConfig, q);
        return res.ok;
      } else {
        const labelQ = q.type === 'explanation' ? 'ពាក្យ' : 'សំណួរ';
        const labelA = q.type === 'explanation' ? 'ការពន្យល់' : 'ចម្លើយ';

        let text = `📌 *${labelQ}៖* ${q.question}\n\n`;
        if (q.type === 'mcq' && q.options) {
          q.options.forEach((o, i) => { text += `${KHMER_PREFIXES[i]}. ${o}${includeAnswer && i === q.correct ? ' ✅' : ''}\n`; });
        } else {
          text += `✅ *${labelA}៖* ${q.answer}\n`;
        }
        text += `\n📋 វិញ្ញាសា៖ ${q.subject}\n✨ Web QCM 🇰🇭`;
        const response = await fetch(`https://api.telegram.org/bot${tgConfig.botToken}/sendMessage`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ chat_id: tgConfig.chatId, text, parse_mode: 'Markdown' })
        });
        const data = await response.json();
        return data.ok;
      }
    } catch (e) { return false; }
    return false;
  };

  const handleEditSubject = (oldName: string, type: 'mcq' | 'short' | 'explanation') => {
    setEditingSubject({ oldName, type, newName: oldName });
  };

  const saveSubjectNameUpdate = () => {
    if (editingSubject && editingSubject.newName.trim() && editingSubject.newName.trim() !== editingSubject.oldName) {
      onUpdateSubject(editingSubject.oldName, editingSubject.type, editingSubject.newName.trim());
    }
    setEditingSubject(null);
  };

  const handleSubmitSingle = () => {
    if (!subject.trim() || !question.trim()) return alert("សូមបំពេញព័ត៌មាន!");
    const cleanQ: Question = {
      subject: subject.trim(),
      question: question.trim(),
      type: qType,
      isActive: true,
      ...(qType === 'mcq' ? { options: options.map(o => o.trim()), correct } : { answer: shortAnswer.trim() })
    };
    if (editingIndex !== null) onUpdate(editingIndex, cleanQ); else onAdd(cleanQ);
    setQuestion(''); setOptions(['', '', '', '']); setShortAnswer(''); setEditingIndex(null);
    alert("រក្សាទុកជោគជ័យ!");
  };

  const handleBulkSubmit = () => {
    if (!subject.trim() || !bulkText.trim()) return alert("សូមបំពេញព័ត៌មាន!");
    const parsed: Question[] = [];
    const lines = bulkText.split('\n');
    let current: any = null;

    if (bulkType === 'mcq') {
       lines.forEach(l => {
        const t = l.trim(); if (!t) return;
        const qm = t.match(/^[០-៩0-9]+\.\s*(.*)/);
        if (qm) {
          if (current && current.options?.length >= 2) parsed.push(current);
          current = { type: 'mcq', subject: subject.trim(), question: qm[1].trim(), options: [], correct: 0, isActive: true };
          return;
        }
        const om = t.match(/^[កខគឃ]\.\s*(.*)/);
        if (om && current) {
          let txt = om[1].replace('(ចម្លើយត្រឹមត្រូវ)', '').trim();
          current.options.push(txt);
          if (om[1].includes('(ចម្លើយត្រឹមត្រូវ)')) current.correct = current.options.length - 1;
        }
      });
      if (current && current.options?.length >= 2) parsed.push(current);
    } else {
      // Shared Logic for Short Answer and Explanation
      let isAnswerMode = false;

      lines.forEach(l => {
        const t = l.trim(); 
        if (!t) return;

        // 1. Check for Answer Header
        const am = t.match(/^ចម្លើយ\s*[៖:]\s*(.*)/);
        if (am) {
          if (current) {
             current.answer = am[1].trim();
             isAnswerMode = true;
          }
          return;
        }

        // 2. Check for Question Start
        const qm = t.match(/^([០-៩0-9]+)\.\s*(.*)/);

        if (qm) {
           const content = qm[2].trim();
           const isNewQuestion = !isAnswerMode || content.startsWith('តើ') || content.endsWith('?') || content.endsWith('?');

           if (isNewQuestion) {
             if (current && (current.answer || current.question)) parsed.push(current);

             current = { type: bulkType, subject: subject.trim(), question: content, answer: '', isActive: true };
             isAnswerMode = false;
             return;
           }
        }

        if (isAnswerMode && current) {
           current.answer += (current.answer ? '\n' : '') + l.trim();
        }
      });

      if (current && (current.answer || current.question)) parsed.push(current);
    }

    if (parsed.length) { onBatchAdd(parsed); setBulkText(''); alert(`បាននាំចូល ${parsed.length} ${bulkType === 'explanation' ? 'ពាក្យ' : 'សំណួរ'}!`); }
  };

  const editFromQuestion = (q: any) => {
    const originalIdx = q.originalIndex !== undefined ? q.originalIndex : quizData.findIndex(item => item === q);
    if (originalIdx !== -1) {
