                               {opt} {i === q.correct && <span className="ml-2">✓</span>}
                             </p>
                          </div>
                        ))}
                      </div>
                    ) : (
                      <div className="p-6 bg-green-600/5 rounded-2xl border border-green-500/20 relative overflow-hidden">
