                {q.type === 'explanation' ? `ពាក្យទី ${toKhmerNumeral(i + 1)}៖ ` : `សំណួរ ${toKhmerNumeral(i + 1)}៖ `}{q.question}
              </p>
              {q.type === 'mcq' ? (
