                  ].map(t => (
                    <button key={t.id} onClick={() => setQType(t.id as any)} className={`px-4 py-2 rounded-lg text-[10px] font-black uppercase transition-all ${qType === t.id ? 'bg-white text-[#800000] shadow-sm' : 'text-gray-400'}`}>{t.lbl}</button>
