                    <button onClick={() => editFromQuestion(q)} className="p-3 bg-indigo-50 text-indigo-600 rounded-2xl border border-indigo-100 hover:bg-indigo-600 hover:text-white transition-all" title="កែសម្រួល">✏️</button>
                    <button onClick={() => { if (confirm('តើអ្នកចង់លុបមែនទេ?')) { onRemove(q.originalIndex); } }} className="p-3 bg-red-50 text-red-500 rounded-2xl border border-red-100 hover:bg-red-500 hover:text-white transition-all">🗑️</button>
