               {individualSendMode === 'image' && (
                  <div className="p-4 bg-blue-50 rounded-2xl border border-blue-200 shadow-inner space-y-4">
                    <div>
                      <p className="text-[10px] font-black text-blue-600 uppercase mb-2">Templates</p>
